import type { Lang } from './ui';
import { allFaqs } from './faqs-all';

export const faqTranslations: Record<Lang, Record<string, string>> = {
  en: {
  },
  es: {
    "The 5% rule estimates that homeownership costs roughly 5% of a property's value annually in unrecoverable expenses (1% property tax, 1% maintenance, and 3% cost of capital). Divide by 12 to find your break-even monthly rent. If you can rent an equivalent home for less, renting plus investing the savings builds greater wealth. For detailed math and worked case studies, read our complete guide: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">How to Decide: Rent vs. Buy Your Home</a>.": "La regla del 5% estima que ser propietario genera anualmente un coste no recuperable de aproximadamente el 5% del valor de la vivienda (1% de IBI e impuestos, 1% de mantenimiento y conservación, y 3% de coste de capital y oportunidad). Divide ese valor entre 12 para hallar el alquiler mensual de equilibrio: si alquilar una casa equivalente te cuesta menos, alquilar e invertir el ahorro acumulado genera un mayor patrimonio. Para ver cálculos detallados y casos prácticos, consulta nuestra guía completa: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">Cómo decidir: alquilar o comprar vivienda</a>.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline). For a deep dive into bank underwriting formulas, salary matrices, and the 28/36 rule, read our complete guide: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">How Much House Can I Afford?</a>.": "La mayoría de los expertos financieros y directrices bancarias recomiendan destinar como máximo entre el 25% y el 28% de tus ingresos brutos mensuales a los costes de vivienda (ratio DTI front-end). Para un análisis exhaustivo sobre las fórmulas de concesión bancaria, tablas salariales y la regla 28/36, consulta nuestra guía: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">¿Cuánta casa puedo pagar?</a>.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Si aplicas la regla del 4% de retiro seguro con una cartera equilibrada (p. ej. 60% renta variable y 40% renta fija), los datos históricos del Estudio Trinity demuestran una probabilidad superior al 95% de que tus ahorros duren al menos 30 años. Retirar a una tasa más elevada (como un 6% o 7% anual) incrementa drásticamente el riesgo de agotar el capital en 15 o 20 años en periodos de caídas de mercado. Consulta nuestra guía: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">Guía de fiscalidad, pagos mensuales y longevidad del 401(k)</a>.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Puedes cancelar o pausar tus aportaciones futuras en cualquier momento sin penalización fijando tu ahorro en el 0% en el departamento de nóminas. Sin embargo, rescatar dinero ya depositado mientras sigues contratado está por lo general prohibido por la normativa fiscal, salvo rescates en servicio activo (a partir de los 59 años y medio) o supuestos de extrema necesidad cualificada. Incluso de ser posible, un rescate anticipado suele acarrear retenciones fiscales y recargos por penalización. Lee nuestra guía: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">¿Puedo cancelar mi 401(k) y retirar el dinero mientras sigo empleado?</a>.",
    "How does this online TVM calculator solve Time Value of Money equations?": "¿Cómo resuelve las ecuaciones financieras esta calculadora online de TVM?",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to solve for any of the five core TVM variables: Present Value (PV), Future Value (FV), Periodic Payment (PMT), Annual Interest Rate (I/Y), and Number of Compounding Periods (N).": "Esta calculadora financiera de TVM utiliza las fórmulas estándar de interés compuesto y descuento de flujos de caja para despejar cualquiera de las cinco variables fundamentales del valor temporal: Valor Actual (PV), Valor Futuro (FV), Pago Periódico (PMT), Tasa de Interés Anual (I/Y) y Número de Periodos (N).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), planned recurring periodic deposits (PMT), interest rate, and duration. The calculator computes the total compounded ending balance instantly.": "Selecciona 'Valor Futuro (FV)' como la variable objetivo a despejar. Introduce tu capital o saldo inicial (PV), las aportaciones periódicas previstas (PMT), la tasa de interés y el plazo temporal. La herramienta calculará el capital acumulado final de manera inmediata.",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (common in lease and insurance contracts), earning an extra compounding cycle of interest.": "En una anualidad ordinaria o pospagable, los flujos se abonan al final de cada periodo (el estándar en préstamos e hipotecas). En una anualidad anticipada o prepagable, los pagos se efectúan al inicio de cada periodo (típico en alquileres y seguros), lo que permite capitalizar un ciclo adicional de intereses.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price. For a full breakdown of the math, comparisons with lump-sum investing, and crypto fee traps, read our complete guide: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">What Does DCA Mean in Crypto?</a>.": "El Dollar-Cost Averaging (DCA) es una estrategia de inversión consistente en aportar una cantidad constante de capital en fechas fijadas independientemente de la cotización puntual del mercado. Para consultar el desglose matemático, la comparación frente a inversiones de capital único y cómo evitar comisiones ocultas, lee nuestra guía completa: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">¿Qué significa DCA en criptomonedas?</a>.",
    "What is the 5% rule for renting vs. buying?": "¿Qué es la regla del 5% para decidir entre alquilar o comprar vivienda?",
    "The 5% rule (popularized by Ben Felix) estimates the non-recoverable annual costs of homeownership at roughly 5% of the property value: 1% for property taxes, 1% for maintenance and repairs, and 3% for the cost of capital (mortgage interest + equity opportunity cost). If renting an equivalent home costs less than 5% of its purchase price annually (or 5%/12 per month), renting is mathematically favorable.": "La regla del 5% (popularizada por Ben Felix) estima que los costes no recuperables anuales de ser propietario ascienden a aproximadamente el 5% del valor del inmueble: un 1% para el IBI e impuestos sobre la propiedad, un 1% para mantenimiento y reparaciones, y un 3% por coste de capital (intereses hipotecarios más el coste de oportunidad del capital propio). Si alquilar una vivienda equivalente cuesta menos del 5% de su valor de compra al año (o el 5%/12 al mes), financieramente resulta más rentable vivir en alquiler e invertir la diferencia.",
    "How much income should I spend on a mortgage?": "¿Qué porcentaje de mis ingresos debo destinar a la hipoteca?",
    "Financial experts and the standard 28/36 rule recommend spending no more than 28% of your gross monthly income on housing costs (PITI: Principal, Interest, Taxes, and Insurance). Total monthly debt obligations (housing + cars + student loans + credit cards) should remain under 36% to maintain financial stability.": "Los expertos financieros y la regla estándar 28/36 aconsejan destinar como máximo el 28% de tus ingresos brutos mensuales a los costes totales de la vivienda (cuota de amortización de capital, intereses, impuestos locales y seguros obligatorios). Asimismo, la suma de todas las deudas mensuales (vivienda, préstamos de coche, créditos al consumo y tarjetas) no debería exceder el 36% de tus ingresos brutos para mantener solvencia financiera.",
    "How long will my 401(k) last in retirement?": "¿Durante cuántos años durará mi dinero en la jubilación?",
    "Under the empirical 4% Safe Withdrawal Rule, your retirement savings are statistically projected to last at least 30 years with a balanced stock/bond portfolio. For example, withdrawing 4% annually ($40,000 from a $1,000,000 balance) adjusted annually for inflation has historically survived almost every 30-year retirement window in modern market history.": "Bajo la regla empírica del 4% de retiro seguro, los ahorros acumulados están estadísticamente proyectados para perdurar al menos 30 años con una cartera diversificada de renta variable y fija. Por ejemplo, retirar anualmente un 4% del capital inicial (40.000 $ anuales sobre un patrimonio de 1.000.000 $) ajustado por la inflación ha resistido con éxito prácticamente todos los ciclos de 30 años en la historia financiera moderna.",
    "Can I cancel my 401(k) and cash out while still employed?": "¿Puedo cancelar mis aportaciones o rescatar el plan mientras sigo trabajando?",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an \"in-service distribution\" (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Puedes pausar o cancelar tus aportaciones futuras en cualquier momento desde nóminas fijando tu porcentaje de ahorro en el 0% sin ninguna penalización. Sin embargo, rescatar el dinero ya acumulado en tu cuenta mientras continúas contratado en la empresa está restringido por la normativa fiscal, salvo que el plan contemple rescates en servicio activo (habitualmente a partir de los 59 años y medio) o supuestos de dificultad extrema cualificada. Además, un rescate anticipado suele activar retenciones fiscales y recargos por penalización. Consulta nuestra guía detallada: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">¿Puedo cancelar mi 401(k) y retirar el dinero mientras sigo empleado?</a>.",
    "What is the Time Value of Money (TVM)?": "¿Qué es el valor temporal del dinero (TVM)?",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest over time.": "El principio del Valor Temporal del Dinero establece que una cantidad de dinero hoy vale más que la misma cantidad en el futuro, debido a su potencial intrínseco de generar rendimientos por intereses y a la erosión del poder adquisitivo causada por la inflación.",
    "How does this online TVM calculator solve Time Value of Money problems?": "¿Cómo resuelve los problemas financieros esta calculadora online de TVM?",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Number of Periods (Nper), and Periodic Payment (PMT). By inputting any four variables, our solver computes the fifth unknown mathematically using standard financial algebra formulas.": "Esta herramienta conecta cinco variables matemáticas fundamentales: Valor Actual (PV), Valor Futuro (FV), Tasa de Interés periódica (Rate), Número de Periodos (Nper) y Cuota o Pago periódico (PMT). Al introducir cuatro variables conocidas, el motor resuelve de forma instantánea la quinta incógnita aplicando las fórmulas algebraicas estándar del cálculo financiero.",
    "How do I use this as a Future Value calculator?": "¿Cómo utilizar esta herramienta como calculadora de Valor Futuro?",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and total periods (years or months), specify any periodic recurring payment (PMT), and leave Future Value empty. The calculator instantly compounds your principal and contributions to reveal the ending balance.": "Para calcular el Valor Futuro, introduce tu depósito o saldo inicial como Valor Actual (PV), indica la tasa de interés anual y el número de periodos (años o meses), especifica la cuota mensual de ahorro (PMT) si realizas aportaciones periódicas y deja en blanco la casilla de Valor Futuro. El simulador capitalizará los flujos y calculará el saldo acumulado final.",
    "What is the difference between an ordinary annuity and an annuity due?": "¿Cuál es la diferencia entre una anualidad ordinaria y una anualidad anticipada?",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and personal loans). In an annuity due, payments occur at the beginning of each period (common in lease payments and rent), allowing each cash flow to earn an extra period of compounding interest.": "En una anualidad ordinaria o vencida, las cuotas se abonan al final de cada periodo (como ocurre habitualmente en préstamos e hipotecas). En una anualidad anticipada, los pagos se efectúan al inicio de cada periodo (como en los contratos de arrendamiento o primas de seguros), lo que permite que cada flujo genere un periodo adicional de interés compuesto.",
    "What is Dollar-Cost Averaging (DCA)?": "¿Qué es el Dollar-Cost Averaging (DCA)?",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested into equal periodic purchases (e.g. $50 every week) regardless of asset price, smoothing out market volatility over time.": "El Dollar-Cost Averaging (DCA) o inversión periódica constante es una disciplina que consiste en invertir una cantidad fija de dinero en intervalos regulares (por ejemplo, 50 $ cada semana o mes) sin importar el precio del activo en ese momento, reduciendo el riesgo de entrada en máximos y suavizando la volatilidad en el largo plazo.",
    "What is the formula for calculating Future Value with regular contributions?": "¿Cuál es la fórmula para calcular el Valor Futuro con aportaciones periódicas?",
    "For a lump sum with regular periodic additions: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], where PV is present value, r is annual interest rate, m is compounding frequency per year, t is time in years, and PMT is periodic contribution.": "Para un capital inicial con aportaciones periódicas regulares: VF = VA × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], donde VA es el valor actual inicial, r es la tasa anual nominal, m es la frecuencia de capitalización al año, t es el tiempo en años y PMT es el importe de la aportación periódica.",
    "What is the difference between an ordinary annuity and annuity due for future value?": "¿En qué se diferencian una anualidad ordinaria y una anticipada al calcular el valor futuro?",
    "In an ordinary annuity, contributions are deposited at the end of each period. In an annuity due, contributions are made at the beginning of each period, which gives every contribution an extra period to compound and results in a higher ending future value.": "En una anualidad ordinaria los depósitos se efectúan al final de cada periodo. En una anualidad anticipada las aportaciones se realizan al comienzo del periodo, lo que proporciona a cada depósito un ciclo extra de capitalización por intereses y genera un valor futuro final superior.",
    "How does compounding frequency impact the future value of an investment?": "¿Cómo influye la frecuencia de capitalización en el valor futuro de una inversión?",
    "More frequent compounding cycles (such as monthly or daily versus annually) result in higher future values because interest earned in earlier cycles begins generating its own interest sooner.": "Una mayor frecuencia de capitalización (por ejemplo mensual o diaria frente a anual) produce un valor final más elevado, ya que los intereses generados en los primeros periodos se incorporan antes al saldo principal y comienzan a producir nuevos intereses de forma anticipada.",
    "How is a mortgage payment calculated?": "¿Cómo se calcula el pago de una hipoteca?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and sometimes Private Mortgage Insurance (PMI) or HOA fees. The principal and interest portion is calculated using the standard amortization formula.": "La cuota mensual de una hipoteca suele componerse de capital e intereses (amortización francesa), a los que pueden sumarse impuestos municipales, seguros obligatorios de hogar o seguro de crédito hipotecario. La parte de capital e intereses se calcula aplicando la fórmula matemática estándar de amortización de préstamos.",
    "What does PITI stand for?": "¿Qué significa PITI?",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a total monthly mortgage payment when using an escrow account.": "PITI hace referencia a Principal (capital amortizado), Interés (coste de financiación), Taxes (impuestos sobre bienes inmuebles) e Insurance (seguro del inmueble). Son los cuatro componentes esenciales que forman el desembolso mensual total de la vivienda en una cuenta de depósito en garantía (escrow).",
    "How much should I contribute to my 401(k)?": "¿Cuánto debería aportar a mi plan de jubilación?",
    "Most financial advisors recommend contributing at least 15% of your gross annual salary toward retirement (including employer matching). At a minimum, always contribute enough to capture your employer's full matching contribution—missing the match is walking away from free money and an instant 50% to 100% return. For 2024, the IRS employee elective deferral limit is $23,000 per year, or $30,500 if you are age 50 or older.": "La mayoría de los asesores financieros recomiendan destinar al menos el 15% de tu salario bruto anual a la jubilación (incluyendo la aportación de tu empleador). Como mínimo absoluto, aporta siempre lo suficiente para aprovechar el match completo de la empresa, ya que no hacerlo equivale a rechazar dinero gratis y una rentabilidad inmediata del 50% al 100%.",
    "How does this 401(k) calculator with match calculate employer contributions?": "¿Cómo calcula esta herramienta la aportación complementaria de la empresa?",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% or 100%) up to your company's matching ceiling (e.g., up to 6% of salary). For example, on a $95,000 salary with a 6% contribution ($5,700), a 50% match adds an extra $2,850/year in employer deposits. The calculator projects both your personal deferrals and employer matching contributions compounded across your entire retirement horizon.": "La calculadora de 401(k) con match aplica la fórmula de tu empresa (por ejemplo, el 50% de los primeros 6% de tu sueldo, o el 100% hasta el 4%) y suma esa cantidad a tu ahorro personal en cada nómina.",
    "How much should I have in my 401(k) by age?": "¿Cuánto dinero debería tener acumulado para la jubilación según mi edad?",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30; 2x by age 35; 3x by age 40; 4x by age 45; 6x by age 50; 8x by age 60; and 10x your final salary by age 67. If you earn $90,000 at age 40, your target 401(k) balance is approximately $270,000 to remain on track for complete income replacement.": "Las referencias estándar de jubilación sugieren tener ahorrado: 1 vez tu salario anual a los 30 años, 3 veces a los 40 años, 6 veces a los 50 años, 8 veces a los 60 años y 10 veces tu salario anual a los 67 años.",
    "Should I do a Roth or Traditional 401(k)?": "¿Qué es mejor: un plan deducible tradicional o un plan tipo Roth?",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income and federal tax liability today; withdrawals in retirement are taxed as ordinary income. In a Roth 401(k), you contribute after-tax dollars, but your investment earnings grow completely tax-free and all qualified distributions in retirement are 100% tax-free. If you are in a low tax bracket now (early career), choose Roth; if you are currently in your peak earning years and highest tax bracket, choose Traditional.": "En un 401(k) Tradicional aportas antes de impuestos, reduciendo tu renta imponible hoy, pero pagas impuestos al retirar en el retiro. En un Roth aportas después de impuestos, pero las retiradas en la jubilación están 100% libres de impuestos. Elige Roth si prevés estar en un tramo fiscal más alto en el futuro, o Tradicional si estás en un tramo alto hoy.",
    "How much does a 401(k) contribution reduce my taxes?": "¿En cuánto reduce mis impuestos actuales una aportación deducible?",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income dollar-for-dollar. The tax savings formula is: Annual Contribution × Marginal Tax Rate. For example, contributing $10,000 at a 24% federal tax bracket plus 5% state tax saves $2,900 in total taxes. Your take-home pay only drops by $7,100 while your retirement nest egg grows by a full $10,000.": "Cada dólar aportado a un 401(k) Tradicional reduce tu base imponible en un dólar. Por ejemplo, si aportas 10.000 $ y tu tramo marginal es del 24%, ahorras unos 2.400 $ en impuestos federales este año.",
    "How much will my 401(k) be worth at retirement?": "¿Cuánto valdrá mi fondo de jubilación al retirarme?",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, and time. For example, contributing $600 per month starting at age 30 with a $25,000 starting balance and an average 7.5% annual return yields approximately $1,350,000 by age 65. The vast majority of this total (over 70%) comes from compound investment growth rather than out-of-pocket deposits.": "El saldo proyectado depende del interés compuesto, la tasa de aportación, el match del empleador y los años restantes. Utiliza los gráficos interactivos de esta calculadora para simular escenarios conservadores (5%), moderados (7%) y optimistas (9%).",
    "How much in a 401(k) do I need to retire?": "¿Cuánto dinero necesito tener ahorrado para poder jubilarme?",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement living expenses minus Social Security. If you need $60,000 per year from your portfolio, your target retirement nest egg is $1,500,000 ($60,000 × 25). This nest egg provides sustainable inflation-adjusted income throughout a 30-year retirement.": "Según la Regla del 25 (la inversa de la regla de retiro seguro del 4%), necesitas aproximadamente 25 veces tus gastos anuales previstos. Por ejemplo, si necesitas 60.000 $ anuales, requieres un fondo de unos 1,5 millones de dólares ($60.000 × 25).",
    "How much will my 401(k) pay me per month in retirement?": "¿Cuánto dinero podré cobrar al mes de mi fondo de jubilación?",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $500,000 401(k) generates ~$1,667/month ($20,000/year); a $1,000,000 401(k) generates ~$3,333/month ($40,000/year); and a $1,500,000 401(k) generates ~$5,000/month ($60,000/year). Combined with Social Security, this replaces 70% to 90% of pre-retirement income.": "Según la regla de retiro del 4%, tu pensión mensual estimada se calcula como: (Saldo final × 0,04) / 12. Un fondo de 1.000.000 $ genera unos 3.333 $ al mes ajustados por inflación durante un retiro de 30 años.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\\\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\\\" class=\\\"text-primary underline font-medium\\\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Si aplicas la regla del 4% y mantienes una cartera diversificada (60% acciones / 40% bonos), los estudios históricos (Estudio Trinity) indican una probabilidad superior al 95% de que dure al menos 30 años sin agotarse.",
    "How much tax and penalty do I pay on early 401(k) withdrawals?": "¿Qué penalización e impuestos se pagan por retirar dinero antes de tiempo?",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty PLUS ordinary federal and state income taxes on the distributed amount. For someone in the 22% federal bracket and 5% state bracket, an early withdrawal of $20,000 forfeits $7,400 (37%) to penalties and taxes, leaving only $12,600. Key exceptions to the penalty include the Rule of 55 (leaving an employer at age 55 or older), qualifying hardship distributions, or Substantially Equal Periodic Payments (SEPP / Rule 72t).": "Retirar fondos antes de los 59 años y medio conlleva una penalización del 10% del IRS más los impuestos ordinarios sobre la renta del importe total retirado, pudiendo superar el 35% o 45% en total.",
    "What is a Solo 401(k) and how does it work for the self-employed?": "¿Qué es un plan de pensiones individual o para autónomos?",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals, freelancers, and small business owners with no full-time W-2 employees (other than a spouse). It allows dual contributions: up to $23,000 in elective employee deferrals ($30,500 if age 50+) PLUS an employer profit-sharing contribution up to 25% of net adjusted business earnings (20% for sole proprietors), up to a combined maximum of $69,000 in 2024.": "Es un plan de retiro para profesionales independientes y autónomos sin empleados a tiempo completo, que permite realizar aportaciones como empleado y como empresa, permitiendo límites de deducción fiscal mucho mayores.",
    "Can I borrow against my 401(k) instead of taking an early withdrawal?": "¿Se puede solicitar un anticipo o préstamo sobre el plan de jubilación?",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000, whichever is less. A 401(k) loan avoids income tax and the 10% IRS penalty because you repay principal and interest back into your own account (usually over 5 years). However, if you leave your employer before repaying, the remaining balance usually becomes due by the federal tax filing deadline, or it converts into a taxable early distribution.": "Sí, muchos planes permiten un préstamo por hasta el 50% de tu saldo consolidado (máximo 50.000 $). Los intereses que pagas vuelven a tu propia cuenta sin activar impuestos ni multas si se devuelven en plazo (normalmente 5 años).",
    "How do I use this as a Roth vs Traditional 401(k) calculator?": "¿Cómo comparar la opción Tradicional frente a la opción Roth?",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) with one click. A Traditional 401k calculator mode shows your immediate federal and state tax savings today, while retirement withdrawals are taxed as ordinary income. A Roth 401k calculator mode models post-tax contributions that generate 100% tax-free growth and 100% tax-free withdrawals in retirement.": "Nuestra calculadora te permite alternar entre aportaciones Tradicionales (antes de impuestos) y Roth (después de impuestos), modelando el poder de gasto neto en la jubilación para que compruebes qué opción maximiza tu patrimonio final.",
    "How does the Dave Ramsey 401(k) calculator 15% rule work?": "¿En qué consiste la regla del 15% para el retiro de Dave Ramsey?",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into retirement once consumer debt is eliminated and a 3-to-6 month emergency fund is established. The Dave Ramsey 401k calculator strategy follows a 3-step order: (1) Invest in your company 401(k) up to the full employer match; (2) Max out a Roth IRA; (3) Put any remaining portion of the 15% into your Roth 401(k) or Traditional 401(k). Use our 'Dave Ramsey (15% Rule)' preset to model this exact path.": "En el Paso 4 de Dave Ramsey, inviertes el 15% de los ingresos brutos del hogar en cuentas de jubilación con ventajas fiscales una vez eliminadas todas las deudas de consumo, aprovechando primero el match y luego planes Roth.",
    "What is a SIMPLE 401(k) calculator and who qualifies for a SIMPLE plan?": "¿Qué es un plan de pensiones simplificado de empleo?",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. A simple 401k calculator models the required employer contributions: either a dollar-for-dollar match up to 3% of salary, or a flat 2% non-elective contribution for all eligible workers. SIMPLE 401(k) plans feature 100% immediate vesting, no complex nondiscrimination testing, and lower contribution limits ($16,000 in 2024, or $19,500 if age 50+).": "Un plan SIMPLE 401(k) está diseñado para pequeñas empresas de 100 empleados o menos, con aportaciones obligatorias de la empresa (un match del 3% o una aportación fija del 2%).",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\\\"/blog/can-i-cancel-401k-cash-out-while-employed/\\\" class=\\\"text-primary underline font-medium\\\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Puedes pausar o cancelar tus aportaciones futuras en cualquier momento desde nóminas sin penalización. No obstante, retirar el dinero ya acumulado mientras sigues en la empresa está restringido a supuestos de dificultad extrema demostrable.",
    "What is a realistic annual rate of return for an investment calculator?": "¿Qué tasa de rentabilidad anual es realista para simular inversiones?",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of approximately 10% annually over long multi-decade horizons (or roughly 7% after adjusting for inflation). A diversified portfolio of stocks and bonds typically targets 6% to 8% nominal annual return.": "Históricamente, el mercado bursátil diversificado (S&P 500) ha generado una rentabilidad nominal media de ~10% anual antes de inflación. Descontando entre un 2,5% y un 3% de inflación y comisiones de gestión, una hipótesis prudente a largo plazo es de un 6,5% a 7,0% real anual.",
    "How do regular recurring investments compare to a one-time lump sum?": "¿Qué diferencia hay entre invertir periódicamente (DCA) y una suma única?",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility by consistently purchasing shares at both market highs and lows. While lump-sum investing mathematically outperforms about 68% of the time due to long-term market upward trends, recurring monthly deposits instill discipline and build substantial wealth steadily.": "Invertir periódicamente mediante compras recurrentes (Dollar-Cost Averaging) reduce el riesgo temporal y el estrés de volatilidad, comprando más participaciones cuando los precios bajan y menos cuando suben.",
    "What is the difference between nominal return and real return?": "¿Cuál es la diferencia entre rentabilidad nominal y rentabilidad real?",
    "Nominal return is the raw percentage gain generated by your investments before inflation. Real return is the purchasing power gain after subtracting the rate of inflation (Real Return ≈ Nominal Return - Inflation Rate).": "La rentabilidad nominal es el porcentaje bruto de ganancia de tus inversiones. La rentabilidad real es el aumento de tu poder adquisitivo efectivo tras descontar la tasa de inflación.",
    "How does compound interest multiply investment portfolios over time?": "¿Cómo multiplica el interés compuesto una cartera con los años?",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contributions make up the majority of your balance; however, after 10 to 20 years, investment returns and compounded earnings account for over 60% to 80% of total portfolio value.": "El crecimiento compuesto produce una expansión exponencial. Al principio tus depósitos componen casi toda la cartera, pero a los 20 o 30 años los rendimientos reinvertidos superan todo el dinero aportado.",
    "What is a good salary increase percentage?": "¿Qué porcentaje se considera un buen aumento de sueldo?",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong performance or merit raises average 4% to 7%, and promotions or job changes typically command a 10% to 20%+ increase in base compensation.": "Un ajuste habitual por coste de vida oscila entre el 3% y el 5%. Un aumento por rendimiento profesional suele ser del 4% al 8%, y un ascenso interno promedia entre el 8% y el 12%. Cambiar de empresa suele aportar incrementos del 15% al 25%.",
    "How do I calculate a salary increase percentage?": "¿Cómo se calcula el porcentaje de un aumento de sueldo?",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: Raise % = ((New Salary - Old Salary) / Old Salary) × 100%.": "Resta tu salario anterior al salario nuevo para obtener el aumento en dinero, divide entre el salario anterior y multiplica por 100: [(Sueldo nuevo - Sueldo anterior) / Sueldo anterior] × 100.",
    "How do I convert an hourly pay raise into an annual salary increase?": "¿Cómo convertir un aumento por hora en un incremento salarial anual?",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Considerando una jornada completa estándar de 40 horas semanales y 52 semanas al año (2.080 horas anuales), multiplica el aumento por hora por 2.080. Por ejemplo, 2,50 $/hora equivale a 5.200 $ brutos anuales.",
    "Will a pay raise push me into a higher tax bracket and reduce my take-home pay?": "¿Puede una subida de sueldo reducir mis ingresos netos por subir de tramo fiscal?",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above each tax bracket threshold are taxed at the higher marginal rate; income below the threshold remains taxed at the lower previous rates. A pay raise will always increase your net take-home pay.": "No. Los impuestos sobre la renta son progresivos y funcionan por tramos marginales. El tipo impositivo más alto solo se aplica al dinero que supere el nuevo tramo, por lo que un aumento siempre incrementa tus ingresos netos en mano.",
    "What is Future Value (FV)?": "¿Qué es el Valor Futuro (VF) en finanzas?",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or compounding interest.": "El Valor Futuro (FV) es el valor dinerario que alcanzará un capital presente o una serie de pagos periódicos en una fecha futura concreta, asumiendo una tasa determinada de interés o rentabilidad.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees. For the complete mathematical formula and a comparison with reverse mortgages, read our comprehensive guide: <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">What is a Reverse Mortgage & How Payments Work</a>.": "La cuota hipotecaria mensual estándar se compone de Capital e Intereses (amortización francesa), impuestos sobre la propiedad (como el IBI o predial), seguro de hogar, seguro de impago o garantía hipotecaria (PMI si la entrada es inferior al 20%) y gastos de comunidad.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "El pago hipotecario mensual estándar se compone de Capital e Intereses (P&I), impuestos sobre la propiedad, seguro de hogar, seguro hipotecario privado (PMI) si el pago inicial es inferior al 20%, y cuotas de comunidad (HOA).",
    "What is PMI and when do I pay it?": "¿Qué es el PMI y cuándo se paga?",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "El Seguro Hipotecario Privado (PMI) protege al prestamista en caso de impago. Generalmente se exige en préstamos convencionales si la entrada es inferior al 20% del precio de la vivienda.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI significa Capital (Principal), Intereses, Impuestos (Taxes) y Seguros (Insurance). Son los cuatro componentes clave de la cuota mensual de una vivienda.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "¿Es mejor una hipoteca a 15 años que una a 30 años?",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "A 15 años se obtiene menor interés y se liquida el préstamo en la mitad de tiempo ahorrando miles de euros. A 30 años la mensualidad es más baja y da mayor holgura mensual.",
    "How do extra payments affect my mortgage payoff schedule?": "¿Cómo afectan los pagos adicionales al calendario de la hipoteca?",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Cualquier pago extra reduce directamente el capital principal pendiente, disminuyendo los intereses futuros y acortando años de hipoteca.",
    "How does an amortized loan work?": "¿Cómo funciona un préstamo amortizable?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest. Over time, an increasing portion goes toward paying down the principal balance until the debt is fully paid off.": "En un préstamo amortizable realizas pagos periódicos iguales. Al principio, la mayor parte de cada cuota se destina a intereses; con el tiempo, una proporción creciente amortiza capital hasta liquidar la deuda.",
    "What is the difference between fixed-rate and variable-rate loans?": "¿Cuál es la diferencia entre un préstamo a tipo fijo y uno variable?",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the loan term. A variable-rate loan has an interest rate that adjusts periodically based on benchmark interest rates, which can increase or decrease your payments.": "Un préstamo a tipo fijo mantiene exactamente el mismo interés y cuota durante todo el plazo. En uno variable, el tipo se revisa periódicamente según índices de referencia, haciendo variar la cuota.",
    "Can I pay off my loan early without penalty?": "¿Puedo cancelar mi préstamo anticipadamente sin penalización?",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders may charge an early payoff fee. Check your loan contract terms before making lump-sum payments.": "La mayoría de los préstamos personales y préstamos modernos permiten amortizaciones anticipadas totales o parciales sin comisión o con comisiones legales mínimas. Revisa las condiciones particulares de tu contrato antes de realizar un pago extraordinario.",
    "What is compound interest?": "¿Qué es el interés compuesto?",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It enables wealth to grow exponentially over time compared to simple interest.": "El interés compuesto es el cálculo de rendimientos tanto sobre el capital inicial depositado como sobre los intereses devengados y reinvertidos en periodos anteriores. Esto permite que el patrimonio crezca de forma exponencial en lugar de lineal.",
    "What is the Rule of 72?": "¿Qué es la regla del 72?",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your expected annual interest rate (e.g., at 8% annual return, your money doubles in approximately 9 years: 72 / 8 = 9).": "La Regla del 72 es una fórmula rápida de cálculo mental para estimar cuántos años tarda en duplicarse tu dinero: divide 72 entre la tasa de interés anual esperada (por ejemplo, al 8% anual: 72 / 8 = 9 años para duplicar el capital invertido).",
    "How does compounding frequency affect total returns?": "¿Cómo afecta la frecuencia de capitalización al rendimiento final?",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total returns. More frequent compounding means interest starts earning interest sooner, producing slightly higher annual percentage yields (APY).": "Cuanto más frecuente sea la capitalización (anual, mensual o diaria), mayor será el rendimiento total acumulado. Al capitalizar con mayor frecuencia, los intereses comienzan a generar nuevos rendimientos antes, elevando la Tasa Anual Equivalente (TAE / APY).",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement (including employer matching). At a bare minimum, contribute enough to capture the full employer match—otherwise, you are leaving free compensation on the table.": "La mayoría de los asesores financieros recomiendan destinar al menos el 15% de tus ingresos brutos anuales al ahorro para el retiro (incluyendo la aportación de tu empresa). Como mínimo absoluto, aporta lo necesario para aprovechar la totalidad de la aportación de tu empleador.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary, or dollar-for-dollar up to 4%) and calculates the combined total deposited into your retirement account each pay period.": "Aplica la fórmula específica de tu empresa (por ejemplo, el 50% de los primeros 6% de tu salario, o el 100% hasta el 4%) y suma esa aportación a tu ahorro personal en cada periodo de liquidación.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by age 40, 6x by age 50, 8x by age 60, and 10x by age 67.": "Las guías de referencia internacionales sugieren tener acumulado: 1 vez tu salario anual a los 30 años, 3 veces a los 40 años, 6 veces a los 50 años, 8 veces a los 60 años y 10 veces tu salario anual al jubilarte.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, but pay income tax on withdrawals in retirement. In a Roth 401(k), you contribute after-tax dollars, but qualified withdrawals in retirement are 100% tax-free. Generally, choose Roth if you expect to be in a higher tax bracket in retirement, and Traditional if you are in a high tax bracket today.": "En un plan Tradicional aportas dinero antes de impuestos (reduciendo tu IRPF hoy), pero tributas al retirar en la jubilación. En un plan Roth aportas con dinero neto tras impuestos, pero todas las retiradas y plusvalías en la jubilación están totalmente exentas de impuestos.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you contribute $10,000 and your marginal tax bracket is 24%, you save approximately $2,400 in federal income taxes this year.": "Cada euro o dólar aportado a un plan de pensiones deducible reduce directamente tu base imponible. Si aportas 5.000 € y tu tramo marginal de IRPF es del 30%, obtienes un ahorro fiscal directo de 1.500 € en tu declaración anual de la renta.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer match, investment returns, and years until retirement. Use this calculator's interactive chart to simulate your balance under conservative (5%), moderate (7%), and aggressive (9%) return assumptions.": "Dependerá del interés compuesto acumulado, tu ritmo de aportación, la aportación de tu empresa, la rentabilidad anual media y los años que te falten para retirarte. Puedes simular con hipótesis conservadoras (5%), moderadas (7%) u optimistas (9%).",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 times your anticipated annual retirement expenses. For example, if you need $60,000 per year from your portfolio, you need an estimated $1.5 million nest egg ($60,000 × 25).": "Según la Regla del 25 (la inversa de la regla del 4% de retiro seguro), necesitas aproximadamente 25 veces tus gastos anuales previstos en la jubilación. Si necesitas 40.000 € al año de tu cartera, tu fondo objetivo es de aproximadamente 1.000.000 €.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending Balance × 0.04) / 12. For instance, a $1,000,000 retirement portfolio generates approximately $3,333 per month in sustainable retirement income, adjusted for inflation over a 30-year retirement.": "Siguiendo la regla de retiro seguro del 4%, tu pensión mensual estimada se calcula como: (Fondo final × 0,04) / 12. Un fondo de 600.000 € generaría unos 2.000 € al mes ajustados por inflación durante un retiro de 30 años.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities / 40% fixed income), historical backtesting (Trinity Study) indicates your portfolio has an over 95% probability of lasting at least 30 years without running out of money.": "Si aplicas la regla de retiro del 4% y mantienes una cartera diversificada de acciones y bonos, los análisis históricos (Estudio Trinity) demuestran una probabilidad superior al 95% de que tu fondo dure al menos 30 años sin agotarse.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty plus standard income tax on the entire amount. Total taxes and penalties can easily exceed 35%–45% of your withdrawal.": "El rescate anticipado de un plan de pensiones antes de la edad reglamentaria de jubilación o supuestos excepcionales tributa como rendimiento del trabajo al tipo marginal del IRPF, y en muchas jurisdicciones acarrea recargos o penalizaciones del 10% al 20%.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no full-time employees. It allows business owners to contribute both as employee and employer, enabling significantly higher annual tax-deductible contribution limits.": "Es un plan de ahorro para el retiro diseñado para autónomos y profesionales por cuenta propia, que permite desgravar aportaciones tanto a título personal como en calidad de empresa, maximizando los límites legales de deducción fiscal.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000). The interest you pay goes back into your own account, avoiding taxes and penalties as long as you repay it on schedule (usually within 5 years).": "En algunos sistemas de empleo se permite solicitar préstamos sobre el saldo acumulado sin liquidar impuestos ni penalizaciones, devolviendo el capital con intereses que se reinvierten en tu propia cuenta dentro de un plazo pactado.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions. The tool models post-tax spending power at retirement so you can see whether paying taxes now vs. at retirement yields a larger final nest egg.": "Nuestra calculadora te permite contrastar la deducción fiscal inmediata frente a la exención fiscal futura, evaluando cuál te proporciona mayor poder adquisitivo en la jubilación según tu nivel de ingresos esperado.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer non-mortgage debt is fully cleared. You first invest up to the employer match, then fund a Roth IRA, and put any remainder back into your employer plan.": "Es una pauta de finanzas personales que aconseja destinar el 15% de los ingresos brutos del hogar a la jubilación una vez liquidadas todas las deudas de consumo, aprovechando primero el match de la empresa y luego planes libres de impuestos.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It provides cost-effective retirement plans with mandatory employer contributions (either a 3% match or a 2% non-elective contribution).": "Es un plan de jubilación simplificado diseñado para pequeñas y medianas empresas (hasta 100 trabajadores), con menores costes de gestión y aportaciones empresariales obligatorias del 2% al 3% del salario.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your HR or plan administrator. However, cashing out existing vested funds while still actively employed is generally prohibited by plan rules, unless you qualify for a hardship distribution. For detailed options, see our guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Employed?</a>": "Puedes suspender o modificar tus aportaciones futuras en cualquier momento sin penalización a través del departamento de nóminas. Sin embargo, rescatar el dinero acumulado mientras sigues en activo está restringido a supuestos de extrema necesidad o desempleo de larga duración.",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of ~10% annually before inflation. After factoring in 2.5%–3% average inflation and ETF expense ratios, a realistic long-term real return assumption is 6.5% to 7.0% per year for a 100% equity portfolio, or 5.0% to 6.0% for a balanced 60/40 stocks and bonds portfolio.": "Históricamente, los mercados bursátiles mundiales diversificados han generado en torno a un 8% a 10% nominal anual. Descontando una inflación media del 2,5% - 3% y comisiones de fondos indexados, una hipótesis prudente a largo plazo es de un 6% a 7% real anual en renta variable, o del 4% a 5% en carteras mixtas de acciones y bonos.",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility stress by purchasing more shares when prices are low and fewer when prices are high. While historical data shows investing a lump sum immediately outperforms DCA about 68% of the time because markets rise long-term, recurring contributions are far easier to budget and provide psychological discipline.": "Aportar periódicamente (Dollar-Cost Averaging) reduce el riesgo de entrar en un mal momento de mercado y promedia los precios de compra. Aunque invertir todo el capital de golpe supera estadísticamente al DCA dos de cada tres veces porque la bolsa tiende a subir, las aportaciones mensuales son la forma natural y más disciplinada de ahorrar para la mayoría de las personas.",
    "Nominal return is the raw percentage gain generated by your investments before inflation and taxes. Real return is your actual purchasing power gain after subtracting the inflation rate. For example, if your portfolio gains 9% nominal in a year where inflation is 3%, your real return is approximately 6%.": "La rentabilidad nominal es el porcentaje bruto de beneficio que genera tu cartera. La rentabilidad real es la ganancia efectiva de poder adquisitivo tras restar la inflación. Por ejemplo, con un rendimiento del 8% y una inflación del 3%, tu rentabilidad real es aproximadamente del 5%.",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contribution cash makes up the vast majority of your portfolio. Over 20 to 30 years, accumulated reinvested earnings surpass your total principal deposits and begin generating more annual income than your own salary.": "En los primeros años, el total de tu cartera está compuesto casi exclusivamente por tus aportaciones de dinero. Pasados 15 o 25 años, los rendimientos acumulados reinvertidos superan todo el dinero aportado de tu bolsillo y empiezan a generar más ganancias anuales que tu propio sueldo.",
    "What is the 20/4/10 rule for buying a car?": "¿En qué consiste la regla 20/4/10 para comprar un coche?",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation costs (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income. This prevents you from becoming 'car poor' and prevents negative equity.": "Recomienda aportar al menos un 20% de entrada en efectivo, financiar a un plazo máximo de 4 años (48 meses) y que los costes mensuales totales del vehículo (cuota, seguro, combustible y mantenimiento) no excedan el 10% de tus ingresos brutos mensuales.",
    "Is a longer auto loan term better?": "¿Conviene alargar el plazo del préstamo de coche a 6 o 7 años?",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk owing more than the vehicle is worth (negative equity or being 'underwater') as the car depreciates. Sticking to 48 or 60 months is significantly safer.": "Un plazo largo (como 72 u 84 meses) reduce la cuota mensual en apariencia, pero multiplica los intereses totales que pagas y provoca que debas más dinero del que vale el coche en el mercado (patrimonio negativo). Es mucho más prudente mantenerse en 48 o 60 meses.",
    "How does vehicle depreciation affect my loan?": "¿Cómo influye la depreciación del vehículo en el préstamo?",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance can exceed the market value of the car. If the car is totaled or stolen, standard insurance only pays market value, leaving you responsible for the remaining loan balance unless you have GAP insurance.": "Los coches nuevos pierden hasta un 20% de su valor durante el primer año. Si no aportas suficiente entrada, la deuda con el banco superará el valor de mercado del coche. En caso de siniestro total, el seguro solo indemniza el valor venal del vehículo, dejándote a deber la diferencia si no cuentas con seguro de amortización o brecha (GAP).",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit-based raise typically ranges from 4% to 8%, while a promotion within the same company averages 8% to 12%. Switching companies or industries often commands a 15% to 25% salary increase.": "Un ajuste anual habitual por coste de vida oscila entre el 3% y el 5%. Un aumento por méritos profesionales suele situarse entre el 5% y el 8%, mientras que una promoción interna alcanza del 8% al 12%. Cambiar de empresa en el mismo sector suele proporcionar incrementos del 15% al 25%.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100. Formula: [(New Salary - Old Salary) / Old Salary] × 100. For example, moving from $60,000 to $66,000 is a 10% raise: ($6,000 / $60,000) × 100.": "Resta tu salario anterior al salario nuevo para obtener la subida bruta en dinero, divide ese resultado entre tu salario anterior y multiplica por 100: [(Sueldo nuevo - Sueldo anterior) / Sueldo anterior] × 100. Por ejemplo, pasar de 30.000 € a 33.000 € representa un 10% de subida: (3.000 / 30.000) × 100.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly wage increase by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Tomando como base una jornada completa de 40 horas semanales y 52 semanas al año (2.080 horas anuales), multiplica el incremento por hora por 2.080. Por ejemplo, una subida de 2 €/hora equivale a un aumento bruto anual de 4.160 € (2 € × 2.080).",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of income that falls into the new, higher bracket is taxed at the higher percentage rate. Every dollar earned below that threshold is still taxed at the lower previous rates. A pay raise will always increase your total net take-home pay.": "No, es un error conceptual común. Los sistemas tributarios modernos son progresivos por tramos marginales. El tipo impositivo más alto se aplica únicamente al dinero que sobrepase el límite del tramo, mientras que todo el sueldo previo se sigue gravando a los tipos más bajos. Un aumento de sueldo siempre incrementa tu dinero neto en el bolsillo.",
    "What is the Debt Snowball method?": "¿Qué es el método Bola de Nieve?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on everything else. Once the smallest debt is cleared, you roll its entire payment into the next smallest debt. This generates psychological momentum through rapid early wins.": "El método Bola de Nieve consiste en pagar primero las deudas de menor importe, con independencia de su tasa de interés, manteniendo los mínimos en las demás. Al liquidar la primera, sumas toda esa cuota a la siguiente más pequeña, generando victorias psicológicas rápidas que mantienen tu motivación.",
    "What is the Debt Avalanche method?": "¿Qué es el método Avalancha?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while paying minimums on all others. Mathematically, this minimizes total interest charges paid across all debts and clears debt in the fastest possible timeframe.": "El método Avalancha consiste en amortizar primero las deudas con la tasa de interés más alta (TAE/CAT). Matemáticamente es la estrategia más eficiente: minimiza el gasto total en intereses y te libera de las deudas en el menor tiempo posible.",
    "Which method is better: Debt Snowball or Debt Avalanche?": "¿Cuál es mejor: Bola de Nieve o Avalancha?",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, behavioural studies show that the Debt Snowball method often yields higher real-world completion rates because the psychological motivation of eliminating individual accounts quickly prevents people from giving up on their debt-free plan.": "Matemáticamente, la Avalancha es superior porque ahorra el máximo dinero en intereses. Sin embargo, los estudios demuestran que la Bola de Nieve tiene una tasa de éxito práctico mayor, ya que tachar deudas rápidamente de la lista da el impulso emocional necesario para no abandonar el plan.",
    "How does the 'extra payment' roll over in these strategies?": "¿Cómo se transfiere el 'pago extra' en estas estrategias?",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt. Once that target debt is paid in full, its entire monthly budget (its minimum payment + the extra cash) rolls into the next debt on your roster, creating an ever-larger monthly payment that accelerates debt payoff.": "Pagas el mínimo obligatorio en todas tus deudas y concentras todo tu ahorro disponible en la deuda número uno. Cuando esa deuda queda a cero, todo su presupuesto mensual se acumula a la cuota de la siguiente, creando un pago cada vez más potente que acelera la amortización.",
    "Can I do a hybrid of Snowball and Avalanche?": "¿Se puede combinar la Bola de Nieve y la Avalancha?",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain motivation (Snowball), and then switch to attacking the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sí. Muchas personas optan por liquidar una o dos deudas pequeñas primero para ganar confianza y liberar flujo de caja (Bola de Nieve), y luego pasan a ordenar las deudas restantes por mayor tipo de interés para maximizar el ahorro económico (Avalancha).",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or interest. It answers the fundamental financial question: 'How much will my money be worth tomorrow if I invest it today?'": "El Valor Futuro (FV) es el valor patrimonial que alcanzará una cantidad de dinero actual o una serie de flujos periódicos en una fecha futura determinada, en función de una tasa de rentabilidad o interés supuesta. Responde a la pregunta básica: ¿cuánto valdrá mi dinero mañana si lo invierto hoy?",
    "What is inflation?": "¿Qué es la inflación?",
    "Inflation is the general rise in prices for goods and services over time, resulting in a reduction in purchasing power per unit of currency. When inflation occurs, each dollar or euro buys a smaller percentage of a good or service.": "La inflación es el aumento continuo y generalizado de los precios de los bienes y servicios en una economía a lo largo del tiempo, lo que se traduce en una pérdida del poder adquisitivo del dinero.",
    "How does inflation affect my savings?": "¿Cómo deteriora la inflación los ahorros?",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only have the purchasing power equivalent of about $7,440 in 10 years, even though the nominal account balance remains unchanged.": "El dinero estacionado en cuentas corrientes sin remuneración pierde valor real cada año. Con una inflación del 3% anual, 10.000 € hoy equivaldrán a solo unos 7.440 € de poder de compra real dentro de 10 años, aunque la cifra numérica en la libreta siga siendo la misma.",
    "How is inflation officially measured?": "¿Cómo se mide oficialmente la inflación?",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average change over time in prices paid by consumers for a representative 'basket' of goods and services, including housing, food, transportation, energy, and healthcare.": "Se mide principalmente a través del Índice de Precios al Consumo (IPC), que analiza la evolución temporal del coste de una 'cesta de la compra' representativa de bienes y servicios (alimentación, vivienda, energía, transporte, sanidad y ocio).",
    "What is the historical average inflation rate?": "¿Cuál ha sido la inflación histórica promedio?",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.2% per year over multi-decade periods, though short-term supply shocks can cause temporary surges.": "En las economías desarrolladas, la inflación media histórica a largo plazo ha oscilado entre el 2% y el 3,2% anual, coincidiendo con los objetivos oficiales de estabilidad de precios de los bancos centrales (como el Banco Central Europeo y la Reserva Federal).",
    "How can I protect my money from losing value to inflation?": "¿Cómo proteger el patrimonio frente a la pérdida de valor por inflación?",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds / ETFs), real estate, inflation-protected government bonds (TIPS or bonos ligados al IPC), and commodities—historically provides the most reliable long-term protection against purchasing power loss.": "La forma más contrastada históricamente es invertir en activos productivos cuyos rendimientos superen la inflación: fondos indexados globales de renta variable (acciones), bienes raíces e inmuebles con rentas de alquiler, y títulos de deuda pública indexados a la inflación.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Consiste en liquidar primero las deudas de menor saldo, sin importar su tipo de interés, fomentando la motivación mediante victorias psicológicas rápidas.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Consiste en pagar primero las deudas con el tipo de interés más alto. Matemáticamente minimiza los intereses totales pagados y acelera la liberación de deudas.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Matemáticamente la Avalancha es superior al ahorrar más dinero, pero la Bola de Nieve suele tener mayor tasa de éxito práctico por el refuerzo psicológico de cancelar cuentas rápidamente.",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Pagas los mínimos en todas las deudas y destinas el dinero extra a la deuda objetivo. Una vez saldada, transfieres esa cuota íntegra a la siguiente deuda.",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sí. Puedes cancelar una o dos deudas pequeñas primero para ganar motivación y liquidez (Bola de Nieve), y luego liquidar las restantes por tipo de interés (Avalancha).",
    "When should I refinance my loan?": "¿Cuándo conviene refinanciar un préstamo?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Conviene refinanciar si obtienes un tipo de interés más bajo, reduces la cuota mensual o acortas el plazo, asegurando que el ahorro total en intereses supere los gastos de formalización.",
    "What closing costs are associated with refinancing?": "¿Qué costes de cierre conlleva la refinanciación?",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Suelen incluir comisiones de apertura, tasación, gestoría, registro y verificación legal, oscilando habitualmente entre el 2% y el 6% del importe financiado.",
    "How do I calculate my refinance break-even point?": "¿Cómo calculo el punto de equilibrio de la refinanciación?",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Divide los gastos totales de cierre entre el ahorro mensual obtenido. Por ejemplo: 3.000 $ de gastos / 150 $ de ahorro al mes = 20 meses para recuperar el desembolso.",
    "What is the 28/36 rule?": "¿Qué es la regla 28/36?",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "Es una norma estándar de suscripción hipotecaria que establece que los gastos de vivienda no deben superar el 28% de los ingresos brutos mensuales, y el total de deudas no debe exceder el 36%.",
    "How does DTI affect my mortgage application?": "¿Cómo influye el DTI en la solicitud de hipoteca?",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Los prestamistas usan el DTI para evaluar tu capacidad de pago. Un DTI elevado indica sobreendeudamiento, mientras que niveles inferiores al 36% se consideran de bajo riesgo.",
    "What is the difference between front-end and back-end DTI?": "¿Cuál es la diferencia entre el DTI inicial y el DTI total?",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "El DTI front-end sólo incluye los gastos de vivienda (cuota, impuestos, seguro). El DTI back-end añade todas las demás obligaciones mensuales recurrentes (tarjetas, créditos de coche, préstamos).",
    "How can I lower my Debt-to-Income ratio?": "¿Cómo puedo reducir mi ratio Deuda-Ingreso?",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Aumentando tus ingresos brutos mensuales o amortizando deudas para eliminar cuotas mensuales del cómputo general.",
    "What is the SAVE plan?": "¿Qué es el plan SAVE?",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "El plan SAVE (Saving on a Valuable Education) es el plan de pago basado en ingresos más reciente. Eleva la protección del ingreso disponible al 225% del umbral de pobreza, reduce las cuotas al 5% para préstamos de grado y detiene la acumulación de intereses impagados.",
    "How is discretionary income calculated for student loans?": "¿Cómo se calcula el ingreso disponible para préstamos estudiantiles?",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "Es la diferencia entre el Ingreso Bruto Ajustado (AGI) y un porcentaje del umbral federal de pobreza fijado para el tamaño de su familia.",
    "How do I calculate stock returns?": "¿Cómo se calcula la rentabilidad de las acciones?",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Resta el precio de compra al de venta para hallar la plusvalía, suma los dividendos recibidos, divide entre el precio de compra y multiplica por 100.",
    "What is CAGR in stock returns?": "¿Qué es la tasa CAGR en bolsa?",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "Es la Tasa de Crecimiento Anual Compuesto. Representa la rentabilidad anualizada geométrica obtenida a lo largo de un período.",
    "What is the Capital Asset Pricing Model (CAPM)?": "¿Qué es el modelo de valoración de activos financieros (CAPM)?",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "Es un modelo financiero que calcula la rentabilidad esperada de un activo en función de su riesgo sistemático (Beta) frente al mercado.",
    "What does Asset Beta (β) represent?": "¿Qué mide la Beta (β) de un activo?",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Mide la volatilidad o riesgo sistemático respecto al mercado general. Beta = 1 se mueve con el mercado; Beta > 1 implica mayor volatilidad y riesgo.",
    "What is net worth?": "¿Qué es el patrimonio neto?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "Es el valor monetario de todo lo que posees (activos) menos todo lo que debes (pasivos). Es la métrica fundamental de salud financiera.",
    "How much emergency fund is recommended?": "¿Cuánto dinero se recomienda tener en el fondo de emergencia?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "La mayoría de expertos aconseja ahorrar entre 3 y 6 meses de gastos básicos imprescindibles. Si tus ingresos son variables, conviene aspirar a 9 o 12 meses.",
    "What is an expense ratio?": "¿Qué es el ratio de gastos (Expense Ratio)?",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Es la comisión anual que cobra un fondo de inversión o ETF por su gestión, expresada como porcentaje del capital invertido.",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "Consiste en invertir una suma fija de forma periódica (semanal o mensual) sin importar el precio, reduciendo la volatilidad y el riesgo de mercado.",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "Es el aumento generalizado de precios y la consiguiente pérdida del poder adquisitivo del dinero a lo largo del tiempo.",
    "What is the key difference between a Roth and Traditional IRA?": "¿Cuál es la diferencia esencial entre una cuenta IRA Roth y una Tradicional?",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "La Tradicional permite desgravar las aportaciones hoy y tributar en la jubilación. La Roth utiliza capital neto y garantiza que el crecimiento y rescate queden exentos de impuestos.",
    "How does debt consolidation save you money?": "¿Cómo ahorra dinero la consolidación de deudas?",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "La consolidación agrupa múltiples deudas con altos intereses (como tarjetas de crédito al 20%–29% TAE) en un único préstamo personal con un tipo fijo menor (ej. 8%–14% TAE). Esto reduce tu pago mensual total y ahorra miles de dólares o euros en intereses.",
    "Does debt consolidation hurt your credit score?": "¿Afecta la consolidación de deudas a tu calificación crediticia?",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Solicitar un nuevo préstamo causa una pequeña bajada temporal por la consulta de crédito. Sin embargo, cancelar las tarjetas saturadas reduce de inmediato tu ratio de utilización de crédito, lo que suele aumentar tu puntuación crediticia en un plazo de 30 a 60 días.",
    "What is the difference between debt consolidation and debt settlement?": "¿Cuál es la diferencia entre consolidación y liquidación de deudas?",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "La consolidación paga íntegramente a tus acreedores mediante un nuevo préstamo con menor interés sin dañar tu historial. La liquidación implica dejar de pagar para negociar quitas, lo que provoca daños graves y duraderos en tu informe crediticio.",
    "What should I look out for before consolidating debt?": "¿Qué precauciones debo tomar antes de consolidar deudas?",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Presta atención a las comisiones de apertura (normalmente entre el 1% y el 6%), asegúrate de que la nueva cuota mensual se ajuste cómodamente a tu presupuesto y evita endeudarte de nuevo en las tarjetas liquidadas.",
    "What is daily compound interest and how does it work?": "¿Qué es el interés compuesto diario y cómo funciona?",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "El interés compuesto diario calcula y añade los intereses generados al saldo cada día (365 veces al año). En los días siguientes, ganas intereses sobre el capital inicial y sobre los intereses acumulados previamente, acelerando el crecimiento exponencial del patrimonio.",
    "What is the formula for daily compound interest?": "¿Cuál es la fórmula del interés compuesto diario?",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "La fórmula es A = P(1 + r/365)^(365 × t), donde P es el capital inicial, r es la tasa anual (en decimal) y t es el tiempo en años. Al añadir depósitos periódicos, los intereses se calculan sobre el saldo diario acumulado.",
    "How much more money do you earn with daily vs monthly compounding?": "¿Cuánto más se gana con capitalización diaria frente a mensual?",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "En un depósito de 100.000 $ al 7% TAE a 20 años, la capitalización diaria produce 405.514 $ frente a 403.873 $ de la mensual, lo que genera 1.641 $ adicionales únicamente por la mayor frecuencia de capitalización.",
    "Do high-yield savings accounts (HYSA) compound daily?": "¿Las cuentas de ahorro de alto rendimiento generan interés compuesto diario?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Sí, la gran mayoría de cuentas de ahorro remuneradas y fondos monetarios capitalizan intereses diariamente y abonan el importe en tu saldo el último día hábil de cada mes.",
    "What is the FIRE movement and what does it mean?": "¿Qué es el movimiento FIRE y qué significa?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE significa 'Independencia Financiera, Jubilación Temprana' (Financial Independence, Retire Early). Es una filosofía donde se maximiza la tasa de ahorro (a menudo del 40% al 70%) y se invierte en fondos indexados hasta que la cartera genere suficientes ingresos pasivos para cubrir los gastos de por vida.",
    "What is the 4% Safe Withdrawal Rule?": "¿Qué es la regla del 4% de retiro seguro?",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Procedente del Estudio Trinity, la regla del 4% indica que puedes retirar el 4% del valor inicial de tu cartera al año (ajustado anualmente por inflación) con más del 95% de probabilidad de no agotar tus fondos durante una jubilación de 30 años.",
    "How is your FIRE Number calculated?": "¿Cómo se calcula tu Cifra FIRE?",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Tu cifra FIRE equivale a tus gastos anuales multiplicados por 25 (según la regla del 4%) o por 33 (con un enfoque conservador del 3%). Por ejemplo, si gastas 60.000 $ al año, tu cifra FIRE es de 1.500.000 $.",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "¿Cuál es la diferencia entre Lean FIRE, Standard FIRE y Fat FIRE?",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Lean FIRE cubre únicamente gastos esenciales y minimalistas (menos de 40.000 $/año). Standard FIRE sostiene un estilo de vida de clase media acomodada (50.000 $–100.000 $/año). Fat FIRE permite gastos de alto nivel y viajes de lujo (más de 120.000 $/año) sin restricciones financieras.",
    "When is the earliest age I can claim Social Security retirement benefits?": "¿Cuál es la edad mínima para solicitar los beneficios de jubilación de la Seguridad Social?",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Puedes comenzar a recibir prestaciones de la Seguridad Social desde los 62 años. No obstante, solicitarlo anticipadamente reduce permanentemente tu mensualidad hasta un 30% en comparación con esperar a la Plena Edad de Jubilación (FRA).",
    "What is my Full Retirement Age (FRA)?": "¿Cuál es mi Plena Edad de Jubilación (FRA)?",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Para cualquier persona nacida en 1960 o después, la Plena Edad de Jubilación es a los 67 años. Si solicitas el beneficio a esa edad, recibes el 100% de la cantidad básica asignada sin penalizaciones por retiro anticipado.",
    "How much more do I get if I delay claiming Social Security until age 70?": "¿Cuánto más recibo si retraso la solicitud de la Seguridad Social hasta los 70 años?",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Por cada año que demores la solicitud más allá de tu edad reglamentaria (hasta los 70 años), tu pensión aumenta un 8% anual por créditos de jubilación postergada. Esperar hasta los 70 te otorga cerca del 124% de tu prestación total de forma vitalicia.",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "¿Cuál es la edad de equilibrio entre jubilarse a los 62 o a los 70 años?",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "La edad de equilibrio se sitúa habitualmente entre los 78 y los 81 años. Si estimas vivir más allá de los 80 años, retrasar la solicitud hasta los 70 produce casi siempre una retribución total acumulada superior a lo largo de la vida.",
    "What is the Australian Superannuation Guarantee (SG) rate?": "¿Cuál es la tasa de la Garantía de Superannuation (SG) australiana?",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Por ley de la Commonwealth de Australia, los empleadores están obligados a aportar un porcentaje de tu salario ordinario a tu fondo de pensiones designado. La tasa está legislada para alcanzar el 12%.",
    "How is money inside Australian Super taxed?": "¿Cómo tributa el dinero dentro de un fondo Super australiano?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Las aportaciones con ventajas fiscales (incluidas las patronales y el sacrificio salarial antes de impuestos) tributan a una tasa reducida del 15% dentro del fondo, frente a los tramos marginales del IRPF que pueden alcanzar el 45% más el gravamen de Medicare.",
    "How much super do I need for a comfortable retirement in Australia?": "¿Cuánto dinero en el fondo Super se necesita para una jubilación cómoda en Australia?",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Según el estándar de jubilación de la ASFA, una persona soltera necesita un saldo de aproximadamente 595.000 $ a los 67 años, mientras que una pareja requiere unos 690.000 $ para mantener un nivel de vida confortable durante el retiro.",
    "How does salary sacrificing boost superannuation growth?": "¿Cómo impulsa el crecimiento del fondo Super el sacrificio salarial (Salary Sacrifice)?",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "El sacrificio salarial permite transferir ingresos brutos antes de impuestos directamente al plan de pensiones. Al evitar tipos impositivos marginales más altos y aprovechar el interés compuesto durante décadas, puede sumar cientos de miles de dólares a tu fondo de jubilación.",
    "How does student loan forgiveness work under IDR plans?": "¿Cómo funciona la condonación de préstamos estudiantiles bajo planes IDR?",
    "If you pay under an IDR plan for 20 or 25 years (or as little as 10 years under SAVE for low initial balances), any remaining student debt is forgiven. However, under current tax laws, this forgiven balance may be treated as taxable income, although federal tax on forgiven student loans is temporarily suspended through 2025.": "Si abonas tus cuotas bajo un plan IDR durante 20 o 25 años (o desde 10 años en SAVE para saldos iniciales bajos), el saldo restante queda condonado por completo.",
    "Which IDR plan is best for me?": "¿Cuál es el mejor plan IDR para mí?",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. However, if your income is very high relative to your debt, plans like PAYE or IBR might be better because they cap your monthly payment at what it would be under the Standard 10-Year Repayment Plan, whereas SAVE has no payment cap.": "Para la mayoría de los prestatarios, el plan SAVE ofrece el pago mensual más bajo y el mejor subsidio de intereses. Sin embargo, si tus ingresos son muy altos en relación con la deuda, PAYE o IBR tienen un tope mensual que puede convenirte.",
    "Can I switch student loan repayment plans at any time?": "¿Puedo cambiar de plan de amortización en cualquier momento?",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause outstanding unpaid interest to capitalize (be added to your principal balance), which means you will start paying interest on that interest.": "Sí, puedes solicitar el cambio de plan de forma gratuita en studentaid.gov. Sin embargo, cambiar de plan en ocasiones puede capitalizar intereses pendientes sobre el principal.",
    "What is a 'no-closing-cost' refinance?": "¿Qué es una refinanciación 'sin gastos de cierre'?",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into your new total loan balance or charges a slightly higher interest rate to cover them. This avoids paying cash upfront but increases the lifetime cost of the loan.": "No significa que los gastos desaparezcan. La entidad financiera añade los gastos al saldo financiado o aplica un tipo de interés ligeramente mayor para compensarlos.",
    "Does refinancing lower my monthly payment or total interest?": "¿La refinanciación reduce la cuota mensual o los intereses totales?",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same or shorter term, you save on both. However, if you reset your term back to 30 years to get the lowest possible monthly payment, you might end up paying more total interest over the life of the loan despite the monthly savings.": "Depende del plazo elegido. Si reduces el tipo manteniendo o acortando el plazo, ahorras en ambos. Si alargas el plazo a 30 años, la cuota baja pero los intereses totales pueden aumentar.",
    "What is the maximum DTI ratio lenders will accept?": "¿Cuál es el DTI máximo que aceptan las entidades bancarias?",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though many will approve up to 43%. Government-backed loans like FHA and VA loans can be more flexible, sometimes allowing back-end DTIs up to 50% or higher if you have a strong credit score or significant cash reserves.": "En hipotecas convencionales se prefiere un 36% o menos, aunque muchos aprueban hasta el 43%. Con buen historial crediticio y ahorros, ciertos programas permiten hasta el 50%.",
    "Which IRA plan is better for me?": "¿Qué plan IRA me conviene más?",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower than it is today, a Traditional IRA is better.": "Si prevés estar en un tramo impositivo superior en la jubilación, conviene el modelo Roth. Si tu tramo fiscal será inferior, conviene el modelo Tradicional.",
    "What are the contribution limits for IRAs in 2024?": "¿Cuáles son los límites de aportación a cuentas IRA?",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under age 50, and $8,000 for those age 50 or older (which includes a $1,000 catch-up contribution).": "El límite anual general es de 7.000 $ para menores de 50 años, y de 8.000 $ para personas de 50 años o más.",
    "Are there income limits for contributing to Traditional and Roth IRAs?": "¿Existen límites de ingresos para poder aportar a las cuentas IRA?",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers, and $230,000 to $240,000 for married couples filing jointly. Anyone can contribute to a Traditional IRA regardless of income, but the tax deductibility phases out if your income is high and you have access to a workplace retirement plan (like a 401k).": "Las cuentas Roth tienen límites de ingresos estrictos, mientras que en las tradicionales cualquiera puede aportar, variando la desgravación según los ingresos.",
    "Can I withdraw money from my IRA before age 59½ without penalty?": "¿Puedo retirar dinero antes de los 59 años y medio sin penalización?",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax- and penalty-free, but withdrawing earnings early incurs taxes and a 10% penalty. With a Traditional IRA, withdrawing any funds early generally triggers both regular income tax and a 10% penalty, except for specific IRS-approved exemptions (e.g., qualifying first-time home purchase, higher education expenses, or disability).": "En cuentas Roth puedes retirar tus aportaciones iniciales en cualquier momento sin penalizaciones, pero retirar rendimientos antes de tiempo suele conllevar recargos fiscales.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It causes your wealth to grow exponentially over time.": "Es el interés calculado sobre el capital inicial más los intereses acumulados de periodos anteriores, provocando un crecimiento exponencial del patrimonio.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your annual interest rate (e.g. at 8%, your money doubles in about 9 years).": "Es una fórmula rápida para estimar en cuántos años se duplica su dinero: divida 72 entre la tasa de interés anual (al 8%, se duplica en unos 9 años).",
    "The more frequently interest compounds (annually, monthly, daily), the higher your effective annual yield (APY) will be, as interest starts earning interest sooner.": "A mayor frecuencia de capitalización (mensual, diaria), mayor rendimiento efectivo anual (APY) se obtiene, al reinvertirse los beneficios con mayor celeridad.",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest.": "Es el principio financiero que postula que un dólar hoy vale más que un dólar en el futuro por su capacidad intrínseca de generar rendimientos invertido.",
    "What are the core components of TVM calculations?": "¿Cuáles son las variables clave del modelo TVM?",
    "The five core variables are Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Total Number of Periods (Nper), and Periodic Payment (PMT).": "Las cinco magnitudes son: Valor Actual (PV), Valor Futuro (FV), Tasa de Interés (Rate), Número de Periodos (Nper) y Cuota Periódica (PMT).",
    "What is the difference between an ordinary annuity and annuity due?": "¿Cuál es la diferencia entre una renta ordinaria y una renta anticipada?",
    "In an ordinary annuity, payments occur at the end of each period. In an annuity due, payments occur at the beginning of each period, earning an extra compounding cycle of interest.": "En la ordinaria los pagos se realizan al final de cada periodo. En la anticipada se hacen al inicio, devengando un ciclo adicional de intereses compuestos.",
    "How is Return on Investment (ROI) calculated?": "¿Cómo se calcula el retorno sobre la inversión (ROI)?",
    "ROI is calculated by subtracting the initial cost of the investment from the final value, and dividing that net gain by the initial cost: ROI = (Net Profit / Cost of Investment) × 100%.": "Se calcula restando el coste inicial al valor final y dividiendo la ganancia neta entre el coste inicial: ROI = (Beneficio Neto / Coste de Inversión) × 100%.",
    "What is the difference between simple ROI and annualized ROI?": "¿Qué diferencia hay entre el ROI simple y el ROI anualizado?",
    "Simple ROI measures total percentage return regardless of duration. Annualized ROI (CAGR) standardizes the return into a per-year geometric rate, enabling fair comparison between investments held for different lengths of time.": "El ROI simple mide la rentabilidad porcentual global; el anualizado (CAGR) la estandariza a una tasa geométrica por año para poder comparar activos de distinta duración.",
    "What is considered a good ROI?": "¿Qué porcentaje se considera un buen ROI?",
    "Historically, the broad stock market (S&P 500) has returned an average of 7% to 10% annually before inflation. Investments with higher expected returns generally involve higher risk of capital loss.": "Históricamente, la renta variable diversificada (S&P 500) ha generado una media anual del 7% al 10% antes de inflación. Rendimientos mayores implican asumir mayor volatilidad y riesgo.",
    "How do I calculate how much to save monthly for a goal?": "¿Cómo calculo cuánto ahorrar mensualmente para una meta?",
    "You divide your target savings amount by the number of months until your deadline, while factoring in the compounding interest earned on your growing balance.": "Divida el capital objetivo entre los meses disponibles, descontando los intereses compuestos que irá generando el saldo acumulado.",
    "Should I keep savings goal funds in high-yield savings or stocks?": "¿Debo mantener mis ahorros para metas a corto plazo en cuentas remuneradas o en bolsa?",
    "For goals under 3 to 5 years (like a car or home down payment), keep funds in safe, liquid instruments like High-Yield Savings Accounts (HYSA) or CDs. For goals 5+ years away, a diversified investment portfolio may be suitable.": "Para metas a menos de 3 o 5 años (coche, entrada de vivienda), recurra a cuentas remuneradas o depósitos seguros. Para horizontes superiores a 5 años, una cartera de inversión es apropiada.",
    "How can I stay on track with my savings goals?": "¿Cómo ser constante y alcanzar los objetivos de ahorro?",
    "Automate recurring monthly transfers into a dedicated savings account immediately after your paycheck arrives (the 'pay yourself first' strategy).": "Automatice transferencias mensuales a una cuenta separada nada más cobrar la nómina (estrategia de 'pagarse a uno mismo primero').",
    "Total stock return equals capital gains (ending price minus purchase price) plus any dividends received, divided by the original purchase cost.": "El rendimiento total equivale a las plusvalías (precio final menos precio de compra) más los dividendos percibidos, dividido entre el coste inicial de compra.",
    "Compound Annual Growth Rate (CAGR) measures the geometric mean annual return of a stock over multiple years, smoothing out annual market fluctuations.": "La Tasa de Crecimiento Anual Compuesto (CAGR) mide el rendimiento geométrico medio por año suavizando la volatilidad entre ejercicios.",
    "What is the difference between simple return and annualized return?": "¿Qué diferencia existe entre el rendimiento simple y el anualizado?",
    "Simple return measures absolute percentage gain over the entire holding period, while annualized return shows the steady annual rate required to achieve that result.": "El rendimiento simple expresa el beneficio porcentual de todo el periodo, mientras que el anualizado indica el ritmo de crecimiento anual constante equivalente.",
    "CAPM calculates an asset's expected return based on its risk relative to the overall market, using the formula: Expected Return = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate).": "Calcula el rendimiento esperado de un activo según su riesgo sistemático: Rentabilidad Esperada = Tasa Libre de Riesgo + Beta × (Rentabilidad de Mercado - Tasa Libre de Riesgo).",
    "Beta measures an asset's volatility compared to the broader market. A beta of 1.0 indicates market-level volatility; above 1.0 indicates higher volatility, and below 1.0 indicates lower volatility.": "Mide la sensibilidad de un activo frente al mercado. Beta = 1 replica el mercado; Beta > 1 implica mayor volatilidad y riesgo; Beta < 1 menor volatilidad.",
    "What is the Risk-Free Rate?": "¿Qué es la tasa libre de riesgo?",
    "The risk-free rate is the theoretical rate of return of an investment with zero risk of default, typically represented by long-term government bond yields (like 10-year US Treasuries).": "Es el rendimiento de un activo con riesgo de impago nulo, habitualmente representado por la rentabilidad de los bonos soberanos a 10 años de máxima calificación.",
    "What is the Market Risk Premium?": "¿Qué es la prima de riesgo de mercado?",
    "The market risk premium is the additional return investors demand for choosing risky market equities over risk-free government securities.": "Es la rentabilidad adicional que exigen los inversores por asumir el riesgo de invertir en bolsa en lugar de activos libres de riesgo.",
    "What is dividend yield versus yield on cost?": "¿Qué diferencia hay entre el Dividend Yield y el Yield on Cost?",
    "Dividend yield is the annual dividend divided by the current stock price. Yield on cost is the annual dividend divided by your original purchase price, which increases as companies raise their dividends over time.": "El Dividend Yield divide el dividendo entre la cotización actual. El Yield on Cost lo divide entre el precio original de compra, creciendo conforme la empresa incrementa dividendos.",
    "What is a Dividend Reinvestment Plan (DRIP)?": "¿Qué es un plan de reinversión de dividendos (DRIP)?",
    "A DRIP automatically uses your cash dividend payments to purchase additional shares or fractional shares of the stock, compounding your share count and future payouts without commission fees.": "Es un mecanismo que utiliza automáticamente los dividendos cobrados para comprar más acciones o fracciones de la misma empresa, acelerando el interés compuesto.",
    "Are dividend payments guaranteed?": "¿Están garantizados los dividendos de las empresas?",
    "No, company boards can reduce, suspend, or eliminate dividend payouts at any time depending on company profitability and economic conditions.": "No, el consejo de administración puede recortar, suspender o cancelar los dividendos en función de los resultados del negocio y del ciclo económico.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a decline in the purchasing power of money.": "Es el aumento generalizado y sostenido en los precios de bienes y servicios, lo que disminuye progresivamente el poder adquisitivo del dinero.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation is 3%, $100 today will only buy about $97 worth of goods next year.": "El dinero en efectivo o en cuentas sin remuneración pierde valor. Con una inflación del 3%, 100 $ de hoy comprarán bienes equivalentes a 97 $ el próximo año.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks price changes across a standard market basket of consumer goods and services.": "Se mide principalmente mediante el Índice de Precios al Consumo (IPC), que monitoriza la cesta de la compra representativa de las familias.",
    "In the United States, inflation has historically averaged between 2.5% and 3.2% per year over long multi-decade horizons.": "Históricamente, en las economías desarrolladas la inflación media ha oscilado entre el 2,5% y el 3,2% anual a largo plazo.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities, Treasury Inflation-Protected Securities (TIPS), real estate, and inflation-indexed bonds.": "Invirtiendo en activos con rendimientos superiores a la inflación: renta variable global, bonos indexados a la inflación (TIPS) e inmuebles.",
    "What is FICA tax?": "¿Qué son los impuestos FICA / seguridad social?",
    "FICA is a federal payroll tax that funds Social Security (6.2% on wages up to the wage base limit) and Medicare (1.45% plus an additional 0.9% on high earners).": "Son cotizaciones de nómina destinadas a financiar la pensión de jubilación pública y la cobertura médica pública de salud.",
    "What is the difference between pre-tax and post-tax deductions?": "¿Qué diferencia hay entre deducciones antes y después de impuestos?",
    "Pre-tax deductions (like 401k and health insurance) reduce your taxable gross income before taxes are computed. Post-tax deductions (like Roth contributions or wage garnishments) are taken after taxes.": "Las deducciones antes de impuestos (planes de pensiones, seguro médico) minoran la base imponible; las posteriores se retienen tras liquidar el impuesto.",
    "What is the difference between gross pay and net pay?": "¿Cuál es la diferencia entre sueldo bruto y sueldo neto?",
    "Gross pay is the total amount earned before any taxes or deductions. Net pay (take-home pay) is the actual cash deposited into your bank account after all deductions.": "El sueldo bruto es la retribución total pactada; el sueldo neto es la cantidad líquida real que ingresa en su cuenta bancaria tras retenciones fiscales.",
    "How does my W-4 filing status affect my paycheck?": "¿Cómo influyen las retenciones en mi nómina?",
    "Your W-4 form informs your employer how much federal income tax to withhold each pay period based on your filing status, dependents, and other income.": "Determina qué porcentaje de IRPF retiene su empleador en cada paga según su estado civil, personas a cargo y tramo de ingresos.",
    "Why do state and local taxes vary so much?": "¿Por qué varían los impuestos regionales y locales?",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have progressive tax rates). Local taxes may also apply depending on the specific city or county you work or live in.": "Cada comunidad autónoma, estado o municipio fija sus propios tramos impositivos y deducciones, existiendo regiones con tipos notablemente más bajos o exenciones.",
    "Net worth is the total market value of everything you own (assets) minus everything you owe to creditors (liabilities).": "Es el valor de mercado de todos sus bienes y derechos (activos) menos el conjunto de sus deudas y obligaciones financieras (pasivos).",
    "How often should I calculate my net worth?": "¿Con qué frecuencia se debe calcular el patrimonio neto?",
    "Reviewing your net worth quarterly or semi-annually gives you a clear high-level view of your financial health without obsessing over daily market swings.": "Revisarlo de forma trimestral o semestral brinda una visión estratégica de su salud financiera sin verse afectado por el ruido diario de los mercados.",
    "What counts as an asset vs. a liability?": "¿Qué se considera un activo y qué un pasivo?",
    "Assets include bank balances, investment accounts, home equity, and retirement funds. Liabilities include mortgages, student loans, car loans, and credit card debt.": "Activos son cuentas corrientes, carteras de inversión, inmuebles y fondos de pensiones. Pasivos son hipotecas, préstamos personales y deudas en tarjetas.",
    "Should I include my house and mortgage in my net worth?": "¿Debo incluir mi vivienda habitual y la hipoteca en mi patrimonio neto?",
    "Yes, you include the current fair market value of the home under assets and the remaining mortgage balance under liabilities. The difference is your home equity.": "Sí, imputando el valor razonable actual de la vivienda como activo y la deuda hipotecaria pendiente como pasivo; la diferencia es su patrimonio neto inmobiliario.",
    "What does it mean to have a negative net worth?": "¿Qué significa tener un patrimonio neto negativo?",
    "A negative net worth means your total debts exceed your total assets. This is common for young adults and recent graduates with student loans.": "Significa que las deudas superan el valor total de los bienes. Es una situación habitual en graduados recientes o al inicio de la vida laboral.",
    "Most financial planners recommend saving 3 to 6 months of essential living expenses, or 9 to 12 months for freelancers or single-income households.": "Los asesores financieros recomiendan entre 3 y 6 meses de gastos fijos básicos, elevándose a 9 o 12 meses en profesionales autónomos o familias con un único sueldo.",
    "What expenses should be included in an emergency fund budget?": "¿Qué gastos deben incluirse al presupuestar el fondo de emergencia?",
    "Include only non-negotiable living costs: housing (rent/mortgage), utilities, groceries, basic transportation, minimum debt payments, and healthcare insurance.": "Únicamente costes imprescindibles de subsistencia: hipoteca/alquiler, suministros, alimentación básica, seguros y cuotas mínimas de deuda.",
    "Where should I keep my emergency fund?": "¿Dónde se debe depositar el fondo de emergencia?",
    "In a dedicated High-Yield Savings Account (HYSA) or money market account where it is FDIC-insured, earns interest, and can be accessed immediately without risk.": "En cuentas remuneradas seguras o fondos monetarios con total liquidez, garantizados y sin riesgo de pérdida de capital.",
    "Should I pay off debt or build an emergency fund first?": "¿Es mejor liquidar deudas o crear el fondo de emergencia primero?",
    "Build a starter emergency fund of 1 month of expenses or $1,000 to $2,000 first, then aggressively pay off high-interest consumer debt before expanding to 3-6 months.": "Cree primero un fondo inicial de emergencia de 1 mes de gastos (o 1.000-2.000 $), amortice luego las deudas de alto interés y finalmente amplíe el fondo a 3-6 meses.",
    "When is it appropriate to use emergency fund savings?": "¿Cuándo está justificado recurrir al fondo de emergencia?",
    "Use it only for genuine, unexpected emergencies: sudden medical bills, unexpected car repairs, or living expenses following job loss.": "Únicamente ante emergencias imprevistas y sobrevenidas: gastos médicos urgentes, reparaciones indispensables del vehículo o desempleo.",
    "An expense ratio is the annual percentage fee charged by mutual funds and ETFs to cover fund management, administrative expenses, and operating costs.": "Es el porcentaje anual que deducen los fondos de inversión y ETFs para sufragar su gestión, custodia y costes operativos.",
    "How do fees compound over time?": "¿Cómo se multiplican las comisiones en el tiempo?",
    "Fees are deducted annually from your total assets, meaning you lose both the fee money and all future compounding returns that money would have earned.": "Las comisiones se descuentan anualmente del capital total, provocando que se pierda tanto el dinero de la comisión como el interés compuesto que habría generado en décadas.",
    "What is a good expense ratio for an index fund?": "¿Cuál es un buen ratio de gastos en un fondo indexado?",
    "Low-cost index funds and ETFs typically have expense ratios between 0.02% and 0.10%, whereas actively managed mutual funds often charge 0.60% to 1.50% or more.": "Los fondos indexados y ETFs competitivos cobran entre el 0,02% y el 0,10%, mientras que los fondos tradicionales de gestión activa suelen aplicar entre el 0,60% y el 1,50% o más.",
    "What other investment fees should I look out for?": "¿De qué otras comisiones de inversión debo cuidarme?",
    "Watch out for advisory fees (AUM fees of 1%), front-end or back-end sales loads, trading commissions, account maintenance fees, and custodial charges.": "Comisiones por asesoramiento (1% sobre patrimonio), comisiones de suscripción o reembolso, corretaje por compraventa y mantenimiento de cuenta.",
    "How much can a 1% fee difference affect my retirement savings?": "¿Cuánto merman mis ahorros para la jubilación una comisión del 1%?",
    "A 1% annual fee difference can erode 25% to 30% of your total ending portfolio wealth over a 30-year investment horizon.": "Una diferencia del 1% en comisiones anuales puede llegar a devorar entre un 25% y un 30% del patrimonio acumulado final tras 30 años de inversión.",
    "What is a 529 plan?": "¿Qué es un plan de ahorro universitario 529?",
    "A 529 plan is a tax-advantaged savings and investment plan designed to encourage saving for future higher education expenses with tax-free growth and qualified withdrawals.": "Es un plan de ahorro con beneficios fiscales diseñado para financiar la educación superior con plusvalías y retiradas exentas de tributación.",
    "How fast do college costs increase?": "¿A qué ritmo se encarecen los costes de la universidad?",
    "Historically, higher education tuition and fees have increased at an annual rate of 4% to 6%, outpacing general consumer inflation.": "Históricamente, las matrículas y gastos universitarios han crecido a un ritmo del 4% al 6% anual, superando a la inflación general.",
    "What happens to 529 funds if my child does not go to college?": "¿Qué ocurre con los fondos si mi hijo decide no ir a la universidad?",
    "You can change the beneficiary to another qualifying family member, use up to $10,000 for student loan repayment, or roll over up to $35,000 into a Roth IRA under SECURE 2.0 rules.": "Puede transferir el beneficiario a otro familiar, amortizar hasta 10.000 $ en préstamos de estudios o traspasar hasta 35.000 $ a una cuenta Roth IRA.",
    "Can I use a 529 plan for trade schools or K-12 tuition?": "¿Sirve el plan para escuelas de oficios o colegios privados?",
    "Yes, qualified distributions can cover accredited trade schools, vocational programs, apprenticeships, and up to $10,000 per year for K-12 private school tuition.": "Sí, cubre escuelas de formación profesional y hasta 10.000 $ al año en matrícula de educación primaria o secundaria.",
    "How does a 529 plan impact financial aid eligibility?": "¿Cómo afecta el plan 529 a las becas y ayudas estudiantiles?",
    "Parent-owned 529 plans are assessed as parental assets on the FAFSA at a maximum rate of 5.64%, having minimal negative impact on financial aid eligibility.": "Si está a nombre de los padres, solo computa hasta un máximo del 5,64% como patrimonio, teniendo un impacto mínimo sobre la concesión de becas.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price.": "Es una estrategia en la que se invierte una suma fija de dinero de forma periódica con independencia de la cotización puntual del activo.",
    "How does DCA apply to high-volatility assets like Crypto?": "¿Cómo ayuda el DCA en activos muy volátiles como las criptomonedas?",
    "DCA prevents emotional decisions during extreme market peaks and crashes, automatically buying more units when prices are low and fewer when prices are high.": "Evita decisiones emocionales durante euforias o caídas de mercado, comprando más unidades a precios bajos y menos cuando suben.",
    "Is DCA better than investing a lump sum?": "¿Es mejor el DCA o invertir todo el capital de golpe (Lump Sum)?",
    "Lump sum investing historically wins in steadily rising markets, but DCA provides superior peace of mind, lower emotional risk, and downside protection in highly volatile markets.": "Invertir de golpe suele ganar en mercados alcistas constantes, pero el DCA ofrece mayor tranquilidad mental y protección en activos con fuerte volatilidad.",
    "What is the best frequency for crypto DCA?": "¿Cuál es la frecuencia ideal para hacer DCA?",
    "Weekly or bi-weekly DCA aligned with your pay cycle is ideal for capturing market volatility while keeping trading fees manageable.": "Efectuar compras semanales o quincenales sincronizadas con la nómina permite aprovechar la volatilidad conteniendo las comisiones.",
    "Does DCA guarantee profits in cryptocurrency?": "¿Garantiza el DCA ganancias en criptoactivos?",
    "No, DCA does not protect against prolonged declines or failing crypto projects; it only ensures you achieve the weighted average market purchase price.": "No, no protege contra proyectos fallidos o tendencias bajistas prolongadas; únicamente asegura obtener el precio medio ponderado del mercado.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, but some lenders include a prepayment penalty clause. Always verify your loan agreement terms before making accelerated principal payments.": "Muchos préstamos permiten amortizaciones anticipadas gratuitas, pero algunos contratos bancarios incluyen comisiones por cancelación total o parcial. Revise siempre su contrato.",
    "What is the difference between interest rate and APR?": "¿Qué diferencia hay entre el tipo de interés y la TAE / APR?",
    "The interest rate is the nominal cost of borrowing the principal balance. The Annual Percentage Rate (APR) reflects the total annual cost of the loan including points, broker fees, and origination charges.": "El tipo de interés es el coste nominal del capital prestado. La Tasa Anual Equivalente (TAE / APR) refleja el coste real anual integrando comisiones bancarias y gastos de apertura.",
    "Why is APR higher than the advertised interest rate?": "¿Por qué la TAE suele ser mayor que el tipo de interés nominal anunciado?",
    "APR is higher because it amortizes all upfront lender fees, discount points, and closing costs into the effective yearly rate, revealing the true cost of credit.": "Es mayor porque prorratea todos los gastos iniciales, comisiones y costes de formalización en una tasa porcentual anual efectiva.",
    "Is APR useful for comparing different loan offers?": "¿Es útil la TAE para comparar distintas ofertas de préstamo?",
    "Yes, APR is the best metric for comparing loan offers with different fee structures, provided you plan to keep the loan for its full term.": "Sí, la TAE / APR es el mejor indicador para comparar ofertas financieras con distintas comisiones, siempre que mantenga el préstamo durante el plazo acordado.",
    "How long do I need to stay in a home for buying to beat renting?": "¿Cuánto tiempo debo vivir en una casa para que comprar sea mejor que alquilar?",
    "Because upfront closing costs, moving fees, and commissions are substantial, homeowners usually need to stay in a property for 4 to 7 years for buying to financially outperform renting.": "Dado que los gastos de escrituración e impuestos iniciales son elevados, suele requerirse habitar la vivienda entre 4 y 7 años para que comprar supere al alquiler.",
    "What hidden costs of homeownership should renters consider?": "¿Qué gastos ocultos de tener vivienda propia debe considerar un inquilino?",
    "Homeowners must pay property taxes, homeowners insurance, maintenance and repairs (typically 1-2% of home value annually), HOA dues, and potential capital improvement costs.": "Se deben asumir impuestos sobre bienes inmuebles, seguros, mantenimiento (un 1-2% del valor anual), cuotas de comunidad y derramas extraordinarias.",
    "What is the opportunity cost of buying a home?": "¿Cuál es el coste de oportunidad al comprar una vivienda?",
    "The money spent on down payment, closing costs, and ongoing property maintenance could otherwise remain invested in liquid assets like index funds that compound over time.": "El capital desembolsado en la entrada y gastos iniciales deja de estar invertido en activos líquidos como fondos indexados, que generan interés compuesto.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline).": "Los expertos recomiendan no sobrepasar el 25% o 28% de los ingresos brutos mensuales en gastos de vivienda (cuota hipotecaria, impuestos y seguro).",
    "How does down payment size impact affordability?": "¿Cómo repercute el importe de la entrada en la capacidad de compra?",
    "A larger down payment reduces your loan amount, eliminates Private Mortgage Insurance (PMI) if you put down 20%, and lowers your monthly mortgage payment.": "Una mayor entrada reduce el importe a financiar, elimina el seguro hipotecario privado (con el 20% o más) y abarata la cuota mensual.",
    "How do interest rates affect purchasing power?": "¿Cómo afectan los tipos de interés a mi poder adquisitivo inmobiliario?",
    "Every 1% increase in mortgage interest rates reduces your home purchasing power by roughly 10% for the same monthly payment budget.": "Cada incremento del 1% en el tipo de interés hipotecario reduce su capacidad de compra en torno a un 10% para la misma mensualidad.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total vehicle expenses under 10% of gross monthly income.": "Aconseja dar al menos el 20% de entrada, financiar a un máximo de 4 años (48 meses) y que los gastos del vehículo no superen el 10% de sus ingresos brutos.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk becoming 'underwater' (owing more than the vehicle is worth).": "Plazos largos bajan la cuota mensual, pero multiplican los intereses totales y provocan que el valor residual del coche sea inferior a la deuda restante.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, you risk owing more on your loan than the car's market value.": "Los vehículos nuevos pierden en torno a un 20% de su valor el primer año; sin una buena entrada inicial, la deuda puede superar el valor real de mercado del coche.",
    "Why does paying only the minimum take so long?": "¿Por qué pagar solo el mínimo retrasa tanto la liquidación de la tarjeta?",
    "Credit card minimum payments are often set around 1% to 2% of the balance plus accrued interest. As the balance slowly drops, the required minimum drops, extending payoff times to decades.": "Los pagos mínimos cubren apenas los intereses devengados y un 1% o 2% del saldo, prolongando la deuda durante décadas.",
    "How much faster can I pay off credit cards by paying extra?": "¿Cuánto acelero la amortización aportando pagos extraordinarios?",
    "Paying even $50 or $100 above the minimum payment can cut your payoff timeline by several years and save thousands of dollars in compounding interest charges.": "Añadir 50 $ o 100 $ adicionales sobre el mínimo recorta años de endeudamiento y ahorra miles de dólares en intereses acumulados.",
    "Should I use a balance transfer card to pay off debt?": "¿Conviene usar una tarjeta con transferencia de saldo al 0% TAE?",
    "A 0% APR balance transfer credit card can save significant interest if you pay off the full balance during the promotional period (typically 12-21 months) and factor in the 3%-5% transfer fee.": "Puede ser muy ventajosa para ahorrar intereses si cancela la totalidad dentro del periodo promocional sin intereses (12-21 meses), asumiendo la comisión de transferencia (3%-5%).",
    "What is the 4% rule in retirement planning?": "¿Qué es la regla del 4% en la jubilación?",
    "The 4% rule suggests that withdrawing 4% of your retirement portfolio in the first year, adjusted for inflation annually thereafter, provides a high probability that your nest egg will last at least 30 years.": "Establece que retirar un 4% del patrimonio el primer año, ajustándolo anualmente por inflación, ofrece una altísima probabilidad de que los fondos duren al menos 30 años.",
    "How much money do I need to retire comfortably?": "¿Cuánto dinero necesito para jubilarme con tranquilidad?",
    "A common benchmark is accumulating 25 times your anticipated annual retirement expenses, or replacing 70% to 80% of your pre-retirement income.": "La referencia más extendida es acumular 25 veces sus gastos anuales previstos de jubilación, o asegurar entre un 70% y un 80% de sus ingresos previos.",
    "How does inflation impact retirement spending?": "¿Cómo afecta la inflación a los gastos en la jubilación?",
    "Inflation steadily reduces the purchasing power of your savings. At a 3% inflation rate, everyday living expenses double roughly every 24 years, requiring growing investment portfolios.": "La inflación deteriora el poder adquisitivo; con una tasa del 3%, el coste de la vida se duplica cada 24 años, lo que exige invertir en activos de crecimiento.",
    "What is an employer 401(k) match?": "¿Qué es la aportación complementaria de la empresa (Match)?",
    "An employer match is money your employer contributes to your 401(k) account based on your own contributions (e.g. matching 50% of contributions up to 6% of your salary). It is effectively an instant return on your savings.": "Es una contribución que el empleador abona a su plan en función de sus propias aportaciones (ej. 50% hasta el 6% del salario). Supone una rentabilidad directa e inmediata.",
    "What are the 401(k) contribution limits for 2024?": "¿Cuáles son los límites de aportación para 2024?",
    "For 2024, the employee contribution limit is $23,000 for those under 50. Individuals aged 50 and older can contribute an additional $7,500 catch-up contribution for a total of $30,500.": "El límite legal de aportación para menores de 50 años es de 23.000 $. A partir de 50 años se permite una aportación adicional de 7.500 $ (total 30.500 $).",
    "What is the difference between Traditional 401(k) and Roth 401(k)?": "¿Cuál es la diferencia entre un plan Tradicional y uno Roth?",
    "Traditional 401(k) contributions are pre-tax and reduce your current taxable income, with withdrawals taxed in retirement. Roth 401(k) contributions are post-tax, but all qualified growth and withdrawals are completely tax-free.": "El plan Tradicional reduce los impuestos hoy y tributa al rescatarlo en la jubilación. El Roth se aporta con dinero neto, pero sus plusvalías y retiradas futuras son 100% libres de impuestos.",
    "What is the standard tipping percentage?": "¿Cuál es el porcentaje habitual de propina?",
    "In the United States and Canada, standard restaurant tipping guidelines range from 15% for adequate service, 18% for good service, to 20% or more for exceptional service.": "En países donde es costumbre, las pautas oscilan entre el 15% por servicio correcto, el 18% por buen servicio y el 20% o más por un trato excelente.",
    "Should tips be calculated before or after sales tax?": "¿Debe calcularse la propina antes o después de impuestos?",
    "Etiquette traditionally dictates calculating the tip percentage on the pre-tax food and beverage subtotal, though many automated payment terminals calculate tip on the post-tax total.": "Tradicionalmente se calcula sobre el subtotal de comida y bebida antes de impuestos, aunque muchos datáfonos la calculan sobre el total final.",
    "How do you split a bill evenly among friends?": "¿Cómo dividir la cuenta a partes iguales entre amigos?",
    "Calculate the total bill including food, beverages, tax, and tip, and divide the total amount equally by the number of paying participants.": "Sume el importe íntegro de consumiciones, impuestos y propina, y divida la cifra resultante entre el número total de comensales.",
    "How do you calculate a percentage discount?": "¿Cómo se calcula un descuento porcentual?",
    "Multiply the original price by the discount percentage divided by 100 to find the savings, and subtract that amount from the original price: Final Price = Original Price × (1 - Discount%).": "Multiplique el precio original por el porcentaje de rebaja dividido entre 100 y reste el resultado al precio original: Precio Final = Precio Original × (1 - Descuento%).",
    "How do multiple stacked discounts work?": "¿Cómo funcionan los descuentos acumulables?",
    "Stacked discounts apply sequentially rather than additively. For example, 20% off plus an extra 10% off results in an effective 28% total discount, not 30%.": "Se aplican de forma sucesiva y no sumatoria. Por ejemplo, un 20% de descuento más un 10% extra equivale a una rebaja real del 28%, no del 30%.",
    "Is sales tax applied before or after store discounts?": "¿Se aplica el impuesto antes o después de la rebaja?",
    "In most jurisdictions, sales tax is calculated on the discounted post-sale price, meaning you pay sales tax only on the actual money spent.": "En la mayoría de normativas, los impuestos sobre ventas o IVA se calculan sobre el precio ya rebajado, pagando impuestos solo por lo realmente desembolsado.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility.": "Una hipoteca a 15 años ofrece un tipo de interés más bajo y amortiza el inmueble el doble de rápido, ahorrando decenas de miles en intereses. Sin embargo, a 30 años la mensualidad es menor, ofreciendo mayor liquidez mes a mes.",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule.": "Todo pago adicional amortiza directamente el capital principal. Esto reduce el saldo pendiente y los intereses futuros, permitiendo liquidar la hipoteca años antes y ahorrando gran cantidad de dinero.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum helps people stick to their plan.": "Matemáticamente la Avalancha es superior al ahorrar más intereses. No obstante, en la práctica la Bola de Nieve suele tener mayor éxito porque el refuerzo anímico ayuda a mantener el compromiso.",
    "You continue paying minimums on all debts and add your extra cash to the target debt. Once that target debt is fully paid off, you roll its entire payment into the next debt on your list.": "Pagas las cuotas mínimas en todas las deudas y concentras el excedente en la deuda prioritaria. Al liquidarla, transfieres todo ese dinero a la siguiente deuda de la lista.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate (Avalanche).": "Sí. Muchas personas amortizan primero una o dos deudas pequeñas para liberar flujo de caja (Bola de Nieve), y luego atacan las restantes por mayor tipo de interés (Avalancha).",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term, provided your total interest savings exceed the closing costs.": "Conviene refinanciar si consigues una tasa de interés menor, reduces la cuota mensual o acortas el plazo, siempre que el ahorro total en intereses supere los gastos de cierre.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees, ranging from 2% to 6% of the loan amount.": "Suelen incluir comisiones de apertura, tasación, gastos de notaría y registro, oscilando habitualmente entre el 2% y el 6% del importe del préstamo.",
    "Divide your total refinance closing costs by your monthly payment savings. If closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150).": "Divide los costes totales de cierre entre el ahorro mensual obtenido. Si los gastos son 3.000 $ y ahorras 150 $ al mes, tu punto de equilibrio es de 20 meses.",
    "A no-closing-cost refinance means the lender either rolls the closing fees into your new total loan balance or charges a slightly higher interest rate to cover them.": "Significa que la entidad financiera suma dichos gastos al capital financiado o aplica un tipo de interés ligeramente mayor para compensarlos.",
    "It depends on the term. Refinancing to a lower rate with the same or shorter term saves on both. Resetting your term back to 30 years lowers the monthly payment but can increase total lifetime interest.": "Depende del plazo. Si refinancias a un tipo menor manteniendo o acortando el plazo, ahorras en ambos. Si alargas el plazo a 30 años, la cuota baja pero el interés total puede aumentar.",
    "The Saving on a Valuable Education (SAVE) plan is an income-driven repayment (IDR) plan that protects discretionary income up to 225% of the poverty line, lowers payments to 5%-10%, and stops unpaid interest from accumulating.": "Es un plan de pago basado en ingresos (IDR) que protege el 225% del umbral de pobreza, reduce las cuotas al 5%-10% del ingreso disponible y frena la acumulación de intereses no pagados.",
    "If you pay under an IDR plan for 20 or 25 years (or 10 years under SAVE for low initial balances), any remaining student debt is forgiven.": "Si abonas tus cuotas bajo un plan IDR durante 20 o 25 años (o 10 años en SAVE para importes iniciales bajos), el saldo restante queda condonado por completo.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. Borrowers with very high incomes relative to debt may prefer PAYE or IBR due to payment caps.": "Para la mayoría, el plan SAVE brinda la cuota más reducida y el mejor subsidio de intereses. Quienes perciben ingresos muy altos pueden preferir PAYE o IBR por tener topes de pago.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause unpaid interest to capitalize.": "Sí, puede solicitar el cambio de forma gratuita en studentaid.gov. No obstante, cambiar de plan a veces puede provocar que los intereses pendientes se capitalicen.",
    "The 28/36 rule is a standard mortgage underwriting guideline stating that housing costs should not exceed 28% of gross monthly income, and total debt payments should not exceed 36%.": "Es una guía bancaria que estipula que los gastos de vivienda no deben exceder el 28% de los ingresos brutos mensuales, y el pago total de deudas no debe sobrepasar el 36%.",
    "Lenders use DTI to measure your ability to manage monthly payments. Lower DTIs below 36% receive the most favorable mortgage terms and lowest interest rates.": "Las entidades utilizan el ratio deuda-ingreso para valorar el riesgo. Un DTI inferior al 36% obtiene las mejores condiciones y tipos de interés más competitivos.",
    "Front-end DTI only includes housing expenses (mortgage, property tax, insurance, HOA). Back-end DTI includes housing plus all recurring debts like credit cards, auto loans, and student loans.": "El DTI inicial contempla únicamente la vivienda (hipoteca, impuestos, seguros, comunidad). El DTI total añade todos los créditos recurrentes como tarjetas, coche y estudios.",
    "Conventional mortgages typically prefer back-end DTIs of 36% to 43%. Government-backed loans like FHA and VA may allow DTIs up to 50% with strong compensating factors.": "En hipotecas estándar se suele exigir un DTI total de hasta el 36% o 43%. Con buen perfil de solvencia y ahorros, ciertos programas permiten hasta el 50%.",
    "You can lower your DTI by increasing gross income or paying off smaller debts completely to eliminate their recurring monthly minimum payments.": "Puede rebajarlo incrementando sus ingresos brutos o amortizando préstamos pequeños para eliminar cuotas mensuales del cómputo.",
    "If you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower, a Traditional IRA is better.": "Si espera tributar a un tipo superior en su jubilación, elija Roth. Si prevé estar en un tramo impositivo más bajo al jubilarse, elija la Tradicional.",
    "For 2024, the annual contribution limit for Traditional and Roth IRAs is $7,000 for individuals under age 50, and $8,000 for individuals age 50 or older.": "El límite anual es de 7.000 $ para menores de 50 años y de 8.000 $ para personas de 50 años o más.",
    "Roth IRAs have income phase-out ranges that restrict high earners. Anyone with earned income can contribute to a Traditional IRA, but tax deductibility may be limited by income and workplace retirement coverage.": "Las cuentas Roth tienen topes de ingresos que restringen a rentas altas. A la Tradicional puede aportar cualquiera, aunque la deducibilidad fiscal depende de los ingresos.",
    "Roth IRA original contributions can be withdrawn at any time penalty-free. Withdrawing investment earnings early or withdrawing Traditional IRA funds before 59½ usually incurs income taxes and a 10% penalty.": "En la Roth puede retirar sus aportaciones originales en cualquier momento sin recargo. Retirar rendimientos antes de los 59 años y medio suele acarrear impuestos y un 10% de penalización.",
    "State income tax rates range from 0% (in states like Texas, Florida, and Washington) to over 13% in high-tax states, while some cities also impose local municipal income taxes.": "Cada región o autonomía aplica sus propios tramos impositivos sobre la renta, existiendo zonas con gravámenes muy reducidos y otras con tipos superiores.",
  },
  de: {
    "The 5% rule estimates that homeownership costs roughly 5% of a property's value annually in unrecoverable expenses (1% property tax, 1% maintenance, and 3% cost of capital). Divide by 12 to find your break-even monthly rent. If you can rent an equivalent home for less, renting plus investing the savings builds greater wealth. For detailed math and worked case studies, read our complete guide: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">How to Decide: Rent vs. Buy Your Home</a>.": "Die 5%-Regel beziffert die unwiederbringlichen jährlichen Kosten des Immobilieneigentums auf ca. 5 % des Immobilienwerts (1 % Grundsteuer, 1 % Instandhaltung und 3 % Kapitalkosten). Geteilt durch 12 ergibt sich die monatliche Kaltmiete zur Gewinnschwelle: Können Sie ein vergleichbares Objekt günstiger mieten und die Ersparnis anlegen, baut Mieten mehr Vermögen auf. Detaillierte Beispielrechnungen finden Sie in unserem Leitfaden: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">Entscheidungshilfe: Mieten oder Kaufen</a>.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline). For a deep dive into bank underwriting formulas, salary matrices, and the 28/36 rule, read our complete guide: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">How Much House Can I Afford?</a>.": "Die meisten Banken und Finanzexperten empfehlen, maximal 25 % bis 28 % des monatlichen Bruttoeinkommens für Wohnkosten aufzuwenden (Front-End-DTI). Detaillierte Beleihungsformeln, Gehaltstabellen und die 28/36-Regel finden Sie in unserem Leitfaden: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">Wie viel Haus kann ich mir leisten?</a>.",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to solve for any of the five core TVM variables: Present Value (PV), Future Value (FV), Periodic Payment (PMT), Annual Interest Rate (I/Y), and Number of Compounding Periods (N).": "Dieser TVM-Finanzrechner verwendet Standardformeln für Zinseszins und abgezinste Cashflows, um jede der fünf TVM-Kernvariablen zu berechnen: Barwert (PV), Endwert (FV), periodische Zahlung (PMT), jährlicher Zinssatz (I/Y) und Anzahl der Zinsperioden (N).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), planned recurring periodic deposits (PMT), interest rate, and duration. The calculator computes the total compounded ending balance instantly.": "Wählen Sie 'Endwert (FV)' als Zielgröße. Tragen Sie Ihr Startguthaben (PV), die geplante Monatsrate (PMT), den Zinssatz und die Laufzeit ein. Der Rechner ermittelt den endgültigen Zinseszinsbetrag sofort.",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (common in lease and insurance contracts), earning an extra compounding cycle of interest.": "Bei einer nachschüssigen Rente (Standard bei Krediten und Baufinanzierungen) erfolgen Zahlungen am Periodenende. Bei einer vorschüssigen Rente (üblich bei Leasing und Miete) wird zu Periodenbeginn gezahlt, was eine zusätzliche Zinsperiode einbringt.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price. For a full breakdown of the math, comparisons with lump-sum investing, and crypto fee traps, read our complete guide: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">What Does DCA Mean in Crypto?</a>.": "Der Durchschnittskosteneffekt (Dollar-Cost Averaging / DCA) beschreibt eine Anlagestrategie, bei der unabhängig von kurzfristigen Kursschwankungen regelmäßig feste Beträge investiert werden. Detaillierte Berechnungen, Vergleiche mit Einmalanlagen und Krypto-Gebührenfallen finden Sie in unserem Leitfaden: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">Was bedeutet DCA bei Krypto?</a>.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an \"in-service distribution\" (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Sie können laufende Sparbeiträge über die Personalabteilung jederzeit kostenfrei stoppen und auf 0 % setzen. Ein vorzeitiges Auscashen des bereits bestehenden Kapitals ist während des Arbeitsverhältnisses meist ausgeschlossen oder löst empfindliche steuerliche Nachteile aus. Ausführliche Details finden Sie in unserem Leitfaden: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Altersvorsorge kündigen und während der Beschäftigung auszahlen lassen?</a>.",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Number of Periods (Nper), and Periodic Payment (PMT). By inputting any four variables, our solver computes the fifth unknown mathematically using standard financial algebra formulas.": "Der TVM-Rechner verbindet fünf fundamentale Variablen: Barwert (PV), Endwert (FV), Zinssatz pro Periode (Rate), Periodenanzahl (Nper) und periodische Rate (PMT). Sobald Sie vier Variablen eingeben, löst das Rechenwerk die fünfte Unbekannte mathematisch exakt.",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and total periods (years or months), specify any periodic recurring payment (PMT), and leave Future Value empty. The calculator instantly compounds your principal and contributions to reveal the ending balance.": "Um den Endwert zu berechnen, tragen Sie Ihr Startkapital als Barwert (PV) ein, bestimmen Zinssatz und Laufzeit und ergänzen bei Bedarf monatliche Sparraten (PMT). Der Rechner verzinst Kapital und Sparraten und weist das Gesamtrenditeergebnis detailliert aus.",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and personal loans). In an annuity due, payments occur at the beginning of each period (common in lease payments and rent), allowing each cash flow to earn an extra period of compounding interest.": "Bei einer nachschüssigen Rente erfolgen Zahlungen am Periodenende (Standard bei Hypotheken und Ratenkrediten). Bei einer vorschüssigen Rente wird zu Periodenbeginn gezahlt (typisch bei Leasing). Durch die frühere Wertstellung generiert jede Rate einen zusätzlichen Zinszyklus, was zu einem höheren Endwert führt.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested into equal periodic purchases (e.g. $50 every week) regardless of asset price, smoothing out market volatility over time.": "Der Cost-Average-Effekt entsteht, wenn eine Gesamtanlagesumme über regelmäßige Intervalle gestreckt investiert wird (z. B. im Monatssparplan). Dadurch kaufen Sie bei niedrigen Kursen automatisch mehr Anteile und bei hohen Kursen weniger, was den mittleren Einstiegskurs glättet.",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement living expenses minus Social Security. If you need $60,000 per year from your portfolio, your target retirement nest egg is $1,500,000 ($60,000 × 25). This nest egg provides sustainable inflation-adjusted income throughout a 30-year retirement.": "Nach der 25er-Regel (Kehrwert der 4%-Entnahmerate) benötigen Sie etwa das 25- bis 30-fache Ihrer jährlichen Netto-Versorgungslücke im Ruhestand. Bei einem jährlichen Zusatzbedarf von 30.000 € aus dem Portfolio entspricht dies einem Zielkapital von ca. 750.000 € bis 900.000 €.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $500,000 401(k) generates ~$1,667/month ($20,000/year); a $1,000,000 401(k) generates ~$3,333/month ($40,000/year); and a $1,500,000 401(k) generates ~$5,000/month ($60,000/year). Combined with Social Security, this replaces 70% to 90% of pre-retirement income.": "Basierend auf der 4%-Entnahmerate errechnet sich die monatliche Rente wie folgt: (Endkapital × 0,04) ÷ 12. Ein Portfolio von 1.000.000 € erbringt somit rund 3.333 € monatlich vor Steuern, jährlich an die Inflation angepasst.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\\\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\\\" class=\\\"text-primary underline font-medium\\\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Wenn Sie die 4%-Regel mit einem ausgewogenen Portfolio (z. B. 60 % Aktien / 40 % Anleihen) anwenden, zeigt die Trinity-Studie eine 95%+ Wahrscheinlichkeit, dass Ihr Erspartes mindestens 30 Jahre reicht. Höhere Entnahmeraten (z. B. 6 % oder 7 %) erhöhen das Risiko einer vorzeitigen Erschöpfung in Baisse-Phasen deutlich.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty PLUS ordinary federal and state income taxes on the distributed amount. For someone in the 22% federal bracket and 5% state bracket, an early withdrawal of $20,000 forfeits $7,400 (37%) to penalties and taxes, leaving only $12,600. Key exceptions to the penalty include the Rule of 55 (leaving an employer at age 55 or older), qualifying hardship distributions, or Substantially Equal Periodic Payments (SEPP / Rule 72t).": "Eine vorzeitige Entnahme aus geförderten Altersvorsorgeverträgen vor dem 60. bzw. 62. Lebensjahr löst die Rückforderung staatlicher Förderungen und eine volle Nachversteuerung zum persönlichen Spitzensteuersatz aus. Bei einer Entnahme von 20.000 € können Steuern und Abzüge schnell über 30 % bis 40 % der Summe aufzehren.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals, freelancers, and small business owners with no full-time W-2 employees (other than a spouse). It allows dual contributions: up to $23,000 in elective employee deferrals ($30,500 if age 50+) PLUS an employer profit-sharing contribution up to 25% of net adjusted business earnings (20% for sole proprietors), up to a combined maximum of $69,000 in 2024.": "Vorsorgepläne für Selbstständige und Freiberufler (wie die Basisrente / Rürup-Rente) ermöglichen es Alleininhabern, hohe jährliche Beträge steuerlich voll als Sonderausgaben abzusetzen und ein pfändungssicheres Altersvorsorgekapital am Kapitalmarkt aufzubauen.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000, whichever is less. A 401(k) loan avoids income tax and the 10% IRS penalty because you repay principal and interest back into your own account (usually over 5 years). However, if you leave your employer before repaying, the remaining balance usually becomes due by the federal tax filing deadline, or it converts into a taxable early distribution.": "Einige betriebliche Versorgungswerke lassen Darlehen auf angesparte Anwartschaften zu. Verlassen Sie jedoch das Unternehmen, wird die Restschuld häufig sofort fällig oder in eine steuerpflichtige Entnahme umgewandelt. Für kurzfristige Notlagen ist ein Tagesgeldpuffer stets vorzuziehen.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) with one click. A Traditional 401k calculator mode shows your immediate federal and state tax savings today, while retirement withdrawals are taxed as ordinary income. A Roth 401k calculator mode models post-tax contributions that generate 100% tax-free growth and 100% tax-free withdrawals in retirement.": "Mit unserem Rechner vergleichen Sie steuerbegünstigte Einzahlungen heute (nachgelagerte Besteuerung) mit steuerfreien Auszahlungen im Alter. Spitzenverdiener profitieren meist von sofortigen Abzügen; bei niedrigen aktuellen Steuersätzen lohnt sich die steuerfreie Auszahlung.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\\\"/blog/can-i-cancel-401k-cash-out-while-employed/\\\" class=\\\"text-primary underline font-medium\\\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Sie können laufende Sparbeiträge über die Personalabteilung jederzeit kostenfrei stoppen und auf 0 % setzen. Ein vorzeitiges Auscashen des bereits bestehenden Kapitals ist während des Arbeitsverhältnisses meist ausgeschlossen oder löst empfindliche steuerliche Nachteile aus. Details finden Sie in unserem Leitfaden: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Altersvorsorge kündigen und während der Beschäftigung auszahlen lassen?</a>.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong performance or merit raises average 4% to 7%, and promotions or job changes typically command a 10% to 20%+ increase in base compensation.": "Ein gewöhnlicher Inflationsausgleich beträgt 2 % bis 4 %, eine fundierte Leistungsanpassung liegt bei 5 % bis 8 %, während Beförderungen oder Arbeitgeberwechsel meist 10 % bis 20 % Gehaltsplus einbringen. Jede Erhöhung oberhalb der Inflation steigert Ihre reale Kaufkraft.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: Raise % = ((New Salary - Old Salary) / Old Salary) × 100%.": "Subtrahieren Sie Ihr bisheriges Gehalt vom neuen Gehalt, teilen Sie die Differenz durch das bisherige Gehalt und multiplizieren Sie mit 100: ((Neues Gehalt - Altes Gehalt) ÷ Altes Gehalt) × 100. Eine Erhöhung von 50.000 € auf 55.000 € entspricht genau 10 % Gehaltserhöhung.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Ausgehend von einer 40-Stunden-Woche und 52 Wochen (2.080 Jahresarbeitsstunden) multiplizieren Sie die Stundenlohnerhöhung mit 2.080. Eine Erhöhung um 2,50 €/h ergibt somit 5.200 € mehr Brutto-Jahresgehalt.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above each tax bracket threshold are taxed at the higher marginal rate; income below the threshold remains taxed at the lower previous rates. A pay raise will always increase your net take-home pay.": "Nein. Moderne Steuersysteme arbeiten mit progressiven Grenzsteuersätzen. Nur der Einkommensanteil, der über der Tarifgrenze liegt, wird mit dem höheren Satz besteuert – niemals das gesamte Gehalt. Eine Gehaltserhöhung führt daher stets zu einem höheren Nettoverdienst.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees. For the complete mathematical formula and a comparison with reverse mortgages, read our comprehensive guide: <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">What is a Reverse Mortgage & How Payments Work</a>.": "Eine monatliche Baufinanzierungsrate besteht aus Zins und Tilgung (Annuität) sowie anteiligen Nebenkosten für Grundsteuer und Gebäudeversicherung. Bei geringem Eigenkapital verlangen Banken mitunter Zinsaufschläge für höhere Beleihungsausläufe.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders may charge an early payoff fee. Check your loan contract terms before making lump-sum payments.": "Bei Ratenkrediten sind Sondertilgungen gesetzlich jederzeit zulässig (die Vorfälligkeitsentschädigung ist auf 1 % bzw. 0,5 % begrenzt). Bei Baufinanzierungen mit Festzinsbindung sollten Sie ein jährliches Sondertilgungsrecht (z. B. 5 % bis 10 % kostenfrei) vereinbaren.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It enables wealth to grow exponentially over time compared to simple interest.": "Zinseszins bezeichnet die Verzinsung nicht nur des ursprünglichen Kapitals, sondern auch der in Vorperioden erwirtschafteten und wiederangelegten Zinsen. Dies erzeugt über längere Zeiträume ein exponentielles Portfoliowachstum.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your expected annual interest rate (e.g., at 8% annual return, your money doubles in approximately 9 years: 72 / 8 = 9).": "Die 72er-Regel ist eine praktische Faustformel zur Berechnung der Kapitalverdopplungszeit: Teilen Sie 72 durch den jährlichen Zinssatz. Bei 8 % Rendite verdoppelt sich das Vermögen in rund 72 ÷ 8 = 9 Jahren.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total returns. More frequent compounding means interest starts earning interest sooner, producing slightly higher annual percentage yields (APY).": "Je kürzer das Zinsintervall ist (jährlich, vierteljährlich, monatlich oder täglich), desto höher fällt die Gesamtrendite aus. Durch die unterjährige Zinseszinswirkung übersteigt der Effektivzins den nominalen Ausweis.",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement (including employer matching). At a bare minimum, contribute enough to capture the full employer match—otherwise, you are leaving free compensation on the table.": "Finanzplaner raten, mindestens 15 % des Bruttoeinkommens für das Alter zu investieren. Nutzen Sie stets den vollen Arbeitgeberzuschuss Ihrer betrieblichen Vorsorge – dies ist eine risikolose Sofortrendite auf Ihre eigenen Sparbeiträge.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary, or dollar-for-dollar up to 4%) and calculates the combined total deposited into your retirement account each pay period.": "Der Rechner wendet die genaue Zuschussformel Ihres Arbeitgebers an (z. B. 50 % Zuschuss auf die ersten 6 % Gehaltsumwandlung), um den jährlichen Arbeitgeberbonus exakt zu ermitteln.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by age 40, 6x by age 50, 8x by age 60, and 10x by age 67.": "Klassische Ruhestands-Richtwerte empfehlen: Das 1-fache des Jahresgehalts mit 30 Jahren, das 3-fache mit 40, das 6-fache mit 50, das 8-fache mit 60 und das 10-fache bis zum Renteneintritt mit 67 Jahren angespart zu haben.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, but pay income tax on withdrawals in retirement. In a Roth 401(k), you contribute after-tax dollars, but qualified withdrawals in retirement are 100% tax-free. Generally, choose Roth if you expect to be in a higher tax bracket in retirement, and Traditional if you are in a high tax bracket today.": "Bei steuerbegünstigten Verträgen zahlen Sie aus dem Bruttogehalt ein (sofortige Steuerersparnis) und versteuern erst die Rentenzahlungen im Alter. Bei privaten ETF-Sparplänen investieren Sie aus versteuertem Nettoeinkommen und profitieren von Freibeträgen und günstigeren Teilfreistellungen.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you contribute $10,000 and your marginal tax bracket is 24%, you save approximately $2,400 in federal income taxes this year.": "Jeder Euro, der steuerlich absetzbar in die Vorsorge fließt, verringert das zu versteuernde Einkommen direkt. Bei 42 % Spitzensteuersatz spart eine Einzahlung von 10.000 € somit unmittelbar 4.200 € Einkommensteuer.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer match, investment returns, and years until retirement. Use this calculator's interactive chart to simulate your balance under conservative (5%), moderate (7%), and aggressive (9%) return assumptions.": "Das prognostizierte Vorsorgevermögen hängt primär von Sparrate, Arbeitgeberzuschuss, Zinseszinseffekt, Marktrendite und niedrigen Verwaltungskosten ab.",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 times your anticipated annual retirement expenses. For example, if you need $60,000 per year from your portfolio, you need an estimated $1.5 million nest egg ($60,000 × 25).": "Nach der 25er-Regel (Kehrwert der 4%-Regel) benötigen Sie etwa das 25-fache Ihrer jährlichen Nettoausgaben im Ruhestand. Bei 40.000 € jährlichem Bedarf entspricht dies einem Ruhestandskapital von 1.000.000 €.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending Balance × 0.04) / 12. For instance, a $1,000,000 retirement portfolio generates approximately $3,333 per month in sustainable retirement income, adjusted for inflation over a 30-year retirement.": "Basierend auf der 4%-Regel entspricht die monatliche Rente: (Endvermögen × 0,04) ÷ 12. Ein Guthaben von 500.000 € erbringt ca. 1.667 € pro Monat vor Steuern.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities / 40% fixed income), historical backtesting (Trinity Study) indicates your portfolio has an over 95% probability of lasting at least 30 years without running out of money.": "Mit der 4%-Regel und einem diversifizierten Portfolio (z. B. 60 % Aktien / 40 % Anleihen) reicht das angesparte Kapital mit über 95 % Wahrscheinlichkeit für mindestens 30 Jahre Ruhestand.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty plus standard income tax on the entire amount. Total taxes and penalties can easily exceed 35%–45% of your withdrawal.": "Vorzeitige Entnahmen vor dem regulären Rentenalter lösen in geförderten Verträgen empfindliche Strafabzüge und volle Nachversteuerung aus, wodurch schnell über ein Drittel des Auszahlungsbetrags verloren geht.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no full-time employees. It allows business owners to contribute both as employee and employer, enabling significantly higher annual tax-deductible contribution limits.": "Altersvorsorgemodelle für Selbstständige (wie die Basisrente) bieten steuerliche Abzugsfähigkeit der Beiträge als Sonderausgaben bis zu den gesetzlichen Höchstbeträgen und lebenslange Rentenzahlungen.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000). The interest you pay goes back into your own account, avoiding taxes and penalties as long as you repay it on schedule (usually within 5 years).": "Einige Versorgungswerke erlauben Policendarlehen bis zu 50 % des Deckungskapitals. Verlassen Sie den Arbeitgeber, wird die Restschuld häufig sofort fällig oder steuerpflichtig abgerechnet.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions. The tool models post-tax spending power at retirement so you can see whether paying taxes now vs. at retirement yields a larger final nest egg.": "Unser Rechner ermöglicht den direkten Vergleich zwischen steuerbegünstigten Einzahlungen (Brutto-Entgeltumwandlung) und nachgelagert steuerfreien Auszahlungsmodellen.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer non-mortgage debt is fully cleared. You first invest up to the employer match, then fund a Roth IRA, and put any remainder back into your employer plan.": "Nach Dave Ramseys 'Baby Step 4' legen Sie 15 % Ihres Haushaltsbruttoeinkommens für das Alter an, sobald alle Konsumschulden beglichen sind und ein Notgroschen von 3 bis 6 Monatsausgaben auf dem Tagesgeldkonto steht.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It provides cost-effective retirement plans with mandatory employer contributions (either a 3% match or a 2% non-elective contribution).": "Vorsorgemodelle für Kleinbetriebe erfordern feste Arbeitgeberzuschüsse (z. B. Pflichtzuschuss zur Entgeltumwandlung), bieten dafür aber unkomplizierte Verwaltungswege ohne hohe bürokratische Hürden.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your HR or plan administrator. However, cashing out existing vested funds while still actively employed is generally prohibited by plan rules, unless you qualify for a hardship distribution. For detailed options, see our guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Employed?</a>": "Laufende Beiträge können Sie bei der Personalabteilung jederzeit kostenfrei stoppen und auf 0 % setzen. Ein vorzeitiges Auscashen des bestehenden Kapitals ist während des Arbeitsverhältnisses in der Regel gesetzlich ausgeschlossen.",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of ~10% annually before inflation. After factoring in 2.5%–3% average inflation and ETF expense ratios, a realistic long-term real return assumption is 6.5% to 7.0% per year for a 100% equity portfolio, or 5.0% to 6.0% for a balanced 60/40 stocks and bonds portfolio.": "Historisch betrachtet erzielte ein breit diversifiziertes Weltaktienportfolio (wie der MSCI World) über Anlagezeiträume von 15+ Jahren eine durchschnittliche Nominalrendite von ca. 7 % bis 9 % p.a. Nach Abzug von Inflation und Fondskosten ist eine reale Rendite von 5 % bis 7 % eine solide Planungsgrundlage.",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility stress by purchasing more shares when prices are low and fewer when prices are high. While historical data shows investing a lump sum immediately outperforms DCA about 68% of the time because markets rise long-term, recurring contributions are far easier to budget and provide psychological discipline.": "Regelmäßige Sparraten (Cost-Average-Effekt) mindern das Timing-Risiko und emotionale Fehlentscheidungen, indem sowohl in Hoch- als auch in Tiefphasen Anteile erworben werden. Einmalanlagen schneiden statistisch in rund zwei Dritteln der Fälle besser ab, da Märkte langfristig steigen; Sparpläne bieten jedoch maximale Disziplin und Praxistauglichkeit.",
    "Nominal return is the raw percentage gain generated by your investments before inflation and taxes. Real return is your actual purchasing power gain after subtracting the inflation rate. For example, if your portfolio gains 9% nominal in a year where inflation is 3%, your real return is approximately 6%.": "Die Nominalrendite bezeichnet den reinen prozentualen Wertzuwachs Ihres Kapitals vor Inflation. Die Realrendite beziffert den tatsächlichen Kaufkraftzuwachs nach Abzug der Inflationsrate (Realrendite ≈ Nominalrendite - Inflationsrate).",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contribution cash makes up the vast majority of your portfolio. Over 20 to 30 years, accumulated reinvested earnings surpass your total principal deposits and begin generating more annual income than your own salary.": "Zinseszinsen erzeugen ein exponentielles Wachstum. In den ersten Jahren stammen die Zuwächse primär aus eigenen Einzahlungen. Nach 15 bis 25 Jahren machen die reinvestierten Erträge und Zinseszinsen jedoch über 70 % bis 80 % des gesamten Vermögens aus.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation costs (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income. This prevents you from becoming 'car poor' and prevents negative equity.": "Die 20/4/10-Regel empfiehlt: Mindestens 20 % Anzahlung leisten, die Finanzierung auf maximal 4 Jahre (48 Monate) begrenzen und die gesamten Kfz-Kosten (Rate, Versicherung, Sprit, Wartung) unter 10 % des Bruttoeinkommens halten.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk owing more than the vehicle is worth (negative equity or being 'underwater') as the car depreciates. Sticking to 48 or 60 months is significantly safer.": "Längere Laufzeiten (wie 72 oder 84 Monate) senken zwar die Monatsrate, erhöhen aber den Gesamtzinsaufwand beträchtlich. Zudem droht eine negative Eigenkapitalquote, da Neuwagen schneller an Wert verlieren, als getilgt wird.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance can exceed the market value of the car. If the car is totaled or stolen, standard insurance only pays market value, leaving you responsible for the remaining loan balance unless you have GAP insurance.": "Neuwagen verlieren im ersten Jahr bis zu 20 % ihres Werts. Ohne ausreichende Eigenmittel übersteigt der Restsaldo den Marktwert des Autos, was bei vorzeitigem Verkauf oder Totalschaden zu einer Finanzierungslücke führt.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit-based raise typically ranges from 4% to 8%, while a promotion within the same company averages 8% to 12%. Switching companies or industries often commands a 15% to 25% salary increase.": "Ein typischer jährlicher Inflationsausgleich liegt zwischen 2 % und 4 %. Leistungszulagen bewegen sich im Bereich von 4 % bis 8 %, während eine Beförderung oder ein Stellenwechsel oft 10 % bis 20 % Gehaltszuwachs ermöglicht.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100. Formula: [(New Salary - Old Salary) / Old Salary] × 100. For example, moving from $60,000 to $66,000 is a 10% raise: ($6,000 / $60,000) × 100.": "Ziehen Sie Ihr altes Gehalt vom neuen Gehalt ab, teilen Sie die Differenz durch das bisherige Gehalt und multiplizieren Sie mit 100: ((Neues Gehalt - Altes Gehalt) ÷ Altes Gehalt) × 100. Ein Sprung von 50.000 € auf 55.000 € entspricht genau 10 % Gehaltserhöhung.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly wage increase by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Ausgehend von einer Vollzeitstelle mit 40 Wochenstunden und 52 Wochen (2.080 Arbeitsstunden/Jahr) multiplizieren Sie die Erhöhung mit 2.080. Eine Lohnerhöhung um 3,00 €/h bringt somit rund 6.240 € mehr Brutto-Jahresgehalt.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of income that falls into the new, higher bracket is taxed at the higher percentage rate. Every dollar earned below that threshold is still taxed at the lower previous rates. A pay raise will always increase your total net take-home pay.": "Nein. Moderne Steuertarife sind progressiv gestaffelt. Nur der Einkommensteil, der die jeweilige Progressionsstufe überschreitet, unterliegt dem höheren Grenzsteuersatz. Das bisherige Einkommen wird weiterhin mit den niedrigeren Sätzen besteuert – mehr Brutto führt immer zu mehr Netto.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on everything else. Once the smallest debt is cleared, you roll its entire payment into the next smallest debt. This generates psychological momentum through rapid early wins.": "Bei der Schneeball-Methode zahlen Sie zuerst die Kredite mit den kleinsten Restbeträgen ab – unabhängig vom Zinssatz –, während Sie bei allen anderen nur die Mindestrate bedienen. Die schnellen Teilerfolge sorgen für maximale Motivation beim Schuldenabbau.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while paying minimums on all others. Mathematically, this minimizes total interest charges paid across all debts and clears debt in the fastest possible timeframe.": "Bei der Lawinen-Methode tilgen Sie konsequent die Schulden mit den höchsten Zinssätzen zuerst. Sobald der teuerste Kredit getilgt ist, fließt die gesamte Monatsrate in den Kredit mit dem zweithöchsten Zinssatz.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, behavioural studies show that the Debt Snowball method often yields higher real-world completion rates because the psychological motivation of eliminating individual accounts quickly prevents people from giving up on their debt-free plan.": "Mathematisch ist die Lawinen-Methode die beste Strategie, da sie die gesamten Zinskosten minimiert und die Entschuldungsdauer verkürzt. Verhaltensökonomisch bietet die Schneeball-Methode jedoch schnelle mentale Belohnungen, die das Durchhalten erleichtern.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt. Once that target debt is paid in full, its entire monthly budget (its minimum payment + the extra cash) rolls into the next debt on your roster, creating an ever-larger monthly payment that accelerates debt payoff.": "Sie zahlen weiterhin auf alle Verbindlichkeiten die vereinbarte Mindestrate und leiten jeden zusätzlichen Sparbetrag in die Tilgung der ausgewählten Prioritätsschuld.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain motivation (Snowball), and then switch to attacking the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Ja. Viele Kreditnehmer tilgen zuerst ein oder zwei kleine Restschulden, um monatliche Liquidität freizusetzen, und wechseln dann zur Lawinen-Methode, um teure Zinsen mathematisch optimal einzusparen.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or interest. It answers the fundamental financial question: 'How much will my money be worth tomorrow if I invest it today?'": "Der finanzmathematische Endwert (Future Value / FV) beziffert den Gesamtwert, den ein heutiger Geldbetrag oder eine Serie regelmäßiger Raten zu einem festgelegten Zukunftszeitpunkt bei gegebener Verzinsung erreicht.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a reduction in purchasing power per unit of currency. When inflation occurs, each dollar or euro buys a smaller percentage of a good or service.": "Inflation bezeichnet die anhaltende Steigerung des allgemeinen Preisniveaus für Waren und Dienstleistungen, wodurch die reale Kaufkraft Ihres Geldes im Zeitablauf erodiert.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only have the purchasing power equivalent of about $7,440 in 10 years, even though the nominal account balance remains unchanged.": "Unverzinstes Bar- oder Giroguthaben verliert jedes Jahr an Kaufkraft. Bei 3 % jährlicher Inflation können Sie mit 10.000 € nach 10 Jahren nur noch Waren im heutigen Gegenwert von ca. 7.440 € erwerben.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average change over time in prices paid by consumers for a representative 'basket' of goods and services, including housing, food, transportation, energy, and healthcare.": "Die Inflation wird amtlich anhand des Verbraucherpreisindex (VPI) gemessen, der die Preisentwicklung eines repräsentativen Warenkorbs (Wohnen, Nahrungsmittel, Mobilität, Gesundheit) monatlich erfasst.",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.2% per year over multi-decade periods, though short-term supply shocks can cause temporary surges.": "In Deutschland und entwickelten Volkswirtschaften lag die durchschnittliche Inflationsrate über die letzten Jahrzehnte hinweg bei rund 2 % bis 3 % p.a., wenngleich es kurzfristig zu höheren Ausschlägen kommen kann.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds / ETFs), real estate, inflation-protected government bonds (TIPS or bonos ligados al IPC), and commodities—historically provides the most reliable long-term protection against purchasing power loss.": "Ein wirksamer Schutz gelingt durch Investition in ertragsstarke Sachwerte, vor allem breit gestreute Aktien-ETFs, werthaltige Immobilien und inflationsgeschützte Staatsanleihen.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. However, if your income is very high relative to your debt, plans like PAYE or IBR might be better because they cap your monthly payment at what it would be under the Standard 10-Year Repayment Plan, whereas SAVE has no payment cap.": "Einkommensabhängige Rückzahlungspläne bieten bei Bildungskrediten die flexibelste Ratenanpassung an die tatsächliche finanzielle Leistungsfähigkeit.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause outstanding unpaid interest to capitalize (be added to your principal balance), which means you will start paying interest on that interest.": "Ja, bei Förderkrediten und Bildungsdarlehen kann bei veränderten Lebensverhältnissen in der Regel ein Wechsel des Tilgungsplans oder eine Stundung beantragt werden.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into your new total loan balance or charges a slightly higher interest rate to cover them. This avoids paying cash upfront but increases the lifetime cost of the loan.": "Ein Umschuldungskredit 'ohne Abschlussgebühr' bedeutet nicht, dass keine Gebühren anfallen; die Kosten werden meist in einen geringfügig höheren Effektivzinssatz einkalkuliert.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same or shorter term, you save on both. However, if you reset your term back to 30 years to get the lowest possible monthly payment, you might end up paying more total interest over the life of the loan despite the monthly savings.": "Das hängt von der gewählten Laufzeit ab: Bleibt die Laufzeit bei geringerem Zinssatz gleich, sinkt die Monatsrate. Bei verkürzter Laufzeit steigt die Rate, aber Sie sparen erhebliche Gesamtzinsen ein.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though many will approve up to 43%. Government-backed loans like FHA and VA loans can be more flexible, sometimes allowing back-end DTIs up to 50% or higher if you have a strong credit score or significant cash reserves.": "Banken bevorzugen eine Gesamtschuldenquote von maximal 35 % bis 40 % des Nettoeinkommens, um eine nachhaltige Haushaltsrechnung und Kreditsicherheit zu gewährleisten.",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower than it is today, a Traditional IRA is better.": "Grundsätzlich gilt: Erwarten Sie im Ruhestand einen höheren Steuersatz als heute, sind steuerfreie Auszahlungen vorteilhafter. Ist Ihr Steuersatz im Alter voraussichtlich niedriger, lohnt sich der sofortige Steuerabzug.",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under age 50, and $8,000 for those age 50 or older (which includes a $1,000 catch-up contribution).": "Für steuerlich begünstigte Altersvorsorgepläne gelten jährliche Höchstgrenzen, die im Rahmen der Einkommensteuererklärung steuermindernd geltend gemacht werden können.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers, and $230,000 to $240,000 for married couples filing jointly. Anyone can contribute to a Traditional IRA regardless of income, but the tax deductibility phases out if your income is high and you have access to a workplace retirement plan (like a 401k).": "Bei bestimmten Förderungen und Zulagen existieren Einkommensgrenzen, ab denen staatliche Förderbeiträge schrittweise entfallen.",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax- and penalty-free, but withdrawing earnings early incurs taxes and a 10% penalty. With a Traditional IRA, withdrawing any funds early generally triggers both regular income tax and a 10% penalty, except for specific IRS-approved exemptions (e.g., qualifying first-time home purchase, higher education expenses, or disability).": "Eigenanteile aus privaten ungeförderten Wertpapierdepots können jederzeit flexibel, gebührenfrei und steuerneutral entnommen werden.",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have progressive tax rates). Local taxes may also apply depending on the specific city or county you work or live in.": "Das Netto-Gehalt hängt entscheidend von Steuerklasse, Freibeträgen, Kirchensteuer, Solidaritätszuschlag und den gesetzlichen Beiträgen zur Sozialversicherung ab.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Laufende Sparraten können in der Regel jederzeit pausiert werden. Das vorzeitige Auflösen bereits gebundenen Vorsorgekapitals ist jedoch steuerlich stark reglementiert und meist mit Steuernachzahlungen und Verlust von Förderungen verbunden.",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and loans). In an annuity due, payments occur at the beginning of each period (standard for lease agreements). Because money is invested earlier in an annuity due, it compounds for one additional cycle, resulting in a higher Future Value.": "Bei nachschüssiger Fälligkeit fließen Raten am Periodenende (Standard bei Baufinanzierungen und Darlehen). Bei vorschüssiger Fälligkeit erfolgt die Zahlung zu Beginn (üblich bei Leasingverträgen). Durch die frühere Verzinsung entsteht bei vorschüssigen Renten ein rechnerisch höherer Endwert.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $1,000,000 portfolio generates approximately $3,333 per month before taxes, with annual adjustments for inflation.": "Basierend auf der 4%-Regel entspricht die monatliche Auszahlung: (Endkapital × 0,04) ÷ 12. Ein Vermögen von 1.000.000 € liefert somit rund 3.333 € monatlich vor Steuern, jährlich an die Inflation angepasst.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Nach der anerkannten 4%-Regel der Trinity-Studie können Sie bei einem breit gestreuten Portfolio jährlich 4 % des anfänglichen Kapitals entnehmen (inflationsangepasst), mit einer statistischen Wahrscheinlichkeit von über 95 %, dass das Vermögen mindestens 30 Jahre lang vorhält.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty on top of ordinary income taxes at your marginal rate. A $20,000 withdrawal by someone in the 22% bracket would surrender roughly $6,400 in combined taxes and penalties.": "Eine vorzeitige Auflösung von steuerlich geförderten Altersvorsorgeverträgen führt im Regelfall zur Rückzahlung erhaltener Förderungen und zur vollen Nachversteuerung mit dem persönlichen Grenzsteuersatz. Zudem entfällt der Zinseszinseffekt.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New Salary - Old Salary) ÷ Old Salary) × 100. For example, moving from $60,000 to $66,000 is a 10% raise.": "Ziehen Sie das alte Gehalt vom neuen Gehalt ab, teilen Sie die Differenz durch das bisherige Gehalt und multiplizieren Sie mit 100: ((Neues Gehalt - Altes Gehalt) ÷ Altes Gehalt) × 100. Ein Anstieg von 50.000 € auf 55.000 € entspricht genau 10 % Gehaltserhöhung.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals $2.50 × 2,080 = $5,200 more in pre-tax annual income.": "Ausgehend von einer 40-Stunden-Woche und ca. 2.080 Arbeitsstunden pro Jahr multiplizieren Sie die Erhöhung des Stundenlohns mit 2.080. Eine Erhöhung um 2,50 € pro Stunde entspricht somit rund 5.200 € mehr Brutto-Jahresgehalt.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above a tax bracket threshold are taxed at the higher marginal rate—never your entire income. A pay raise will always increase your total take-home pay.": "Nein. Moderne Einkommensteuersysteme arbeiten mit einem progressiven Grenzsteuersatz. Nur der Einkommensanteil, der über der jeweiligen Stufengrenze liegt, wird mit dem höheren Satz versteuert – niemals das gesamte Einkommen. Eine Gehaltserhöhung führt daher ausnahmslos zu mehr Netto.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and HOA fees (if applicable). If your down payment is under 20%, private mortgage insurance (PMI) is also included.": "Eine monatliche Baufinanzierungsrate besteht aus Zins und Tilgung (Annuität) sowie anteiligen Nebenkosten für Grundsteuer und Gebäudeversicherung. Bei geringem Eigenkapital verlangen Banken mitunter Zinsaufschläge für höhere Beleihungsausläufe.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money: divide 72 by your expected annual interest rate. For example, at an 8% return, money doubles in roughly 72 ÷ 8 = 9 years.": "Die 72er-Regel ist eine mathematische Faustformel, um die Verdopplungszeit eines Kapitals im Kopf zu schätzen: Teilen Sie 72 durch den jährlichen Zinssatz. Bei 8 % Rendite verdoppelt sich das Kapital in etwa 72 ÷ 8 = 9 Jahren.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, and pay ordinary income tax upon withdrawal in retirement. In a Roth 401(k), you contribute after-tax dollars, but all qualified retirement withdrawals—including all compound investment gains—are 100% tax-free.": "Bei steuerlich geförderter Altersvorsorge (bAV/Basisrente) sparen Sie heute Steuern auf Ihre Einzahlungen und versteuern die Auszahlungen im Ruhestand. Bei rein privaten ETF-Depots investieren Sie aus versteuertem Einkommen und nutzen den jährlichen Sparer-Pauschbetrag für Erträge.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities, 40% bonds), historical data indicates a 95%+ probability that your savings will last at least 30 years.": "Mit der 4%-Regel und einem diversifizierten Portfolio (z. B. 60 % Aktien / 40 % Anleihen) reicht das angesparte Kapital mit über 95 % Wahrscheinlichkeit für mindestens 30 Jahre Ruhestand.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000), which you repay through payroll deductions with interest going back into your account.": "Viele betriebliche Vorsorgepläne erlauben Darlehen auf bis zu 50 % des angesparten Kapitals, die über die Gehaltsabrechnung zuzüglich Zinsen an das eigene Konto zurückgezahlt werden.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions to compare long-term tax advantages.": "Unser Rechner ermöglicht den direkten Vergleich zwischen steuerbegünstigten Einzahlungen (Brutto-Entgeltumwandlung) und nachgelagert steuerfreien Auszahlungsmodellen.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts (such as a 401k up to the match, then a Roth IRA) after paying off all non-mortgage debt and building a 3- to 6-month emergency fund.": "Nach Dave Ramseys 'Baby Step 4' legen Sie 15 % Ihres Haushaltsbruttoeinkommens für das Alter an, sobald alle Konsumschulden beglichen sind und ein Notgroschen von 3 bis 6 Monatsausgaben auf dem Tagesgeldkonto steht.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It features lower contribution limits than a standard 401(k) but requires mandatory employer contributions (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Vorsorgemodelle für Kleinbetriebe erfordern feste Arbeitgeberzuschüsse (z. B. Pflichtzuschuss zur Entgeltumwandlung), bieten dafür aber unkomplizierte Verwaltungswege ohne hohe bürokratische Hürden.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your employer's HR or payroll department and updating your deferral percentage to 0%. However, cashing out existing money while still employed is generally prohibited by IRS regulations unless your plan offers an 'in-service distribution' (usually after age 59½) or you qualify for an IRS Hardship Withdrawal (which incurs income taxes and a 10% penalty).": "Sie können laufende Sparbeiträge über die Personalabteilung jederzeit kostenfrei stoppen und auf 0 % setzen. Ein vorzeitiges Auscashen des bereits bestehenden Kapitals ist während des Arbeitsverhältnisses meist ausgeschlossen oder löst empfindliche steuerliche Nachteile aus.",
    "Nominal return is the raw percentage gain generated by your investments before inflation. Real return is the purchasing power gain after subtracting the rate of inflation (Real Return ≈ Nominal Return - Inflation Rate).": "Die Nominalrendite bezeichnet den reinen prozentualen Wertzuwachs Ihres Kapitals vor Inflation. Die Realrendite beziffert den tatsächlichen Kaufkraftzuwachs nach Abzug der Inflationsrate (Realrendite ≈ Nominalrendite - Inflationsrate).",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit raise for strong performance typically falls between 4% and 8%, while a major promotion or job switch often commands a 10% to 20% salary increase.": "Ein typischer jährlicher Inflationsausgleich liegt zwischen 2 % und 4 %. Leistungszulagen bewegen sich im Bereich von 4 % bis 8 %, während eine Beförderung oder ein Stellenwechsel oft 10 % bis 20 % Gehaltszuwachs ermöglicht.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New - Old) ÷ Old) × 100. For example, moving from $75,000 to $82,500 is a 10% raise.": "Ziehen Sie Ihr altes Gehalt vom neuen Gehalt ab, teilen Sie die Differenz durch das bisherige Gehalt und multiplizieren Sie mit 100: ((Neues Gehalt - Altes Gehalt) ÷ Altes Gehalt) × 100. Ein Sprung von 50.000 € auf 55.000 € entspricht genau 10 % Gehaltserhöhung.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $3.00/hour raise equals $3.00 × 2,080 = $6,240 more in pre-tax annual compensation.": "Ausgehend von einer Vollzeitstelle mit 40 Wochenstunden und 52 Wochen (2.080 Arbeitsstunden/Jahr) multiplizieren Sie die Erhöhung mit 2.080. Eine Lohnerhöhung um 3,00 €/h bringt somit rund 6.240 € mehr Brutto-Jahresgehalt.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of your income that falls into the higher tax bracket is taxed at the higher percentage rate. Your prior earnings are still taxed at their original lower rates, so a pay raise will always result in higher total take-home pay.": "Nein. Moderne Steuertarife sind progressiv gestaffelt. Nur der Einkommensteil, der die jeweilige Progressionsstufe überschreitet, unterliegt dem höheren Grenzsteuersatz. Das bisherige Einkommen wird weiterhin mit den niedrigeren Sätzen besteuert – mehr Brutto führt immer zu mehr Netto.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while making minimum payments on all other accounts. Once the smallest balance is eliminated, you roll its payment into the next smallest debt, generating psychological momentum through quick wins.": "Bei der Schneeball-Methode zahlen Sie zuerst die Kredite mit den kleinsten Restbeträgen ab – unabhängig vom Zinssatz –, während Sie bei allen anderen nur die Mindestrate bedienen. Die schnellen Teilerfolge sorgen für maximale Motivation beim Schuldenabbau.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on all others. Once the balance with the highest APR is cleared, you redirect that full payment toward the next highest interest rate account.": "Bei der Lawinen-Methode tilgen Sie konsequent die Schulden mit den höchsten Zinssätzen zuerst. Sobald der teuerste Kredit getilgt ist, fließt die gesamte Monatsrate in den Kredit mit dem zweithöchsten Zinssatz.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid and eliminates debt faster. However, behavioral research shows that the quick psychological wins of the Debt Snowball method help many borrowers stay committed to their debt payoff journey.": "Mathematisch ist die Lawinen-Methode die beste Strategie, da sie die gesamten Zinskosten minimiert und die Entschuldungsdauer verkürzt. Verhaltensökonomisch bietet die Schneeball-Methode jedoch schnelle mentale Belohnungen, die das Durchhalten erleichtern.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds), real estate, inflation-protected securities (TIPS), and high-yield savings accounts—preserves and grows your real wealth.": "Ein wirksamer Schutz gelingt durch Investition in Sachwerte, deren Erträge die Inflation langfristig übertreffen – vor allem breit diversifizierte Aktien-ETFs, werthaltige Immobilien und inflationsindexierte Wertpapiere.",
    "How does this online TVM calculator solve Time Value of Money equations?": "Wie löst dieser Online-TVM-Rechner die Gleichungen des Zeitwerts des Geldes?",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to link five core variables: Present Value (PV), Future Value (FV), Payment (PMT), Periodic Interest Rate (r), and Total Periods (n). You enter any four known variables, and the mathematical engine automatically calculates the fifth missing parameter instantly.": "Dieser TVM-Finanzrechner nutzt standardisierte Zinseszins- und Barwertformeln, um fünf Kernvariablen zu verknüpfen: Barwert (PV), Endwert (FV), periodische Zahlung (PMT), Zinssatz pro Periode (r) und Gesamtlaufzeit (n). Sie geben vier bekannte Werte ein, und der Rechner ermittelt den fünften gesuchten Parameter in Echtzeit.",
    "How does this online TVM calculator solve Time Value of Money problems?": "Wie berechnet dieser Online-TVM-Rechner den Zeitwert des Geldes?",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (i), Number of Periods (n), and Periodic Payment (PMT). By inputting any four of these values, the calculator solves for the fifth using closed-form financial equations or numerical approximation (for interest rate).": "Der TVM-Rechner verbindet fünf fundamentale finanzmathematische Kennzahlen: Barwert (PV), Endwert (FV), Periodenzinssatz (i), Anzahl der Zahlungsperioden (n) und regelmäßige Rate (PMT). Sobald Sie vier Variablen eingeben, löst das System die Gleichung analytisch oder per Newton-Raphson-Näherung (beim Zinssatz).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), the periodic installment you plan to deposit (PMT), the expected annual interest rate (r), the compounding frequency, and the total duration in years. The calculator solves for the exact final balance, displaying total interest earned and visual amortization charts.": "Wählen Sie 'Endwert (FV)' als Zielgröße. Geben Sie Ihr Startkapital (PV), die geplante regelmäßige Sparrate (PMT), den erwarteten Jahreszins (r), die Zinseszinsperiode und die Laufzeit in Jahren ein. Der Rechner ermittelt das Endvermögen, den Zinsertrag und den Vermögensverlauf.",
    "How do I use this as a Future Value calculator?": "Wie nutze ich diesen Rechner als Endwertrechner (Future Value)?",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and duration, and optionally add recurring monthly payments (PMT). The calculator compounds the initial principal and annuity payments over time, displaying the final accumulated portfolio value and total interest earned.": "Geben Sie Ihre Einmalanlage als Barwert (PV) ein, bestimmen Sie den Zinssatz und die Anlagedauer und tragen Sie optional eine Monatsrate (PMT) ein. Der Rechner verzinst das Startkapital sowie die Sparraten und weist das gesamte Endvermögen samt Zinseszinsen aus.",
    "What is the difference between an ordinary annuity and an annuity due?": "Was ist der Unterschied zwischen einer nachschüssigen und einer vorschüssigen Rente?",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (standard for lease agreements and rent). Because payments in an annuity due occur earlier, each installment earns an additional period of compound interest, resulting in a higher Future Value or higher Present Value.": "Bei einer nachschüssigen Zahlung (Ordinary Annuity / END) erfolgt die Rate am Ende der Periode (Standard bei Bankkrediten und Hypotheken). Bei einer vorschüssigen Zahlung (Annuity Due / BGN) wird die Rate zu Beginn fällig (typisch bei Miet- und Leasingverträgen). Durch die frühere Fälligkeit generiert jede Rate eine Zinsperiode mehr, was zu einem höheren End- bzw. Barwert führt.",
    "What is the 5% rule for renting vs. buying?": "Was besagt die 5%-Regel beim Vergleich von Mieten vs. Kaufen?",
    "The 5% rule (popularized by Ben Felix) estimates the non-recoverable annual costs of homeownership at roughly 5% of the property value: 1% for property taxes, 1% for maintenance and repairs, and 3% for the cost of capital (mortgage interest + equity opportunity cost). If renting an equivalent home costs less than 5% of its purchase price annually (or 5%/12 per month), renting is mathematically favorable.": "Die 5%-Regel (bekannt durch Ben Felix) beziffert die unwiederbringlichen jährlichen Kosten des Immobilieneigentums auf rund 5 % des Kaufpreises: 1 % Grundsteuer, 1 % Instandhaltungsrücklage und 3 % Kapitalkosten (Kreditzinsen plus entgangene Eigenkapitalrendite). Kostet die Kaltmiete einer vergleichbaren Wohnung weniger als 5 % des Kaufpreises pro Jahr (bzw. 5 % / 12 pro Monat), ist Mieten plus Anlegen der Differenz mathematisch vorteilhafter.",
    "How much income should I spend on a mortgage?": "Wie viel vom Einkommen darf maximal in die Baufinanzierung fließen?",
    "Financial experts and the standard 28/36 rule recommend spending no more than 28% of your gross monthly income on housing costs (PITI: Principal, Interest, Taxes, and Insurance). Total monthly debt obligations (housing + cars + student loans + credit cards) should remain under 36% to maintain financial stability.": "Banken und Finanzexperten empfehlen nach der klassischen 28/36-Regel, maximal 28 % des monatlichen Bruttoeinkommens für die gesamte Warmmiete bzw. Kreditrate (Zins, Tilgung, Grundsteuer, Gebäudeversicherung) aufzuwenden. Die gesamten monatlichen Kreditverbindlichkeiten sollten 36 % des Bruttoeinkommens nicht überschreiten.",
    "Under the empirical 4% Safe Withdrawal Rule, your retirement savings are statistically projected to last at least 30 years with a balanced stock/bond portfolio. For example, withdrawing 4% annually ($40,000 from a $1,000,000 balance) adjusted annually for inflation has historically survived almost every 30-year retirement window in modern market history.": "Gemäß der empirischen 4%-Regel (Trinity-Studie) reicht ein diversifiziertes Portfolio aus Aktien und Anleihen mit einer Wahrscheinlichkeit von über 95 % für mindestens 30 Jahre Ruhestand. Eine anfängliche Entnahme von 4 % (z. B. 40.000 € pro 1.000.000 € Depotwert), die jährlich um die Inflationsrate angepasst wird, hat historisch nahezu jedes 30-jährige Marktszenario überstanden.",
    "What is the Time Value of Money (TVM)?": "Was bedeutet der Zeitwert des Geldes (TVM)?",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest over time.": "Der Grundsatz des Zeitwerts des Geldes besagt, dass ein Geldbetrag heute mehr wert ist als derselbe Betrag in der Zukunft, da das heutige Kapital investiert werden und durch Zinsen wachsen kann, während Inflation künftige Kaufkraft mindert.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested across periodic purchases rather than investing everything in a single lump sum. By buying fixed dollar amounts at regular intervals, you automatically purchase more shares when prices are low and fewer shares when prices are high, lowering your average cost per share over time.": "Der Cost-Average-Effekt (Durchschnittskosteneffekt) entsteht, wenn regelmäßig feste Geldbeträge (z. B. per ETF-Sparplan) investiert werden. Bei niedrigen Kursen erwerben Sie automatisch mehr Anteile, bei hohen Kursen weniger. Dies senkt den durchschnittlichen Einstiegspreis und nimmt das Timing-Risiko aus der Geldanlage.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of share price.": "Der Durchschnittskosteneffekt beschreibt die Methode, in festen Zeitintervallen konstante Beträge anzulegen, um Marktschwankungen zu glätten und Timing-Fehler zu vermeiden.",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement. At a minimum, always contribute enough to capture 100% of your employer's 401(k) match, as this provides an immediate 50% to 100% risk-free return on your money.": "Finanzplaner empfehlen, mindestens 15 % des Bruttoeinkommens für die Altersvorsorge zurückzulegen. Schöpfen Sie in jedem Fall den vollen Arbeitgeberzuschuss der betrieblichen Altersversorgung ab – dies entspricht einer risikofreien Sofortrendite.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you are in the 24% federal tax bracket and contribute $10,000, you reduce your current tax bill by $2,400.": "Jeder Euro, der in eine steuerlich abzugsfähige Vorsorge (z. B. Entgeltumwandlung oder Basisrente) fließt, mindert das zu versteuernde Einkommen direkt. Bei einem Grenzsteuersatz von 42 % spart eine Einzahlung von 10.000 € somit unmittelbar 4.200 € Einkommensteuer.",
    "How much in a 401(k) do I need to retire?": "Wie viel Altersvorsorgekapital benötigt man für den Ruhestand?",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement spending minus guaranteed income like Social Security. For example, if you need $60,000 per year from your portfolio, your target nest egg is $1,500,000 to $1,800,000.": "Nach der 25er-Regel (Kehrwert der 4%-Entnahmerate) benötigen Sie etwa das 25- bis 30-fache Ihrer jährlichen Netto-Versorgungslücke im Ruhestand (Wunschbudget abzüglich gesetzlicher Rente). Bei einer Rentenlücke von 30.000 € p.a. liegt das Zielkapital bei ca. 750.000 € bis 900.000 €.",
    "How much will my 401(k) pay me per month in retirement?": "Wie viel monatliche Rente bringt das angesparte Vorsorgekapital?",
    "How much tax and penalty do I pay on early 401(k) withdrawals?": "Welche Steuern und Abzüge fallen bei vorzeitiger Auszahlung an?",
    "What is a Solo 401(k) and how does it work for the self-employed?": "Was ist eine Altersvorsorge für Selbstständige und wie funktioniert sie?",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no common-law employees. It allows you to contribute both as an employee (deferring up to $23,000 in 2024) and as the employer (up to 25% of net business compensation), providing substantial tax deductions.": "Selbstständige und Freiberufler können Vorsorgeaufwendungen (z. B. Basisrente / Rürup-Rente) steuermindernd als Sonderausgaben geltend machen. Dies erlaubt es, erhebliche Beträge steueroptimiert in breit gestreute Anlageformen anzulegen.",
    "Can I borrow against my 401(k) instead of taking an early withdrawal?": "Kann man sich Geld aus der eigenen Altersvorsorge leihen?",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000 (whichever is less). You repay the loan with interest back into your own account, usually over 5 years. However, if you leave your job, the outstanding balance typically becomes due rapidly or converts to a taxable distribution.": "Bei betrieblichen Modellen ist ein Darlehen rechtlich selten möglich; bei vorzeitiger Kündigung droht der Verlust von Steuervorteilen. Es empfiehlt sich daher, für unvorhergesehene Liquiditätsbedarfe einen separaten Notgroschen auf einem Tagesgeldkonto zu halten.",
    "How do I use this as a Roth vs Traditional 401(k) calculator?": "Wie vergleicht man steuerfreie Auszahlungen mit sofortigen Steuerabzügen?",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) contributions. Traditional saves money on taxes today during your peak earning years, while Roth offers completely tax-free withdrawals in retirement.": "Mit unserem Rechner können Sie zwischen sofortiger steuerlicher Absetzbarkeit (nachgelagerte Besteuerung) und steuerfreien Erträgen im Ruhestand vergleichen. Hohe Spitzensteuersätze heute sprechen für sofortige Abzüge; ein niedriger heutiger Steuersatz begünstigt steuerfreie Modelle.",
    "What is a good salary increase percentage?": "Was ist eine gute prozentuale Gehaltserhöhung?",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong merit raises range from 5% to 8%, and promotions or job switches typically yield 10% to 20% increases. Any raise above current inflation increases your real purchasing power.": "Ein reiner Inflationsausgleich liegt historisch meist bei 2 % bis 4 %. Eine solide Leistungsanpassung beträgt 5 % bis 8 %, während eine Beförderung oder ein Arbeitgeberwechsel typischerweise 10 % bis 20 % Gehaltszuwachs bringt. Jede Erhöhung oberhalb der Inflationsrate steigert Ihre reale Kaufkraft.",
    "How do I calculate a salary increase percentage?": "Wie berechnet man die prozentuale Gehaltserhöhung?",
    "How do I convert an hourly pay raise into an annual salary increase?": "Wie rechnet man eine Stundenlohnerhöhung auf das Jahresgehalt um?",
    "Will a pay raise push me into a higher tax bracket and reduce my take-home pay?": "Kann eine Gehaltserhöhung durch eine höhere Steuerklasse zu weniger Netto führen?",
    "How does an amortized loan work?": "Wie funktioniert ein Annuitätendarlehen?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest charges; over time, as the principal balance decreases, a progressively larger portion of each payment reduces the principal debt.": "Bei einem Annuitätendarlehen zahlen Sie eine konstante monatliche Rate (Annuität). Zu Beginn fließt der Großteil der Rate in die Zinsen; mit sinkender Restschuld verringert sich der Zinsanteil kontinuierlich, und der Tilgungsanteil wächst Monat für Monat.",
    "What is the difference between fixed-rate and variable-rate loans?": "Was unterscheidet ein Festzinsdarlehen von einem variablen Kredit?",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the borrowing term, protecting you against rising interest rates. A variable-rate loan fluctuates with a market index, meaning payments can rise or fall over time.": "Bei einem Festzinsdarlehen (Zinsbindung) bleibt der Zinssatz über die vereinbarte Laufzeit (z. B. 10 oder 15 Jahre) unverändert fest, was maximale Planungssicherheit bietet. Ein variables Darlehen passt sich regelmäßig den Marktzinsen (z. B. Euribor) an.",
    "Can I pay off my loan early without penalty?": "Kann ich meinen Kredit jederzeit ohne Vorfälligkeitsentschädigung ablösen?",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders charge prepayment fees within the first 3 to 5 years. Always verify your loan agreement's prepayment terms before submitting extra payments.": "Bei Ratenkrediten ist eine Sondertilgung oder Gesamtfreistellung gesetzlich jederzeit möglich (die gesetzliche Vorfälligkeitsentschädigung ist gedeckelt). Bei Immobilienkrediten mit Zinsbindung sollten Sie vertragliche Sondertilgungsrechte (meist 5 % p.a. kostenfrei) vorab vereinbaren.",
    "What is compound interest?": "Was versteht man unter dem Zinseszinseffekt?",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from prior periods. Unlike simple interest, compound growth produces an exponential wealth curve over long time horizons.": "Der Zinseszinseffekt entsteht, wenn erwirtschaftete Zinsen nicht ausgezahlt, sondern reinvestiert werden. In den Folgeperioden werden die Zinsen mitverzinst, was zu einem exponentiellen Vermögenswachstum führt.",
    "What is the Rule of 72?": "Was ist die 72er-Regel?",
    "How does compounding frequency affect total returns?": "Wie beeinflusst das Zinsintervall den Endertrag?",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total return. More frequent compounding converts interest into principal faster, creating a higher Effective Annual Rate (EAR) than the stated nominal APR.": "Je häufiger die Zinsgutschrift erfolgt (jährlich, vierteljährlich, monatlich oder täglich), desto höher fällt das Endkapital aus. Durch die unterjährige Zinseszinswirkung liegt der effektive Jahreszins messbar über dem Nominalzins.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary) to determine the exact annual employer contribution added to your balance.": "Der Rechner berücksichtigt die Zuschussformel Ihres Arbeitgebers (z. B. 50 % Zuschuss bis zu 6 % Gehaltsumwandlung) und addiert diesen garantierten Bonus direkt zu Ihrem monatlichen Sparbetrag.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by 40, 6x by 50, 8x by 60, and 10x by age 67.": "Als Richtwert für den Ruhestand empfehlen Vorsorgeexperten: Das 1-fache des Jahresbruttogehalts mit 30 Jahren, das 3-fache mit 40, das 6-fache mit 50, das 8-fache mit 60 und das 10-fache bei Renteneintritt.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, investment returns, and fee drag.": "Ihr prognostiziertes Endvermögen hängt entscheidend von Sparrate, Arbeitgeberzuschuss, Marktrendite, Zeithorizont und niedrigen Fondskosten (TER) ab.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer debt (except the home mortgage) is paid off and a 3- to 6-month emergency fund is established.": "Nach Dave Ramseys 'Baby Step 4' investieren Sie 15 % Ihres Haushaltsbruttoeinkommens in die Altersvorsorge, sobald alle Konsumschulden getilgt sind und ein Notgroschen von 3 bis 6 Monatsausgaben auf dem Tagesgeldkonto liegt.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees, requiring a mandatory employer contribution (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Betriebliche Kleinbetriebspläne verpflichten Arbeitgeber zu verlässlichen Mindestzuschüssen für die Belegschaft, um auch in kleinen Unternehmen eine solide Vorsorgegrundlage zu schaffen.",
    "What is the 20/4/10 rule for buying a car?": "Was besagt die 20/4/10-Autoregel?",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation expenses (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income.": "Die 20/4/10-Regel besagt: Mindestens 20 % Anzahlung leisten, die Kreditlaufzeit auf maximal 4 Jahre (48 Monate) begrenzen und die gesamten Kfz-Kosten (Kreditrate, Versicherung, Sprit, Wartung) unter 10 % des monatlichen Bruttoeinkommens halten.",
    "Is a longer auto loan term better?": "Sind sehr lange Autokredit-Laufzeiten sinnvoll?",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more in total interest. Additionally, you risk becoming 'upside-down' (owing more than the car is worth) due to rapid vehicle depreciation.": "Längere Laufzeiten (z. B. 72 oder 84 Monate) senken zwar die monatliche Rate, erhöhen aber die gezahlten Gesamtzinsen drastisch. Zudem riskieren Sie eine Unterdeckung, bei der das Auto schneller an Wert verliert, als Sie den Kredit tilgen.",
    "How does vehicle depreciation affect my loan?": "Wie wirkt sich der Wertverlust auf den Kredit aus?",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance will exceed the vehicle's market value, leaving you in negative equity if the car is totaled or sold early.": "Neuwagen verlieren im ersten Jahr oft bis zu 20 % bis 25 % ihres Wertes. Ohne ausreichende Anzahlung übersteigt die Restschuld den Fahrzeugwert, was bei einem Unfall oder vorzeitigen Verkauf zu finanziellen Verlusten führt.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on all other debts. Once the smallest debt is eliminated, you roll its payment into the next smallest balance to build rapid psychological momentum.": "Bei der Schneeball-Methode tilgen Sie zuerst die Kredite mit den kleinsten Restbeträgen – unabhängig vom Zinssatz –, während Sie für alle anderen nur die Mindestrate zahlen. Das sorgt für schnelle Erfolgserlebnisse und stärkt die Motivation.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on the rest. Once your highest-APR balance is cleared, you target the next highest rate.": "Bei der Lawinen-Methode tilgen Sie zuerst die Kredite mit den höchsten Zinssätzen. Sobald der teuerste Kredit getilgt ist, fließt das freiwerdende Geld in den Kredit mit dem zweithöchsten Zinssatz.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest you pay and eliminates debt in the shortest calendar time. However, the Debt Snowball provides psychological quick wins that help many borrowers stick with their payoff plan.": "Mathematisch ist die Lawinen-Methode überlegen, da sie die gesamten Zinskosten minimiert und die Gesamtlaufzeit verkürzt. Die Schneeball-Methode bietet jedoch wertvolle psychologische Teilerfolge, die beim Durchhalten helfen.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt until it is completely paid off.": "Sie zahlen weiterhin auf alle Verbindlichkeiten die vereinbarte Mindestrate und leiten jeden zusätzlichen Euro in die Tilgung der ausgewählten Prioritätsschuld.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain confidence, then switch to the Avalanche method to tackle high-interest credit cards mathematically.": "Ja. Viele Schuldner tilgen zunächst ein oder zwei kleine Kredite für schnelle mentale Erfolge und wechseln anschließend zur Lawinen-Methode, um teure Zinsen mathematisch optimal einzusparen.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of compound interest over time.": "Der finanzmathematische Endwert (Future Value / FV) beziffert den Betrag, zu dem ein heutiges Kapital oder eine Serie regelmäßiger Zahlungen bis zu einem bestimmten Zukunftszeitpunkt bei gegebener Verzinsung anwächst.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a progressive decline in the purchasing power of your money.": "Inflation bezeichnet den kontinuierlichen Anstieg des allgemeinen Preisniveaus für Güter und Dienstleistungen, wodurch die reale Kaufkraft des Geldes im Zeitverlauf sinkt.",
    "How does inflation affect my savings?": "Wie schadet Inflation meinen Ersparnissen?",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only buy about $7,440 worth of goods and services in 10 years.": "Guthaben auf unverzinsten Konten verliert jedes Jahr real an Wert. Bei einer Inflationsrate von 3 % p.a. entspricht die Kaufkraft von 10.000 € nach 10 Jahren nur noch ca. 7.440 € heutiger Waren.",
    "How is inflation officially measured?": "Wie wird die Inflationsrate ermittelt?",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average price change over time for a representative basket of consumer goods and services like housing, food, transportation, and medical care.": "Die Inflation wird amtlich anhand des Verbraucherpreisindex (VPI) gemessen, der die monatliche Preisentwicklung eines repräsentativen Warenkorbs (Wohnen, Nahrungsmittel, Mobilität, Gesundheit) erfasst.",
    "What is the historical average inflation rate?": "Wie hoch war die Inflation historisch im Schnitt?",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.5% annually over multi-decade periods, though short-term spikes can exceed this range.": "In Deutschland und entwickelten Volkswirtschaften lag die durchschnittliche Inflationsrate über die letzten Jahrzehnte hinweg bei rund 2 % bis 3 % p.a., wenngleich es kurzfristig zu Spitzen kommen kann.",
    "How can I protect my money from losing value to inflation?": "Wie schützt man Vermögen vor Entwertung?",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy.": "Einkommensabhängige Rückzahlungspläne bieten bei Studienkrediten die flexibelste Ratenanpassung an das tatsächliche Einkommen.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching may capitalize unpaid interest.": "Ja, bei den meisten Förderkrediten und Studienförderungen kann ein Wechsel des Tilgungsplans oder eine Stundung bei geänderten Einkommensverhältnissen beantragt werden.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into the loan balance or charges a slightly higher interest rate.": "Ein Umschuldungskredit 'ohne Bearbeitungsgebühr' bedeutet nicht, dass keine Kosten anfallen; die Kreditkosten werden in der Regel in einen leicht höheren Effektivzinssatz eingerechnet.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same remaining term, you lower your monthly payment. If you shorten the term, your payment may rise, but you pay off the debt faster.": "Das hängt von der gewählten Laufzeit ab: Behalten Sie die Restlaufzeit bei niedrigerem Zins bei, sinkt die Monatsrate. Verkürzen Sie die Laufzeit, steigt die Rate, aber Sie sind wesentlich schneller schuldenfrei.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though approvals up to 43% or even 50% are possible with strong credit scores.": "Banken bevorzugen eine Gesamtschuldenquote von maximal 35 % bis 40 % des Nettoeinkommens, um ein tragbares Kreditausfallrisiko sicherzustellen.",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, Roth is superior. If you expect your tax bracket to be lower in retirement, Traditional is usually better.": "Grundsätzlich gilt: Erwarten Sie im Ruhestand einen höheren Steuersatz als heute, sind steuerfreie Auszahlungen vorteilhaft. Ist Ihr Steuersatz im Ruhestand voraussichtlich niedriger als im heutigen Berufsleben, lohnt sich die sofortige steuerliche Absetzbarkeit.",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under 50, and $8,000 for those 50 and older.": "Für private steuerbegünstigte Altersvorsorgepläne gelten jährliche steuerliche Höchstbeträge, die im Rahmen der Einkommensteuererklärung als Sonderausgaben geltend gemacht werden können.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers.": "Bei bestimmten Förderungen greifen Einkommensgrenzen, ab denen Förderzulagen schrittweise abgeschmolzen werden.",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax-free and penalty-free.": "Eigenanteile aus privaten ungeförderten Wertpapierdepots können jederzeit flexibel und steuerneutral entnommen werden.",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have top rates exceeding 10%).": "Das Netto-Gehalt hängt entscheidend von Steuerklasse, Freibeträgen, Solidaritätszuschlag, Kirchensteuer und den gesetzlichen Sozialversicherungsbeiträgen ab.",
    "How is a mortgage payment calculated?": "Wie setzt sich eine Baufinanzierungsrate zusammen?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and sometimes Private Mortgage Insurance (PMI) or HOA fees. The principal and interest portion is calculated using the standard amortization formula.": "Die monatliche Rate eines Annuitätendarlehens besteht aus Zins und Tilgung, berechnet über die Annuitätenformel. Bei Immobilien kommen laufende Nebenkosten wie Grundsteuer, Wohngebäudeversicherung und eventuell Hausgeld oder Instandhaltungsrücklagen hinzu.",
    "What does PITI stand for?": "Wofür steht die Abkürzung PITI?",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a total monthly mortgage payment when using an escrow account.": "Die Gesamtwohnkosten einer finanzierten Immobilie umfassen Zins (Finanzierungskosten), Tilgung (Kreditrückzahlung), Grundsteuer sowie Gebäudeversicherungen und Betriebskosten.",
    "How much should I contribute to my 401(k)?": "Wie viel sollte ich monatlich für die Altersvorsorge sparen?",
    "Most financial advisors recommend contributing at least 15% of your gross annual salary toward retirement (including employer matching). At a minimum, always contribute enough to capture your employer's full matching contribution—missing the match is walking away from free money and an instant 50% to 100% return. For 2024, the IRS employee elective deferral limit is $23,000 per year, or $30,500 if you are age 50 or older.": "Finanzexperten empfehlen, mindestens 15 % des Bruttoeinkommens für die Altersvorsorge zurückzulegen (einschließlich Arbeitgeberzuschüssen). Schöpfen Sie stets mindestens den vollen Arbeitgeberzuschuss der betrieblichen Altersversorgung (bAV) aus, da dies einer sofortigen risikofreien Rendite entspricht.",
    "How does this 401(k) calculator with match calculate employer contributions?": "Wie berechnet dieser Vorsorgerechner den Arbeitgeberzuschuss?",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% or 100%) up to your company's matching ceiling (e.g., up to 6% of salary). For example, on a $95,000 salary with a 6% contribution ($5,700), a 50% match adds an extra $2,850/year in employer deposits. The calculator projects both your personal deferrals and employer matching contributions compounded across your entire retirement horizon.": "Der Rechner berücksichtigt den prozentualen Zuschuss des Arbeitgebers (z. B. 50 % oder 100 %) bis zur unternehmensspezifischen Obergrenze und verzinst sowohl Ihre Eigenbeiträge als auch die Arbeitgeberzuschüsse über die gesamte Laufzeit.",
    "How much should I have in my 401(k) by age?": "Wie viel Altersvorsorgekapital sollte man je nach Lebensalter aufgebaut haben?",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30; 2x by age 35; 3x by age 40; 4x by age 45; 6x by age 50; 8x by age 60; and 10x your final salary by age 67. If you earn $90,000 at age 40, your target 401(k) balance is approximately $270,000 to remain on track for complete income replacement.": "Als Daumenregel gilt: Mit 30 Jahren etwa 1 Jahresbruttogehalt, mit 40 Jahren das Dreifache, mit 50 Jahren das Sechsfache und zum Renteneintritt mit 67 Jahren etwa das Zehnfache des Jahresbruttoeinkommens im Depot oder in Vorsorgevermögen.",
    "Should I do a Roth or Traditional 401(k)?": "Sollte ich steuerbegünstigt vor oder nach Steuern vorsorgen?",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income and federal tax liability today; withdrawals in retirement are taxed as ordinary income. In a Roth 401(k), you contribute after-tax dollars, but your investment earnings grow completely tax-free and all qualified distributions in retirement are 100% tax-free. If you are in a low tax bracket now (early career), choose Roth; if you are currently in your peak earning years and highest tax bracket, choose Traditional.": "Bei einer steuerbegünstigten Entgeltumwandlung (wie der bAV) sparen Sie aus dem Bruttogehalt, mindern heute Ihre Steuerlast und versteuern die Rente erst im Alter (nachgelagerte Besteuerung). Bei privaten Sparplänen (wie ETF-Depots) investieren Sie aus dem versteuerten Netto, profitieren im Alter aber von steuerlichen Teilfreistellungen.",
    "How much does a 401(k) contribution reduce my taxes?": "Wie stark senken Altersvorsorgebeiträge die laufende Steuerlast?",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income dollar-for-dollar. The tax savings formula is: Annual Contribution × Marginal Tax Rate. For example, contributing $10,000 at a 24% federal tax bracket plus 5% state tax saves $2,900 in total taxes. Your take-home pay only drops by $7,100 while your retirement nest egg grows by a full $10,000.": "Jeder Euro, der vor Steuern in die Altersvorsorge fließt, verringert das zu versteuernde Einkommen direkt. Die Steuerersparnis entspricht dem Beitrag multipliziert mit Ihrem persönlichen Grenzsteuersatz.",
    "How much will my 401(k) be worth at retirement?": "Wie viel Vermögen kommt bis zum Renteneintritt zusammen?",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, and time. For example, contributing $600 per month starting at age 30 with a $25,000 starting balance and an average 7.5% annual return yields approximately $1,350,000 by age 65. The vast majority of this total (over 70%) comes from compound investment growth rather than out-of-pocket deposits.": "Das Endvermögen hängt entscheidend von Anlagedauer, Sparrate und Zinseszins ab. Bei einer monatlichen Sparrate von 500 € über 35 Jahre bei 7 % Rendite wächst das Vermögen auf über 880.000 € an – wovon mehr als 75 % rein aus erwirtschafteten Zinsen und Kursgewinnen stammen.",
    "How long will my 401(k) last in retirement?": "Wie lange reicht das angesparte Kapital im Ruhestand?",
    "Can I cancel my 401(k) and cash out while still employed?": "Kann ich Vorsorgebeiträge stoppen oder vorzeitig auflösen?",
    "How does the Dave Ramsey 401(k) calculator 15% rule work?": "Wie funktioniert die 15%-Sparregel nach Dave Ramsey?",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into retirement once consumer debt is eliminated and a 3-to-6 month emergency fund is established. The Dave Ramsey 401k calculator strategy follows a 3-step order: (1) Invest in your company 401(k) up to the full employer match; (2) Max out a Roth IRA; (3) Put any remaining portion of the 15% into your Roth 401(k) or Traditional 401(k). Use our 'Dave Ramsey (15% Rule)' preset to model this exact path.": "Nach dem 'Baby Step 4' investiert man 15 % des Bruttoeinkommens in die Altersvorsorge, sobald Konsumschulden vollständig getilgt sind und ein Notgroschen von 3 bis 6 Monatsausgaben aufgebaut wurde.",
    "What is a SIMPLE 401(k) calculator and who qualifies for a SIMPLE plan?": "Was sind vereinfachte Altersvorsorgemodelle für Kleinbetriebe?",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. A simple 401k calculator models the required employer contributions: either a dollar-for-dollar match up to 3% of salary, or a flat 2% non-elective contribution for all eligible workers. SIMPLE 401(k) plans feature 100% immediate vesting, no complex nondiscrimination testing, and lower contribution limits ($16,000 in 2024, or $19,500 if age 50+).": "Für kleine Unternehmen existieren vereinfachte Modelle der betrieblichen Altersversorgung mit festen Arbeitgeberzuschüssen ohne hohen Verwaltungsaufwand.",
    "What is Future Value (FV)?": "Was ist der Endwert (Future Value / FV)?",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or compounding interest.": "Der Endwert (Future Value) beziffert den Betrag, auf den ein heutiger Geldbetrag oder eine Reihe regelmäßiger Zahlungen bis zu einem zukünftigen Zeitpunkt bei einem bestimmten Zinseszins anwächst.",
    "What is the formula for calculating Future Value with regular contributions?": "Wie lautet die Formel zur Endwertberechnung mit regelmäßigen Sparraten?",
    "For a lump sum with regular periodic additions: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], where PV is present value, r is annual interest rate, m is compounding frequency per year, t is time in years, and PMT is periodic contribution.": "Für eine Einmalanlage mit periodischen Sparraten lautet die Formel: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], wobei PV der Barwert, r der Jahreszins, m die jährliche Zinseszinsfrequenz, t die Laufzeit in Jahren und PMT die monatliche Sparrate ist.",
    "What is the difference between an ordinary annuity and annuity due for future value?": "Was unterscheidet nachschüssige und vorschüssige Zahlungsweisen beim Endwert?",
    "In an ordinary annuity, contributions are deposited at the end of each period. In an annuity due, contributions are made at the beginning of each period, which gives every contribution an extra period to compound and results in a higher ending future value.": "Bei nachschüssiger Zahlung erfolgt die Einzahlung am Ende jeder Periode. Bei vorschüssiger Zahlung erfolgt sie zu Beginn der Periode, wodurch jede Einzahlung eine Zinsperiode länger verzinst wird und ein höherer Endwert resultiert.",
    "How does compounding frequency impact the future value of an investment?": "Wie wirkt sich die Zinseszinsfrequenz auf das Endergebnis aus?",
    "More frequent compounding cycles (such as monthly or daily versus annually) result in higher future values because interest earned in earlier cycles begins generating its own interest sooner.": "Häufigere Zinsgutschriften (wie monatlich oder täglich statt jährlich) führen zu einem höheren Endkapital, da Zinserträge früher dem Kapitalstock zufließen und Zinseszinsen erwirtschaften.",
    "What is a realistic annual rate of return for an investment calculator?": "Welche jährliche Rendite ist für Investitionsberechnungen realistisch?",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of approximately 10% annually over long multi-decade horizons (or roughly 7% after adjusting for inflation). A diversified portfolio of stocks and bonds typically targets 6% to 8% nominal annual return.": "Historisch betrachtet erzielte ein breit diversifiziertes globales Aktienportfolio (wie der MSCI World) über Anlagezeiträume von 15+ Jahren eine durchschnittliche Nominalrendite von ca. 7 % bis 9 % p.a. Nach Abzug von Inflation und Produktkosten ist eine reale Rendite von 5 % bis 7 % eine solide Planungsgrundlage.",
    "How do regular recurring investments compare to a one-time lump sum?": "Wie schneidet ein regelmäßiger Sparplan im Vergleich zu einer Einmalanlage ab?",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility by consistently purchasing shares at both market highs and lows. While lump-sum investing mathematically outperforms about 68% of the time due to long-term market upward trends, recurring monthly deposits instill discipline and build substantial wealth steadily.": "Regelmäßige Sparraten (Cost-Average-Effekt) mindern das Timing-Risiko und emotionale Fehlentscheidungen, indem sowohl in Hoch- als auch in Tiefphasen Anteile erworben werden. Einmalanlagen schneiden statistisch in rund zwei Dritteln der Fälle besser ab, da Märkte langfristig steigen; Sparpläne bieten jedoch maximale Disziplin und Praxistauglichkeit.",
    "What is the difference between nominal return and real return?": "Was ist der Unterschied zwischen Nominalrendite und Realrendite?",
    "How does compound interest multiply investment portfolios over time?": "Wie vervielfacht der Zinseszinseffekt das Anlageportfolio im Zeitverlauf?",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contributions make up the majority of your balance; however, after 10 to 20 years, investment returns and compounded earnings account for over 60% to 80% of total portfolio value.": "Zinseszinsen erzeugen ein exponentielles Wachstum. In den ersten Jahren stammen die Zuwächse primär aus eigenen Einzahlungen. Nach 15 bis 25 Jahren machen die reinvestierten Erträge und Zinseszinsen jedoch über 70 % bis 80 % des gesamten Vermögens aus.",
    "How do I calculate a percentage salary increase?": "Wie berechnet man eine prozentuale Gehaltserhöhung?",
    "To calculate the percentage increase: subtract your old salary from your new salary, divide the difference by your old salary, and multiply by 100: ((New - Old) / Old) × 100. For example, moving from $75,000 to $82,500 is (($82,500 - $75,000) / $75,000) × 100 = 10%.": "Subtrahieren Sie Ihr bisheriges Gehalt vom neuen Gehalt, teilen Sie die Differenz durch das bisherige Gehalt und multiplizieren Sie mit 100: ((Neues Gehalt - Altes Gehalt) / Altes Gehalt) × 100. Ein Sprung von 50.000 € auf 55.000 € entspricht somit genau 10 % Gehaltserhöhung.",
    "How much of my salary raise will I actually take home after taxes?": "Wie viel von der Gehaltserhöhung kommt netto tatsächlich auf dem Konto an?",
    "Your net take-home boost depends on your marginal tax bracket and payroll deductions. Because raises are taxed at your highest marginal rate rather than your lower average rate, you typically take home between 55% and 75% of your gross increase (depending on state taxes and FICA).": "Ihr tatsächlicher Netto-Zuwachs richtet sich nach Ihrem persönlichen Grenzsteuersatz und den Sozialversicherungsbeiträgen. Da die Erhöhung mit dem jeweils höchsten Steuersatz versteuert wird, verbleiben bei durchschnittlichen Einkommen in der Regel zwischen 50 % und 65 % der Bruttoerhöhung als Netto-Auszahlung.",
    "What is the difference between a merit raise and a cost-of-living adjustment (COLA)?": "Was unterscheidet eine Leistungsanpassung von einem Inflationsausgleich?",
    "A Cost of Living Adjustment (COLA) is an across-the-board raise (typically 2% to 4%) designed to keep your purchasing power level with consumer inflation. A merit or performance raise is an individualized increase rewarded for outstanding work, increased duties, or hitting high performance benchmarks.": "Ein Inflationsausgleich dient der reinen Sicherung der realen Kaufkraft gegenüber den Verbraucherpreisen. Eine Leistungszulage oder Gehaltserhöhung spiegelt hingegen erweiterte Verantwortung, gestiegene Qualifikation und persönliche Zielerreichung wider.",
    "How often should you ask for a salary increase?": "Wie oft sollte man über eine Gehaltserhöhung verhandeln?",
    "Standard corporate practice evaluates compensation annually during performance reviews. However, you should initiate compensation discussions whenever you take on significantly expanded responsibilities, complete major high-value certifications, or outperform annual targets by a substantial margin.": "In den meisten Unternehmen finden Gehaltsgespräche im jährlichen Turnus statt. Ein Gespräch empfiehlt sich jedoch auch immer dann, wenn Sie dauerhaft zusätzliche Führungs- oder Projektverantwortung übernommen oder herausragende Ergebnisse erzielt haben.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "Eine typische Monatsrate besteht aus Zins und Tilgung (Kapitaldienst), Grundsteuer, Wohngebäudeversicherung, ggf. Restschuld- oder Risikolebensversicherung sowie Nebenkosten und Hausgeld.",
    "What is PMI and when do I pay it?": "Was ist eine Hypothekenversicherung (PMI) und wann fällt sie an?",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "Die Private Mortgage Insurance (PMI) schützt das Kreditinstitut vor Kreditausfällen. Sie wird fällig, wenn das eingebrachte Eigenkapital unter 20 % des Kaufpreises liegt.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI steht für Tilgung (Principal), Zinsen (Interest), Steuern (Taxes) und Versicherungen (Insurance) – die vier Kernkomponenten der monatlichen Immobilienbetriebskosten.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Ist eine 15-jährige Zinsbindung besser als eine 30-jährige?",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "15 Jahre bieten günstigere Zinsen und schnellere Entschuldung, 30 Jahre bieten geringere Monatsraten und mehr finanziellen Spielraum.",
    "How do extra payments affect my mortgage payoff schedule?": "Wie wirken sich Sondertilgungen auf die Baufinanzierung aus?",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Jede Sondertilgung wird unmittelbar mit der verbleibenden Restschuld verrechnet. Dies senkt die künftige Zinsbelastung, verkürzt die Kreditlaufzeit oft um mehrere Jahre und spart beträchtliche Zinskosten.",
    "What is the Debt Snowball method?": "Was ist die Schneeball-Methode zum Schuldenabbau?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Sie tilgen die Kredite mit den kleinsten Restbeträgen zuerst, unabhängig vom Zinssatz. Schnelle Erfolge schaffen psychologische Motivation zum Weitermachen.",
    "What is the Debt Avalanche method?": "Was ist die Lawinen-Methode zum Schuldenabbau?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Sie tilgen Verbindlichkeiten mit den höchsten Zinsen zuerst. Rein rechnerisch minimiert dies die Zinslast und führt am schnellsten zur Schuldenfreiheit.",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Welche Methode ist besser: Schneeball oder Lawine?",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Mathematisch ist die Lawinen-Methode überlegen, da sie durch Priorisierung der teuersten Zinsen die Gesamtkosten minimiert. In der Praxis ist die Schneeball-Methode jedoch oft erfolgreicher, weil schnelle Tilgungserfolge bei kleinen Krediten die Motivation aufrechterhalten.",
    "How does the 'extra payment' roll over in these strategies?": "Wie wird der zusätzliche Tilgungsbetrag weitergegeben?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Bei beiden Methoden zahlen Sie zunächst die Mindestraten aller Kredite. Überschüssiges Budget fließt in den primären Fokuskredit. Sobald dieser getilgt ist, wird dessen gesamte Rate auf den nächsten Kredit übertragen – wie ein Schneeball, der anwächst.",
    "Can I do a hybrid of Snowball and Avalanche?": "Kann man Schneeball- und Lawinen-Methode kombinieren?",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Ja. Viele tilgen zuerst ein oder zwei kleine Kredite, um schnelle Erfolgserlebnisse zu verbuchen und monatlichen Cashflow freizusetzen (Schneeball), und wechseln danach zur Tilgung nach dem höchsten Zinssatz (Lawine).",
    "When should I refinance my loan?": "Wann lohnt sich eine Umschuldung oder Anschlussfinanzierung?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Eine Umschuldung lohnt sich in der Regel, wenn Sie einen spürbar niedrigeren Zinssatz erhalten, die monatliche Rate senken oder die Laufzeit verkürzen können – vorausgesetzt, die Zinsersparnis übersteigt eventuelle Vorfälligkeitsentschädigungen oder Wechselkosten.",
    "What closing costs are associated with refinancing?": "Welche Kosten fallen bei einer Kreditumschuldung an?",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Mögliche Nebenkosten umfassen Bearbeitungsgebühren, Notar- und Grundbuchkosten für die Abtretung von Grundschulden sowie etwaige Vorfälligkeitsentschädigungen der bisherigen Bank. Sie betragen meist 1 % bis 3 % der Restsumme.",
    "How do I calculate my refinance break-even point?": "Wie berechnet man den Amortisationszeitpunkt (Break-Even)?",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Teilen Sie die gesamten Umschuldungsnebenkosten durch die monatliche Ratenersparnis. Beispiel: Bei 1.500 € Nebenkosten und 75 € Ersparnis pro Monat ist der Break-Even nach 20 Monaten erreicht (1.500 € / 75 €).",
    "What is the 28/36 rule?": "Was besagt die 28/36-Haushaltsregel?",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "Maximal 28 % des Bruttoeinkommens für Wohnen und maximal 36 % für sämtliche Schuldenverpflichtungen.",
    "How does DTI affect my mortgage application?": "Wie beeinflusst die Schuldenquote (DTI) die Darlehenszusage?",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Banken nutzen das Verhältnis von Verbindlichkeiten zu Einkommen (DTI), um Ihre finanzielle Tragfähigkeit zu prüfen. Eine DTI unter 36 % gilt als risikoarm und erhöht die Chancen auf beste Konditionen deutlich.",
    "What is the difference between front-end and back-end DTI?": "Was unterscheidet Front-End- von Back-End-DTI?",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "Front-End-DTI berücksichtigt nur die reinen Wohnkosten (Kreditrate, Grundsteuer, Gebäudeversicherung). Back-End-DTI umfasst alle monatlichen Zahlungsverpflichtungen zusammen (Wohnen plus Ratenkredite, Kreditkarten und Unterhalt).",
    "How can I lower my Debt-to-Income ratio?": "Wie kann ich meine persönliche Schuldenquote senken?",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Indem Sie Ihr Bruttoeinkommen steigern oder bestehende monatliche Verbindlichkeiten tilgen. Besonders das vollständige Abzahlen kleinerer Kredite senkt die monatliche Ratenlast sofort spürbar.",
    "What is the SAVE plan?": "Was ist das einkommensabhängige SAVE-Rückzahlungsmodell?",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "Der SAVE-Plan schützt das Einkommen bis zu 225 % der Armutsgrenze, senkt Raten auf 5-10 % des verfügbaren Einkommens und stoppt das Anwachsen nicht bezahlter Zinsen.",
    "How is discretionary income calculated for student loans?": "Wie wird das frei verfügbare Einkommen bei Studienkrediten berechnet?",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "Es ist die Differenz zwischen dem bereinigten Bruttoeinkommen und dem gesetzlichen Existenzminimum multipliziert mit der Familiengröße.",
    "How do I calculate stock returns?": "Wie berechnet man die Gesamtrendite einer Aktie?",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Ziehen Sie den Kaufpreis vom Verkaufspreis ab (Kursgewinn), addieren Sie alle erhaltenen Dividenden, teilen Sie das Ergebnis durch den Kaufpreis und multiplizieren Sie mit 100 für den prozentualen Ertrag.",
    "What is CAGR in stock returns?": "Was bedeutet CAGR bei Aktien?",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "CAGR steht für Compound Annual Growth Rate (durchschnittliche jährliche Wachstumsrate). Sie beschreibt die geglättete jährliche Rendite einer Anlage über einen bestimmten Zeitraum unter Berücksichtigung des Zinseszinseffekts.",
    "What is the Capital Asset Pricing Model (CAPM)?": "Was ist das Capital Asset Pricing Model (CAPM)?",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "CAPM ist ein finanzmathematisches Bewertungsmodell, das die erwartete Rendite eines Wertpapiers anhand seines systematischen Marktrisikos (Beta) im Verhältnis zum risikofreien Zinssatz und der Marktrisikoprämie schätzt.",
    "What does Asset Beta (β) represent?": "Was misst das Beta (β) einer Aktie?",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Beta misst die Schwankungsbreite (Volatilität) eines Wertpapiers im Vergleich zum Gesamtmarkt. Ein Beta von 1,0 bedeutet marktkonforme Bewegung, über 1,0 höhere Volatilität und unter 1,0 geringere Kursschwankungen.",
    "What is net worth?": "Was ist das persönliche Nettovermögen?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "Der Gesamtwert aller Vermögenswerte abzüglich sämtlicher Verbindlichkeiten und Schulden.",
    "How much emergency fund is recommended?": "Wie hoch sollte der Notgroschen sein?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Empfohlen werden 3 bis 6 Monatsausgaben an lebensnotwendigen Kosten auf einem Tagesgeldkonto.",
    "What is an expense ratio?": "Was ist die Gesamtkostenquote (TER)?",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Die Total Expense Ratio (TER) gibt die jährlichen Verwaltungskosten eines Fonds oder ETFs als Prozentsatz des investierten Vermögens an (z. B. 0,15 % = 1,50 € pro 1.000 € Anlagebetrag).",
    "What is Dollar-Cost Averaging (DCA)?": "Was ist der Durchschnittskosteneffekt (DCA / Sparplan)?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "Regelmäßiges Investieren fester Beträge zur Glättung von Kursschwankungen und Ausschaltung von Emotionen.",
    "What is inflation?": "Was ist Inflation?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "Der anhaltende Anstieg des allgemeinen Preisniveaus und der damit einhergehende Verlust der Kaufkraft.",
    "What is the key difference between a Roth and Traditional IRA?": "Was unterscheidet ein traditionelles IRA von einem Roth IRA?",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "Beim traditionellen IRA sind Einzahlungen heute steuerlich abzugsfähig und im Alter steuerpflichtig; beim Roth IRA erfolgt die Anlage aus versteuertem Einkommen mit lebenslanger Steuerfreiheit auf Erträge.",
    "How does debt consolidation save you money?": "Wie spart eine Umschuldung (Schuldenkonsolidierung) Geld?",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "Durch die Zusammenfassung mehrerer teurer Kredite (z. B. Dispositions- und Kreditkartenschulden mit 12 %–20 % Zinsen) in einem einzigen Ratenkredit mit niedrigerem Festzins (z. B. 5 %–8 %) sinkt die monatliche Rate und Sie sparen Tausende Euro an Zinskosten.",
    "Does debt consolidation hurt your credit score?": "Beeinträchtigt eine Kreditumschuldung die Bonität (Schufa)?",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Die Kreditanfrage kann den Score kurzfristig minimal beeinflussen. Das Ablösen mehrerer offener Kreditlinien verbessert jedoch das Kreditauslastungsverhältnis, was die Bonität in der Regel binnen 1 bis 2 Monaten deutlich steigert.",
    "What is the difference between debt consolidation and debt settlement?": "Was unterscheidet Umschuldung von Schuldenvergleich oder Insolvenz?",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "Eine Umschuldung begleicht alle Forderungen vollständig über ein neues Darlehen ohne Bonitätsschaden. Ein Schuldenvergleich oder Erlassversuch stoppt Zahlungen, um Gläubiger zu Verzicht zu bewegen, was zu schweren, jahrelangen Bonitätseinträgen führt.",
    "What should I look out for before consolidating debt?": "Worauf sollte man vor einer Umschuldung achten?",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Achten Sie auf Bearbeitungskosten oder Vorfälligkeitsentschädigungen, stellen Sie sicher, dass die neue Monatsrate dauerhaft tragbar ist, und vermeiden Sie es, abbezahlte Kreditkarten oder Dispokredite erneut zu belasten.",
    "What is daily compound interest and how does it work?": "Was ist täglicher Zinseszins und wie funktioniert er?",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Beim täglichen Zinseszins werden die Zinsen an jedem Tag (365 Mal im Jahr) berechnet und dem Guthaben zugeschlagen. An Folgetagen verzinst sich somit sowohl das Anfangskapital als auch der aufgelaufene Zinsgewinn, was das Vermögenswachstum exponentiell beschleunigt.",
    "What is the formula for daily compound interest?": "Wie lautet die mathematische Formel für täglichen Zinseszins?",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "Die Zinseszinsformel lautet A = P × (1 + r/365)^(365 × t), wobei P das Anfangskapital, r der Jahreszinssatz (als Dezimalzahl) und t die Anlagedauer in Jahren ist. Bei laufenden Sparraten wird der Zins täglich fortgeschrieben.",
    "How much more money do you earn with daily vs monthly compounding?": "Wie viel Mehrertrag bringt tägliche gegenüber monatlicher Verzinsung?",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Bei einem Anlagebetrag von 100.000 € zu 7 % über 20 Jahre ergibt die tägliche Verzinsung 405.514 € gegenüber 403.873 € bei monatlicher Verzinsung – das sind 1.641 € reiner Mehrertrag nur durch die Zinsfrequenz.",
    "Do high-yield savings accounts (HYSA) compound daily?": "Verzinsen Tagesgeldkonten das Guthaben täglich?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Ja, die überwiegende Mehrheit der modernen Tagesgeldkonten und Geldmarktfonds verzinst das Guthaben taggenau (Valuta) und schreibt den Ertrag monatlich oder quartalsweise gut.",
    "What is the FIRE movement and what does it mean?": "Was bedeutet die FIRE-Bewegung?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE steht für 'Financial Independence, Retire Early' (Finanzielle Freiheit, früher Ruhestand). Ziel ist eine hohe Sparquote (40 %–70 %) und langfristiges Investieren in breit gestreute ETFs, bis das Vermögen alle Lebenshaltungskosten dauerhaft passiv deckt.",
    "What is the 4% Safe Withdrawal Rule?": "Was besagt die 4-%-Regel zur sicheren Entnahme?",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Basierend auf der renommierten Trinity-Studie besagt die 4-%-Regel, dass Sie jährlich 4 % Ihres Startportfolios (jährlich inflationsbereinigt) entnehmen können, mit einer Wahrscheinlichkeit von über 95 %, dass das Vermögen über einen 30-jährigen Ruhestand niemals aufgebraucht wird.",
    "How is your FIRE Number calculated?": "Wie wird die persönliche FIRE-Vermögenssumme berechnet?",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Die FIRE-Zahl entspricht Ihren jährlichen Ausgaben multipliziert mit 25 (bei einer Entnahmerate von 4 %) oder multipliziert mit 33 (bei konservativeren 3 %). Bei jährlichen Kosten von 48.000 € liegt das Zielvermögen bei 1.200.000 €.",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Was unterscheidet Lean FIRE, Standard FIRE und Fat FIRE?",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Lean FIRE zielt auf frugalen, minimalistischen Lebensstil mit niedrigen Ausgaben ab. Standard FIRE finanziert einen komfortablen bürgerlichen Lebensstandard. Fat FIRE erlaubt gehobenen Lebenskomfort, Reisen und Konsum ohne Budgetbeschränkungen.",
    "When is the earliest age I can claim Social Security retirement benefits?": "Ab welchem Alter ist ein vorzeitiger Rentenantritt möglich?",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "In Systemen wie der US Social Security ist der Renteneintritt ab 62 Jahren möglich, führt jedoch zu lebenslangen Abschlägen von bis zu 30 % gegenüber dem Erreichen der regulären Regelaltersgrenze.",
    "What is my Full Retirement Age (FRA)?": "Was ist das reguläre Renteneintrittsalter?",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Für Personen mit Geburtsjahrgang 1960 oder später liegt das reguläre Renteneintrittsalter bei 67 Jahren. Wer erst zu diesem Zeitpunkt in Rente geht, erhält 100 % der vollen Ansprüche ohne lebenslange Rentenkürzung.",
    "How much more do I get if I delay claiming Social Security until age 70?": "Wie viel höher fällt die Rente aus, wenn man den Ruhestand bis 70 aufschiebt?",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Für jedes Jahr des Hinausschiebens über das reguläre Rentenalter hinaus steigt der Rentenanspruch um ca. 8 % pro Jahr. Ein Rentenbeginn mit 70 Jahren sichert so dauerhaft rund 124 % der ursprünglichen Regelrente.",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "In welchem Alter liegt der Break-Even-Punkt zwischen Frührente und spätem Rentenbeginn?",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "Der lebenslange Break-Even-Punkt liegt typischerweise zwischen 78 und 81 Jahren. Wer älter als 80 wird, erzielt durch den aufgeschobenen Rentenbeginn eine deutlich höhere kumulierte Gesamtauszahlung.",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Was ist die gesetzliche Rentenabgabe in Australien (Superannuation SG)?",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Nach australischem Recht sind Arbeitgeber verpflichtet, einen gesetzlich festgelegten Prozentsatz des Bruttogehalts in den persönlichen Altersvorsorgefonds (Super) der Beschäftigten einzuzahlen. Der Satz steigt schrittweise auf 12 %.",
    "How is money inside Australian Super taxed?": "Wie wird das Vorsorgekapital im australischen Rentenfonds besteuert?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Steuerbegünstigte Beiträge (einschließlich Arbeitgeberbeiträge und Gehaltsumwandlung) werden im Fonds pauschal mit nur 15 % versteuert – deutlich weniger als der persönliche Grenzsteuersatz von bis zu 45 %.",
    "How much super do I need for a comfortable retirement in Australia?": "Wie viel Vorsorgekapital wird für einen komfortablen Ruhestand benötigt?",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Nach dem ASFA-Altersvorsorgestandard benötigt ein Alleinstehender mit 67 Jahren ein Fondsguthaben von rund 595.000 AUD und ein Paar rund 690.000 AUD, um einen komfortablen Lebensstandard im Alter zu finanzieren.",
    "How does salary sacrificing boost superannuation growth?": "Wie beschleunigt die Entgeltumwandlung (Salary Sacrifice) den Vermögensaufbau?",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "Bei der Entgeltumwandlung fließen Gehaltsteile vor Steuern direkt in die Altersvorsorge. Durch die Ersparnis beim persönlichen Einkommensteuersatz und den jahrzehntelangen Zinseszinseffekt wächst das Endvermögen um sechsstellige Zusatzbeträge.",
    "How does student loan forgiveness work under IDR plans?": "Wie funktioniert der Schuldenerlass bei einkommensabhängigen Krediten?",
    "If you pay under an IDR plan for 20 or 25 years (or as little as 10 years under SAVE for low initial balances), any remaining student debt is forgiven. However, under current tax laws, this forgiven balance may be treated as taxable income, although federal tax on forgiven student loans is temporarily suspended through 2025.": "Nach 20 bis 25 Jahren regelmäßiger einkommensabhängiger Zahlungen wird die verbleibende Restschuld vollständig erlassen.",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest. Over time, an increasing portion goes toward paying down the principal balance until the debt is fully paid off.": "Bei einem Annuitätendarlehen zahlen Sie konstante Raten. Anfangs überwiegt der Zinsanteil; mit sinkender Restschuld steigt der Tilgungsanteil kontinuierlich bis zur vollständigen Rückzahlung.",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the loan term. A variable-rate loan has an interest rate that adjusts periodically based on benchmark interest rates, which can increase or decrease your payments.": "Ein Festzinskredit garantiert feste Zinssätze und gleichbleibende Raten über die gesamte Sollzinsbindung; variable Kredite passen sich regelmäßig dem Marktzinsniveau an.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, but some lenders include a prepayment penalty clause. Always verify your loan agreement terms before making accelerated principal payments.": "Bei Ratenkrediten sind Sondertilgungen oft kostenlos, bei Baudarlehen verlangen Banken außerhalb vertraglicher Sondertilgungsrechte meist eine Vorfälligkeitsentschädigung.",
    "What is the difference between interest rate and APR?": "Was ist der Unterschied zwischen Sollzins und effektivem Jahreszins (APR)?",
    "The interest rate is the nominal cost of borrowing the principal balance. The Annual Percentage Rate (APR) reflects the total annual cost of the loan including points, broker fees, and origination charges.": "Der Sollzins beziffert nur die reine Zinszahlung; der Effektivzins (APR) beinhaltet zusätzlich alle Bearbeitungsgebühren, Vermittlungskosten und Nebenspesen.",
    "What is the 4% rule in retirement planning?": "Was besagt die 4-Prozent-Regel für den Ruhestand?",
    "The 4% rule suggests that withdrawing 4% of your retirement portfolio in the first year, adjusted for inflation annually thereafter, provides a high probability that your nest egg will last at least 30 years.": "Wer im ersten Rentenjahr 4 % seines Kapitals entnimmt und den Betrag künftig nur um die Inflation anpasst, hat eine hohe Wahrscheinlichkeit, dass das Vermögen mindestens 30 Jahre reicht.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It causes your wealth to grow exponentially over time.": "Zinsen werden nicht nur auf das Startkapital berechnet, sondern auch auf bereits gutgeschriebene Zinserträge früherer Perioden, was zu exponentiellem Vermögenswachstum führt.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your annual interest rate (e.g. at 8%, your money doubles in about 9 years).": "Eine Faustformel zur Berechnung der Verdopplungszeit von Kapital: 72 geteilt durch den Zinssatz (bei 8 % Zinsen verdoppelt sich das Geld in ca. 9 Jahren).",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price.": "Man investiert in festen Zeitabständen stets denselben Geldbetrag, unabhängig vom aktuellen Börsenkurs des Vermögenswerts.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility.": "Ein Darlehen mit 15 Jahren Laufzeit bietet meist günstigere Zinsen und halbiert die Entschuldungszeit, was erhebliche Zinskosten spart; 30 Jahre bieten jedoch niedrigere Monatsraten und mehr Liquiditätsspielraum.",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule.": "Sondertilgungen fließen direkt in die Rückzahlung der Restschuld. Dadurch sinkt der verbleibende Zinsaufwand rapide, sodass die Immobilie viele Jahre früher schuldenfrei wird.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum helps people stick to their plan.": "Mathematisch ist die Lawinen-Methode überlegen, in der Praxis führt der Schneeball durch frühe Erfolgserlebnisse jedoch oft verlässlicher zum Ziel.",
    "You continue paying minimums on all debts and add your extra cash to the target debt. Once that target debt is fully paid off, you roll its entire payment into the next debt on your list.": "Sie zahlen überall die Mindestraten und bündeln alle Überschüsse auf die Zielforderung. Ist diese getilgt, übertragen Sie das frei gewordene Budget auf den nächsten Kredit.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate (Avalanche).": "Ja. Viele tilgen anfangs ein oder zwei Minikredite für sofortige Erleichterung (Schneeball) und gehen danach strikt nach dem höchsten Zinssatz vor (Lawine).",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term, provided your total interest savings exceed the closing costs.": "Eine Umschuldung lohnt sich, wenn ein spürbar günstigerer Zinssatz die monatliche Belastung senkt und die Zinsersparnis sämtliche Wechselgebühren übersteigt.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees, ranging from 2% to 6% of the loan amount.": "Typisch sind Notar- und Grundbuchgebühren für die Grundschuldabtretung sowie eventuelle Vorfälligkeitsentschädigungen der alten Bank (meist 1 % bis 3 %).",
    "Divide your total refinance closing costs by your monthly payment savings. If closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150).": "Teilen Sie die gesamten Umschuldungskosten durch die monatliche Ersparnis. Bei 3.000 € Kosten und 150 € Ersparnis/Monat ist der Break-Even nach 20 Monaten erreicht.",
    "What is a 'no-closing-cost' refinance?": "Was bedeutet eine Umschuldung 'ohne Abschlusskosten'?",
    "A no-closing-cost refinance means the lender either rolls the closing fees into your new total loan balance or charges a slightly higher interest rate to cover them.": "Die Kosten entfallen nicht, sondern werden auf den Darlehensbetrag aufgeschlagen oder über einen geringfügig höheren Zinssatz einkalkuliert.",
    "Does refinancing lower my monthly payment or total interest?": "Senkt eine Umschuldung die Monatsrate oder die Gesamtzinsen?",
    "It depends on the term. Refinancing to a lower rate with the same or shorter term saves on both. Resetting your term back to 30 years lowers the monthly payment but can increase total lifetime interest.": "Bei gleicher oder kürzerer Laufzeit sinken sowohl Rate als auch Gesamtzinsen; verlängert man die Laufzeit stark, sinkt die Rate, die Zinslast über die Zeit kann jedoch steigen.",
    "The Saving on a Valuable Education (SAVE) plan is an income-driven repayment (IDR) plan that protects discretionary income up to 225% of the poverty line, lowers payments to 5%-10%, and stops unpaid interest from accumulating.": "Ein US-amerikanisches Rückzahlungsmodell für Studienkredite, das das geschützte Einkommen auf 225 % der Armutsgrenze anhebt und Raten auf 5 % bis 10 % begrenzt.",
    "If you pay under an IDR plan for 20 or 25 years (or 10 years under SAVE for low initial balances), any remaining student debt is forgiven.": "Nach 20 bis 25 Jahren regelmäßiger Ratenzahlung (bei geringen Kreditsummen im SAVE-Plan teils nach 10 Jahren) wird die verbleibende Restschuld vollständig erlassen.",
    "Which IDR plan is best for me?": "Welcher einkommensabhängige Tilgungsplan ist am besten?",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. Borrowers with very high incomes relative to debt may prefer PAYE or IBR due to payment caps.": "Für die meisten bietet der SAVE-Plan die niedrigste Rate; Besserverdiener bevorzugen oft PAYE oder IBR, da diese Pläne eine Ratenobergrenze haben.",
    "Can I switch student loan repayment plans at any time?": "Kann man den Tilgungsplan für Studienkredite jederzeit wechseln?",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause unpaid interest to capitalize.": "Ja, ein Wechsel ist kostenlos möglich, kann jedoch dazu führen, dass aufgelaufene Zinsen der Hauptschuld zugeschlagen werden.",
    "The 28/36 rule is a standard mortgage underwriting guideline stating that housing costs should not exceed 28% of gross monthly income, and total debt payments should not exceed 36%.": "Maximal 28 % des Bruttoeinkommens sollten für Wohnkosten aufgewendet werden und nicht mehr als 36 % für alle Kredite und Verbindlichkeiten zusammen.",
    "Lenders use DTI to measure your ability to manage monthly payments. Lower DTIs below 36% receive the most favorable mortgage terms and lowest interest rates.": "Banken prüfen die Tragfähigkeit der Raten. Eine Quote unter 36 % gilt als risikoarm und sichert erstklassige Zinskonditionen.",
    "Front-end DTI only includes housing expenses (mortgage, property tax, insurance, HOA). Back-end DTI includes housing plus all recurring debts like credit cards, auto loans, and student loans.": "Front-End-DTI umfasst nur die reinen Wohnkosten; Back-End-DTI addiert alle weiteren monatlichen Verbindlichkeiten (Autokredit, Ratenkauf, Kreditkarten).",
    "What is the maximum DTI ratio lenders will accept?": "Welche maximale Schuldenquote akzeptieren Kreditinstitute?",
    "Conventional mortgages typically prefer back-end DTIs of 36% to 43%. Government-backed loans like FHA and VA may allow DTIs up to 50% with strong compensating factors.": "Standardkredite fordern meist maximal 36 % bis 43 %; bei guter Bonität und hohem Eigenkapital werden vereinzelt bis zu 50 % bewilligt.",
    "You can lower your DTI by increasing gross income or paying off smaller debts completely to eliminate their recurring monthly minimum payments.": "Durch Erhöhung des Bruttoeinkommens oder die vollständige Tilgung kleinerer Kredite, um deren monatliche Mindestrate aus der Rechnung zu entfernen.",
    "Why is APR higher than the advertised interest rate?": "Warum ist der Effektivzins höher als der nominale Werbezins?",
    "APR is higher because it amortizes all upfront lender fees, discount points, and closing costs into the effective yearly rate, revealing the true cost of credit.": "Weil er alle einmaligen Nebenkosten und Gebühren auf die Jahresrate umlegt und so die echten Kreditkosten transparent macht.",
    "Is APR useful for comparing different loan offers?": "Eignet sich der Effektivzins zum Vergleich verschiedener Kreditangebote?",
    "Yes, APR is the best metric for comparing loan offers with different fee structures, provided you plan to keep the loan for its full term.": "Ja, der Effektivzins normiert unterschiedliche Gebührenmodelle und ist die verlässlichste Kennzahl für den Angebotsvergleich.",
    "How long do I need to stay in a home for buying to beat renting?": "Wie lange muss man in einer Immobilie wohnen, damit sich Kaufen gegenüber Mieten lohnt?",
    "Because upfront closing costs, moving fees, and commissions are substantial, homeowners usually need to stay in a property for 4 to 7 years for buying to financially outperform renting.": "Wegen hoher Kaufnebenkosten (Grunderwerbsteuer, Notar, Makler) amortisiert sich ein Immobilienkauf finanziell meist erst nach 4 bis 7 Jahren Wohndauer.",
    "What hidden costs of homeownership should renters consider?": "Welche versteckten Kosten müssen Mieter beim Eigenheimkauf beachten?",
    "Homeowners must pay property taxes, homeowners insurance, maintenance and repairs (typically 1-2% of home value annually), HOA dues, and potential capital improvement costs.": "Eigentümer tragen Grundsteuer, Gebäudeversicherungen, Instandhaltungsrücklagen (oft 1-2 % des Gebäudewerts pro Jahr) sowie Sanierungskosten.",
    "What is the opportunity cost of buying a home?": "Welche Opportunitätskosten entstehen beim Immobilienkauf?",
    "The money spent on down payment, closing costs, and ongoing property maintenance could otherwise remain invested in liquid assets like index funds that compound over time.": "Eigenkapital und Nebenkosten sind in der Immobilie gebunden und können nicht mehr am Kapitalmarkt (z. B. in ETFs) Zinseszinsen erwirtschaften.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline).": "Finanzexperten raten dazu, nicht mehr als 25 % bis 30 % des monatlichen Nettoeinkommens für Zins und Tilgung auszugeben.",
    "How does down payment size impact affordability?": "Wie wirkt sich die Eigenkapitalhöhe auf die Finanzierbarkeit aus?",
    "A larger down payment reduces your loan amount, eliminates Private Mortgage Insurance (PMI) if you put down 20%, and lowers your monthly mortgage payment.": "Mehr Eigenkapital senkt die Kreditsumme, verbessert den Beleihungsauslauf und sorgt für erstklassige Zinskonditionen der Bank.",
    "How do interest rates affect purchasing power?": "Wie stark beeinflussen Zinsänderungen das Kaufkraftbudget?",
    "Every 1% increase in mortgage interest rates reduces your home purchasing power by roughly 10% for the same monthly payment budget.": "Ein Zinsanstieg um 1 Prozentpunkt verringert das bezahlbare Immobilienbudget bei gleichbleibender Wunschrate um etwa 10 %.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total vehicle expenses under 10% of gross monthly income.": "Mindestens 20 % Anzahlung leisten, die Finanzierung auf maximal 4 Jahre (48 Monate) begrenzen und die gesamten Kfz-Kosten unter 10 % des Bruttoeinkommens halten.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk becoming 'underwater' (owing more than the vehicle is worth).": "Lange Laufzeiten drücken zwar die Monatsrate, erhöhen aber den Gesamtzins massiv und führen oft dazu, dass der Autowert unter die Restschuld sinkt.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, you risk owing more on your loan than the car's market value.": "Neuwagen verlieren im ersten Jahr bis zu 20 % ihres Werts; ohne ausreichende Anzahlung droht eine gefährliche Unterdeckung.",
    "Why does paying only the minimum take so long?": "Warum dauert die Tilgung bei Mindestrückzahlung so lange?",
    "Credit card minimum payments are often set around 1% to 2% of the balance plus accrued interest. As the balance slowly drops, the required minimum drops, extending payoff times to decades.": "Die Mindestrate deckt oft nur die Zinsen und 1 % bis 2 % der Schuld. Weil die Rate mit sinkender Schuld schrumpft, zieht sich die Tilgung über Jahrzehnte.",
    "How much faster can I pay off credit cards by paying extra?": "Wie viel bringt eine feste monatliche Mehrzahlung bei der Kreditkarte?",
    "Paying even $50 or $100 above the minimum payment can cut your payoff timeline by several years and save thousands of dollars in compounding interest charges.": "Bereits 50 € oder 100 € zusätzlich pro Monat verkürzen die Entschuldungszeit um viele Jahre und sparen beträchtliche Zinskosten.",
    "Should I use a balance transfer card to pay off debt?": "Lohnt sich eine Umschuldungskarte mit 0 % Aktionszins?",
    "A 0% APR balance transfer credit card can save significant interest if you pay off the full balance during the promotional period (typically 12-21 months) and factor in the 3%-5% transfer fee.": "Ja, wenn Sie den Saldo innerhalb der zinsfreien Frist komplett tilgen und die anfallende Übertragungsgebühr (meist 2 % bis 4 %) einkalkulieren.",
    "How much money do I need to retire comfortably?": "Wie viel Vermögen benötigt man für einen sorgenfreien Ruhestand?",
    "A common benchmark is accumulating 25 times your anticipated annual retirement expenses, or replacing 70% to 80% of your pre-retirement income.": "Als Faustregel gilt das 25-Fache der erwarteten jährlichen Ausgaben oder eine Absicherung von 70 % bis 80 % des bisherigen Nettoeinkommens.",
    "How does inflation impact retirement spending?": "Wie gefährdet die Inflation das Altersruhegeld?",
    "Inflation steadily reduces the purchasing power of your savings. At a 3% inflation rate, everyday living expenses double roughly every 24 years, requiring growing investment portfolios.": "Sie halbiert bei 3 % Teuerungsrate die Kaufkraft in ca. 24 Jahren, weshalb ein Teil des Alterskapitals zwingend rentabel angelegt bleiben muss.",
    "What is an employer 401(k) match?": "Was ist der Arbeitgeberzuschuss (Employer Match)?",
    "An employer match is money your employer contributes to your 401(k) account based on your own contributions (e.g. matching 50% of contributions up to 6% of your salary). It is effectively an instant return on your savings.": "Eine direkte finanzielle Beteiligung des Arbeitgebers an der betrieblichen Altersvorsorge, die eine sofortige risikolose Rendite auf eigene Sparbeiträge darstellt.",
    "What are the 401(k) contribution limits for 2024?": "Wie hoch sind die steuerlichen Höchstbeiträge?",
    "For 2024, the employee contribution limit is $23,000 for those under 50. Individuals aged 50 and older can contribute an additional $7,500 catch-up contribution for a total of $30,500.": "Für unter 50-Jährige liegt der Höchstbetrag bei 23.000 $, ab 50 Jahren dürfen zusätzlich 7.500 $ als Nachholbeitrag eingezahlt werden.",
    "What is the difference between Traditional 401(k) and Roth 401(k)?": "Was ist der Unterschied zwischen klassischer und Roth-Altersvorsorge?",
    "Traditional 401(k) contributions are pre-tax and reduce your current taxable income, with withdrawals taxed in retirement. Roth 401(k) contributions are post-tax, but all qualified growth and withdrawals are completely tax-free.": "Klassische Beiträge mindern das aktuelle Bruttoeinkommen steuerlich, Auszahlungen im Alter werden versteuert; Roth-Modelle nutzen Nettoeinkommen, dafür sind alle Erträge im Alter komplett steuerfrei.",
    "Which IRA plan is better for me?": "Welches Vorsorgekonto passt besser zu mir?",
    "If you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower, a Traditional IRA is better.": "Erwarten Sie im Alter einen höheren Steuersatz, lohnt sich das Roth-Modell; rechnen Sie mit einem geringeren Alterseinkommen, ist das traditionelle Modell günstiger.",
    "What are the contribution limits for IRAs in 2024?": "Wie hoch ist der jährliche Maximalbeitrag für IRAs?",
    "For 2024, the annual contribution limit for Traditional and Roth IRAs is $7,000 for individuals under age 50, and $8,000 for individuals age 50 or older.": "Der Höchstbetrag beträgt 7.000 $ pro Jahr (8.000 $ für Personen ab 50 Jahren).",
    "Are there income limits for contributing to Traditional and Roth IRAs?": "Gibt es Einkommensgrenzen für die Einzahlung?",
    "Roth IRAs have income phase-out ranges that restrict high earners. Anyone with earned income can contribute to a Traditional IRA, but tax deductibility may be limited by income and workplace retirement coverage.": "Für Roth IRAs gelten Einkommensobergrenzen für Spitzenverdiener; in traditionelle Konten darf jeder Erwerbstätige einzahlen, die steuerliche Abzugsfähigkeit variiert.",
    "Can I withdraw money from my IRA before age 59½ without penalty?": "Kann man vor dem Alter von 59½ Jahren straffrei Geld entnehmen?",
    "Roth IRA original contributions can be withdrawn at any time penalty-free. Withdrawing investment earnings early or withdrawing Traditional IRA funds before 59½ usually incurs income taxes and a 10% penalty.": "Eigene Einzahlungen im Roth IRA können jederzeit straffrei entnommen werden; bei Erträgen oder traditionellen IRAs fallen vor 59½ Steuern plus 10 % Strafgebühr an.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your effective annual yield (APY) will be, as interest starts earning interest sooner.": "Je häufiger Zinsen gutgeschrieben werden (monatlich, täglich), desto höher ist die effektive Jahresrendite (APY).",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest.": "Ein Euro heute ist mehr wert als ein Euro in der Zukunft, weil das heutige Geld sofort investiert werden kann und Rendite erwirtschaftet.",
    "What are the core components of TVM calculations?": "Welche fünf Kernvariablen bestimmen die Barwert- und Endwertrechnung?",
    "The five core variables are Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Total Number of Periods (Nper), and Periodic Payment (PMT).": "Barwert (PV), Endwert (FV), Periodenzinssatz (Rate), Laufzeit/Periodenanzahl (Nper) und periodische Zahlung/Rate (PMT).",
    "What is the difference between an ordinary annuity and annuity due?": "Was unterscheidet vorschüssige von nachschüssigen Zahlungen?",
    "In an ordinary annuity, payments occur at the end of each period. In an annuity due, payments occur at the beginning of each period, earning an extra compounding cycle of interest.": "Nachschüssige Zahlungen erfolgen am Periodenende; vorschüssige Zahlungen zu Periodenbeginn, wodurch sie eine Zinsperiode länger Erträge generieren.",
    "How is Return on Investment (ROI) calculated?": "Wie wird der Return on Investment (ROI) berechnet?",
    "ROI is calculated by subtracting the initial cost of the investment from the final value, and dividing that net gain by the initial cost: ROI = (Net Profit / Cost of Investment) × 100%.": "Nettogewinn (Endwert minus Anschaffungskosten) geteilt durch die Anschaffungskosten multipliziert mit 100: ROI = (Gewinn / Kapitaleinsatz) × 100 %.",
    "What is the difference between simple ROI and annualized ROI?": "Was unterscheidet den einfachen ROI von der annualisierten Rendite (CAGR)?",
    "Simple ROI measures total percentage return regardless of duration. Annualized ROI (CAGR) standardizes the return into a per-year geometric rate, enabling fair comparison between investments held for different lengths of time.": "Der einfache ROI misst den Gesamterfolg über die gesamte Laufzeit; die annualisierte Rendite (CAGR) normiert das Ergebnis auf ein durchschnittliches Jahreswachstum.",
    "What is considered a good ROI?": "Was gilt als gute Rendite?",
    "Historically, the broad stock market (S&P 500) has returned an average of 7% to 10% annually before inflation. Investments with higher expected returns generally involve higher risk of capital loss.": "Der breite Aktienmarkt hat historisch rund 7 % bis 10 % p.a. vor Inflation erzielt; deutlich höhere Renditeerwartungen erfordern entsprechend höhere Risiken.",
    "How do I calculate how much to save monthly for a goal?": "Wie berechnet man die monatliche Sparrate für ein festes Ziel?",
    "You divide your target savings amount by the number of months until your deadline, while factoring in the compounding interest earned on your growing balance.": "Teilen Sie die Zielsumme durch die Restmonate und berücksichtigen Sie die erwirtschafteten Zinsen auf das anwachsende Guthaben.",
    "Should I keep savings goal funds in high-yield savings or stocks?": "Gehört das Sparziel aufs Tagesgeld oder in Aktien?",
    "For goals under 3 to 5 years (like a car or home down payment), keep funds in safe, liquid instruments like High-Yield Savings Accounts (HYSA) or CDs. For goals 5+ years away, a diversified investment portfolio may be suitable.": "Für Ziele unter 3 bis 5 Jahren (Autokauf, Anzahlung) empfiehlt sich risikoarmes Tages- oder Festgeld; ab 5 Jahren Laufzeit sind breit gestreute ETFs sinnvoll.",
    "How can I stay on track with my savings goals?": "Wie erreicht man Sparziele diszipliniert?",
    "Automate recurring monthly transfers into a dedicated savings account immediately after your paycheck arrives (the 'pay yourself first' strategy).": "Richten Sie am Tag des Gehaltseingangs einen automatischen Dauerauftrag auf ein separates Sparkonto ein ('Pay yourself first').",
    "Total stock return equals capital gains (ending price minus purchase price) plus any dividends received, divided by the original purchase cost.": "Kursgewinn plus alle vereinnahmten Dividenden geteilt durch das ursprünglich eingesetzte Kaufkapital.",
    "Compound Annual Growth Rate (CAGR) measures the geometric mean annual return of a stock over multiple years, smoothing out annual market fluctuations.": "Die durchschnittliche jährliche Wachstumsrate (CAGR) glättet Kursschwankungen und zeigt die rechnerische Jahresrendite bei Reinvestition.",
    "What is the difference between simple return and annualized return?": "Was unterscheidet die absolute von der jährlichen Rendite?",
    "Simple return measures absolute percentage gain over the entire holding period, while annualized return shows the steady annual rate required to achieve that result.": "Die absolute Rendite zeigt den prozentualen Zuwachs über die gesamte Haltedauer; die annualisierte Rendite zeigt das jährliche Äquivalent.",
    "CAPM calculates an asset's expected return based on its risk relative to the overall market, using the formula: Expected Return = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate).": "Ein finanzmathematisches Modell, das die erwartete Rendite eines Wertpapiers anhand seines Marktrisikos (Beta) berechnet: Erwartete Rendite = Risikofreier Zins + Beta × Marktrisikoprämie.",
    "Beta measures an asset's volatility compared to the broader market. A beta of 1.0 indicates market-level volatility; above 1.0 indicates higher volatility, and below 1.0 indicates lower volatility.": "Es misst die Schwankungsintensität relativ zum Gesamtmarkt: Beta = 1 bedeutet Marktbewegung, Beta > 1 höhere Volatilität, Beta < 1 geringere Schwankung.",
    "What is the Risk-Free Rate?": "Was ist der risikolose Zinssatz?",
    "The risk-free rate is the theoretical rate of return of an investment with zero risk of default, typically represented by long-term government bond yields (like 10-year US Treasuries).": "Die theoretische Rendite einer Anlage ohne Ausfallrisiko, meist abgeleitet aus 10-jährigen Staatsanleihen bester Bonität (z. B. deutsche Bundesanleihen).",
    "What is the Market Risk Premium?": "Was ist die Marktrisikoprämie?",
    "The market risk premium is the additional return investors demand for choosing risky market equities over risk-free government securities.": "Die Mehrrendite, die Investoren für das Eingehen von Aktienmarktrisiken gegenüber risikofreien Staatsanleihen einfordern.",
    "What is dividend yield versus yield on cost?": "Was unterscheidet Dividendenrendite und persönliche Einstandsrendite (Yield on Cost)?",
    "Dividend yield is the annual dividend divided by the current stock price. Yield on cost is the annual dividend divided by your original purchase price, which increases as companies raise their dividends over time.": "Die Dividendenrendite bezieht sich auf den aktuellen Börsenkurs; die persönliche Einstandsrendite bezieht die Ausschüttung auf den damaligen Kaufkurs.",
    "What is a Dividend Reinvestment Plan (DRIP)?": "Was ist ein Dividenden-Wiederanlageplan (DRIP)?",
    "A DRIP automatically uses your cash dividend payments to purchase additional shares or fractional shares of the stock, compounding your share count and future payouts without commission fees.": "Ein automatisierter Service, der erhaltene Bardividenden sofort gebührenfrei in neue Aktienanteile reinvestiert, um den Zinseszins zu maximieren.",
    "Are dividend payments guaranteed?": "Sind Dividendenzahlungen garantiert?",
    "No, company boards can reduce, suspend, or eliminate dividend payouts at any time depending on company profitability and economic conditions.": "Nein, der Vorstand kann Dividendenausschüttungen je nach Geschäftslage und Liquidität jederzeit kürzen oder streichen.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a decline in the purchasing power of money.": "Der allgemeine und anhaltende Anstieg des Preisniveaus für Waren und Dienstleistungen, der den realen Geldwert mindert.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation is 3%, $100 today will only buy about $97 worth of goods next year.": "Unverzinstes Barvermögen verliert stetig an Kaufkraft; bei 3 % Inflation haben 100 € im Folgejahr nur noch die reale Kaufkraft von 97 €.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks price changes across a standard market basket of consumer goods and services.": "Primär über den Verbraucherpreisindex (VPI), der die Preisentwicklung eines repräsentativen Warenkorbs für private Haushalte erfasst.",
    "In the United States, inflation has historically averaged between 2.5% and 3.2% per year over long multi-decade horizons.": "In den westlichen Industrienationen lag sie langfristig über mehrere Jahrzehnte im Schnitt zwischen 2,0 % und 3,0 % pro Jahr.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities, Treasury Inflation-Protected Securities (TIPS), real estate, and inflation-indexed bonds.": "Durch Anlage in Sachwerte wie breit gestreute Aktien, inflationsgeschützte Staatsanleihen und werthaltige Immobilien.",
    "What is FICA tax?": "Was sind Lohnnebenkosten und Sozialabgaben?",
    "FICA is a federal payroll tax that funds Social Security (6.2% on wages up to the wage base limit) and Medicare (1.45% plus an additional 0.9% on high earners).": "Gesetzliche Pflichtabgaben zur Finanzierung von Renten-, Kranken-, Pflege- und Arbeitslosenversicherung, die direkt vom Bruttoentgelt abgezogen werden.",
    "What is the difference between pre-tax and post-tax deductions?": "Was unterscheidet steuerfreie von steuerpflichtigen Entgeltabzügen?",
    "Pre-tax deductions (like 401k and health insurance) reduce your taxable gross income before taxes are computed. Post-tax deductions (like Roth contributions or wage garnishments) are taken after taxes.": "Vorbesteuerte Abzüge (z. B. Entgeltumwandlung) mindern das zu versteuernde Einkommen direkt; nachgelagerte Abzüge erfolgen erst nach Steuerabzug vom Netto.",
    "What is the difference between gross pay and net pay?": "Was ist der Unterschied zwischen Brutto- und Nettogehalt?",
    "Gross pay is the total amount earned before any taxes or deductions. Net pay (take-home pay) is the actual cash deposited into your bank account after all deductions.": "Das Bruttogehalt ist das vertraglich vereinbarte Gesamteinkommen; das Nettogehalt ist der Auszahlungsbetrag nach Abzug aller Steuern und Sozialbeiträge.",
    "How does my W-4 filing status affect my paycheck?": "Welchen Einfluss hat die Steuerklasse auf das Nettogehalt?",
    "Your W-4 form informs your employer how much federal income tax to withhold each pay period based on your filing status, dependents, and other income.": "Sie bestimmt die Höhe des monatlichen Lohnsteuerabzugs anhand von Familienstand, Kinderfreibeträgen und Zweiteinkommen.",
    "Why do state and local taxes vary so much?": "Warum variieren regionale Steuern so stark?",
    "State income tax rates range from 0% (in states like Texas, Florida, and Washington) to over 13% in high-tax states, while some cities also impose local municipal income taxes.": "Je nach Bundesland oder Gemeinde gelten unterschiedliche Hebesätze, Kirchensteuersätze oder regionale Zuschläge.",
    "Net worth is the total market value of everything you own (assets) minus everything you owe to creditors (liabilities).": "Der Marktwert aller Vermögenswerte (Aktiva) abzüglich sämtlicher bestehender Schulden und Verbindlichkeiten (Passiva).",
    "How often should I calculate my net worth?": "Wie oft sollte man sein Nettovermögen ermitteln?",
    "Reviewing your net worth quarterly or semi-annually gives you a clear high-level view of your financial health without obsessing over daily market swings.": "Ein viertel- oder halbjährlicher Überblick reicht völlig aus, um den finanziellen Fortschritt objektiv zu bewerten.",
    "What counts as an asset vs. a liability?": "Was zählt als Vermögenswert und was als Verbindlichkeit?",
    "Assets include bank balances, investment accounts, home equity, and retirement funds. Liabilities include mortgages, student loans, car loans, and credit card debt.": "Aktiva: Kontoguthaben, Depots, Immobilienwert, Altersvorsorge. Passiva: Hypotheken, Autokredite, Ratenkredite, Kreditkartenschulden.",
    "Should I include my house and mortgage in my net worth?": "Gehören Eigenheim und Hypothek ins Nettovermögen?",
    "Yes, you include the current fair market value of the home under assets and the remaining mortgage balance under liabilities. The difference is your home equity.": "Ja, der aktuelle Marktwert wird als Vermögen verbucht und die Restschuld als Verbindlichkeit; die Differenz ist das reine Eigenkapital.",
    "What does it mean to have a negative net worth?": "Was bedeutet ein negatives Nettovermögen?",
    "A negative net worth means your total debts exceed your total assets. This is common for young adults and recent graduates with student loans.": "Die Schulden übersteigen das Vermögen; dies ist bei Studienabsolventen oder zu Beginn einer Immobilienfinanzierung nicht unüblich.",
    "Most financial planners recommend saving 3 to 6 months of essential living expenses, or 9 to 12 months for freelancers or single-income households.": "Finanzexperten raten zu 3 bis 6 monatlichen Grundlebenshaltungskosten (bei Selbstständigen 9 bis 12 Monate).",
    "What expenses should be included in an emergency fund budget?": "Welche Ausgaben gehören in das Notfall-Budget?",
    "Include only non-negotiable living costs: housing (rent/mortgage), utilities, groceries, basic transportation, minimum debt payments, and healthcare insurance.": "Ausschließlich unverzichtbare Fixkosten: Miete/Rate, Energie, Grundnahrungsmittel, Basismobilität und notwendige Versicherungen.",
    "Where should I keep my emergency fund?": "Wo sollte der Notgroschen geparkt werden?",
    "In a dedicated High-Yield Savings Account (HYSA) or money market account where it is FDIC-insured, earns interest, and can be accessed immediately without risk.": "Auf einem separaten, täglich verfügbaren Tagesgeldkonto mit Einlagensicherung, ohne Kursrisiko.",
    "Should I pay off debt or build an emergency fund first?": "Erst Schulden tilgen oder den Notgroschen aufbauen?",
    "Build a starter emergency fund of 1 month of expenses or $1,000 to $2,000 first, then aggressively pay off high-interest consumer debt before expanding to 3-6 months.": "Zuerst einen Mini-Notgroschen von ca. 1 Monatsausgabe (1.000-2.000 €) ansparen, dann teure Konsumschulden tilgen und danach das Polster auf 3 bis 6 Monate ausbauen.",
    "When is it appropriate to use emergency fund savings?": "Wann darf man an den Notgroschen ran?",
    "Use it only for genuine, unexpected emergencies: sudden medical bills, unexpected car repairs, or living expenses following job loss.": "Ausschließlich für unvorhersehbare echte Notfälle: unaufschiebbare Reparaturen, Zahnersatz oder Überbrückung bei Jobverlust.",
    "An expense ratio is the annual percentage fee charged by mutual funds and ETFs to cover fund management, administrative expenses, and operating costs.": "Die Total Expense Ratio beziffert die jährliche Gebühr in Prozent des Fondsvolumens für Verwaltung, Verwahrung und Betrieb.",
    "How do fees compound over time?": "Wie wirkt sich der Gebühren-Zinseszins langfristig aus?",
    "Fees are deducted annually from your total assets, meaning you lose both the fee money and all future compounding returns that money would have earned.": "Gebühren mindern das Anlagevermögen jedes Jahr, wodurch auch sämtliche künftigen Zinseszinsen auf diesen Betrag unwiederbringlich verloren gehen.",
    "What is a good expense ratio for an index fund?": "Welche Kostenquote gilt bei ETFs als günstig?",
    "Low-cost index funds and ETFs typically have expense ratios between 0.02% and 0.10%, whereas actively managed mutual funds often charge 0.60% to 1.50% or more.": "Günstige Indexfonds und ETFs kosten 0,05 % bis 0,20 % p.a.; aktiv gemanagte Fonds verlangen häufig 1,5 % bis 2,0 % plus Ausgabeaufschlag.",
    "What other investment fees should I look out for?": "Auf welche weiteren Wertpapiergebühren ist zu achten?",
    "Watch out for advisory fees (AUM fees of 1%), front-end or back-end sales loads, trading commissions, account maintenance fees, and custodial charges.": "Depotgebühren, Transaktionskosten (Orderprovisionen), Ausgabeaufschläge und laufende Vermögensverwaltungsgebühren.",
    "How much can a 1% fee difference affect my retirement savings?": "Wie viel Vermögen kostet ein Gebührenunterschied von 1 %?",
    "A 1% annual fee difference can erode 25% to 30% of your total ending portfolio wealth over a 30-year investment horizon.": "Über einen Zeitraum von 30 Jahren vernichtet ein scheinbar kleiner Gebührenunterschied von 1 % rund 25 % bis 30 % des gesamten Endvermögens!",
    "What is a 529 plan?": "Was ist ein Ausbildungssparplan (529 Plan)?",
    "A 529 plan is a tax-advantaged savings and investment plan designed to encourage saving for future higher education expenses with tax-free growth and qualified withdrawals.": "Ein steuerbegünstigter Sparplan für künftige Bildungs- und Studienkosten mit steuerfreiem Vermögenswachstum.",
    "How fast do college costs increase?": "Wie stark steigen Ausbildungskosten?",
    "Historically, higher education tuition and fees have increased at an annual rate of 4% to 6%, outpacing general consumer inflation.": "Studiengebühren und Ausbildungsausgaben steigen historisch mit 4 % bis 6 % pro Jahr deutlich schneller als die allgemeine Teuerungsrate.",
    "What happens to 529 funds if my child does not go to college?": "Was geschieht mit dem Geld, wenn das Kind nicht studiert?",
    "You can change the beneficiary to another qualifying family member, use up to $10,000 for student loan repayment, or roll over up to $35,000 into a Roth IRA under SECURE 2.0 rules.": "Man kann den Begünstigten auf Geschwister übertragen, Kredite ablösen oder bis zu 35.000 $ in ein Rentenkonto überführen.",
    "Can I use a 529 plan for trade schools or K-12 tuition?": "Kann man die Mittel auch für Berufsausbildung oder Schulen nutzen?",
    "Yes, qualified distributions can cover accredited trade schools, vocational programs, apprenticeships, and up to $10,000 per year for K-12 private school tuition.": "Ja, anerkannte Fach- und Meisterschulen sowie bis zu 10.000 $ Schulgeld pro Jahr für Privatschulen sind förderfähig.",
    "How does a 529 plan impact financial aid eligibility?": "Beeinflusst der Sparplan staatliche BAföG- oder Stipendienansprüche?",
    "Parent-owned 529 plans are assessed as parental assets on the FAFSA at a maximum rate of 5.64%, having minimal negative impact on financial aid eligibility.": "Elterliche Bildungssparvermögen werden nur zu einem geringen Bruchteil angerechnet und mindern die Förderchancen kaum.",
    "How does DCA apply to high-volatility assets like Crypto?": "Warum ist DCA bei volatilen Krypto-Assets besonders nützlich?",
    "DCA prevents emotional decisions during extreme market peaks and crashes, automatically buying more units when prices are low and fewer when prices are high.": "Es schaltet Emotionen aus, kauft bei Kurseinbrüchen automatisch mehr Anteile und senkt so den mittleren Einstiegspreis über die Zeit.",
    "Is DCA better than investing a lump sum?": "Ist ein Sparplan besser als eine Einmalanlage?",
    "Lump sum investing historically wins in steadily rising markets, but DCA provides superior peace of mind, lower emotional risk, and downside protection in highly volatile markets.": "In rein steigenden Märkten gewinnt historisch die Einmalanlage; bei starken Schwankungen bietet DCA jedoch emotionalen Schutz vor Fehl-Timings.",
    "What is the best frequency for crypto DCA?": "Welches Intervall eignet sich für Krypto-Sparpläne?",
    "Weekly or bi-weekly DCA aligned with your pay cycle is ideal for capturing market volatility while keeping trading fees manageable.": "Wöchentliche oder zweiwöchentliche Ausführungen glätten Kursspitzen optimal ab, ohne übermäßige Transaktionsgebühren zu verursachen.",
    "Does DCA guarantee profits in cryptocurrency?": "Garantiert DCA sichere Gewinne bei Krypto-Anlagen?",
    "No, DCA does not protect against prolonged declines or failing crypto projects; it only ensures you achieve the weighted average market purchase price.": "Nein, ein Sparplan schützt nicht vor Totalverlust oder dauerhaften Bärenmärkten; er garantiert lediglich den fairen Durchschnittspreis.",
    "What is the standard tipping percentage?": "Welche Trinkgeldhöhe ist üblich?",
    "In the United States and Canada, standard restaurant tipping guidelines range from 15% for adequate service, 18% for good service, to 20% or more for exceptional service.": "In Nordamerika sind 15 % bis 20 % Standard; im europäischen Raum gelten bei gutem Service im Restaurant 5 % bis 10 % als üblich.",
    "Should tips be calculated before or after sales tax?": "Berechnet man Trinkgeld vom Rechnungsbetrag vor oder nach Steuern?",
    "Etiquette traditionally dictates calculating the tip percentage on the pre-tax food and beverage subtotal, though many automated payment terminals calculate tip on the post-tax total.": "Klassisch wird das Trinkgeld auf den reinen Speisen- und Getränkebetrag vor Mehrwertsteuer berechnet, Kartenterminals nutzen oft die Bruttosumme.",
    "How do you split a bill evenly among friends?": "Wie teilt man eine Restaurantrechnung fair unter Freunden auf?",
    "Calculate the total bill including food, beverages, tax, and tip, and divide the total amount equally by the number of paying participants.": "Gesamtsumme inklusive Mehrwertsteuer und Trinkgeld addieren und gleichmäßig durch die Zahl der zahlenden Personen teilen.",
    "How do you calculate a percentage discount?": "Wie berechnet man einen prozentualen Rabatt?",
    "Multiply the original price by the discount percentage divided by 100 to find the savings, and subtract that amount from the original price: Final Price = Original Price × (1 - Discount%).": "Originalpreis mit dem Rabattsatz multiplizieren und durch 100 teilen, dann vom Ausgangspreis abziehen: Endpreis = Grundpreis × (1 - Rabatt%).",
    "How do multiple stacked discounts work?": "Wie funktionieren kombinierte Rabatte?",
    "Stacked discounts apply sequentially rather than additively. For example, 20% off plus an extra 10% off results in an effective 28% total discount, not 30%.": "Mehrere Rabatte werden nacheinander angewandt, nicht addiert: 20 % plus 10 % extra ergeben rechnerisch 28 % Gesamtrabatt (nicht 30 %).",
    "Is sales tax applied before or after store discounts?": "Fällt die Mehrwertsteuer vor oder nach Abzug des Rabatts an?",
    "In most jurisdictions, sales tax is calculated on the discounted post-sale price, meaning you pay sales tax only on the actual money spent.": "Die Mehrwertsteuer wird auf den tatsächlich reduzierten Kaufpreis berechnet, Sie zahlen Steuer also nur auf den reell gezahlten Betrag.",
  },
  ja: {
    "The 5% rule estimates that homeownership costs roughly 5% of a property's value annually in unrecoverable expenses (1% property tax, 1% maintenance, and 3% cost of capital). Divide by 12 to find your break-even monthly rent. If you can rent an equivalent home for less, renting plus investing the savings builds greater wealth. For detailed math and worked case studies, read our complete guide: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">How to Decide: Rent vs. Buy Your Home</a>.": "5%ルールでは、住宅所有にかかる回収不能コスト（固定資産税約1%、修繕維持費約1%、資本コスト約3%）を年間で物件価格の約5%と試算します。この金額を12で割ることで、損益分岐点となる月額家賃を算出できます。同等の物件にそれより安い家賃で居住でき、差額を運用に回せる場合は、賃貸の方が長期的に大きな資産を築ける傾向があります。詳細な計算式や実践的なケーススタディは、当サイトの完全ガイドをご覧ください：<a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">住宅購入 vs. 賃貸の賢い選び方</a>。",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline). For a deep dive into bank underwriting formulas, salary matrices, and the 28/36 rule, read our complete guide: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">How Much House Can I Afford?</a>.": "多くのファイナンシャルプランナーや金融機関の融資基準では、月額の総収入（額面給与）に占める住宅関連費用の割合を25%〜28%以内（フロントエンドDTI比率）に抑えることを推奨しています。金融機関の審査基準、年収別借入限度額、および28/36ルールに関する詳細な解説は、完全ガイドをご覧ください：<a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">いくらの住宅が購入できるか？適正予算の決め方</a>。",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to solve for any of the five core TVM variables: Present Value (PV), Future Value (FV), Periodic Payment (PMT), Annual Interest Rate (I/Y), and Number of Compounding Periods (N).": "この金融TVM計算機は、標準的な複利計算および現在価値・将来価値の割引キャッシュフロー数式を用いて、貨幣の時間価値における主要5変数（現在価値 PV、将来価値 FV、定期支払額 PMT、年間金利 I/Y、複利期間数 N）のいずれでも瞬時に算出します。",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), planned recurring periodic deposits (PMT), interest rate, and duration. The calculator computes the total compounded ending balance instantly.": "目標変数として「将来価値（FV）」を選択します。現在の元本残高（PV）、定期的な積立額（PMT）、期待金利、および運用期間を入力してください。計算機が複利運用による最終到達残高を自動的に算出します。",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (common in lease and insurance contracts), earning an extra compounding cycle of interest.": "期末払年金（通常年金）では、住宅ローンや一般的な借入金のように各期間の「末日」に支払いや積立が行われます。一方、期首払年金ではリース料や保険料のように各期間の「初日」に資金移動が生じるため、丸1期間分の複利運用期間が余分に加わり、利息の増加や将来価値の向上が生じます。",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price. For a full breakdown of the math, comparisons with lump-sum investing, and crypto fee traps, read our complete guide: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">What Does DCA Mean in Crypto?</a>.": "ドルコスト平均法（DCA）とは、資産の価格変動にかかわらず、定期的に一定額を投資し続ける運用手法です。計算式の仕組み、一括投資との徹底比較、仮想通貨特有の手数料リスクについては、完全ガイドをご覧ください：<a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">仮想通貨におけるDCA（ドルコスト平均法）の基本と実践</a>。",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an \"in-service distribution\" (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "将来の給与天引き積立は、設定を0%に変更することでいつでもペナルティなしで停止・一時中断できます。しかし、在職中にすでに年金口座（401k / 確定拠出年金）に蓄積された資金を引き出すことは税法上の厳格な制限があり、特別事由（在職中引出制度や法定の経済的困窮基準）を満たす必要があります。また要件を満たさない早期引出には、強制源泉徴収に加えてペナルティ税が課されます。詳細はこちらのガイドをご覧ください：<a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">在職中に確定拠出年金を解約・現金化することは可能か？</a>。",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Number of Periods (Nper), and Periodic Payment (PMT). By inputting any four variables, our solver computes the fifth unknown mathematically using standard financial algebra formulas.": "TVM（貨幣の時間価値）計算機は、5つの基本変数を連動させています：現在価値（PV）、将来価値（FV）、期間利率（Rate）、期間数（Nper）、定期支払額（PMT）。既知の4変数を入力することで、金融代数の標準公式に基づいて残る第5の未知数を数学的に導き出します。",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and total periods (years or months), specify any periodic recurring payment (PMT), and leave Future Value empty. The calculator instantly compounds your principal and contributions to reveal the ending balance.": "将来価値を求めるには、当初預託金を現在価値（PV）に入力し、年利と総期間数（年数または月数）を設定した上で、毎期の積立額（PMT）を入力し、将来価値を空欄にして計算を実行します。元本と積立金に対する複利効果が自動計算され、最終到達額が算出されます。",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and personal loans). In an annuity due, payments occur at the beginning of each period (common in lease payments and rent), allowing each cash flow to earn an extra period of compounding interest.": "期末払年金（通常年金）では各期間の終了時に支払いが発生します（ローン返済の標準）。期首払年金では各期間の開始時に支払いが行われます（家賃やリース料など）。期首払いの方が資金が早く投資されるため、1期間分の複利効果が余分に働き、将来価値（FV）がより大きくなります。",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested into equal periodic purchases (e.g. $50 every week) regardless of asset price, smoothing out market volatility over time.": "ドルコスト平均法（DCA）は、投資総額を分割し、価格の高低にかかわらず一定期間ごとに同額ずつ買い付ける投資手法です（例：毎週50ドル・5,000円など）。市場の短期的なボラティリティを平滑化し、高値掴みのリスクを分散する効果があります。",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement living expenses minus Social Security. If you need $60,000 per year from your portfolio, your target retirement nest egg is $1,500,000 ($60,000 × 25). This nest egg provides sustainable inflation-adjusted income throughout a 30-year retirement.": "25倍の法則（4%安全取崩しルールの逆数）に基づくと、定年退職時に必要な老後資金の目標額は、想定される年間引退後支出の約25〜30倍と試算されます。例えば年間支出が500万円の場合、約1億2,500万円の資産蓄積が目安となります。",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $500,000 401(k) generates ~$1,667/month ($20,000/year); a $1,000,000 401(k) generates ~$3,333/month ($40,000/year); and a $1,500,000 401(k) generates ~$5,000/month ($60,000/year). Combined with Social Security, this replaces 70% to 90% of pre-retirement income.": "4%の安全資産取崩しルールに基づくと、毎月の受取可能額の目安は「（最終年金資産残高 × 4%）÷ 12」で計算されます。例えば1億円（約100万ドル）の蓄積資産がある場合、資産を枯渇させずに毎月約33.3万円（約3,333ドル）を引き出し続けることが可能です。",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\\\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\\\" class=\\\"text-primary underline font-medium\\\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "4%ルールを遵守し、株式60%・債券40%などの分散ポートフォリオを維持した場合、米トリニティ大学の歴史的バックテスト研究によると、資産が最低30年以上持続する確率は95%を超えています。取崩し率を年6〜7%以上に引き上げると、市場下落時に資産枯渇リスクが跳ね上がります。完全ガイドはこちら：<a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">確定拠出年金の税金・月額給付額・資産寿命ガイド</a>。",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty PLUS ordinary federal and state income taxes on the distributed amount. For someone in the 22% federal bracket and 5% state bracket, an early withdrawal of $20,000 forfeits $7,400 (37%) to penalties and taxes, leaving only $12,600. Key exceptions to the penalty include the Rule of 55 (leaving an employer at age 55 or older), qualifying hardship distributions, or Substantially Equal Periodic Payments (SEPP / Rule 72t).": "59歳半未満の時点で従来型401(k)等の確定拠出年金から資金を引き出すと、通常の所得税課税に加えて10%の早期引出ペナルティ税が課されます。例外規定（法的に定められた重度障害、一部の医療費控除対象額など）に該当しない限り、早期の現金化は資産を大きく毀損します。",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals, freelancers, and small business owners with no full-time W-2 employees (other than a spouse). It allows dual contributions: up to $23,000 in elective employee deferrals ($30,500 if age 50+) PLUS an employer profit-sharing contribution up to 25% of net adjusted business earnings (20% for sole proprietors), up to a combined maximum of $69,000 in 2024.": "ソロ401(k)（個人事業主向け確定拠出年金）は、従業員のいない自営業者やひとり法人のオーナーを対象とした強力な年金制度です。加入者は「従業員」としての給与天引き枠と「事業主」としての会社拠出枠の双方を活用でき、一般的な個人年金制度を大幅に上回る年間拠出限度額を活用できます。",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000, whichever is less. A 401(k) loan avoids income tax and the 10% IRS penalty because you repay principal and interest back into your own account (usually over 5 years). However, if you leave your employer before repaying, the remaining balance usually becomes due by the federal tax filing deadline, or it converts into a taxable early distribution.": "はい、多くの企業型確定拠出年金制度では、権利確定残高の最大50%（上限5万ドル等）までを担保として借り入れる「401(k)ローン」が認められています。利息は自身の口座に戻るため金融会社への利息流出がなく、所定の期日（通常5年以内）に返済すれば課税対象にもなりません。",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) with one click. A Traditional 401k calculator mode shows your immediate federal and state tax savings today, while retirement withdrawals are taxed as ordinary income. A Roth 401k calculator mode models post-tax contributions that generate 100% tax-free growth and 100% tax-free withdrawals in retirement.": "当計算機では、拠出時に所得控除を受け受取時に課税される「従来型（Traditional / iDeCo型）」と、手取り資金で拠出し将来の運用益・受取時が非課税となる「Roth（NISA型）」を切り替えて比較シミュレーションできます。",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\\\"/blog/can-i-cancel-401k-cash-out-while-employed/\\\" class=\\\"text-primary underline font-medium\\\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "給与天引きによる年金積立は、社内手続きで天引き割合を0%に変更することでいつでもペナルティなく中断できます。ただし、既に積み立てられた元本の解約・現金化は税法上制限されており、法定の早期引出要件や在職中引出規定に合致しない限り、退職前の中途解約は原則不可能です。完全ガイド：<a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">在職中に年金口座を解約して現金化できるか？</a>。",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong performance or merit raises average 4% to 7%, and promotions or job changes typically command a 10% to 20%+ increase in base compensation.": "歴史的なデータに基づくと、一般的な物価スライド（生活費調整）昇給率は年3%〜4%程度、実績・評価に基づく成果昇給は5%〜8%、昇進や転職を伴う昇給では10%〜20%以上が標準的な目安とされています。",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: Raise % = ((New Salary - Old Salary) / Old Salary) × 100%.": "昇給額（改定後給与 − 改定前給与）を算出し、それを改定前給与で除して100を乗じます。例えば、給与が月額30万円から33万円に昇給した場合、（33万 − 30万）÷ 30万 × 100 = 10.0%の昇給率となります。",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "週40時間勤務・年52週（年間実働2,080時間）を標準労働時間とした場合、時給アップ額に2,080を乗じることで年収増加額を算出できます。例えば時給が500円（または5ドル）上がった場合、年間で104万円（10,400ドル）の年収増となります。",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above each tax bracket threshold are taxed at the higher marginal rate; income below the threshold remains taxed at the lower previous rates. A pay raise will always increase your net take-home pay.": "いいえ。所得税は超過累進税率を採用しているため、昇給によって高い税率区分に入ったとしても、手取り額が減ることはありません。税率が上がるのは「境界値を超過した増額分」のみであり、以前の所得部分には従来の低い税率がそのまま適用されます。",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees. For the complete mathematical formula and a comparison with reverse mortgages, read our comprehensive guide: <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">What is a Reverse Mortgage & How Payments Work</a>.": "毎月の住宅ローン返済額（PITI）は、借入元金と利息（P&I）、固定資産税、火災保険・地震保険料、および管理費や保証料で構成されます。リバースモーゲージとの比較や詳しい計算式についてはこちらの記事をご覧ください：<a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">リバースモーゲージの仕組みと返済構造の解説</a>。",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders may charge an early payoff fee. Check your loan contract terms before making lump-sum payments.": "一般的な消費者ローンや住宅ローンでは、繰り上げ返済による違約金やペナルティなしで元金を前倒し返済できる契約が主流です。ただし、一部の特殊な固定金利型融資やビジネスローンでは繰上返済手数料が設定されている場合があるため、金銭消費貸借契約書をご確認ください。",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It enables wealth to grow exponentially over time compared to simple interest.": "複利とは、当初の元本だけでなく、それまでに発生した利息に対してもさらに利息が上乗せされていく運用・利息計算の仕組みです。期間が長期化するほど、雪だるま式に利息が加速度的に膨らんでいく効果があります。",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your expected annual interest rate (e.g., at 8% annual return, your money doubles in approximately 9 years: 72 / 8 = 9).": "「72の法則」とは、投資資金が複利運用によって2倍になるまでにおよそ何年かかるかを暗算できる便利な法則です。「72 ÷ 年利（%）」で計算します。例えば年利8%の場合、72 ÷ 8 = 約9年で元本が2倍になります。",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total returns. More frequent compounding means interest starts earning interest sooner, producing slightly higher annual percentage yields (APY).": "複利の頻度（年1回、月次、日次など）が細かくなるほど、利息が元本に組み込まれるタイミングが早まり、最終的な利息総額・将来価値は高くなります。日次複利は年次複利に比べて実行利回り（APY）を向上させます。",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement (including employer matching). At a bare minimum, contribute enough to capture the full employer match—otherwise, you are leaving free compensation on the table.": "多くのファイナンシャルアドバイザーは、税引前の額面年収の少なくとも15%を退職・老後資金に積み立てることを推奨しています。少なくとも、勤務先のマッチング拠出（会社上乗せ給付）を最大まで受け取れる比率は必ず拠出すべきです。",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary, or dollar-for-dollar up to 4%) and calculates the combined total deposited into your retirement account each pay period.": "マッチング機能付き年金計算機は、勤務先の拠出ルール（例：給与の6%拠出に対して50%マッチング等）を自動計算し、雇用主からの追加給付が数十年でどれほど大きな資産形成につながるかを視覚化します。",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by age 40, 6x by age 50, 8x by age 60, and 10x by age 67.": "大手金融機関（Fidelity等）が提示する標準的な資産形成ベンチマークによると、30歳時点で年収の1倍、40歳で3倍、50歳で6倍、60歳で8倍、退職時（67歳）に年収の10倍の資産蓄積が推奨されています。",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, but pay income tax on withdrawals in retirement. In a Roth 401(k), you contribute after-tax dollars, but qualified withdrawals in retirement are 100% tax-free. Generally, choose Roth if you expect to be in a higher tax bracket in retirement, and Traditional if you are in a high tax bracket today.": "従来型（Traditional / iDeCo）では税引前給与から拠出するため目先の所得控除を受けられますが、受取時に課税されます。Roth型（NISA等）では税引後資金で投資しますが、将来の運用益および受取時の引き出しが恒久的に非課税となります。",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you contribute $10,000 and your marginal tax bracket is 24%, you save approximately $2,400 in federal income taxes this year.": "税引前の従来型確定拠出年金に拠出した資金は、その全額が所得控除の対象となり課税所得を直接引き下げます。例えば限界税率24%の方が年100万円を拠出すると、その年の所得税・住民税が約24万円軽減されます。",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer match, investment returns, and years until retirement. Use this calculator's interactive chart to simulate your balance under conservative (5%), moderate (7%), and aggressive (9%) return assumptions.": "退職時の予想年金資産残高は、投資利回り（複利効果）、拠出率、事業主マッチング拠出、および退職までの運用年数によって決まります。キャリア早期から投資を開始することで、複利の加速度的な恩恵を受けられます。",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 times your anticipated annual retirement expenses. For example, if you need $60,000 per year from your portfolio, you need an estimated $1.5 million nest egg ($60,000 × 25).": "「25倍の法則」（4%ルールの逆算）によれば、リタイア後の生活を維持するためには、年間計画支出額の約25倍の資産が必要です。年間支出が400万円の場合、目標準備資産は1億円（400万 × 25）となります。",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending Balance × 0.04) / 12. For instance, a $1,000,000 retirement portfolio generates approximately $3,333 per month in sustainable retirement income, adjusted for inflation over a 30-year retirement.": "4%の安全取崩しルールに基づく毎月の引出可能額は「（退職時資産残高 × 4%）÷ 12」で求められます。例えば資産が5,000万円の場合、年間200万円、月額約16.6万円を持続的に引き出せます。",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities / 40% fixed income), historical backtesting (Trinity Study) indicates your portfolio has an over 95% probability of lasting at least 30 years without running out of money.": "4%ルールを守り、株式と債券の分散ポートフォリオ（例：株60%、債券40%）を維持すれば、歴史的相場シミュレーション（トリニティ・スタディ）において30年以上の退職期間で資産が枯渇しない確率は95%を超えます。",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty plus standard income tax on the entire amount. Total taxes and penalties can easily exceed 35%–45% of your withdrawal.": "59歳半に達する前に従来型401(k)等の確定拠出年金から資金を引き出すと、通常課される所得税に加えて10%の早期引出ペナルティ税が課されます。老後資金の複利成長を止めてしまうため、緊急時以外の早期解約は避けるべきです。",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no full-time employees. It allows business owners to contribute both as employee and employer, enabling significantly higher annual tax-deductible contribution limits.": "ソロ401(k)は、従業員を持たない個人事業主や法人経営者のための確定拠出年金制度です。自身への給与からの拠出枠と、事業主としての利益配分拠出枠の両方を併用できるため、極めて高い節税・資産形成効果があります。",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000). The interest you pay goes back into your own account, avoiding taxes and penalties as long as you repay it on schedule (usually within 5 years).": "はい。多くの企業型年金プランでは、権利確定残高の50%（上限5万ドル）までを上限とする年金担保貸付が用意されています。利息は自身の年金口座に払い戻されるため外部流出がなく、信用スコアにも影響しません。",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions. The tool models post-tax spending power at retirement so you can see whether paying taxes now vs. at retirement yields a larger final nest egg.": "当計算機では、現在の所得控除を優先する「従来型（Traditional）」と、将来の非課税受取を狙う「Roth型」を簡単に切り替え可能です。現在の限界税率と老後の想定税率を比較して最適な選択を検証できます。",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer non-mortgage debt is fully cleared. You first invest up to the employer match, then fund a Roth IRA, and put any remainder back into your employer plan.": "デイブ・ラムジー氏が提唱する「ベビーステップ4」では、緊急予備資金の確保と借金完済（住宅ローン除く）を終えた後、世帯総収入の15%を確定拠出年金などの税制優遇投資口座に定期投資することを推奨しています。",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It provides cost-effective retirement plans with mandatory employer contributions (either a 3% match or a 2% non-elective contribution).": "SIMPLE 401(k)（従業員数100人以下の小規模企業向け年金プラン）は、一般企業型401(k)に比べて管理コストや複雑な差別的是正テストを簡素化した制度で、雇用主による一定のマッチング拠出が義務付けられています。",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your HR or plan administrator. However, cashing out existing vested funds while still actively employed is generally prohibited by plan rules, unless you qualify for a hardship distribution. For detailed options, see our guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Employed?</a>": "給与天引きの変更・停止は、勤務先の担当部署やオンラインポータルを通じて拠出率を0%に設定することで、いつでも手数料なく手続き可能です。ただし口座内資産の早期解約には制限と税務ペナルティが伴います。",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of ~10% annually before inflation. After factoring in 2.5%–3% average inflation and ETF expense ratios, a realistic long-term real return assumption is 6.5% to 7.0% per year for a 100% equity portfolio, or 5.0% to 6.0% for a balanced 60/40 stocks and bonds portfolio.": "歴史的に、米国株式市場（S&P 500指数）は過去数十年にわたり年平均約10%の名目リターン（インフレ調整後の実質リターンで約7%）を記録しています。ただし年ごとの市場変動は大きく上下します。",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility stress by purchasing more shares when prices are low and fewer when prices are high. While historical data shows investing a lump sum immediately outperforms DCA about 68% of the time because markets rise long-term, recurring contributions are far easier to budget and provide psychological discipline.": "定期定額投資（ドルコスト平均法）は、相場のタイミングを計るリスクと感情的な判断ミスを排除します。価格が安い時期に自動的に多くの口数を買い増すことで、ポートフォリオ全体の平均取得単価を引き下げます。",
    "Nominal return is the raw percentage gain generated by your investments before inflation and taxes. Real return is your actual purchasing power gain after subtracting the inflation rate. For example, if your portfolio gains 9% nominal in a year where inflation is 3%, your real return is approximately 6%.": "名目リターンとはインフレや手数料を考慮しない表面上の運用利回りであり、実質リターンとは名目利回りからインフレ率を差し引いた実質的な購買力の増加率を表します。",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contribution cash makes up the vast majority of your portfolio. Over 20 to 30 years, accumulated reinvested earnings surpass your total principal deposits and begin generating more annual income than your own salary.": "複利効果は資産形成に指数関数的な加速をもたらします。初期の数年間は自己資金の積立額が残高の大部分を占めますが、年数が経過すると過去の運用益が生み出す再投資利息が自己拠出額を遥かに凌駕するようになります。",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation costs (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income. This prevents you from becoming 'car poor' and prevents negative equity.": "20/4/10ルールとは健全な自動車購入のガイドラインです。頭金を最低20%支払い、ローン期間は最長4年（48ヶ月）以内とし、毎月のローン返済・保険・燃料代などの総自動車維持費を手取り月収の10%以内に抑えることを推奨します。",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk owing more than the vehicle is worth (negative equity or being 'underwater') as the car depreciates. Sticking to 48 or 60 months is significantly safer.": "72ヶ月や84ヶ月などの超長期ローンを組むと毎月の返済額は下がりますが、支払う総利息額が激増し、車の減価償却スピードがローン残高の減少ペースを上回る「債務超過（残債割れ）」に陥る危険が高まります。",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance can exceed the market value of the car. If the car is totaled or stolen, standard insurance only pays market value, leaving you responsible for the remaining loan balance unless you have GAP insurance.": "新車は購入後の値落ち（減価償却）が激しく、最初の1年で価値の約20%を失うことがあります。十分な頭金を入れないと、車の売却価値よりもローン残高の方が大きくなる「オーバーローン」状態に直面します。",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit-based raise typically ranges from 4% to 8%, while a promotion within the same company averages 8% to 12%. Switching companies or industries often commands a 15% to 25% salary increase.": "一般的な生活費調整（COLA / 物価スライド）による定期昇給率は3%〜5%前後です。成果に応じた能力昇給では5%〜8%、昇進や社内グレード昇格では10%〜15%以上の昇給が見込めます。",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100. Formula: [(New Salary - Old Salary) / Old Salary] × 100. For example, moving from $60,000 to $66,000 is a 10% raise: ($6,000 / $60,000) × 100.": "昇給後の給与から従来の給与を差し引いて昇給額を求め、それを従来の給与で割って100を掛けます。例：（昇給後額 − 昇給前額）÷ 昇給前額 × 100 = 昇給率（%）。",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly wage increase by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "週40時間労働・年52週（年間2,080労働時間）を基準とします。時給アップ額に2,080を掛けることで年間の総支給額アップ分が算出されます（例：時給300円アップなら年額62.4万円の増収）。",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of income that falls into the new, higher bracket is taxed at the higher percentage rate. Every dollar earned below that threshold is still taxed at the lower previous rates. A pay raise will always increase your total net take-home pay.": "いいえ。所得税は超過累進課税制度を採用しているため、昇給によって高い税率ブラケットに突入しても、手取り額が減る逆転現象は起きません。高い税率が課されるのは境界を超えた増加部分のみです。",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on everything else. Once the smallest debt is cleared, you roll its entire payment into the next smallest debt. This generates psychological momentum through rapid early wins.": "デット・スノーボール（雪だるま）返済方式とは、金利の高低にかかわらず残高が最も少ない借入から順番に全額完済していく手法です。早期に完済体験を得ることで心理的達成感とモチベーションを維持できます。",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while paying minimums on all others. Mathematically, this minimizes total interest charges paid across all debts and clears debt in the fastest possible timeframe.": "デット・アバランチ（雪崩）返済方式とは、すべての借入金の中で金利（実質年率）が最も高い借入から優先して完済していく手法です。返済期間全体の支払利息総額を数学的に最小化できます。",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, behavioural studies show that the Debt Snowball method often yields higher real-world completion rates because the psychological motivation of eliminating individual accounts quickly prevents people from giving up on their debt-free plan.": "数学的には、最も高い金利の負債を真っ先に削るデット・アバランチ方式の方が、完済までの総利息額を最小にし、完済期間も最短にできるため最も経済合理性に優れています。",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt. Once that target debt is paid in full, its entire monthly budget (its minimum payment + the extra cash) rolls into the next debt on your roster, creating an ever-larger monthly payment that accelerates debt payoff.": "すべての借入に対して毎月の最低返済額（ミニマムペイメント）を支払いつつ、余剰資金のすべてを最優先の1件に集中投下します。1件が完済できたら、その返済原資を次のターゲットに上乗せして返済を加速させます。",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain motivation (Snowball), and then switch to attacking the remaining debts by highest interest rate to save on interest costs (Avalanche).": "はい。最初の1〜2件は少額の借金をスノーボール方式で速やかに完済して手元のキャッシュフローと自信を確保し、その後は高金利の借入をターゲットにするアバランチ方式へ移行するハイブリッド手法も非常に有効です。",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or interest. It answers the fundamental financial question: 'How much will my money be worth tomorrow if I invest it today?'": "将来価値（FV）とは、現在の資産や一括投資資金、または定期的なキャッシュフローが、特定の金利（利回り）のもとで複利運用された場合に、将来の特定時点でいくらになっているかを表す金額です。",
    "Inflation is the general rise in prices for goods and services over time, resulting in a reduction in purchasing power per unit of currency. When inflation occurs, each dollar or euro buys a smaller percentage of a good or service.": "インフレーション（物価上昇）とは、モノやサービスの一般的な価格水準が時間の経過とともに継続的に上昇し、相対的に現金の購買力が低下する現象を指します。",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only have the purchasing power equivalent of about $7,440 in 10 years, even though the nominal account balance remains unchanged.": "無利息の普通預金や現金で放置された資産は、インフレによって実質的な購買力が年々損なわれます。インフレ率が年3%の場合、今日の100万円の購買力は約24年後には半分に縮小してしまいます。",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average change over time in prices paid by consumers for a representative 'basket' of goods and services, including housing, food, transportation, energy, and healthcare.": "インフレ率は主に消費者物価指数（CPI）を用いて測定されます。これは一般家庭が日常的に購入する生活必需品、食料、エネルギー、住宅関連費用などの価格変動を総合的に指数化したものです。",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.2% per year over multi-decade periods, though short-term supply shocks can cause temporary surges.": "主要先進国において、歴史的な年間総合インフレ率は平均で2%〜3%前後で推移してきました。主要中央銀行の金融政策も多くが年間インフレ率2%を安定目標として設定しています。",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds / ETFs), real estate, inflation-protected government bonds (TIPS or bonos ligados al IPC), and commodities—historically provides the most reliable long-term protection against purchasing power loss.": "インフレによる資産目減りを防ぐには、幅広い世界株式インデックスファンド、不動産投資信託（REIT）、物価連動国債など、インフレ率を上回る名目利回りを提供する成長資産に投資することが不可欠です。",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "給与天引きの年金拠出は、会社の手続きを通じていつでも0%に変更して停止できます。ただし、既に口座内にある資金を引き出す行為は、法的な要件を満たさない限り重い税務ペナルティの対象となります。",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and loans). In an annuity due, payments occur at the beginning of each period (standard for lease agreements). Because money is invested earlier in an annuity due, it compounds for one additional cycle, resulting in a higher Future Value.": "期末払年金では各期間の終了時に資金が支払われます（一般的な分割払いやローン返済）。期首払年金では各期間の開始時に支払われるため、運用期間が1回分長くなり、利息の再投資効果がより大きく働きます。",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $1,000,000 portfolio generates approximately $3,333 per month before taxes, with annual adjustments for inflation.": "4%ルールに基づく毎月の引出想定額は「（退職時資産残高 × 4%）÷ 12」です。例えば1億円の資産蓄積があれば、毎月約33.3万円を取り崩しても資産の長期的な持続が期待できます。",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "4%の安全取崩しルールを適用し、株式と債券の分散投資（例：株60%、債券40%）を継続した場合、30年以上の期間にわたり資金が尽きない確率は95%を超えると歴史的研究で証明されています。",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty on top of ordinary income taxes at your marginal rate. A $20,000 withdrawal by someone in the 22% bracket would surrender roughly $6,400 in combined taxes and penalties.": "59歳半未満の年齢で確定拠出年金から早期引き出しを行うと、通常の所得税に加えて10%の追徴税（ペナルティ）が課されます。老後資金の複利運用を阻害するため慎重な判断が必要です。",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New Salary - Old Salary) ÷ Old Salary) × 100. For example, moving from $60,000 to $66,000 is a 10% raise.": "昇給額（新給与 − 旧給与）を旧給与で割り、100を掛けることで昇給率を計算できます。例：（35万円 − 30万円）÷ 30万円 × 100 = 16.67%の昇給率となります。",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals $2.50 × 2,080 = $5,200 more in pre-tax annual income.": "年間標準労働時間を2,080時間（週40時間 × 52週）として計算します。時給アップ額に2,080を掛けることで、昇給による年間給与増額が簡単に求められます。",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above a tax bracket threshold are taxed at the higher marginal rate—never your entire income. A pay raise will always increase your total take-home pay.": "いいえ。所得税は累進課税方式を採用しているため、昇給により高い税率の段階に進んだとしても、手取り額が減ることはありません。引き上げられた税率が適用されるのは、境界を超えた超過分のみです。",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and HOA fees (if applicable). If your down payment is under 20%, private mortgage insurance (PMI) is also included.": "毎月の住宅ローン支払額（PITI）は、元金および利息の返済分、固定資産税、火災・地震保険料、保証料等で構成されます。家計の負担率を適正に保つことが長期的な住宅維持の鍵となります。",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money: divide 72 by your expected annual interest rate. For example, at an 8% return, money doubles in roughly 72 ÷ 8 = 9 years.": "「72の法則」とは、複利運用で資金が2倍になる年数を素早く試算する公式です。「72 ÷ 年利」で計算でき、例えば年利6%なら約12年（72 ÷ 6）で資産が倍増します。",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, and pay ordinary income tax upon withdrawal in retirement. In a Roth 401(k), you contribute after-tax dollars, but all qualified retirement withdrawals—including all compound investment gains—are 100% tax-free.": "従来型確定拠出年金（Traditional 401k / iDeCo）では、掛金が全額所得控除の対象となるため現役時代の税負担を直接軽減できます。ただし将来の年金受取時には課税対象となります。",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities, 40% bonds), historical data indicates a 95%+ probability that your savings will last at least 30 years.": "4%の安全資産取崩し率を守り、株式と債券を適切に配分したポートフォリオを維持することで、30年間の退職期間中に資産が底をつくリスクを極小化できます。",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000), which you repay through payroll deductions with interest going back into your account.": "はい。多くの確定拠出年金プランでは、自身の残高の最大50%（上限5万ドル）までを担保にした社内融資（401kローン）が認められており、利息は自分の口座へ返済されます。",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions to compare long-term tax advantages.": "当計算機では、拠出時の所得控除を重視する「従来型」と、受取時の非課税恩恵を享受する「Roth型」の資産形成シミュレーションを切り替えて比較検討できます。",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts (such as a 401k up to the match, then a Roth IRA) after paying off all non-mortgage debt and building a 3- to 6-month emergency fund.": "デイブ・ラムジーのベビーステップ4では、借金のない健全な財務基盤を築いた後、世帯年収の15%を確定拠出年金やRoth IRAなどの税制優遇口座に長期投資することを推奨しています。",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It features lower contribution limits than a standard 401(k) but requires mandatory employer contributions (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "SIMPLE 401(k)は中小企業（従業員100人以下）向けの確定拠出年金制度で、管理コストを抑えながら従業員への年金マッチング給付を提供できる仕組みです。",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your employer's HR or payroll department and updating your deferral percentage to 0%. However, cashing out existing money while still employed is generally prohibited by IRS regulations unless your plan offers an 'in-service distribution' (usually after age 59½) or you qualify for an IRS Hardship Withdrawal (which incurs income taxes and a 10% penalty).": "将来の給与天引き拠出は、担当部署への申請によりいつでもペナルティなしで中断・停止できます。手元のキャッシュフローを急遽確保したい場合も安心です。",
    "Nominal return is the raw percentage gain generated by your investments before inflation. Real return is the purchasing power gain after subtracting the rate of inflation (Real Return ≈ Nominal Return - Inflation Rate).": "名目リターンとはインフレを差し引く前の単純な投資利回りです。実質リターンはそこからインフレ率を控除したものであり、実際に資産の購買力がどれだけ伸びたかを示します。",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit raise for strong performance typically falls between 4% and 8%, while a major promotion or job switch often commands a 10% to 20% salary increase.": "物価上昇に応じた生活費調整（COLA）の昇給幅は通常3%〜5%程度です。個人の成果や貢献度に応じた査定昇給では5%〜8%、昇進時には10%以上の給与増が一般的です。",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New - Old) ÷ Old) × 100. For example, moving from $75,000 to $82,500 is a 10% raise.": "昇給率の算出は簡単です。（改定後の新給与 − 改定前の旧給与）÷ 改定前の旧給与 × 100 で計算します。",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $3.00/hour raise equals $3.00 × 2,080 = $6,240 more in pre-tax annual compensation.": "フルタイム勤務（年2,080時間換算）の場合、時給のアップ額に2,080を掛けることで年収の増加見込み額が瞬時に算出されます。",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of your income that falls into the higher tax bracket is taxed at the higher percentage rate. Your prior earnings are still taxed at their original lower rates, so a pay raise will always result in higher total take-home pay.": "いいえ。税率は超過累進制のため、昇給によって上の税率ブラケットに入っても、増額となった部分だけに新税率がかかるため、昇給によって手取りが減少することはありません。",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while making minimum payments on all other accounts. Once the smallest balance is eliminated, you roll its payment into the next smallest debt, generating psychological momentum through quick wins.": "デット・スノーボール返済法は、残高が小さい負債から順に返済していく方法です。小口の借入を素早く片付けることで精神的な達成感が得られ、完済への弾みがつきます。",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on all others. Once the balance with the highest APR is cleared, you redirect that full payment toward the next highest interest rate account.": "デット・アバランチ返済法は、金利が最も高い負債から最優先で完済していく手法です。完済までに支払う利息の総額を最小化できるため、数学的に最も効率的です。",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid and eliminates debt faster. However, behavioral research shows that the quick psychological wins of the Debt Snowball method help many borrowers stay committed to their debt payoff journey.": "数学的観点では、最も高金利の債務を最速で撲滅するデット・アバランチ方式が、支払利息を最小化し最速で完済を達成できる最適な選択肢です。",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds), real estate, inflation-protected securities (TIPS), and high-yield savings accounts—preserves and grows your real wealth.": "インフレによる現金の価値低下に対抗するには、株式市場インデックスや不動産など、企業の成長や物価上昇に連動して収益が拡大する資産への分散投資が不可欠です。",
    "How does this online TVM calculator solve Time Value of Money equations?": "このオンラインTVM計算機は、標準的な複利計算式と割引現在価値の公式を用いて、TVMの5大変数（PV, FV, PMT, Rate, Nper）の関係性を解き明かします。",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to link five core variables: Present Value (PV), Future Value (FV), Payment (PMT), Periodic Interest Rate (r), and Total Periods (n). You enter any four known variables, and the mathematical engine automatically calculates the fifth missing parameter instantly.": "TVM（貨幣の時間価値）計算機は、現在価値、将来価値、定期支払額、利率、期間数の5つの変数のうち、入力された4つの値から残りの1つを厳密な金融数式で導き出します。",
    "How does this online TVM calculator solve Time Value of Money problems?": "このオンラインTVM計算機は、標準的な複利方程式とキャッシュフロー割引モデルを駆使して、あらゆる時間価値の計算問題を瞬時に解きます。",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (i), Number of Periods (n), and Periodic Payment (PMT). By inputting any four of these values, the calculator solves for the fifth using closed-form financial equations or numerical approximation (for interest rate).": "TVM計算機は、現在価値（PV）、将来価値（FV）、期間利率（Rate）、期間数（Nper）、定期支払額（PMT）の5つの要素を数学的に結びつけています。",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), the periodic installment you plan to deposit (PMT), the expected annual interest rate (r), the compounding frequency, and the total duration in years. The calculator solves for the exact final balance, displaying total interest earned and visual amortization charts.": "目標変数に「将来価値（FV）」を選択し、初期元本（PV）、毎期の積立額（PMT）、金利、年数を入力すれば、将来の複利蓄積総額が即座に計算されます。",
    "How do I use this as a Future Value calculator?": "将来価値（FV）計算機として利用する場合は、初期投資額をPVに入力し、期待利回りと運用年数、および毎月の積立額（PMT）を指定して計算します。",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and duration, and optionally add recurring monthly payments (PMT). The calculator compounds the initial principal and annuity payments over time, displaying the final accumulated portfolio value and total interest earned.": "将来価値を計算するには、初期預託金を現在価値（PV）に入れ、金利と期間を設定し、定期積立額（PMT）を入力して将来価値の算出を実行します。",
    "What is the difference between an ordinary annuity and an annuity due?": "期末払年金（通常年金）と期首払年金の違いは、キャッシュフローの発生タイミングです。期首払い（前払い）の方が各支払金が1期分長く複利運用されるため、将来価値が高くなります。",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (standard for lease agreements and rent). Because payments in an annuity due occur earlier, each installment earns an additional period of compound interest, resulting in a higher Future Value or higher Present Value.": "期末払年金（通常年金）では各期間の終了時に支払いが行われます（一般的なローン返済）。期首払年金では各期間の開始時に支払いが行われるため（家賃やリース契約）、資金が1期間分早く複利運用に回り、将来価値（FV）が大きくなります。",
    "What is the 5% rule for renting vs. buying?": "持ち家購入 vs. 賃貸を判断する「5%ルール」とは何ですか？",
    "The 5% rule (popularized by Ben Felix) estimates the non-recoverable annual costs of homeownership at roughly 5% of the property value: 1% for property taxes, 1% for maintenance and repairs, and 3% for the cost of capital (mortgage interest + equity opportunity cost). If renting an equivalent home costs less than 5% of its purchase price annually (or 5%/12 per month), renting is mathematically favorable.": "ベン・フェリックス氏が提唱した5%ルールとは、住宅所有に伴う年間の回収不能コスト（固定資産税約1%、維持修繕費約1%、資本コスト約3%）を物件価格の約5%と見積もる指標です。これを12で割った金額が損益分岐点となる月額家賃になります。",
    "Financial experts and the standard 28/36 rule recommend spending no more than 28% of your gross monthly income on housing costs (PITI: Principal, Interest, Taxes, and Insurance). Total monthly debt obligations (housing + cars + student loans + credit cards) should remain under 36% to maintain financial stability.": "金融の専門家や標準的な「28/36ルール」では、税引前月収の28%以下を住宅費（ローン、保険、税金）に充て、総債務返済額を36%以下に抑えることを推奨しています。",
    "Under the empirical 4% Safe Withdrawal Rule, your retirement savings are statistically projected to last at least 30 years with a balanced stock/bond portfolio. For example, withdrawing 4% annually ($40,000 from a $1,000,000 balance) adjusted annually for inflation has historically survived almost every 30-year retirement window in modern market history.": "経験則に基づく「4%の安全資産取崩しルール」に従えば、適切な分散投資（株式と債券のバランス）を維持することで、30年以上の退職期間にわたり資産が枯渇しない確率が極めて高くなります。",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest over time.": "「貨幣の時間価値（TVM）」の基本原則によれば、今日の1円（1ドル）は将来の1円（1ドル）よりも価値があります。なぜなら、現在保有する資金は投資して利息を生み出すことができ、将来の現金はインフレにより購買力が低下するためです。",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested across periodic purchases rather than investing everything in a single lump sum. By buying fixed dollar amounts at regular intervals, you automatically purchase more shares when prices are low and fewer shares when prices are high, lowering your average cost per share over time.": "ドルコスト平均法（DCA）とは、相場の高低にかかわらず一定期間ごとに同額（例：毎月3万円など）を継続して買い付ける投資戦略です。価格変動リスクを平滑化し、高値掴みを避けることができます。",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of share price.": "ドルコスト平均法（DCA）は、一定の金額を定期的に機械的・自動的に投資し続ける戦略です。感情に左右されず長期的な平均取得単価を引き下げることができます。",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement. At a minimum, always contribute enough to capture 100% of your employer's 401(k) match, as this provides an immediate 50% to 100% risk-free return on your money.": "多くのファイナンシャルアドバイザーは、税引前給与の少なくとも15%を確定拠出年金や個人年金口座などの老後資金に継続投資することを推奨しています。",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you are in the 24% federal tax bracket and contribute $10,000, you reduce your current tax bill by $2,400.": "従来型確定拠出年金（401k / iDeCo）に拠出した金額は全額が課税所得から控除され、その年の所得税と住民税をダイレクトに軽減します。",
    "How much in a 401(k) do I need to retire?": "退職して安心して暮らすには、確定拠出年金（401k / iDeCo）にいくら必要ですか？",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement spending minus guaranteed income like Social Security. For example, if you need $60,000 per year from your portfolio, your target nest egg is $1,500,000 to $1,800,000.": "「25倍の法則」（4%ルールの逆算）によれば、リタイア後の生活を維持するには年間想定支出の約25〜30倍の資産蓄積が必要です。年間支出が400万円の場合、約1億円の資産目標となります。",
    "How much will my 401(k) pay me per month in retirement?": "退職後、年金口座の資産から毎月いくら引き出すことができますか？",
    "How much tax and penalty do I pay on early 401(k) withdrawals?": "確定拠出年金の早期引き出しにはどれくらいの税金とペナルティがかかりますか？",
    "What is a Solo 401(k) and how does it work for the self-employed?": "ソロ401(k)とは何ですか？個人事業主はどのように活用できますか？",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no common-law employees. It allows you to contribute both as an employee (deferring up to $23,000 in 2024) and as the employer (up to 25% of net business compensation), providing substantial tax deductions.": "ソロ401(k)（一人型確定拠出年金）は、従業員を持たない個人事業主や法人オーナー向けの年金制度です。従業員枠と事業主枠の両方から多額の所得控除拠出が可能です。",
    "Can I borrow against my 401(k) instead of taking an early withdrawal?": "早期解約してペナルティを払う代わりに、年金口座から借り入れ（401kローン）を行うことはできますか？",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000 (whichever is less). You repay the loan with interest back into your own account, usually over 5 years. However, if you leave your job, the outstanding balance typically becomes due rapidly or converts to a taxable distribution.": "はい、多くの制度では自己資産残高の最大50%（上限5万ドル）までを担保にした貸付が認められており、利息は自分の口座に返済されるため外部流出がありません。",
    "How do I use this as a Roth vs Traditional 401(k) calculator?": "当計算機で「Roth型」と「従来型（Traditional）」の比較シミュレーションを行うにはどうすればよいですか？",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) contributions. Traditional saves money on taxes today during your peak earning years, while Roth offers completely tax-free withdrawals in retirement.": "当計算機では、拠出時に所得控除される従来型と、受取時の元本および運用益が完全に非課税となるRoth型を切り替えて、将来の受取純額を比較できます。",
    "What is a good salary increase percentage?": "昇給率（ベースアップ・昇給割合）の目安はどれくらいが適正ですか？",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong merit raises range from 5% to 8%, and promotions or job switches typically yield 10% to 20% increases. Any raise above current inflation increases your real purchasing power.": "一般的な生活費調整（COLA）による定期昇給率は3%〜4%程度、実績や評価に基づく成果昇給は5%〜8%、昇進や転職では10%〜20%以上が標準的な指標です。",
    "How do I calculate a salary increase percentage?": "昇給率（パーセンテージ）はどのように計算しますか？",
    "How do I convert an hourly pay raise into an annual salary increase?": "時給の昇給額を年収ベースの昇給額に換算するにはどうすればよいですか？",
    "Will a pay raise push me into a higher tax bracket and reduce my take-home pay?": "昇給によって高い税率ブラケットに入ると、手取り額が減ることはありますか？",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest charges; over time, as the principal balance decreases, a progressively larger portion of each payment reduces the principal debt.": "分割返済ローン（元利均等返済）では、毎期の返済額は一定ですが、返済初期は残高が多いため支払額の大部分が利息に充当され、元金の減りは緩やかです。返済が進むにつれて利息分が減り、元金返済の割合が大きくなります。",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the borrowing term, protecting you against rising interest rates. A variable-rate loan fluctuates with a market index, meaning payments can rise or fall over time.": "固定金利型ローンは借入期間を通じて適用金利と毎月の返済額が一定に維持されるため、将来の市場金利上昇リスクから家計を完全に保護できます。",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders charge prepayment fees within the first 3 to 5 years. Always verify your loan agreement's prepayment terms before submitting extra payments.": "一般的な住宅ローンやオートローンでは、ペナルティなしで元金の繰り上げ返済が可能です。繰り上げ返済した資金は直接元本に充当され、将来発生する利息を削減できます。",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from prior periods. Unlike simple interest, compound growth produces an exponential wealth curve over long time horizons.": "複利とは、投資元本だけでなく、運用によって生み出された過去の利息・配当に対してもさらに利息が生まれる仕組みです。長期になるほど資産は加速度的に増加します。",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total return. More frequent compounding converts interest into principal faster, creating a higher Effective Annual Rate (EAR) than the stated nominal APR.": "複利計算の頻度（年次、月次、日次など）が多いほど、利息の再投資タイミングが前倒しされるため、最終的な受取利息総額や実効利回りが高くなります。",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary) to determine the exact annual employer contribution added to your balance.": "マッチング機能付き年金計算機は、雇用主による上乗せ給付ルール（例：給与の6%拠出に対して50%マッチング）を反映し、会社負担による資産形成の加速効果を算出します。",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by 40, 6x by 50, 8x by 60, and 10x by age 67.": "標準的な資産形成の年齢別ベンチマークによると、30歳時点で年収の1倍、40歳で3倍、50歳で6倍、60歳で8倍、退職時に年収の10倍の資産蓄積が推奨されます。",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, investment returns, and fee drag.": "退職時の予想年金資産残高は、複利運用利回り、毎年の拠出額、勤務先の拠出金マッチング、および運用期間の長さによって決まります。",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer debt (except the home mortgage) is paid off and a 3- to 6-month emergency fund is established.": "デイブ・ラムジーのベビーステップ4では、借金完済と緊急資金準備の完了後、世帯年収の15%を確定拠出年金などの長期投資口座に継続拠出することを提唱しています。",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees, requiring a mandatory employer contribution (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "SIMPLE 401(k)は従業員100人以下の小規模企業向け年金プランで、事業主による一定のマッチング拠出が義務付けられている代わりに運営手続きが簡素化されています。",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation expenses (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income.": "20/4/10ルールでは、頭金を最低20%入れ、ローン期間を4年（48ヶ月）以内とし、返済・保険・燃料費などの総自動車維持費を手取り収入の10%以内に抑えることを推奨します。",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more in total interest. Additionally, you risk becoming 'upside-down' (owing more than the car is worth) due to rapid vehicle depreciation.": "72ヶ月や84ヶ月の超長期ローンは毎月の支払額を抑えられますが、完済までの総利息額が跳ね上がり、車の市場価値がローン残高を下回るリスクが高まります。",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance will exceed the vehicle's market value, leaving you in negative equity if the car is totaled or sold early.": "新車は最初の1年間で価値の約20%を失うほど値落ちが激しいため、十分な頭金を入れないと売却してもローンを完済できない「残債割れ」に陥ります。",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on all other debts. Once the smallest debt is eliminated, you roll its payment into the next smallest balance to build rapid psychological momentum.": "デット・スノーボール返済法は、金利にかかわらず残高が最も小さい借入から順に完済していく手法です。早期の完済体験がモチベーションを高めます。",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on the rest. Once your highest-APR balance is cleared, you target the next highest rate.": "デット・アバランチ返済法は、最も金利が高い負債から優先して集中的に返済していく手法です。トータルで支払う利息総額を数学的に最小化できます。",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest you pay and eliminates debt in the shortest calendar time. However, the Debt Snowball provides psychological quick wins that help many borrowers stick with their payoff plan.": "数学的には、最も高い金利の負債から完済するデット・アバランチ方式の方が、完済までの支払利息総額を最小化し返済期間を最も短縮できます。",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt until it is completely paid off.": "すべての負債について毎月の最低返済額を支払いつつ、余剰資金の全額を最優先の1件に集中投入し、完済したら次の優先債務へ繰り越していきます。",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain confidence, then switch to the Avalanche method to tackle high-interest credit cards mathematically.": "はい。手始めに少額の負債をスノーボール方式で完済して毎月のキャッシュフローを改善し、その後は高金利の負債を狙うアバランチ方式へ移行する併用も効果的です。",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of compound interest over time.": "将来価値（FV）とは、現在の資産や一括投資資金、または定期的な積立金が、特定の金利（利回り）のもとで複利運用された場合に、将来の特定時点でいくらの金額になるかを表す値です。",
    "Inflation is the general rise in prices for goods and services over time, resulting in a progressive decline in the purchasing power of your money.": "インフレとはモノやサービスの価格が全般的に上昇し、相対的に現金の購買力が目減りする現象を指します。",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only buy about $7,440 worth of goods and services in 10 years.": "無利息の普通預金やタンス預金は、インフレによって実質的な購買力が年々低下します。インフレ率が年3%の場合、今日の100万円の購買力は約24年で半減します。",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average price change over time for a representative basket of consumer goods and services like housing, food, transportation, and medical care.": "インフレ率は主に消費者物価指数（CPI）を用いて測定されます。一般世帯が購入するモノやサービスの価格動向を総合的に指数化したものです。",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.5% annually over multi-decade periods, though short-term spikes can exceed this range.": "先進国経済における歴史的な総合インフレ率は平均で年2%〜3%前後であり、主要国の中央銀行もインフレ目標を2%前後に設定しています。",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy.": "多くの連邦学生ローン借入者にとって、SAVEプラン等の所得連動返済プランは月々の返済額を最小化し、未払利息の免除制度を活用できる最も有利な選択肢です。",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching may capitalize unpaid interest.": "はい。連邦学生ローンの返済プランはStudentAid.govからいつでも無料で変更申請が可能です。ただしプラン変更に伴い返済期間や総利息額が変動します。",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into the loan balance or charges a slightly higher interest rate.": "「諸費用ゼロ（No-closing-cost）の借り換え」は手数料が免除されるわけではなく、諸費用が借入残高に上乗せされるか、金利がわずかに高く設定される仕組みです。",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same remaining term, you lower your monthly payment. If you shorten the term, your payment may rise, but you pay off the debt faster.": "借り換えによって毎月の返済額の引き下げと総支払利息の削減の両方を達成できる可能性があります。ただし返済期間を延長すると総利息が増える場合があります。",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though approvals up to 43% or even 50% are possible with strong credit scores.": "住宅ローンの審査において、金融機関は総返済負担率（バックエンドDTI：住宅費＋その他のすべての借入返済額÷月収）を36%〜43%以内に収めることを重視します。",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, Roth is superior. If you expect your tax bracket to be lower in retirement, Traditional is usually better.": "一般に、引退時の所得税率が現役時代よりも高くなると予想される場合はRoth型（受取時非課税）が有利であり、現役時代の税率が高い場合は従来型（拠出時所得控除）が有利です。",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under 50, and $8,000 for those 50 and older.": "米国IRA（個人退職勘定）の年間拠出限度額は、2024年時点で50歳未満が7,000ドル、50歳以上のキャッチアップ拠出適用者は8,000ドルとなっています。",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers.": "Roth IRAには所得制限があり、一定以上の高所得者は直接拠出が制限されます（その場合、裏口Rothと呼ばれるBackdoor Roth手続きが利用されます）。",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax-free and penalty-free.": "Roth IRAでは、過去に拠出した元本（拠出金）であれば、運用益とは異なりいつでもペナルティや税金なしで自由に引き出すことができます。",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have top rates exceeding 10%).": "州所得税は州ごとに税率が異なり、テキサス州やフロリダ州のように州所得税が一切課されない州もあれば、累進課税で高税率が課される州もあります。",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and sometimes Private Mortgage Insurance (PMI) or HOA fees. The principal and interest portion is calculated using the standard amortization formula.": "住宅ローンの毎月の返済額は、借入元金と利息（P&I）、固定資産税、火災保険料、頭金が少ない場合の保証料（PMI）などで構成されます。",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a total monthly mortgage payment when using an escrow account.": "PITIとは、住宅ローンの月額返済の内訳である「Principal（元金）」「Interest（利息）」「Taxes（税金）」「Insurance（保険料）」の頭文字をとった略称です。",
    "How much should I contribute to my 401(k)?": "確定拠出年金（401k / iDeCo）には毎月いくら拠出すべきですか？",
    "Most financial advisors recommend contributing at least 15% of your gross annual salary toward retirement (including employer matching). At a minimum, always contribute enough to capture your employer's full matching contribution—missing the match is walking away from free money and an instant 50% to 100% return. For 2024, the IRS employee elective deferral limit is $23,000 per year, or $30,500 if you are age 50 or older.": "専門家は税引前年収の15%以上を老後資金に投資することを推奨しています。まずは勤務先の会社マッチングを全額獲得できる割合まで拠出することが最優先です。",
    "How does this 401(k) calculator with match calculate employer contributions?": "会社マッチング機能付き年金計算機は、雇用主の拠出上乗せ額をどのように計算しますか？",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% or 100%) up to your company's matching ceiling (e.g., up to 6% of salary). For example, on a $95,000 salary with a 6% contribution ($5,700), a 50% match adds an extra $2,850/year in employer deposits. The calculator projects both your personal deferrals and employer matching contributions compounded across your entire retirement horizon.": "勤務先のマッチング計算式（例：給与の6%拠出に対して50%上乗せ給付など）に基づいて、毎月の事業主拠出額と数十年の複利積立総額を試算します。",
    "How much should I have in my 401(k) by age?": "年齢別に見ると、確定拠出年金にいくら貯蓄しておくべきですか？",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30; 2x by age 35; 3x by age 40; 4x by age 45; 6x by age 50; 8x by age 60; and 10x your final salary by age 67. If you earn $90,000 at age 40, your target 401(k) balance is approximately $270,000 to remain on track for complete income replacement.": "標準的な資産蓄積の目安（Fidelityの指標）では、30歳で年収の1倍、40歳で3倍、50歳で6倍、60歳で8倍、退職時に10倍の資産が推奨されています。",
    "Should I do a Roth or Traditional 401(k)?": "確定拠出年金は「Roth型」と「従来型（Traditional）」のどちらを選ぶべきですか？",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income and federal tax liability today; withdrawals in retirement are taxed as ordinary income. In a Roth 401(k), you contribute after-tax dollars, but your investment earnings grow completely tax-free and all qualified distributions in retirement are 100% tax-free. If you are in a low tax bracket now (early career), choose Roth; if you are currently in your peak earning years and highest tax bracket, choose Traditional.": "従来型は税引前所得から拠出するため目先の節税（所得控除）になりますが受取時に課税されます。Roth型は手取りから投資し将来の受取時が非課税になります。",
    "How much does a 401(k) contribution reduce my taxes?": "確定拠出年金への掛金拠出によって、税金はいくら軽減されますか？",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income dollar-for-dollar. The tax savings formula is: Annual Contribution × Marginal Tax Rate. For example, contributing $10,000 at a 24% federal tax bracket plus 5% state tax saves $2,900 in total taxes. Your take-home pay only drops by $7,100 while your retirement nest egg grows by a full $10,000.": "税引前の従来型口座へ拠出した金額は全額が課税所得から控除されます。限界税率が24%の方なら、100万円の拠出につき約24万円の税金が安くなります。",
    "How much will my 401(k) be worth at retirement?": "退職時までに私の確定拠出年金の総資産はいくらになりますか？",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, and time. For example, contributing $600 per month starting at age 30 with a $25,000 starting balance and an average 7.5% annual return yields approximately $1,350,000 by age 65. The vast majority of this total (over 70%) comes from compound investment growth rather than out-of-pocket deposits.": "退職時の予想資産額は、複利運用による期待利回り、自身の拠出額、勤務先のマッチング拠出額、および退職までの運用期間によって決まります。",
    "How long will my 401(k) last in retirement?": "退職後、私の年金資産は何年間持続しますか？",
    "Can I cancel my 401(k) and cash out while still employed?": "勤務を続けながら確定拠出年金を途中で解約して現金を受け取ることはできますか？",
    "How does the Dave Ramsey 401(k) calculator 15% rule work?": "デイブ・ラムジー氏が推奨する「15%年金投資ルール」はどのように機能しますか？",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into retirement once consumer debt is eliminated and a 3-to-6 month emergency fund is established. The Dave Ramsey 401k calculator strategy follows a 3-step order: (1) Invest in your company 401(k) up to the full employer match; (2) Max out a Roth IRA; (3) Put any remaining portion of the 15% into your Roth 401(k) or Traditional 401(k). Use our 'Dave Ramsey (15% Rule)' preset to model this exact path.": "デイブ・ラムジーのベビーステップ4では、負債を全額返済し3〜6ヶ月分の緊急生活防衛資金を確保した後、世帯総収入の15%を税制優遇年金口座に投資します。",
    "What is a SIMPLE 401(k) calculator and who qualifies for a SIMPLE plan?": "SIMPLE 401(k)計算機とは何ですか？どのような企業や従業員が対象になりますか？",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. A simple 401k calculator models the required employer contributions: either a dollar-for-dollar match up to 3% of salary, or a flat 2% non-elective contribution for all eligible workers. SIMPLE 401(k) plans feature 100% immediate vesting, no complex nondiscrimination testing, and lower contribution limits ($16,000 in 2024, or $19,500 if age 50+).": "SIMPLE 401(k)は従業員100人以下の小規模企業を対象とした年金プランで、事業主による一定割合の拠出上乗せを条件に、事務管理負担が軽減されています。",
    "What is Future Value (FV)?": "将来価値（Future Value: FV）とは何ですか？",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or compounding interest.": "将来価値（FV）とは、手元にある資産や毎期の積立キャッシュフローが、一定の金利（利回り）で複利運用された場合に、将来の特定期日でいくらになるかを表す金額です。",
    "What is the formula for calculating Future Value with regular contributions?": "定期的な積立を行う場合の将来価値（FV）の計算公式はどうなりますか？",
    "For a lump sum with regular periodic additions: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], where PV is present value, r is annual interest rate, m is compounding frequency per year, t is time in years, and PMT is periodic contribution.": "元本（PV）と毎期の定期積立額（PMT）がある場合の複利公式：FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) − 1) ÷ (r/m)] で算出されます。",
    "What is the difference between an ordinary annuity and annuity due for future value?": "将来価値の計算において、通常年金（期末払い）と期首払年金の違いは何ですか？",
    "In an ordinary annuity, contributions are deposited at the end of each period. In an annuity due, contributions are made at the beginning of each period, which gives every contribution an extra period to compound and results in a higher ending future value.": "通常年金では積立が各期間の末日に行われますが、期首払年金では各期間の初日に行われます。期首払いの方が1期間分長く複利運用されるため将来価値が高くなります。",
    "How does compounding frequency impact the future value of an investment?": "複利計算の頻度は、投資の将来価値にどのような影響を与えますか？",
    "More frequent compounding cycles (such as monthly or daily versus annually) result in higher future values because interest earned in earlier cycles begins generating its own interest sooner.": "複利計算の頻度が細かいほど（年1回より月次、日次）、利息が元本に組み込まれるスピードが早くなり、最終的な将来価値が大きくなります。",
    "What is a realistic annual rate of return for an investment calculator?": "投資計算機に入力する年間利回り（期待リターン）として、現実的な水準は何%ですか？",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of approximately 10% annually over long multi-decade horizons (or roughly 7% after adjusting for inflation). A diversified portfolio of stocks and bonds typically targets 6% to 8% nominal annual return.": "歴史的に、米国株式市場（S&P 500）の過去100年間の平均名目リターンは約10%（インフレ控除後の実質リターンで約7%）ですが、年ごとの変動は大きくなります。",
    "How do regular recurring investments compare to a one-time lump sum?": "定期定額投資（積立投資）と一括投資はどのように比較されますか？",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility by consistently purchasing shares at both market highs and lows. While lump-sum investing mathematically outperforms about 68% of the time due to long-term market upward trends, recurring monthly deposits instill discipline and build substantial wealth steadily.": "定期定額投資（ドルコスト平均法）は相場高値での一括投資リスクを軽減し、価格下落局面で多くの口数を購入することで平均購入単価を引き下げる効果があります。",
    "What is the difference between nominal return and real return?": "名目利回り（名目リターン）と実質利回り（実質リターン）の違いは何ですか？",
    "How does compound interest multiply investment portfolios over time?": "時間の経過とともに、複利効果はどのように投資ポートフォリオを倍増させますか？",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contributions make up the majority of your balance; however, after 10 to 20 years, investment returns and compounded earnings account for over 60% to 80% of total portfolio value.": "複利効果は指数関数的な資産成長を生み出します。初期は自己資金の積立が中心ですが、期間が経つと運用益が生む利息が元本を上回る規模へと成長します。",
    "How do I calculate a percentage salary increase?": "昇給率（パーセンテージ）はどのように算出しますか？",
    "To calculate the percentage increase: subtract your old salary from your new salary, divide the difference by your old salary, and multiply by 100: ((New - Old) / Old) × 100. For example, moving from $75,000 to $82,500 is (($82,500 - $75,000) / $75,000) × 100 = 10%.": "昇給率の計算式：（新しい給与 − 以前の給与）÷ 以前の給与 × 100。差額を元の給与で除して100を掛けることで昇給割合が求まります。",
    "How much of my salary raise will I actually take home after taxes?": "昇給した金額のうち、税金や社会保険料を差し引いた実際の手取り額はいくら増えますか？",
    "Your net take-home boost depends on your marginal tax bracket and payroll deductions. Because raises are taxed at your highest marginal rate rather than your lower average rate, you typically take home between 55% and 75% of your gross increase (depending on state taxes and FICA).": "実際の手取り増加額は、自身の限界税率（所得税・住民税・社会保険料率の合計）によって決まります。昇給分の一部は税金や保険料となりますが手取りは確実に増えます。",
    "What is the difference between a merit raise and a cost-of-living adjustment (COLA)?": "成果・能力に応じた昇給（Merit Raise）と物価スライドによる生活費調整（COLA）の違いは何ですか？",
    "A Cost of Living Adjustment (COLA) is an across-the-board raise (typically 2% to 4%) designed to keep your purchasing power level with consumer inflation. A merit or performance raise is an individualized increase rewarded for outstanding work, increased duties, or hitting high performance benchmarks.": "生活費調整（COLA）はインフレによる購買力低下を補う一律昇給（通常2%〜4%）であり、成果昇給は個人の職務実績や貢献度を評価して上乗せされる昇給です。",
    "How often should you ask for a salary increase?": "昇給の交渉はどれくらいの頻度で行うべきですか？",
    "Standard corporate practice evaluates compensation annually during performance reviews. However, you should initiate compensation discussions whenever you take on significantly expanded responsibilities, complete major high-value certifications, or outperform annual targets by a substantial margin.": "一般的な企業慣行では年1回の年次人事評価のタイミングで給与見直しが行われます。ただし大きな職責変更や著しい成果を上げた場合は柔軟な交渉が可能です。",
    "How is a mortgage payment calculated?": "住宅ローンの毎月の返済額はどのように計算されますか？",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "毎月の住宅ローン支払額は、元金と利息、固定資産税、火災保険・地震保険料、頭金20%未満の場合の保証料、および管理費・修繕積立金から構成されます。",
    "What is the Debt Snowball method?": "スノーボール（雪だるま）返済法とは何ですか？",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "金利の高低にかかわらず、残高が最も小さい負債から優先して完済していく手法です。迅速な成功体験により心理的な達成感と継続意欲を高めます。",
    "What is the Debt Avalanche method?": "アバランチ（雪崩）返済法とは何ですか？",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "金利が最も高い負債から集中的に完済していく手法です。数理計算上、支払利息総額を最小限に抑え、最も早く無借金状態に到達できます。",
    "What is net worth?": "個人の純資産（Net Worth）とは何ですか？",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "保有するすべての資産（預貯金・不動産・株式等）から負債（各種ローン）を差し引いた実質的な純価値です。",
    "How much emergency fund is recommended?": "生活防衛資金（緊急用資金）はいくら確保すべきですか？",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "一般的には生活必須費用の3〜6か月分の貯蓄が推奨されます。フリーランスなど収入の変動が大きい方や扶養家族が多い場合は、9〜12か月分を確保しておくと安全です。",
    "What is Dollar-Cost Averaging (DCA)?": "ドルコスト平均法（積立投資）とは何ですか？",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "価格の変動に関係なく、定期的に一定金額（毎週・毎月など）を買い付け続ける投資手法です。短期的な価格の波を平準化し、感情的な売買タイミングの誤りを防ぎます。",
    "What is inflation?": "インフレーション（物価上昇）とは何ですか？",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "モノやサービスの価格が全体的に上昇し、お金の購買力が相対的に低下する現象です。",
    "What is the SAVE plan?": "米国の奨学金・学生ローン返済プラン「SAVE」とは何ですか？",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "卒業後の可処分所得に応じて月々の返済額を調整し、未払い利息の元金組入れを防ぐ最新の公的返済支援制度です。",
    "How is discretionary income calculated for student loans?": "学生ローンにおける「可処分所得」はどのように算出されますか？",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "調整後総所得（AGI）から、世帯人数に応じた連邦貧困基準免除額（SAVEプランでは225%）を控除した差額です。",
    "How does an amortized loan work?": "元利均等返済の仕組みはどうなっていますか？",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest. Over time, an increasing portion goes toward paying down the principal balance until the debt is fully paid off.": "毎回の返済額が一定となる方式です。返済初期は利息の割合が高く、借入残高の減少に伴い元金の充当割合が徐々に高まっていきます。",
    "What is the difference between fixed-rate and variable-rate loans?": "固定金利型と変動金利型にはどのような違いがありますか？",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the loan term. A variable-rate loan has an interest rate that adjusts periodically based on benchmark interest rates, which can increase or decrease your payments.": "固定金利型は全期間で金利と返済額が変わりません。変動金利型は半年ごとなどの基準金利の見直しに応じて返済額が増減します。",
    "Can I pay off my loan early without penalty?": "違約金なしで全額繰り上げ返済や前倒し返済はできますか？",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, but some lenders include a prepayment penalty clause. Always verify your loan agreement terms before making accelerated principal payments.": "一般消費者ローンや多くの住宅ローンでは手数料無料ですが、一部の固定金利商品や信販会社では事務手数料や違約金が設定されている場合があります。",
    "What is the difference between interest rate and APR?": "表面金利（名目金利）と実質年率（APR）の違いは何ですか？",
    "The interest rate is the nominal cost of borrowing the principal balance. The Annual Percentage Rate (APR) reflects the total annual cost of the loan including points, broker fees, and origination charges.": "表面金利は借入元本に対する純粋な金利です。実質年率（APR）は事務手数料や保証料など全ての付帯コストを含めた実質的な年間借入コストです。",
    "What is the 4% rule in retirement planning?": "リタイアメント計画における「4%ルール」とは何ですか？",
    "The 4% rule suggests that withdrawing 4% of your retirement portfolio in the first year, adjusted for inflation annually thereafter, provides a high probability that your nest egg will last at least 30 years.": "退職初年度に資産総額の4%を取り崩し、以降はインフレ率に応じて調整すれば、30年以上にわたり資産が枯渇しない確率が極めて高いとする理論です。",
    "What is compound interest?": "複利とは何ですか？",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It causes your wealth to grow exponentially over time.": "当初の元本だけでなく、過去に発生した利息に対しても新たに利息が付与される計算方式で、雪だるま式に資産が増加します。",
    "What is the Rule of 72?": "「72の法則」とは何ですか？",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your annual interest rate (e.g. at 8%, your money doubles in about 9 years).": "資産が2倍になるまでのおおよその年数を瞬時に算出する公式です。72を年利回りで割ることで求められます（年利8%なら約9年で2倍）。",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price.": "相場価格の変動に関係なく、常に決まった金額を定期的に機械的に買い付け続ける投資手法です。",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "15年返済は金利が低く、返済期間が半減するため利息総額を数万ドル（数百万円）単位で削減できます。一方、30年返済は毎月の返済額が低く抑えられ、家計の資金繰りに余裕を持たせることができます。",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "住宅ローンで増額返済した資金はすべて借入元金に直接充当されます。これにより元本が減り、将来発生する利息が抑えられるため、返済年数を大幅に前倒しし利息を劇的に節約できます。",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "数学的には支払利息を最小化できるアバランチ方式が合理的ですが、研究では小さな借入を素早く完済してモチベーションを維持できるスノーボール方式の方が現実に挫折しにくいと示されています。",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "どちらの手法でも、すべての借入について毎月の最低返済額は維持します。その上で余剰資金を集中対象（残高最少または最高金利）に充当し、完済したらその返済原資（最低返済額＋余剰金）を次の借入にスライドさせて返済を加速します。",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "はい。最初の1〜2件の少額借入を完済して心理的達成感と手元キャッシュフローを確保した（スノーボール）後、残りの借入を高金利順（アバランチ）に切り替えて利息を節約するハイブリッド手法も非常に有効です。",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "金利をより低く見直し、毎月の返済額を削減できるか、返済期間を短縮できる場合に借り換えのメリットがあります。最大のポイントは、利息の総削減額が借換諸費用を上回ることです。",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "借り換え費用には、事務手数料、保証料、物件評価鑑定費用、登記費用、登録免許税などが含まれ、通常は借入金額の2%〜6%程度になります。",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "損益分岐点（月数）を求めるには、借り換えにかかる諸費用の総額を毎月の返済削減額で割ります。例えば諸費用が3,000ドルで毎月150ドル節約できる場合、損益分岐点は20か月（3,000÷150）です。この期間より前に売却や転居を予定している場合は借り換えのメリットが出ません。",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into your new total loan balance or charges a slightly higher interest rate to cover them. This avoids paying cash upfront but increases the lifetime cost of the loan.": "初期費用ゼロの借り換えであっても費用が免除されたわけではありません。諸費用が新規借入元金に上乗せされているか、相殺するために金利が高めに設定されています。手元の現金を温存できますが、ローンの総返済額は増加します。",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same or shorter term, you save on both. However, if you reset your term back to 30 years to get the lowest possible monthly payment, you might end up paying more total interest over the life of the loan despite the monthly savings.": "金利と返済期間の設定によります。期間を変えずに低金利へ借り換えた場合は月額と総利息の両方が減りますが、月額を最低にするために期間を30年にリセットすると、毎月は安くなっても生涯総支払利息は増えることがあります。",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "28/36ルールは住宅ローンの標準的な融資審査基準です。月収（額面）に対する住居費の比率を最大28%、他のすべての負債返済（マイカーローン、クレジットカード、奨学金など）を合算した比率を最大36%以内に抑えるべきとする健全性の目安です。",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "金融機関は毎月の返済能力を測るためにDTI（返済負担率）を用います。DTIが高いと過剰債務とみなされ審査落ちや高金利設定の原因となります。36%未満であれば低リスクと判定されます。",
    "Front-end DTI only includes housing expenses (mortgage principal, interest, taxes, and insurance). Back-end DTI includes housing expenses plus all other recurring debts like student loans, auto loans, and minimum credit card payments.": "フロントエンドDTIは住居費（元金、利息、固定資産税、火災保険料）のみを対象とします。バックエンドDTIは住居費に加えて、自動車ローン、奨学金、クレジットカード最低返済額などすべての定期的な債務返済を含めます。",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though many will approve up to 43%. Government-backed loans like FHA and VA loans can be more flexible, sometimes allowing back-end DTIs up to 50% or higher if you have a strong credit score or significant cash reserves.": "一般的な住宅ローンではバックエンドDTIが36%以下が推奨されますが、43%程度まで承認される場合もあります。信用スコアが高く十分な預貯金があれば50%程度まで許容される制度もあります。",
    "You can lower your DTI by paying down outstanding credit card balances, paying off small personal loans, refinancing to lower rates, or increasing your gross monthly income (e.g. through a side business, raise, or adding a co-borrower).": "クレジットカード残高の繰り上げ返済、少額借入の完済、低金利への借り換え、あるいは収入増加（副業、昇給、連帯債務者の設定など）によりDTIを改善できます。",
    "How does debt consolidation save you money?": "おまとめローン（借換一本化）はどのように利息を節約しますか？",
    "By combining multiple high-interest credit card balances or personal loans into a single personal loan with a lower interest rate, you reduce the total amount of interest that accumulates each month. This lets more of your monthly payment go directly towards the principal balance.": "高金利のクレジットカードのリボ残高や複数の消費者金融ローンを、低金利の単一ローンに一本化することで、毎月発生する利息を大幅に削減できます。これにより返済額の多くが直接元本に充当されるようになります。",
    "Does debt consolidation hurt your credit score?": "おまとめローンを利用すると信用スコア・信用情報に悪影響がありますか？",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "新規申込時に信用照会による一時的な信用スコアの低下が生じますが、限度額いっぱいのカード残高を完済することで利用率（クレジット使用率）が下がり、数か月以内に信用スコアが大きく改善することが一般的です。",
    "What is the difference between debt consolidation and debt settlement?": "おまとめローン（債務統合）と債務整理（減額交渉）の違いは何ですか？",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "おまとめローンは低金利の新規借入で既存の債務を全額返済するため信用情報に傷がつきません。一方、債務整理は支払いを停止して減額を交渉する手続きであり、信用情報機関に重大な事故情報（ブラックリスト）が長期間記録されます。",
    "What should I look out for before consolidating debt?": "借入を一本化する前に気をつけるべき注意点は何ですか？",
    "Watch out for upfront origination fees, prepayment penalties, and ensure the new loan term isn't stretched so far out that you pay more total interest despite a lower monthly payment. Most importantly, avoid running up new balances on the cleared credit cards.": "融資事務手数料や繰り上げ返済違約金の有無を確認し、返済期間を延ばしすぎて総支払利息が増えてしまわないよう注意が必要です。また完済したクレジットカードで再び浪費しない規律が重要です。",
    "When is the earliest age I can claim Social Security retirement benefits?": "公的年金の繰り上げ受給は最短何歳から請求できますか？",
    "The earliest age you can claim Social Security retirement benefits is 62. However, claiming early results in a permanent reduction of up to 30% of your monthly benefit compared to waiting until full retirement age.": "最短で62歳から請求可能ですが、満額受給開始年齢（67歳）と比べて毎月の年金額が生涯にわたり最大30%永久減額されます。",
    "What is my Full Retirement Age (FRA)?": "満額受給開始年齢（FRA）とは何歳ですか？",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "1960年以降生まれの方の満額受給開始年齢は67歳です。この年齢で請求すれば、減額ペナルティを受けることなく標準受給額（PIA）を100%満額で受給できます。",
    "How much more do I get if I delay claiming Social Security until age 70?": "年金の受給開始を70歳まで繰り下げるとどれくらい増額されますか？",
    "For every year you delay claiming Social Security past your Full Retirement Age (up to age 70), your benefit increases by 8% per year in delayed retirement credits (up to a 24% permanent boost at age 70).": "満額受給年齢を超えて1年繰り下げるごとに年金額が年率8%増額され、70歳まで繰り下げた場合は生涯にわたり最大24%の永久加算を受け取ることができます。",
    "What is the Social Security break-even age between claiming early vs delaying?": "繰り上げ受給と繰り下げ受給の受取総額の損益分岐年齢は何歳ですか？",
    "The break-even age between claiming early at age 62 versus waiting until age 70 is typically around age 80 to 82. If you expect to live past this age, waiting until 70 produces significantly more lifetime wealth.": "62歳受給と70歳受給の生涯受給総額の損益分岐点は概ね80歳〜82歳です。これ以上の長生きを見込む場合、70歳まで待つ方が生涯で受け取る年金総額が大幅に多くなります。",
    "What is the Australian Superannuation Guarantee (SG) rate?": "オーストラリアの退職年金保証（SG）拠出率は何%ですか？",
    "Under Australian law, employers are required to contribute a statutory percentage of your ordinary time earnings into your superannuation fund. The rate is legislated to increase progressively to 12%.": "オーストラリア法に基づき、雇用主は通常の給与に対して法定比率を年金ファンドに拠出する義務があります。この比率は段階的に12%まで引き上げられます。",
    "How is money inside Australian Super taxed?": "オーストラリアのSuper年金ファンド内の資金はどのように課税されますか？",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "事業主拠出や給与天引き（サラリーサクリファイス）による税制優遇拠出は、ファンド内で一律15%の優遇税率で課税され、個人の限界所得税率（最大45%＋医療保険料）と比べて大幅に節税されます。",
    "How much super do I need for a comfortable retirement in Australia?": "オーストラリアでゆとりある老後を送るにはいくらの年金資金が必要ですか？",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "ASFA（豪年金基金協会）の基準によると、67歳時点で単身者は約595,000豪ドル、夫婦世帯は約690,000豪ドルの残高があれば、ゆとりある引退生活を維持できると試算されています。",
    "How does salary sacrificing boost superannuation growth?": "給与天引き（Salary Sacrifice）はどのように年金資産を増やしますか？",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "税引前の給与から直接年金ファンドへ拠出することで、高率の所得税を回避しつつ数十年間の複利運用効果を享受できるため、退職時の資産を数十万ドル規模で大きく押し上げることができます。",
    "What is the FIRE movement and what does it mean?": "FIREムーブメントとは何ですか？どのような意味がありますか？",
    "FIRE stands for Financial Independence, Retire Early. It is a financial movement dedicated to extreme savings and intentional investing, allowing people to retire decades before conventional retirement ages.": "FIREとは「経済的自立と早期リタイア（Financial Independence, Retire Early）」の頭文字です。支出を最適化し余剰資金を高配当株やインデックスファンド等に集中的に投資することで、標準的な定年よりも数十年早く退職することを目指すライフスタイルです。",
    "What is the 4% Safe Withdrawal Rule?": "4%ルール（安全な取り崩し率）とは何ですか？",
    "The 4% Rule, established by the Trinity Study, states that you can safely withdraw 4% of your invested portfolio in the first year of retirement, adjust that dollar amount for inflation every year thereafter, and have a 95%+ probability of your money lasting 30+ years.": "トリニティ・スタディに基づく資産管理の法則で、リタイア初年度に投資元本の4%を取り崩し、翌年以降はインフレ率に応じて調整していけば、30年以上にわたり資産が枯渇しない確率が95%以上であるとする理論です。",
    "How is your FIRE Number calculated?": "FIRE達成に必要な目標金額（FIREナンバー）はどう計算しますか？",
    "Your FIRE Number is calculated by multiplying your estimated annual living expenses by 25 (the inverse of the 4% rule): Annual Expenses × 25 = FIRE Goal.": "年間の想定生活費に25を掛けて計算します（4%ルールの逆数）：年間生活費 × 25 = FIRE目標資産額。",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Lean FIRE、Standard FIRE、Fat FIREの違いは何ですか？",
    "Lean FIRE targets a minimalist lifestyle with expenses below average (usually under $40,000/year). Standard FIRE covers typical baseline middle-class expenses ($40,000–$80,000/year). Fat FIRE supports an affluent lifestyle with abundant travel and luxury ($100,000+/year).": "Lean FIREは年間生活費を抑えたミニマリスト的生活（年約400万円未満）、Standard FIREは中流の快適な生活水準（年約400万〜800万円）、Fat FIREは旅行や贅沢も楽しむゆとりのある富裕層生活（年1,000万円以上）を前提とした目標設定です。",
    "What is daily compound interest and how does it work?": "日次複利（日歩複利）とは何ですか？どのように機能しますか？",
    "Daily compound interest calculates interest on both your initial principal and previously accumulated interest each day. Over time, interest begins earning interest rapidly, creating an exponential curve that grows significantly faster than simple or monthly compounding.": "当初元本だけでなく、日々加算される利息に対しても毎日利息が計算される仕組みです。利息が利息を生む複利サイクルが最も高頻度で回るため、単利や月次複利に比べて資産が急激に加速して成長します。",
    "What is the formula for daily compound interest?": "日次複利の計算式はどうなりますか？",
    "The standard daily compounding formula is A = P(1 + r/365)^(365*t), where A is the final balance, P is initial principal, r is annual interest rate (decimal), and t is time in years.": "標準的な計算式は A = P × (1 + r÷365)^(365×t) です。Aは最終残高、Pは当初元本、rは年間利回り、tは年数です。",
    "How much more money do you earn with daily vs monthly compounding?": "月次複利と比べて日次複利はどれくらい多くの利益を得られますか？",
    "On a $100,000 deposit at 5% APY over 20 years, daily compounding yields roughly $300 to $500 more than monthly compounding due to faster compounding reinvestment.": "例えば10万ドルを年利5%で20年運用した場合、利息の再投資タイミングが早いため、月次複利よりも約300〜500ドル多く増えます。",
    "Do high-yield savings accounts (HYSA) compound daily?": "高利回り普通預金（ネット銀行・HYSA）は日次複利で計算されますか？",
    "Yes! Most modern high-yield savings accounts and money market accounts compound interest daily and credit the earnings into your account on a monthly basis.": "はい。多くのネット銀行やMMF（マネー・マーケット・ファンド）では日々の残高に対して日次複利で利息を計算し、毎月1回口座に入金（受取）されます。",
    "What is an HP 12C financial calculator and why is it used?": "HP 12C金融電卓とは何ですか？なぜ今も使われているのですか？",
    "The HP 12C is the gold standard programmable financial calculator created by Hewlett-Packard in 1981. It is renowned for its durability, Reverse Polish Notation (RPN) efficiency, and is one of the few calculators permitted on the CFA, CFP, and Real Estate appraiser certification examinations.": "HP 12Cは1981年にヒューレット・パッカード社が発売した金融電卓の金字塔です。圧倒的な頑丈さとRPN（逆ポーランド記法）による素早い計算効率で知られ、CFA（米国証券アナリスト）、CFP、不動産鑑定士試験で持ち込みが公式認可されている数少ない電卓の1つです。",
    "How does Reverse Polish Notation (RPN) work on the HP 12C?": "HP 12CのRPN（逆ポーランド記法）はどのように操作しますか？",
    "RPN eliminates the need for parentheses and an equals key. You enter numbers first onto a 4-level stack (X, Y, Z, T), and then press the operator. For example, to add 25 and 15, you press [2][5] [ENTER] [1][5] [+], giving 40 immediately.": "括弧やイコールキーを使わずに計算する方式です。数値を4層のスタック（X, Y, Z, T）に入力してから演算子を押します。例えば25に15を足す場合、[2][5] [ENTER] [1][5] [+] と押すだけで瞬時に40が求まります。",
    "How do I calculate Time Value of Money (TVM) on this emulator?": "このエミュレーターでTVM（貨幣の時間価値）を計算するにはどうすればよいですか？",
    "Store your known values into the TVM registers (n for periods, i for interest rate, PV for present value, PMT for payment, FV for future value). Press the key of the unknown variable to solve for it. Remember financial sign conventions: cash outflows are entered with CHS (negative).": "既知の数値を各TVMレジスタ（期間n、金利i、現在価値PV、定期返済PMT、将来価値FV）に格納し、求めたい未知数のキーを押します。資金の流出（投資や借入返済）はCHSキーでマイナス符号をつけるのが金融電卓のルールです。",
    "Can I use my physical computer keyboard with this emulator?": "このエミュレーターでPCの物理キーボードは使えますか？",
    "Yes! Use your computer numpad or number keys for digits 0-9, Enter for the ENTER stack key, standard arithmetic keys (+, -, *, /), and Backspace to clear the entry.": "はい！テンキーや数字キー（0〜9）、Enterキー（ENTER）、四則演算キー（+、-、*、/）、バックスペース（消去）をそのまま操作できます。",
    "Is the TI BA II Plus permitted on CFA and CFP exams?": "TI BA II PlusはCFAやCFPの試験で使用できますか？",
    "Yes! The Texas Instruments BA II Plus (including the Professional model) is one of only two official calculators authorized by the CFA Institute, GARP (FRM), and CFP Board for in-person certification examinations.": "はい！Texas Instruments BA II Plus（プロフェッショナル版を含む）は、CFA協会、GARP（FRM）、CFPボードにより試験会場への持ち込みが公式に許可されている2大公認電卓の1つです。",
    "How do I solve for a TVM variable (like PV or PMT) on the TI BA II Plus?": "TI BA II PlusでPVやPMTなどのTVM変数を求める操作方法は？",
    "Enter your known values by typing the number followed by the variable key (e.g., [1][0] [N], [8] [I/Y], [5][0][0] [CHS] [PMT]). To calculate the unknown value, press [CPT] followed by the variable key (e.g., [CPT] [PV]).": "数値を入力した後に変数のキーを押して登録し（例: [1][0] [N]、[8] [I/Y]）、未知数を求めるには [CPT] を押した後に求めたい変数のキー（例: [CPT] [PV]）を押します。",
    "What is the difference between BGN and END mode?": "BGNモードとENDモードの違いは何ですか？",
    "END mode assumes cash flows occur at the end of each payment period (standard loans, ordinary annuities). BGN mode assumes payments occur at the beginning of each period (annuities due, lease payments).": "ENDモードは支払いが各期末に行われる前提（通常のローン返済や年金）、BGNモードは支払いが各期首に行われる前提（家賃リース料や期首払年金）です。",
    "Why does my answer have a negative sign?": "計算結果にマイナス（負の符号）がつくのはなぜですか？",
    "Financial calculators strictly enforce cash flow conventions. Money paid out (outflow/deposit/investment) is negative; money received (inflow/loan proceeds/future payout) is positive.": "金融計算ではキャッシュフローの方向を厳密に区別するためです。手元から出ていくお金（出金・投資・返済）はマイナス、手元に入ってくるお金（入金・借入金・満期金）はプラスとして表されます。",
    "What is PMI and when do I pay it?": "住宅ローン保証料（PMI）とは何ですか？いつ支払う必要がありますか？",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "債務不履行リスクから金融機関を保護するための保証保険です。通常、購入価格に対する自己資金（頭金）が20%未満の場合に加入が義務付けられます。",
    "What does PITI stand for?": "PITIとは何の略ですか？",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "元金（Principal）、利息（Interest）、税金（Taxes）、保険料（Insurance）の頭文字を取ったもので、住宅保有に伴う毎月の実質的コストの総称です。",
    "Is a 15-year mortgage better than a 30-year mortgage?": "15年返済と30年返済はどちらが有利ですか？",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility.": "15年返済は低金利が適用され総利息負担を大幅に圧縮できますが、30年返済は毎月の支払額を抑えて家計のキャッシュフローにゆとりを持たせることができます。",
    "How do extra payments affect my mortgage payoff schedule?": "繰り上げ返済を行うと返済計画はどう変わりますか？",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule.": "繰り上げ返済額はすべて直接元本の減額に充当されます。これにより将来発生する利息が減少し、完済までの期間を数年単位で短縮できます。",
    "Which method is better: Debt Snowball or Debt Avalanche?": "スノーボール法とアバランチ法はどちらが優れていますか？",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum helps people stick to their plan.": "財務理論上は利息を節約できるアバランチ法が優位ですが、現実には小さな借金を次々に消去できるスノーボール法の方が挫折しにくいと証明されています。",
    "How does the 'extra payment' roll over in these strategies?": "余剰返済資金はどのように引き継がれますか？",
    "You continue paying minimums on all debts and add your extra cash to the target debt. Once that target debt is fully paid off, you roll its entire payment into the next debt on your list.": "他の全負債で最低返済額を維持しつつ、余剰現金を目標の負債に集中投入します。完済後はその返済原資を丸ごと次の負債の返済に繰り越します。",
    "Can I do a hybrid of Snowball and Avalanche?": "両方の手法を組み合わせたハイブリッド運用は可能ですか？",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate (Avalanche).": "はい。最初の1〜2件の少額借入を完済して手元資金を確保し（スノーボール）、その後は高金利順の返済に切り替える（アバランチ）方法が実用的です。",
    "When should I refinance my loan?": "住宅ローンの借り換えはいつ行うべきですか？",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term, provided your total interest savings exceed the closing costs.": "借り換えによって金利を大幅に引き下げられ、利息削減効果が事務手数料や登記費用などの諸経費を上回る場合に推奨されます。",
    "What closing costs are associated with refinancing?": "住宅ローンの借り換えにはどのような初期費用がかかりますか？",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees, ranging from 2% to 6% of the loan amount.": "融資事務手数料、保証料、抵当権抹消・設定の登録免許税、司法書士報酬などがかかり、借入額の2%〜5%程度が一般的です。",
    "How do I calculate my refinance break-even point?": "借り換えの損益分岐点（元が取れる期間）はどう計算しますか？",
    "Divide your total refinance closing costs by your monthly payment savings. If closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150).": "借り換えにかかる諸費用の総額を毎月の返済軽減額で割ります。費用が30万円で毎月1.5万円軽減される場合、損益分岐点は20か月となります。",
    "What is a 'no-closing-cost' refinance?": "手数料実質0円の借り換えとはどのようなものですか？",
    "A no-closing-cost refinance means the lender either rolls the closing fees into your new total loan balance or charges a slightly higher interest rate to cover them.": "手数料が無料になるのではなく、諸費用分が新しい借入元本に上乗せされているか、若干高めの適用金利に転嫁されています。",
    "Does refinancing lower my monthly payment or total interest?": "借り換えで減るのは月々の返済額ですか、それとも総利息ですか？",
    "It depends on the term. Refinancing to a lower rate with the same or shorter term saves on both. Resetting your term back to 30 years lowers the monthly payment but can increase total lifetime interest.": "返済期間によります。期間を変えずに金利を下げれば両方削減されますが、返済期間を延ばすと毎月の負担は減っても総利息が増える可能性があります。",
    "The Saving on a Valuable Education (SAVE) plan is an income-driven repayment (IDR) plan that protects discretionary income up to 225% of the poverty line, lowers payments to 5%-10%, and stops unpaid interest from accumulating.": "所得連動型返済プランで、貧困基準の225%に相当する所得を保護し、月々返済額を可処分所得の5〜10%に抑え、未払利息の元本組入を防ぎます。",
    "How does student loan forgiveness work under IDR plans?": "所得連動プランにおける残債免除はどのように機能しますか？",
    "If you pay under an IDR plan for 20 or 25 years (or 10 years under SAVE for low initial balances), any remaining student debt is forgiven.": "プランの定めに従い20年または25年間（低残高の場合は最短10年間）継続して返済を行えば、残存する債務残高は全額免除されます。",
    "Which IDR plan is best for me?": "どの返済プランが最も適していますか？",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. Borrowers with very high incomes relative to debt may prefer PAYE or IBR due to payment caps.": "大半の借入者にはSAVEプランが最小負担となりますが、負債に対して高収入な方の場合は上限設定があるPAYEやIBRが有利な場合もあります。",
    "Can I switch student loan repayment plans at any time?": "返済プランは途中で自由に変更できますか？",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause unpaid interest to capitalize.": "公式サイトを通じて無料で変更手続きが可能ですが、プラン変更時に未払利息が元本に組み入れられる場合があります。",
    "What is the 28/36 rule?": "28/36基準（返済負担比率ルール）とは何ですか？",
    "The 28/36 rule is a standard mortgage underwriting guideline stating that housing costs should not exceed 28% of gross monthly income, and total debt payments should not exceed 36%.": "住宅関連コストを月収の28%以内に抑え、カードやマイカーローンを含む負債全体の返済額を36%以内に抑える審査基準です。",
    "How does DTI affect my mortgage application?": "返済負担率（DTI）は住宅ローンの審査にどう影響しますか？",
    "Lenders use DTI to measure your ability to manage monthly payments. Lower DTIs below 36% receive the most favorable mortgage terms and lowest interest rates.": "金融機関が返済能力を測定する指標です。比率が30〜36%未満の安全圏にあれば、審査通過率が向上し最優遇金利が適用されます。",
    "What is the difference between front-end and back-end DTI?": "フロントエンド比率とバックエンド比率の違いは何ですか？",
    "Front-end DTI only includes housing expenses (mortgage, property tax, insurance, HOA). Back-end DTI includes housing plus all recurring debts like credit cards, auto loans, and student loans.": "前者は住宅コストのみを対象とし、後者はマイカーローンや教育ローン、クレジットカードのリボ残高など全ての借入を含めます。",
    "What is the maximum DTI ratio lenders will accept?": "金融機関が許容する返済負担率の上限はどれくらいですか？",
    "Conventional mortgages typically prefer back-end DTIs of 36% to 43%. Government-backed loans like FHA and VA may allow DTIs up to 50% with strong compensating factors.": "一般的な基準は35%〜40%以内ですが、信用スコアや頭金比率が高い場合は特例として45〜50%まで認容されるケースもあります。",
    "How can I lower my Debt-to-Income ratio?": "返済負担率（DTI）を下げるにはどうすれば良いですか？",
    "You can lower your DTI by increasing gross income or paying off smaller debts completely to eliminate their recurring monthly minimum payments.": "額面収入を増やすか、小口のローンやキャッシング残高を完済して毎月の返済義務そのものを消滅させることが効果的です。",
    "Why is APR higher than the advertised interest rate?": "なぜ実質年率は広告に表示された金利より高くなるのですか？",
    "APR is higher because it amortizes all upfront lender fees, discount points, and closing costs into the effective yearly rate, revealing the true cost of credit.": "融資実行時に支払う初期手数料や諸経費を毎年の借入期間全体に割り振って計算するため、実質コストを明確に示します。",
    "Is APR useful for comparing different loan offers?": "各金融機関のローンを比較する際、APRは有用ですか？",
    "Yes, APR is the best metric for comparing loan offers with different fee structures, provided you plan to keep the loan for its full term.": "はい。手数料体系が異なる複数プランを同一基準で客観的に横断比較するための最も正確な指標です。",
    "How long do I need to stay in a home for buying to beat renting?": "購入が賃貸より得になるには何年以上住み続ける必要がありますか？",
    "Because upfront closing costs, moving fees, and commissions are substantial, homeowners usually need to stay in a property for 4 to 7 years for buying to financially outperform renting.": "仲介手数料や登記費用などの初期コストが大きいため、購入が賃貸のトータル支出を下回るには通常4〜7年以上の居住期間が必要です。",
    "What hidden costs of homeownership should renters consider?": "持ち家を検討する賃貸居住者が注意すべき隠れコストは何ですか？",
    "Homeowners must pay property taxes, homeowners insurance, maintenance and repairs (typically 1-2% of home value annually), HOA dues, and potential capital improvement costs.": "固定資産税、火災保険、修繕積立金、そして年間建物価格の1〜2%相当とされる給湯器や外壁などの将来的な維持修繕費です。",
    "What is the opportunity cost of buying a home?": "住宅購入に伴う機会損失（機会費用）とは何ですか？",
    "The money spent on down payment, closing costs, and ongoing property maintenance could otherwise remain invested in liquid assets like index funds that compound over time.": "頭金や諸費用に投じた多額の現金を、インデックス投資信託などの成長資産で複利運用し続けた場合に得られたはずの投資リターンです。",
    "How much income should I spend on a mortgage?": "収入の何パーセントまで住宅費に充てるべきですか？",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline).": "ファイナンシャルプランナーは、手取り月収の20〜25%以内（額面総所得の28%以内）に住居費を抑えることを推奨しています。",
    "How does down payment size impact affordability?": "頭金の多寡は借入可能額にどう影響しますか？",
    "A larger down payment reduces your loan amount, eliminates Private Mortgage Insurance (PMI) if you put down 20%, and lowers your monthly mortgage payment.": "頭金を多く入れると借入総額が減り、月々の返済額が軽減され、20%以上拠出すれば保証料負担や金利優遇でも圧倒的に有利になります。",
    "How do interest rates affect purchasing power?": "住宅ローン金利の変動は予算にどれほど影響しますか？",
    "Every 1% increase in mortgage interest rates reduces your home purchasing power by roughly 10% for the same monthly payment budget.": "同じ返済額予算を維持する場合、金利が1%上昇するだけで購入可能な住宅価格は約10%目減りします。",
    "What is the 20/4/10 rule for buying a car?": "自動車購入における「20/4/10ルール」とは何ですか？",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total vehicle expenses under 10% of gross monthly income.": "頭金を20%以上用意し、ローン期間を最長4年（48回）以内とし、維持費を含めた車両関連費用を月収の10%以内に抑える原則です。",
    "Is a longer auto loan term better?": "マイカーローンの返済期間は6年や7年と長い方が得ですか？",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk becoming 'underwater' (owing more than the vehicle is worth).": "長期ローンは月額負担を軽くしますが利息が大幅に膨らみ、車の査定価値がローン残高を下回る残債割れリスクが高まります。",
    "How does vehicle depreciation affect my loan?": "自動車の減価償却（値落ち）はローンにどう影響しますか？",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, you risk owing more on your loan than the car's market value.": "新車は1年目で価値が約20%急落するため、十分な頭金がないと売却額でローンを完済できない債務超過に陥ります。",
    "Why does paying only the minimum take so long?": "クレジットカードのリボ払いで最低額返済を続けると、なぜ完済に何十年もかかるのですか？",
    "Credit card minimum payments are often set around 1% to 2% of the balance plus accrued interest. As the balance slowly drops, the required minimum drops, extending payoff times to decades.": "最低返済額は利息と元本の1〜2%程度しか補填しないよう設計されており、残高の減少とともに返済額も減るため完済期日が延び続けます。",
    "How much faster can I pay off credit cards by paying extra?": "毎月の返済額を少し増額するとどれくらい完済が早まりますか？",
    "Paying even $50 or $100 above the minimum payment can cut your payoff timeline by several years and save thousands of dollars in compounding interest charges.": "月々5,000円〜1万円上乗せして返済するだけで、完済年数を数年単位で短縮し数十万円の手数料を節約できます。",
    "Should I use a balance transfer card to pay off debt?": "おまとめローンや低金利カードへの乗り換えは有効ですか？",
    "A 0% APR balance transfer credit card can save significant interest if you pay off the full balance during the promotional period (typically 12-21 months) and factor in the 3%-5% transfer fee.": "金利優遇期間内に計画通り一括完済できるのであれば、高いリボ金利を解消する手段として極めて有効です。",
    "How much money do I need to retire comfortably?": "ゆとりある老後生活を送るにはいくらの資金が必要ですか？",
    "A common benchmark is accumulating 25 times your anticipated annual retirement expenses, or replacing 70% to 80% of your pre-retirement income.": "想定される年間生活費の25倍の資産を準備するか、現役時代の年収の70〜80%を確保できる原資を蓄えることが目安です。",
    "How does inflation impact retirement spending?": "インフレは老後資金にどのような悪影響を与えますか？",
    "Inflation steadily reduces the purchasing power of your savings. At a 3% inflation rate, everyday living expenses double roughly every 24 years, requiring growing investment portfolios.": "現金の実質的購買力を削り取ります。インフレ率3%では約24年で物価が2倍になるため、退職後も資産の一部を成長資産に配分しておく必要があります。",
    "What is an employer 401(k) match?": "確定拠出年金（401k / 企業型DC）のマッチング拠出とは何ですか？",
    "An employer match is money your employer contributes to your 401(k) account based on your own contributions (e.g. matching 50% of contributions up to 6% of your salary). It is effectively an instant return on your savings.": "従業員本人の拠出額に応じて企業が上乗せ拠出を行う制度で、拠出した瞬間に100%のリターンが得られるのと同等の恩恵があります。",
    "What are the 401(k) contribution limits for 2024?": "2024年の拠出限度額はいくらですか？",
    "For 2024, the employee contribution limit is $23,000 for those under 50. Individuals aged 50 and older can contribute an additional $7,500 catch-up contribution for a total of $30,500.": "50歳未満は年額23,000ドル、50歳以上は追加枠を含め最大30,500ドルです（日本のiDeCoは職種により月額1.2万〜6.8万円）。",
    "What is the difference between Traditional 401(k) and Roth 401(k)?": "従来型（課税繰延）とRoth型（受取時非課税）の違いは何ですか？",
    "Traditional 401(k) contributions are pre-tax and reduce your current taxable income, with withdrawals taxed in retirement. Roth 401(k) contributions are post-tax, but all qualified growth and withdrawals are completely tax-free.": "従来型は拠出時に所得控除を受け受給時に課税されます。Roth型は税引き後の資金で拠出しますが、運用益と将来の受給が全額非課税になります。",
    "What is the key difference between a Roth and Traditional IRA?": "個人退職口座（IRA）の従来型とRoth型の決定的な違いは何ですか？",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "従来型は拠出時に控除され老後に課税されるのに対し、Roth型は非課税口座で積立を行い将来の利益や元本引出が恒久非課税となります（日本の新NISA類似）。",
    "Which IRA plan is better for me?": "自分にはどちらの制度が適していますか？",
    "If you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower, a Traditional IRA is better.": "将来リタイアした時の税率が現在より高いと見込むならRoth型、老後の所得が下がり税率が低くなるなら従来型が適しています。",
    "What are the contribution limits for IRAs in 2024?": "年間拠出枠の上限はいくらですか？",
    "For 2024, the annual contribution limit for Traditional and Roth IRAs is $7,000 for individuals under age 50, and $8,000 for individuals age 50 or older.": "50歳未満は年額7,000ドル、50歳以上は8,000ドルです。",
    "Are there income limits for contributing to Traditional and Roth IRAs?": "所得による口座開設や拠出の制限はありますか？",
    "Roth IRAs have income phase-out ranges that restrict high earners. Anyone with earned income can contribute to a Traditional IRA, but tax deductibility may be limited by income and workplace retirement coverage.": "Roth型には高所得者の拠出を制限する所得基準が設けられていますが、従来型は勤労所得があれば原則どなたでも利用できます。",
    "Can I withdraw money from my IRA before age 59½ without penalty?": "59歳半になる前にペナルティなしで資金を引き出せますか？",
    "Roth IRA original contributions can be withdrawn at any time penalty-free. Withdrawing investment earnings early or withdrawing Traditional IRA funds before 59½ usually incurs income taxes and a 10% penalty.": "Roth型の元本部分はいつでも非課税・無罰金で引き出せますが、運用益の早期引き出しや従来型からの出金には10%の早期解約税が課されます。",
    "How does compounding frequency affect total returns?": "複利の付利頻度は最終資産額にどう影響しますか？",
    "The more frequently interest compounds (annually, monthly, daily), the higher your effective annual yield (APY) will be, as interest starts earning interest sooner.": "年1回より毎月、毎日と利息計算の頻度が高くなるほど、早期に利息が再投資されるため実質年利（APY）は高くなります。",
    "What is the Time Value of Money (TVM)?": "お金の時間的価値（TVM）とは何ですか？",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest.": "今日手元にある1円は、投資によって利息やリターンを生み出すことができるため、将来受け取る1円よりも価値が高いという基本原則です。",
    "What are the core components of TVM calculations?": "時間価値計算における5つの基本要素は何ですか？",
    "The five core variables are Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Total Number of Periods (Nper), and Periodic Payment (PMT).": "現在価値（PV）、将来価値（FV）、期あたり利率（Rate）、期間数（Nper）、定期支払額（PMT）の5要素です。",
    "What is the difference between an ordinary annuity and annuity due?": "期末払い（普通年金）と期首払い（期首年金）の違いは何ですか？",
    "In an ordinary annuity, payments occur at the end of each period. In an annuity due, payments occur at the beginning of each period, earning an extra compounding cycle of interest.": "期末払いは各期間の最終日に拠出しますが、期首払いは各期間の初日に拠出するため、まるまる1期分多く複利運用されます。",
    "How is Return on Investment (ROI) calculated?": "投資利益率（ROI）はどのように算出しますか？",
    "ROI is calculated by subtracting the initial cost of the investment from the final value, and dividing that net gain by the initial cost: ROI = (Net Profit / Cost of Investment) × 100%.": "最終価値から初期投資額を引いて純利益を求め、それを初期投資額で割って百分率にします：ROI = (純利益 ÷ 投資コスト) × 100%。",
    "What is the difference between simple ROI and annualized ROI?": "単純ROIと年換算リターン（CAGR）の違いは何ですか？",
    "Simple ROI measures total percentage return regardless of duration. Annualized ROI (CAGR) standardizes the return into a per-year geometric rate, enabling fair comparison between investments held for different lengths of time.": "単純ROIは投資期間に関係ない総上昇率を示し、年換算ROIは投資期間が異なる資産同士を年平均成長率（幾何平均）で公平に比較します。",
    "What is considered a good ROI?": "どれくらいのROIがあれば優秀と見なされますか？",
    "Historically, the broad stock market (S&P 500) has returned an average of 7% to 10% annually before inflation. Investments with higher expected returns generally involve higher risk of capital loss.": "株式インデックス（S&P 500など）の歴史的平均リターンは年率約7〜10%です。これを大幅に上回る利回りには相応の元本毀損リスクが伴います。",
    "How do I calculate how much to save monthly for a goal?": "目標額を貯めるための毎月の積立額はどう算出しますか？",
    "You divide your target savings amount by the number of months until your deadline, while factoring in the compounding interest earned on your growing balance.": "目標とする金額を満期までの月数で割り、その間に蓄積される残高から得られる複利運用益を差し引いて逆算します。",
    "Should I keep savings goal funds in high-yield savings or stocks?": "目標資金は預貯金で置くべきですか、それとも投資に回すべきですか？",
    "For goals under 3 to 5 years (like a car or home down payment), keep funds in safe, liquid instruments like High-Yield Savings Accounts (HYSA) or CDs. For goals 5+ years away, a diversified investment portfolio may be suitable.": "3〜5年以内の短期目標（車や住宅の頭金）は元本保証の預貯金や国債に置き、5年以上の長期目標であれば株式投資信託が適しています。",
    "How can I stay on track with my savings goals?": "貯蓄目標を途中で挫折せずに継続するコツは何ですか？",
    "Automate recurring monthly transfers into a dedicated savings account immediately after your paycheck arrives (the 'pay yourself first' strategy).": "給与受取日に自動振替設定を行い、使う前に別口座へ先取り貯蓄する「先取り貯蓄（Pay yourself first）」の自動化が最も確実です。",
    "How do I calculate stock returns?": "株式のトータルリターンはどう計算しますか？",
    "Total stock return equals capital gains (ending price minus purchase price) plus any dividends received, divided by the original purchase cost.": "キャピタルゲイン（売却価格－購入価格）に受け取ったすべての配当金を加え、最初の購入代金で割って計算します。",
    "What is CAGR in stock returns?": "株式投資におけるCAGRとは何ですか？",
    "Compound Annual Growth Rate (CAGR) measures the geometric mean annual return of a stock over multiple years, smoothing out annual market fluctuations.": "複数年にわたる年平均成長率（幾何平均）を示す指標で、年ごとの極端な相場の乱高下を均して実質的な成長スピードを示します。",
    "What is the difference between simple return and annualized return?": "単純騰落率と年率リターンの違いは何ですか？",
    "Simple return measures absolute percentage gain over the entire holding period, while annualized return shows the steady annual rate required to achieve that result.": "単純リターンは保有期間全体の絶対的な増加割合を示し、年率リターンはその結果をもたらす年平均の利回りを示します。",
    "What is the Capital Asset Pricing Model (CAPM)?": "資本資産価格モデル（CAPM）とは何ですか？",
    "CAPM calculates an asset's expected return based on its risk relative to the overall market, using the formula: Expected Return = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate).": "個別銘柄の市場リスクに応じて要求される期待リターンを算出する理論です：期待収益率 = 安全資産利子率 + β × (市場期待収益率 － 安全資産利子率)。",
    "What does Asset Beta (β) represent?": "株式のベータ値（β）は何を表していますか？",
    "Beta measures an asset's volatility compared to the broader market. A beta of 1.0 indicates market-level volatility; above 1.0 indicates higher volatility, and below 1.0 indicates lower volatility.": "市場全体に対する株価の感応度（連動性）を示します。β=1は市場並みの変動、1超はハイリスク・ハイリターン、1未満はディフェンシブな動きを示します。",
    "What is the Risk-Free Rate?": "無リスク金利（リスクフリーレート）とは何ですか？",
    "The risk-free rate is the theoretical rate of return of an investment with zero risk of default, typically represented by long-term government bond yields (like 10-year US Treasuries).": "元本割れや債務不履行リスクが皆無とされる投資の理論的利回りで、通常は信用力の高い10年国債の利回りを使用します。",
    "What is the Market Risk Premium?": "マーケット・リスクプレミアムとは何ですか？",
    "The market risk premium is the additional return investors demand for choosing risky market equities over risk-free government securities.": "国債などの安全資産ではなく、あえて不確実性のある株式市場に資金を投じる見返りとして投資家が要求する追加リターンです。",
    "What is dividend yield versus yield on cost?": "配当利回りと買値基準利回り（Yield on Cost）の違いは何ですか？",
    "Dividend yield is the annual dividend divided by the current stock price. Yield on cost is the annual dividend divided by your original purchase price, which increases as companies raise their dividends over time.": "配当利回りは「年間配当額 ÷ 現在株価」ですが、買値基準利回りは「年間配当額 ÷ 自分が買った時の取得単価」であり、増配に伴い上昇します。",
    "What is a Dividend Reinvestment Plan (DRIP)?": "配当金自動再投資（DRIP）とは何ですか？",
    "A DRIP automatically uses your cash dividend payments to purchase additional shares or fractional shares of the stock, compounding your share count and future payouts without commission fees.": "受け取った現金配当を手数料無料で自動的に同銘柄の追加購入（端株含む）に充当し、複利効果を最大化する仕組みです。",
    "Are dividend payments guaranteed?": "企業の配当金の支払いは保証されていますか？",
    "No, company boards can reduce, suspend, or eliminate dividend payouts at any time depending on company profitability and economic conditions.": "いいえ。企業の業績悪化や資金繰りに応じて、取締役会の判断により減配や無配への転落がいつでも起こり得ます。",
    "Inflation is the general rise in prices for goods and services over time, resulting in a decline in the purchasing power of money.": "モノやサービスの値段が全体的に上がり続け、その結果としてお金の価値（購買力）が相対的に目減りする現象です。",
    "How does inflation affect my savings?": "インフレは預金にどのようなダメージを与えますか？",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation is 3%, $100 today will only buy about $97 worth of goods next year.": "金利がつかない銀行預金の実質価値は毎年失われます。インフレ率が3%の場合、現在の100万円は来年約97万円分の価値しか買えなくなります。",
    "How is inflation officially measured?": "インフレ率は公的にどのように測定されていますか？",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks price changes across a standard market basket of consumer goods and services.": "一般世帯が購入する商品やサービスの価格動向をまとめた消費者物価指数（CPI）によって毎月測定されます。",
    "What is the historical average inflation rate?": "歴史的な平均インフレ率はどのくらいですか？",
    "In the United States, inflation has historically averaged between 2.5% and 3.2% per year over long multi-decade horizons.": "主要先進国の長期的な平均インフレ率は、過去数十年のスパンで年率2.0%〜3.0%前後を推移しています。",
    "How can I protect my money from losing value to inflation?": "資産をインフレの目減りから防衛するにはどうすればよいですか？",
    "Investing in assets whose earnings outpace inflation—such as diversified equities, Treasury Inflation-Protected Securities (TIPS), real estate, and inflation-indexed bonds.": "世界株式インデックス投資信託、物価連動国債、不動産など、長期リターンが物価上昇率を上回る資産クラスに分散投資することです。",
    "What is FICA tax?": "社会保険料や給与所得控除とは何ですか？",
    "FICA is a federal payroll tax that funds Social Security (6.2% on wages up to the wage base limit) and Medicare (1.45% plus an additional 0.9% on high earners).": "公的年金、健康保険、介護保険、雇用保険など、国の社会保障制度を維持するために給与から源泉徴収される法定負担金です。",
    "What is the difference between pre-tax and post-tax deductions?": "課税前控除と課税後控除の違いは何ですか？",
    "Pre-tax deductions (like 401k and health insurance) reduce your taxable gross income before taxes are computed. Post-tax deductions (like Roth contributions or wage garnishments) are taken after taxes.": "課税前控除（企業年金や健康保険料）は課税対象所得を直接減らして節税になりますが、課税後控除は税金計算後の手取りから差し引かれます。",
    "What is the difference between gross pay and net pay?": "額面給与と手取り給与の違いは何ですか？",
    "Gross pay is the total amount earned before any taxes or deductions. Net pay (take-home pay) is the actual cash deposited into your bank account after all deductions.": "額面給与は会社が支払う総支給額であり、手取り給与は税金（所得税・住民税）と社会保険料が天引きされて実際に口座に振り込まれる金額です。",
    "How does my W-4 filing status affect my paycheck?": "扶養控除の申告は手取り給与にどう影響しますか？",
    "Your W-4 form informs your employer how much federal income tax to withhold each pay period based on your filing status, dependents, and other income.": "扶養親族の人数や各種所得控除の申請状況に基づき、毎月の源泉徴収税額が適切に軽減されます。",
    "Why do state and local taxes vary so much?": "地方税や住民税に地域差があるのはなぜですか？",
    "State income tax rates range from 0% (in states like Texas, Florida, and Washington) to over 13% in high-tax states, while some cities also impose local municipal income taxes.": "自治体ごとに財政状況や条例に基づく超過課税・減税措置が異なり、地域によって所得税や住民税の実効税率に差が生じます。",
    "Net worth is the total market value of everything you own (assets) minus everything you owe to creditors (liabilities).": "保有するすべての資産（預貯金、不動産、投資商品など）の時価総額から、負債（ローン、借入金）の総額を引いた実質的な純価値です。",
    "How often should I calculate my net worth?": "純資産の集計はどのくらいの頻度で行うべきですか？",
    "Reviewing your net worth quarterly or semi-annually gives you a clear high-level view of your financial health without obsessing over daily market swings.": "日々の相場のノイズに惑わされず財務状況の健全性を定点観測するためには、四半期または半年に1回のペースが最適です。",
    "What counts as an asset vs. a liability?": "資産と負債には具体的に何が含まれますか？",
    "Assets include bank balances, investment accounts, home equity, and retirement funds. Liabilities include mortgages, student loans, car loans, and credit card debt.": "資産には預金、株式・投資信託、不動産評価額、年金残高などが該当し、負債には住宅ローン、自動車ローン、カードローン残高が含まれます。",
    "Should I include my house and mortgage in my net worth?": "純資産の計算に自宅と住宅ローンを含めるべきですか？",
    "Yes, you include the current fair market value of the home under assets and the remaining mortgage balance under liabilities. The difference is your home equity.": "はい。資産側に自宅の適正な現在市場価格を計上し、負債側に住宅ローンの未返済残高を計上します。その差額が住宅の純資産価値です。",
    "What does it mean to have a negative net worth?": "純資産がマイナス（債務超過）とはどういう状態ですか？",
    "A negative net worth means your total debts exceed your total assets. This is common for young adults and recent graduates with student loans.": "借金の総額が所有する資産の総額を上回っている状態です。新卒社会人で奨学金を返済中の方や住宅ローンを組んだ直後には一般的です。",
    "Most financial planners recommend saving 3 to 6 months of essential living expenses, or 9 to 12 months for freelancers or single-income households.": "会社員であれば毎月の基礎生活費の3〜6か月分、個人事業主やフリーランスであれば9〜12か月分をプールしておくのが基本です。",
    "What expenses should be included in an emergency fund budget?": "生活防衛資金の計算に含めるべき支出項目は何ですか？",
    "Include only non-negotiable living costs: housing (rent/mortgage), utilities, groceries, basic transportation, minimum debt payments, and healthcare insurance.": "家賃や住宅ローン、水道光熱費、基本食費、最低限の通信費、保険料など、削ることのできない不可欠な固定費のみを算出します。",
    "Where should I keep my emergency fund?": "生活防衛資金はどこに預けておくべきですか？",
    "In a dedicated High-Yield Savings Account (HYSA) or money market account where it is FDIC-insured, earns interest, and can be accessed immediately without risk.": "元本保証があり、ペイオフの保護対象で、いつでもペナルティなしで即座に引き出せる普通預金口座に隔離して保管します。",
    "Should I pay off debt or build an emergency fund first?": "借金の返済と生活防衛資金の積立はどちらを優先すべきですか？",
    "Build a starter emergency fund of 1 month of expenses or $1,000 to $2,000 first, then aggressively pay off high-interest consumer debt before expanding to 3-6 months.": "まず1か月分の生活費（10万〜20万円）を初期クッションとして確保し、次に高金利の借金を全力で完済し、その後に満額の防衛資金を作ります。",
    "When is it appropriate to use emergency fund savings?": "どのような状況であれば生活防衛資金を使ってよいですか？",
    "Use it only for genuine, unexpected emergencies: sudden medical bills, unexpected car repairs, or living expenses following job loss.": "失職による収入途絶、急な入院・手術、仕事に必須な車の故障など、真に予測不可能な緊急事態に限定して使用します。",
    "What is an expense ratio?": "信託報酬・経費率（Expense Ratio）とは何ですか？",
    "An expense ratio is the annual percentage fee charged by mutual funds and ETFs to cover fund management, administrative expenses, and operating costs.": "投資信託やETFの運用、管理、監査にかかる費用として、信託財産から日々自動的に差し引かれる年間手数料率のことです。",
    "How do fees compound over time?": "運用コストは長期投資でどのように複利で影響しますか？",
    "Fees are deducted annually from your total assets, meaning you lose both the fee money and all future compounding returns that money would have earned.": "毎年総資産から差し引かれるため、支払った手数料そのものだけでなく、その資金が生み出すはずだった将来の複利リターンも永遠に失われます。",
    "What is a good expense ratio for an index fund?": "インデックスファンドの適正な信託報酬水準はどれくらいですか？",
    "Low-cost index funds and ETFs typically have expense ratios between 0.02% and 0.10%, whereas actively managed mutual funds often charge 0.60% to 1.50% or more.": "優良なインデックスETFであれば年率0.03%〜0.15%程度が主流です。アクティブファンドでは1.0%〜2.0%を超えるものも珍しくありません。",
    "What other investment fees should I look out for?": "信託報酬以外に注意すべき投資コストは何ですか？",
    "Watch out for advisory fees (AUM fees of 1%), front-end or back-end sales loads, trading commissions, account maintenance fees, and custodial charges.": "買付時の販売手数料、売却時の信託財産留保額、売買委託手数料、口座管理料などに留意する必要があります。",
    "How much can a 1% fee difference affect my retirement savings?": "たった1%の手数料差が老後資金にどれほど致命的な差を生みますか？",
    "A 1% annual fee difference can erode 25% to 30% of your total ending portfolio wealth over a 30-year investment horizon.": "30年間の長期投資において、わずか年1%の手数料差があるだけで、最終的な資産受取額の約25%〜30%が失われてしまいます！",
    "What is a 529 plan?": "米国の教育資金非課税制度「529プラン」とは何ですか？",
    "A 529 plan is a tax-advantaged savings and investment plan designed to encourage saving for future higher education expenses with tax-free growth and qualified withdrawals.": "将来の大学等の教育資金準備を目的とした優遇税制プランで、運用益が非課税となり適格な学費として引き出す際も無税となります。",
    "How fast do college costs increase?": "大学の学費や教育費はどの程度のペースで上昇していますか？",
    "Historically, higher education tuition and fees have increased at an annual rate of 4% to 6%, outpacing general consumer inflation.": "高等教育費は歴史的に年4%〜6%のハイペースで上昇しており、一般的な物価上昇率を大きく上回り続けています。",
    "What happens to 529 funds if my child does not go to college?": "子どもが大学に進学しなかった場合、預けた資金はどうなりますか？",
    "You can change the beneficiary to another qualifying family member, use up to $10,000 for student loan repayment, or roll over up to $35,000 into a Roth IRA under SECURE 2.0 rules.": "兄弟姉妹へ名義変更するか、奨学金返済に充当するか、法改正に基づき最大35,000ドルまでRoth IRA退職口座へ非課税移管が可能です。",
    "Can I use a 529 plan for trade schools or K-12 tuition?": "専門学校や小中高の学費にも充当できますか？",
    "Yes, qualified distributions can cover accredited trade schools, vocational programs, apprenticeships, and up to $10,000 per year for K-12 private school tuition.": "はい。認可された専門学校や職業訓練、および私立小中高校の授業料として年間最大10,000ドルまで使用できます。",
    "How does a 529 plan impact financial aid eligibility?": "給付型奨学金の受給資格に悪影響を与えますか？",
    "Parent-owned 529 plans are assessed as parental assets on the FAFSA at a maximum rate of 5.64%, having minimal negative impact on financial aid eligibility.": "親名義の資産として判定されるため算入率は最大でも5.64%にとどまり、奨学金受給判定への悪影響は軽微です。",
    "How does DCA apply to high-volatility assets like Crypto?": "ボラティリティの激しい暗号資産でなぜドルコスト平均法が有効なのですか？",
    "DCA prevents emotional decisions during extreme market peaks and crashes, automatically buying more units when prices are low and fewer when prices are high.": "高値掴みや底値での狼狽売りを排除し、価格が安い時期に自動的に多くの数量を買い集めることで平均取得単価を抑制できます。",
    "Is DCA better than investing a lump sum?": "一括投資と積立投資はどちらが有利ですか？",
    "Lump sum investing historically wins in steadily rising markets, but DCA provides superior peace of mind, lower emotional risk, and downside protection in highly volatile markets.": "一貫した上昇相場では一括投資が勝りますが、暗号資産のような乱高下の激しい資産では積立の方が心理的ストレスを大幅に軽減できます。",
    "What is the best frequency for crypto DCA?": "暗号資産の積立に最適な頻度はどれくらいですか？",
    "Weekly or bi-weekly DCA aligned with your pay cycle is ideal for capturing market volatility while keeping trading fees manageable.": "給与サイクルに合わせた週1回または隔週の購入が、取引手数料を抑えつつボラティリティを味方につける最良のバランスです。",
    "Does DCA guarantee profits in cryptocurrency?": "ドルコスト平均法を行えば必ず儲かりますか？",
    "No, DCA does not protect against prolonged declines or failing crypto projects; it only ensures you achieve the weighted average market purchase price.": "いいえ。銘柄自体の長期低迷や破綻リスクを防ぐことはできず、あくまで市場の加権平均価格で買い付けるための手法です。",
    "What is the standard tipping percentage?": "チップの一般的な相場はどれくらいですか？",
    "In the United States and Canada, standard restaurant tipping guidelines range from 15% for adequate service, 18% for good service, to 20% or more for exceptional service.": "北米のレストランでは標準的で15%、良好なサービスで18%、素晴らしい接客なら20%以上が通例です（日本にはチップの習慣はありません）。",
    "Should tips be calculated before or after sales tax?": "チップは消費税抜きの金額で計算すべきですか？",
    "Etiquette traditionally dictates calculating the tip percentage on the pre-tax food and beverage subtotal, though many automated payment terminals calculate tip on the post-tax total.": "伝統的なマナーでは税抜き飲食小計から計算しますが、決済端末の自動計算機能は税込み総額を基準とする場合が増えています。",
    "How do you split a bill evenly among friends?": "割り勘を公平に計算するにはどうすればよいですか？",
    "Calculate the total bill including food, beverages, tax, and tip, and divide the total amount equally by the number of paying participants.": "飲食代金、消費税、チップの総額を合計し、その総合計を支払う人数で均等に頭割りします。",
    "How do you calculate a percentage discount?": "パーセント割引の計算式はどうなりますか？",
    "Multiply the original price by the discount percentage divided by 100 to find the savings, and subtract that amount from the original price: Final Price = Original Price × (1 - Discount%).": "元の価格に割引率を掛けて割引額を求め、元価格から差し引きます：割引後価格 = 定価 × (1 － 割引率 ÷ 100)。",
    "How do multiple stacked discounts work?": "2重割引（重複割引）はどのように計算されますか？",
    "Stacked discounts apply sequentially rather than additively. For example, 20% off plus an extra 10% off results in an effective 28% total discount, not 30%.": "単純な足し算ではなく掛け合わせで順次適用されます。例えば20%引きの後にさらに10%引きとなる場合、合計割引率は30%ではなく実質28%引となります。",
    "Is sales tax applied before or after store discounts?": "消費税は割引前と割引後のどちらに課税されますか？",
    "In most jurisdictions, sales tax is calculated on the discounted post-sale price, meaning you pay sales tax only on the actual money spent.": "ほとんどの場合、値引き後の実際の決済価格に対して課税されるため、値引き分だけ消費税額も安くなります。",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "フロントエンドDTI（住宅費比率）は、住宅ローン返済額、固定資産税、火災保険料、管理費など、住宅関連費用のみが月収（総支給額）に占める割合を計算します。一方、バックエンドDTI（総負債比率）は住宅関連費用に加え、自動車ローン、クレジットカード、奨学金など、すべての毎月の負債返済額を含めて計算します。",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "月々の総収入を増やす（昇給、副業など）か、既存の負債を繰り上げ返済することでDTIを下げることができます。特に残高の小さいローンを完済して毎月の最低返済額そのものをゼロにすることが、DTIの大幅な改善に最も効果的です。",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "株式の総合トータルリターンを計算するには、売却価格から購入価格を引いてキャピタルゲイン（譲渡益）を求め、受け取った配当金を加えます。その合計額を当初の購入金額で割り、100を掛けてパーセンテージで表します。",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "CAGR（年平均成長率）はCompound Annual Growth Rateの略です。複数年にわたる投資期間において、利益が毎年複利で成長したと仮定した場合の幾何平均年間成長率を表します。",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "CAPM（資本資産評価モデル）は、市場全体のシステマティックリスク（ベータ値）に基づいて、資産や株式の期待収益率を算出する代表的な理論モデルです。株主資本コストの算定基準としても広く用いられます。",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "ベータ値（Beta）は、株式市場全体（TOPIXやS&P500など）の値動きに対する個別銘柄の価格感応度（ボラティリティ）を測定する指標です。1.0は市場と完全に同調、1.0超は市場より激しい変動（ハイリスク・ハイリターン）、1.0未満はより安定した値動きを意味します。",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "信託報酬（経費率）とは、投資信託やETFの運用・管理のためにファンド資産から日々差し引かれる年間手数料率です（例：0.10%の場合、100万円の投資資産に対して年間約1,000円の手数料となります）。",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "おまとめローン（負債一本化）は、高金利の複数債務（リボ払いやキャッシングなど）を、1本の低金利な固定金利型ローンに一本化する手法です。毎月の返済総額を減らし、将来支払う利息総額を大幅に圧縮できます。",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "融資事務手数料（借入額の1%〜6%程度）などの諸費用に注意し、新しい返済額が家計に無理のない範囲であることを確認してください。また、一本化によって枠の空いたクレジットカードで再び新たな借入を作らない自己管理が極めて重要です。",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "日次複利（毎日複利）とは、発生した利息が毎日元本に組み入れられる計算方式です（年間365回）。翌日以降は「当初元本＋前日までの累積利息」に対して新たな利息が付与されるため、資産の指数関数的な成長が加速します。",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "日次複利の計算式は「A = P(1 + r/365)^(365 × t)」です（Pは当初元本、rは年利、tは運用年数）。毎月の定期積立がある場合、日々の累積残高に対して毎日利息が計算・累積されます。",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "例えば年利7%で100,000ドルを20年間運用した場合、月次複利では403,873ドルですが、日次複利では405,514ドルとなり、複利頻度が増えるだけで1,641ドル多く増やすことができます。",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "はい。主要な高金利預金口座（High-Yield Savings）やマネー・マーケット・アカウント（MMA）の多くは利息を毎日日次複利で計算し、月末にまとめて口座へ入金反映します。",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIREとは「Financial Independence, Retire Early（経済的自立と早期リタイア）」の略称です。貯蓄率を最大限（収入の40%〜70%）まで高め、低コストのインデックスファンド等に投資することで、資産運用の不労所得だけで一生涯の生活費を賄える状態を目指すライフスタイルです。",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "米トリニティ大学の著名な研究に由来する「4%ルール」とは、リタイア初年度の資産額の4%相当（以降インフレ率に応じて引き出し額を調整）を引き出し続ければ、30年以上の退職期間を通じて資産が枯渇しない確率が95%以上であるとする理論です。",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "FIREナンバー（目標資産額）は、「年間生活費 × 25倍」（4%ルールの場合）、またはより保守的に「年間生活費 × 33倍」（3%ルールの場合）で計算します。例えば年間生活費が400万円なら、目標額は1億円（400万×25）となります。",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Lean FIREは質素・ミニマルな必要最低限の生活費での早期リタイアを目指します。Standard FIREは標準的な中流階級の生活水準を維持します。Fat FIREは旅行や贅沢も我慢せず、ゆとりある高額な年間支出を前提とするリタイア形態です。",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "米国の社会保障給付（ソーシャルセキュリティ）は満62歳から早期受給を開始できますが、正規退職年齢（FRA: 66〜67歳）まで待つ場合と比べて、毎月の受給額が生涯にわたり最大30%減額されます。",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "正規退職年齢を過ぎて受給を繰り下げると、満70歳になるまで毎年8%ずつ受給額が増額されます（繰下げ増額）。70歳まで待つことで、本来の受給基本額の最大約124%〜132%を生涯受け取り続けることができます。",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "社会保障年金を62歳で受給開始する場合と70歳まで繰り下げる場合の損益分岐点（損益分岐年齢）は何歳ですか？",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "損益分岐年齢は一般的に78歳から81歳の間になります。80歳以上まで長生きすると見込まれる場合は、受給を70歳まで繰り下げた方が生涯累計の年金受給総額が圧倒的に多くなります。",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "オーストラリア連邦法の下、雇用主は従業員の通常労働賃金の一定割合を指定スーパーアニュエーション（確定拠出年金ファンド）へ拠出する義務（Superannuation Guarantee）があります。拠出率は法律に基づき12%まで引き上げられています。",
    "If you pay under an IDR plan for 20 or 25 years (or as little as 10 years under SAVE for low initial balances), any remaining student debt is forgiven. However, under current tax laws, this forgiven balance may be treated as taxable income, although federal tax on forgiven student loans is temporarily suspended through 2025.": "所得連動型返済プラン（IDR）で20年または25年間（SAVEプランで借入額が少額なら最短10年間）返済を続けると、残余の学生ローン残高は免除されます。なお、免除額は通常課税対象所得とみなされる場合があります（※現行の連邦税法では一時的措置が適用されています）。",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. However, if your income is very high relative to your debt, plans like PAYE or IBR might be better because they cap your monthly payment at what it would be under the Standard 10-Year Repayment Plan, whereas SAVE has no payment cap.": "多くの借入者にとってSAVEプランが最も低い月額返済額と充実した利息補助を提供します。ただし、負債額に対して収入が非常に高い場合、10年標準返済プランの返済額を上限とするPAYEやIBRの方が有利になる場合があります（SAVEプランには支払額の上限キャップがないため）。",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause outstanding unpaid interest to capitalize (be added to your principal balance), which means you will start paying interest on that interest.": "はい、studentaid.govからいつでも無料で返済プランの変更を申請できます。ただしプラン変更時に未払利息が元本に組み入れられる（利息の元本組入れ・キャピタライゼーション）場合があり、利息に対してさらに利息が発生する点には注意が必要です。",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower than it is today, a Traditional IRA is better.": "大原則として、リタイア後の税率（所得税ブラケット）が現在よりも高くなると予想される場合はRoth IRA（後で非課税）が有利です。逆にリタイア後の税率が現在より低くなると予想される場合はTraditional IRA（今控除を受ける）が有利です。",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under age 50, and $8,000 for those age 50 or older (which includes a $1,000 catch-up contribution).": "2024年のIRA年間拠出限度額は、TraditionalおよびRoth共通で50歳未満が7,000ドル、50歳以上はキャッチアップ枠1,000ドルが加算され8,000ドルです。",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers, and $230,000 to $240,000 for married couples filing jointly. Anyone can contribute to a Traditional IRA regardless of income, but the tax deductibility phases out if your income is high and you have access to a workplace retirement plan (like a 401k).": "Roth IRAには年収制限があり、2024年は単身申告者で146,000〜161,000ドル、夫婦合算申告者で230,000〜240,000ドルで段階的に拠出資格が制限されます。Traditional IRAは誰でも拠出できますが、職場の年金プラン（401k等）に加入している高所得者の場合は所得控除が段階的に制限されます。",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax- and penalty-free, but withdrawing earnings early incurs taxes and a 10% penalty. With a Traditional IRA, withdrawing any funds early generally triggers both regular income tax and a 10% penalty, except for specific IRS-approved exemptions (e.g., qualifying first-time home purchase, higher education expenses, or disability).": "Roth IRAでは、元本拠出分であれば理由を問わずいつでも非課税・ペナルティなしで引き出せますが、運用益を早期に引き出すと課税および10%の追徴金が課されます。Traditional IRAでは、特定の免除事由（初回の住宅購入や高等教育費など）を除き、早期引き出しに対して通常の所得税と10%のペナルティが課されます。",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have progressive tax rates). Local taxes may also apply depending on the specific city or county you work or live in.": "米国の各州は独自に州所得税率を定めています（テキサス州やフロリダ州のように州所得税が0%の州もあれば、累進課税を採用する州もあります）。さらに、居住・勤務する市や郡によって地方税（市町民税）が別途上乗せされる場合もあります。",
  },
  fr: {
    "The 5% rule estimates that homeownership costs roughly 5% of a property's value annually in unrecoverable expenses (1% property tax, 1% maintenance, and 3% cost of capital). Divide by 12 to find your break-even monthly rent. If you can rent an equivalent home for less, renting plus investing the savings builds greater wealth. For detailed math and worked case studies, read our complete guide: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">How to Decide: Rent vs. Buy Your Home</a>.": "La règle des 5 % estime que la propriété immobilière engendre chaque année environ 5 % de la valeur du bien en dépenses non récupérables (1 % de taxe foncière, 1 % d'entretien et réparations, et 3 % de coût du capital / coût d'opportunité). Divisez ce montant par 12 pour déterminer votre loyer d'équilibre : si vous pouvez louer un logement équivalent pour moins cher et placer la différence, la location permet de bâtir un patrimoine supérieur. Pour les calculs détaillés et des cas pratiques, consultez notre guide complet : <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">Comment choisir : louer ou acheter son logement</a>.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline). For a deep dive into bank underwriting formulas, salary matrices, and the 28/36 rule, read our complete guide: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">How Much House Can I Afford?</a>.": "La plupart des experts financiers et des normes bancaires recommandent de ne pas consacrer plus de 25 % à 28 % de vos revenus bruts mensuels aux dépenses de logement (taux d'endettement d'hébergement). Pour découvrir en détail les critères d'octroi bancaire, les grilles salariales et la règle 28/36, consultez notre guide complet : <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">Combien puis-je emprunter pour ma maison ?</a>.",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to solve for any of the five core TVM variables: Present Value (PV), Future Value (FV), Periodic Payment (PMT), Annual Interest Rate (I/Y), and Number of Compounding Periods (N).": "Ce calculateur financier TVM utilise les formules standard d'intérêts composés et d'actualisation des flux pour déterminer l'une des cinq variables clés de la valeur temporelle de l'argent : Valeur Actuelle (PV), Valeur Future (FV), Échéance Périodique (PMT), Taux d'Intérêt Annuel (I/Y) et Nombre de Périodes (N).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), planned recurring periodic deposits (PMT), interest rate, and duration. The calculator computes the total compounded ending balance instantly.": "Sélectionnez 'Valeur Future (FV)' comme variable cible. Saisissez votre capital initial (PV), vos versements périodiques programmés (PMT), le taux d'intérêt et la durée. Le calculateur détermine instantanément le capital final acquis avec intérêts composés.",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (common in lease and insurance contracts), earning an extra compounding cycle of interest.": "Dans une rente ou annuité ordinaire, les versements interviennent à la fin de chaque période (standard pour les prêts immobiliers et personnels). Dans une annuité due (à terme à échoir), les flux sont versés en début de période (courant pour les loyers et assurances), générant un cycle supplémentaire d'intérêts composés.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price. For a full breakdown of the math, comparisons with lump-sum investing, and crypto fee traps, read our complete guide: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">What Does DCA Mean in Crypto?</a>.": "Le Dollar-Cost Averaging (DCA) est une stratégie d'investissement consistant à investir une somme fixe à intervalles réguliers, sans tenir compte des fluctuations du marché. Pour une analyse mathématique complète, la comparaison avec l'investissement en une seule fois et les pièges des frais cachés, consultez notre guide : <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">Que signifie le DCA en crypto ?</a>.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an \"in-service distribution\" (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Vous pouvez interrompre ou modifier vos versements volontaires à tout moment sans pénalité en fixant votre retenue à 0 % auprès du service paie. Cependant, débloquer le capital déjà constitué tout en demeurant salarié est interdit par le code monétaire et fiscal, hors motifs d'exception (invalidité, fin de droits, achat de résidence principale). Un retrait anticipé non exonéré subit l'impôt sur le revenu et les prélèvements sociaux obligatoires. Consultez notre guide complet : <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Puis-je annuler mon plan de retraite et récupérer mon argent tout en restant salarié ?</a>.",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Number of Periods (Nper), and Periodic Payment (PMT). By inputting any four variables, our solver computes the fifth unknown mathematically using standard financial algebra formulas.": "Ce calculateur TVM met en relation cinq variables financières fondamentales : Valeur Actuelle (PV), Valeur Future (FV), Taux d'Intérêt Périodique (Rate), Nombre de Périodes (Nper) et Versement Périodique (PMT). En renseignant quatre de ces valeurs, notre moteur mathématique calcule automatiquement la cinquième inconnue.",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and total periods (years or months), specify any periodic recurring payment (PMT), and leave Future Value empty. The calculator instantly compounds your principal and contributions to reveal the ending balance.": "Pour calculer la valeur future, renseignez votre capital initial comme Valeur Actuelle (PV), indiquez le taux d'intérêt annuel et la durée (en années ou mois), ajoutez éventuellement des versements réguliers (PMT), et laissez le champ Valeur Future vide. L'outil applique les intérêts composés pour afficher le capital final accumulé.",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and personal loans). In an annuity due, payments occur at the beginning of each period (common in lease payments and rent), allowing each cash flow to earn an extra period of compounding interest.": "Dans une annuité ordinaire, les versements ont lieu à la fin de chaque période (standard pour les prêts immobiliers et personnels). Dans une annuité due, les flux sont versés au début de chaque période (loyers, crédit-bail), permettant à chaque versement de bénéficier d'une période supplémentaire de capitalisation des intérêts composés.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested into equal periodic purchases (e.g. $50 every week) regardless of asset price, smoothing out market volatility over time.": "Le Dollar-Cost Averaging (DCA) est une stratégie d'investissement consistant à fractionner le capital à investir en achats périodiques d'un montant fixe (ex. 50 € chaque semaine) quel que soit le cours des actifs, atténuant ainsi la volatilité des marchés au fil du temps.",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement living expenses minus Social Security. If you need $60,000 per year from your portfolio, your target retirement nest egg is $1,500,000 ($60,000 × 25). This nest egg provides sustainable inflation-adjusted income throughout a 30-year retirement.": "Selon la règle des 25 (l'inverse de la règle de retrait de 4 %), vous devez accumuler environ 25 à 30 fois vos dépenses annuelles de retraite estimées (déduction faite des pensions publiques garanties). Si vous avez besoin de 60 000 € par an issus de votre portefeuille, votre capital cible est de 1 500 000 € (60 000 € × 25), fournissant des revenus durables indexés sur l'inflation sur 30 ans.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $500,000 401(k) generates ~$1,667/month ($20,000/year); a $1,000,000 401(k) generates ~$3,333/month ($40,000/year); and a $1,500,000 401(k) generates ~$5,000/month ($60,000/year). Combined with Social Security, this replaces 70% to 90% of pre-retirement income.": "Selon la règle de retrait de 4 %, votre mensualité soutenable se calcule par : (Capital final × 0,04) ÷ 12. Par exemple, un fonds de 500 000 € génère ~1 667 €/mois (20 000 €/an) ; 1 000 000 € génère ~3 333 €/mois (40 000 €/an) ; et 1 500 000 € procure ~5 000 €/mois (60 000 €/an). Cumulé aux retraites publiques, cela permet de remplacer 70 % à 90 % de vos revenus d'activité.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\\\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\\\" class=\\\"text-primary underline font-medium\\\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Si vous appliquez la règle des 4 % de retrait sûr avec un portefeuille équilibré (60 % actions et 40 % obligations), les simulations historiques de l'étude Trinity montrent une probabilité de plus de 95 % que vos économies durent au moins 30 ans. Retirer à un taux plus élevé (6 % ou 7 % par an) accroît fortement le risque d'épuiser vos fonds en 15 à 20 ans en cas de marché baissier. Consultez notre guide complet : <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">Fiscalité, rentes mensuelles et pérennité du capital retraite</a>.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty PLUS ordinary federal and state income taxes on the distributed amount. For someone in the 22% federal bracket and 5% state bracket, an early withdrawal of $20,000 forfeits $7,400 (37%) to penalties and taxes, leaving only $12,600. Key exceptions to the penalty include the Rule of 55 (leaving an employer at age 55 or older), qualifying hardship distributions, or Substantially Equal Periodic Payments (SEPP / Rule 72t).": "Tout retrait anticipé d'un plan de retraite avant l'âge légal sans motif légitime de déblocage déclenche une pénalité fiscale en plus de l'impôt sur le revenu ordinaire et des prélèvements sociaux. Pour un contribuable imposé dans la tranche à 30 %, un rachat anticipé de 20 000 € subit plus de 7 000 € (35 %+) d'impôts et pénalités, ne laissant que 13 000 € nets. Des exceptions s'appliquent en cas d'accident de la vie, de fin de droits au chômage ou d'invalidité.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals, freelancers, and small business owners with no full-time W-2 employees (other than a spouse). It allows dual contributions: up to $23,000 in elective employee deferrals ($30,500 if age 50+) PLUS an employer profit-sharing contribution up to 25% of net adjusted business earnings (20% for sole proprietors), up to a combined maximum of $69,000 in 2024.": "Le plan de retraite pour travailleur non salarié (PER individuel ou Madelin) est conçu pour les indépendants, freelances et gérants majoritaires sans salariés. Il permet une double déduction fiscale : des versements volontaires personnels ainsi qu'une prise en charge des cotisations au titre des charges professionnelles, permettant de déduire d'importantes sommes de son bénéfice imposable.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000, whichever is less. A 401(k) loan avoids income tax and the 10% IRS penalty because you repay principal and interest back into your own account (usually over 5 years). However, if you leave your employer before repaying, the remaining balance usually becomes due by the federal tax filing deadline, or it converts into a taxable early distribution.": "Oui, de nombreux dispositifs d'entreprise autorisent une avance sur épargne salariale jusqu'à 50 % des avoirs consolidés (plafonnée légalement). Cette avance ne déclenche ni impôt ni pénalité car vous remboursez le capital et les intérêts directement sur votre propre compte (généralement sur 5 ans). En revanche, en cas de départ de l'entreprise, le solde restant dû doit être réglé rapidement sous peine de conversion en retrait imposable.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) with one click. A Traditional 401k calculator mode shows your immediate federal and state tax savings today, while retirement withdrawals are taxed as ordinary income. A Roth 401k calculator mode models post-tax contributions that generate 100% tax-free growth and 100% tax-free withdrawals in retirement.": "Notre simulateur vous permet de comparer en un clic le régime de versements déductibles (fiscalité différée à la sortie) et le régime non déductible (exonération fiscale totale sur les gains à la sortie). Le premier mode affiche vos économies d'impôt immédiates aujourd'hui, tandis que le second modélise une croissance patrimoniale et des retraits 100 % défiscalisés à la retraite.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\\\"/blog/can-i-cancel-401k-cash-out-while-employed/\\\" class=\\\"text-primary underline font-medium\\\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Vous pouvez interrompre ou annuler vos versements futurs à tout moment sans pénalité en contactant votre service RH pour fixer votre retenue à 0 %. Débloquer le capital existant en restant salarié est strictement limité aux cas de déblocage légaux (accidents de la vie, achat de la résidence principale). Retirer ces sommes hors motif qualifié entraîne impôts et pénalités. Consultez notre guide complet : <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Puis-je annuler mon plan de retraite et récupérer mon épargne en cours d'emploi ?</a>.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong performance or merit raises average 4% to 7%, and promotions or job changes typically command a 10% to 20%+ increase in base compensation.": "Historiquement, les revalorisations générales au titre de l'inflation se situent entre 2 % et 4 %, les augmentations au mérite ou à la performance atteignent 4 % à 7 %, et les promotions ou changements d'employeur se traduisent généralement par une hausse salariale de 10 % à 20 % ou plus.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: Raise % = ((New Salary - Old Salary) / Old Salary) × 100%.": "Soustrayez votre ancien salaire du nouveau pour obtenir le gain nominal, divisez cette différence par votre ancien salaire et multipliez par 100 : ((Nouveau - Ancien) / Ancien) × 100. Par exemple, passer de 45 000 € à 49 500 € représente une augmentation de 10 %.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Sur la base d'une durée annuelle de travail à temps plein (ex. 2 080 heures), multipliez votre hausse horaire par le volume d'heures annuel. Par exemple, +3,00 €/h correspond à 6 240 € bruts annuels de rémunération supplémentaire.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above each tax bracket threshold are taxed at the higher marginal rate; income below the threshold remains taxed at the lower previous rates. A pay raise will always increase your net take-home pay.": "Non. L'impôt sur le revenu repose sur un barème progressif par tranches marginales. Seuls les revenus situés au-delà du seuil de chaque tranche sont taxés au taux supérieur ; les sommes inférieures restent imposées aux taux plus bas. Une hausse de salaire se traduit donc systématiquement par une augmentation de votre rémunération nette.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees. For the complete mathematical formula and a comparison with reverse mortgages, read our comprehensive guide: <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">What is a Reverse Mortgage & How Payments Work</a>.": "Une mensualité de prêt immobilier standard comprend le remboursement du capital et les intérêts, l'assurance emprunteur obligatoire, la taxe foncière et d'éventuelles charges de copropriété. Pour connaître la formule mathématique détaillée et la comparaison avec d'autres financements immobiliers, consultez notre guide complet : <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">Comment fonctionne le prêt viager hypothécaire et le calcul des échéances</a>.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders may charge an early payoff fee. Check your loan contract terms before making lump-sum payments.": "La plupart des prêts à la consommation et des crédits immobiliers autorisent les remboursements anticipés. La loi plafonne strictement les indemnités de remboursement anticipé (IRA), souvent limitées à 6 mois d'intérêts ou 3 % du capital restant dû. Vérifiez toujours les clauses de votre contrat.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It enables wealth to grow exponentially over time compared to simple interest.": "Les intérêts composés représentent les gains calculés à la fois sur le capital initial et sur les intérêts déjà cumulés lors des périodes précédentes. Ce mécanisme permet au patrimoine de progresser de manière exponentielle, bien au-delà de l'intérêt simple.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your expected annual interest rate (e.g., at 8% annual return, your money doubles in approximately 9 years: 72 / 8 = 9).": "La règle des 72 est une formule de calcul mental rapide pour évaluer le temps nécessaire au doublement d'un capital : divisez 72 par le taux de rendement annuel attendu (ex. à 8 % par an, votre capital double en environ 9 ans : 72 / 8 = 9).",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total returns. More frequent compounding means interest starts earning interest sooner, producing slightly higher annual percentage yields (APY).": "Plus la capitalisation des intérêts est fréquente (annuelle, mensuelle, quotidienne), plus le rendement effectif total est élevé. Une capitalisation rapprochée permet aux intérêts de produire à leur tour des gains plus rapidement, augmentant le taux effectif annuel (TAEG/APY).",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement (including employer matching). At a bare minimum, contribute enough to capture the full employer match—otherwise, you are leaving free compensation on the table.": "La plupart des experts financiers conseillent d'épargner au moins 15 % de vos revenus bruts annuels pour votre retraite (abondement employeur inclus). Au strict minimum, versez le montant requis pour obtenir le plein abondement de votre entreprise : ne pas en profiter revient à refuser un complément de salaire immédiat garanti.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary, or dollar-for-dollar up to 4%) and calculates the combined total deposited into your retirement account each pay period.": "Le calculateur d'épargne salariale intègre la formule d'abondement de votre entreprise (ex. 100 % jusqu'à 4 % du salaire ou 50 % jusqu'à 6 %) pour déterminer le versement total crédité sur votre compte à chaque paie.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by age 40, 6x by age 50, 8x by age 60, and 10x by age 67.": "Les repères patrimoniaux de référence recommandent d'avoir épargné : 1 fois votre salaire annuel à 30 ans, 3 fois à 40 ans, 6 fois à 50 ans, 8 fois à 60 ans et 10 fois à l'âge du départ à la retraite.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, but pay income tax on withdrawals in retirement. In a Roth 401(k), you contribute after-tax dollars, but qualified withdrawals in retirement are 100% tax-free. Generally, choose Roth if you expect to be in a higher tax bracket in retirement, and Traditional if you are in a high tax bracket today.": "Dans un plan déductible (type PER), vos versements sont déduits de votre revenu imposable aujourd'hui, mais la sortie en rente ou capital sera imposée à la retraite. Dans un cadre non déductible (type PEA ou assurance-vie), vous investissez après impôt, mais les gains sont totalement exonérés d'impôt sur le revenu au terme. Choisissez la déduction si votre tranche actuelle est élevée, et l'exonération à la sortie si votre imposition future risque d'être supérieure.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you contribute $10,000 and your marginal tax bracket is 24%, you save approximately $2,400 in federal income taxes this year.": "Chaque euro versé sur un contrat d'épargne retraite déductible diminue votre revenu net imposable d'autant. Par exemple, avec un versement de 10 000 € et un taux marginal d'imposition de 30 %, vous réalisez une économie d'impôt immédiate de 3 000 € cette année.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer match, investment returns, and years until retirement. Use this calculator's interactive chart to simulate your balance under conservative (5%), moderate (7%), and aggressive (9%) return assumptions.": "Le solde prévisionnel de votre épargne retraite dépend des intérêts composés, de votre taux d'effort d'épargne, de l'abondement employeur, du rendement des marchés et de votre horizon temporel. Utilisez le graphique interactif pour tester des hypothèses prudentes (5 %), modérées (7 %) et offensives (9 %).",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 times your anticipated annual retirement expenses. For example, if you need $60,000 per year from your portfolio, you need an estimated $1.5 million nest egg ($60,000 × 25).": "D'après la règle des 25 (l'inverse du taux de retrait de 4 %), vous avez besoin d'environ 25 à 30 fois vos dépenses annuelles de retraite prévues, déduction faite des rentes et pensions publiques garanties. Par exemple, si vous devez prélever 60 000 € par an sur votre portefeuille, votre capital cible se situe entre 1 500 000 € et 1 800 000 €.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending Balance × 0.04) / 12. For instance, a $1,000,000 retirement portfolio generates approximately $3,333 per month in sustainable retirement income, adjusted for inflation over a 30-year retirement.": "Selon la règle des 4 %, votre mensualité brute prélevée s'obtient par : (Capital final × 0,04) ÷ 12. Par exemple, un portefeuille de 1 000 000 € génère environ 3 333 € par mois avant impôts, ajustés annuellement sur l'inflation.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities / 40% fixed income), historical backtesting (Trinity Study) indicates your portfolio has an over 95% probability of lasting at least 30 years without running out of money.": "Si vous appliquez la règle des 4 % avec un portefeuille diversifié (60 % actions / 40 % obligations), les données historiques de l'étude Trinity confirment une probabilité supérieure à 95 % que vos fonds durent au moins 30 ans sans s'épuiser.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty plus standard income tax on the entire amount. Total taxes and penalties can easily exceed 35%–45% of your withdrawal.": "Tout retrait anticipé d'un plan de retraite avant l'âge légal sans motif dérogatoire déclenche l'imposition au barème progressif et des pénalités fiscales. Un rachat de 20 000 € par un contribuable dans la tranche à 30 % peut ainsi subir plus de 6 500 € à 7 000 € d'impôts et pénalités combinés.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no full-time employees. It allows business owners to contribute both as employee and employer, enabling significantly higher annual tax-deductible contribution limits.": "Le contrat de retraite Madelin / PER individuel pour travailleur non salarié est réservé aux indépendants et chefs d'entreprise sans salariés. Il permet d'effectuer des versements déductibles substantiels calculés sur le bénéfice professionnel.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000). The interest you pay goes back into your own account, avoiding taxes and penalties as long as you repay it on schedule (usually within 5 years).": "Oui, de nombreux accords d'épargne d'entreprise permettent d'obtenir une avance remboursable jusqu'à 50 % des encours consolidés. Les intérêts remboursés reviennent directement sur votre compte, évitant imposition et pénalités si l'échéancier est honoré.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions. The tool models post-tax spending power at retirement so you can see whether paying taxes now vs. at retirement yields a larger final nest egg.": "Notre outil permet d'analyser l'impact entre versements déductibles (impôt différé à la sortie) et versements non déductibles (fiscalité nulle sur les gains à la sortie), vous aidant à choisir la stratégie la plus avantageuse pour maximiser votre capital net disponible.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer non-mortgage debt is fully cleared. You first invest up to the employer match, then fund a Roth IRA, and put any remainder back into your employer plan.": "Selon l'étape 4 de la méthode Dave Ramsey, vous devez consacrer 15 % de vos revenus bruts du foyer à des plans d'épargne retraite dès que toutes les dettes de consommation sont remboursées. Vous abondez d'abord jusqu'au plafond employeur, puis alimentez vos enveloppes défiscalisées personnelles.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It provides cost-effective retirement plans with mandatory employer contributions (either a 3% match or a 2% non-elective contribution).": "Le plan d'épargne d'entreprise simplifié pour PME est adapté aux structures de moins de 100 salariés, offrant une solution d'épargne retraite avantageuse avec contribution obligatoire de l'employeur (abondement jusqu'à 3 % ou versement uniforme de 2 % pour tous les salariés).",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your HR or plan administrator. However, cashing out existing vested funds while still actively employed is generally prohibited by plan rules, unless you qualify for a hardship distribution. For detailed options, see our guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Employed?</a>": "Vous pouvez interrompre ou suspendre vos versements d'épargne salariale à tout moment auprès du service paie. En revanche, retirer le capital accumulé en cours de contrat demeure strictement réglementé, sauf survenance d'un cas de déblocage anticipé légal (mariage, acquisition de la résidence principale, rupture de contrat).",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of ~10% annually before inflation. After factoring in 2.5%–3% average inflation and ETF expense ratios, a realistic long-term real return assumption is 6.5% to 7.0% per year for a 100% equity portfolio, or 5.0% to 6.0% for a balanced 60/40 stocks and bonds portfolio.": "Historiquement, les marchés actions mondiaux diversifiés (comme le S&P 500 ou le MSCI World) ont affiché un rendement nominal moyen d'environ 8 % à 10 % par an sur longue période (soit 6 % à 7 % net d'inflation). Un portefeuille équilibré en actions et obligations vise classiquement 5 % à 7 % par an.",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility stress by purchasing more shares when prices are low and fewer when prices are high. While historical data shows investing a lump sum immediately outperforms DCA about 68% of the time because markets rise long-term, recurring contributions are far easier to budget and provide psychological discipline.": "L'investissement programmé régulier (DCA) atténue le risque de mauvais timing et lisse la volatilité en achetant automatiquement dans les phases de hausse comme de baisse. Même si l'investissement en une seule fois surpasse statistiquement le DCA environ 68 % du temps en raison de la tendance haussière séculaire des marchés, les versements mensuels apportent une discipline d'épargne indispensable.",
    "Nominal return is the raw percentage gain generated by your investments before inflation and taxes. Real return is your actual purchasing power gain after subtracting the inflation rate. For example, if your portfolio gains 9% nominal in a year where inflation is 3%, your real return is approximately 6%.": "Le rendement nominal désigne la performance brute affichée par vos placements avant prise en compte de la hausse des prix. Le rendement réel mesure la progression véritable de votre pouvoir d'achat une fois l'inflation déduite (Rendement Réel ≈ Rendement Nominal - Inflation).",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contribution cash makes up the vast majority of your portfolio. Over 20 to 30 years, accumulated reinvested earnings surpass your total principal deposits and begin generating more annual income than your own salary.": "Les intérêts composés créent une croissance exponentielle. Au début, vos versements constituent l'essentiel du capital ; après 15 à 20 ans, les rendements réinvestis représentent plus de 60 % à 80 % de la valeur totale de votre portefeuille.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation costs (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income. This prevents you from becoming 'car poor' and prevents negative equity.": "La règle 20/4/10 préconise au moins 20 % d'apport initial, un emprunt de 4 ans maximum (48 mois) et un budget transport global inférieur à 10 % de vos revenus bruts.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk owing more than the vehicle is worth (negative equity or being 'underwater') as the car depreciates. Sticking to 48 or 60 months is significantly safer.": "Un crédit plus long (comme 72 ou 84 mois) réduit le montant de l'échéance mensuelle, mais alourdit considérablement le coût total des intérêts. De plus, vous risquez de vous retrouver en situation de capital restant dû supérieur à la valeur vénale du véhicule en cas de revente ou de sinistre.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance can exceed the market value of the car. If the car is totaled or stolen, standard insurance only pays market value, leaving you responsible for the remaining loan balance unless you have GAP insurance.": "Les voitures neuves se déprécient très vite (souvent 20 % à 25 % dès la première année). Sans apport suffisant, votre dette dépasse la valeur résiduelle du véhicule. En cas de vol ou de perte totale, l'assurance rembourse à dire d'expert, laissant le solde de l'emprunt à votre charge à défaut d'assurance garantie perte pécuniaire (GAP).",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit-based raise typically ranges from 4% to 8%, while a promotion within the same company averages 8% to 12%. Switching companies or industries often commands a 15% to 25% salary increase.": "Historiquement, une revalorisation au titre de l'inflation varie de 2 % à 4 %. Une augmentation au mérite s'établit généralement entre 4 % et 8 %, une promotion interne entre 8 % et 12 %, et changer d'entreprise permet d'obtenir couramment 15 % à 25 % de hausse salariale.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100. Formula: [(New Salary - Old Salary) / Old Salary] × 100. For example, moving from $60,000 to $66,000 is a 10% raise: ($6,000 / $60,000) × 100.": "Soustrayez l'ancien salaire du nouveau, divisez la différence par l'ancien salaire et multipliez par 100 : ((Nouveau - Ancien) / Ancien) × 100. Par exemple, passer de 40 000 € à 44 000 € représente 10 % d'augmentation.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly wage increase by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "En prenant comme référence une durée de travail à temps plein (ex. 2 080 heures par an), multipliez l'augmentation horaire par 2 080. Par exemple, +2,50 €/h correspond à 5 200 € bruts annuels supplémentaires.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of income that falls into the new, higher bracket is taxed at the higher percentage rate. Every dollar earned below that threshold is still taxed at the lower previous rates. A pay raise will always increase your total net take-home pay.": "Non. Le barème de l'impôt sur le revenu est progressif et s'applique par tranches marginales. Seule la fraction de vos revenus qui dépasse le seuil de la nouvelle tranche est taxée au taux le plus élevé. Les sommes antérieures continuent de bénéficier des taux inférieurs. Une augmentation accroît donc toujours votre salaire net disponible.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on everything else. Once the smallest debt is cleared, you roll its entire payment into the next smallest debt. This generates psychological momentum through rapid early wins.": "La méthode de la boule de neige (Debt Snowball) consiste à solder en priorité les dettes dont le montant restant dû est le plus faible, quel que soit leur taux d'intérêt, tout en payant le minimum sur les autres. Une fois le premier crédit éteint, vous reportez la mensualité libérée sur la suivante. Cette méthode procure une motivation psychologique immédiate grâce à des succès rapides.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while paying minimums on all others. Mathematically, this minimizes total interest charges paid across all debts and clears debt in the fastest possible timeframe.": "La méthode de l'avalanche consiste à rembourser en priorité les dettes affichant le taux d'intérêt le plus élevé (TAEG le plus fort), tout en maintenant les mensualités minimales sur les autres. D'un point de vue purement financier et mathématique, cette stratégie minimise le total des intérêts payés et accélère la date d'extinction totale de la dette.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, behavioural studies show that the Debt Snowball method often yields higher real-world completion rates because the psychological motivation of eliminating individual accounts quickly prevents people from giving up on their debt-free plan.": "Mathématiquement, l'avalanche est la plus économique car elle réduit au maximum les frais financiers. Cependant, les études comportementales prouvent que la boule de neige affiche un meilleur taux de réussite pratique, car la satisfaction d'éliminer rapidement des lignes de crédit évite le découragement.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt. Once that target debt is paid in full, its entire monthly budget (its minimum payment + the extra cash) rolls into the next debt on your roster, creating an ever-larger monthly payment that accelerates debt payoff.": "Vous réglez les échéances minimales sur tous vos emprunts et concentrez votre surplus d'épargne sur la dette prioritaire. Dès qu'elle est intégralement remboursée, la totalité de son budget mensuel s'ajoute à la mensualité de la dette suivante, créant un effet boule de neige qui accélère votre désendettement.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain motivation (Snowball), and then switch to attacking the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Oui. Beaucoup de débiteurs soldent d'abord un ou deux petits crédits pour libérer du pouvoir d'achat mensuel et renforcer leur motivation (boule de neige), puis basculent sur la méthode de l'avalanche pour neutraliser les taux d'intérêt les plus élevés.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or interest. It answers the fundamental financial question: 'How much will my money be worth tomorrow if I invest it today?'": "La Valeur Future (FV ou valeur acquise) représente la valeur patrimoniale qu'atteindra un capital initial ou une série de versements réguliers à une date future, selon un taux de rendement ou d'intérêt attendu. Elle répond à la question clé : 'Combien vaudra mon épargne demain si je l'investis aujourd'hui ?'",
    "Inflation is the general rise in prices for goods and services over time, resulting in a reduction in purchasing power per unit of currency. When inflation occurs, each dollar or euro buys a smaller percentage of a good or service.": "L'inflation est la hausse généralisée et continue des prix des biens et services au fil du temps, entraînant une diminution du pouvoir d'achat de la monnaie. Chaque euro permet ainsi d'acheter une quantité moindre de biens et services.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only have the purchasing power equivalent of about $7,440 in 10 years, even though the nominal account balance remains unchanged.": "L'argent qui dort sur des comptes courants non rémunérés perd chaque année de son pouvoir d'achat. Avec une inflation de 3 % par an, 10 000 € aujourd'hui n'équivaudront plus qu'à environ 7 440 € de pouvoir d'achat réel dans 10 ans, bien que le solde nominal reste identique.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average change over time in prices paid by consumers for a representative 'basket' of goods and services, including housing, food, transportation, energy, and healthcare.": "L'inflation est principalement mesurée par l'Indice des Prix à la Consommation (IPC), qui suit l'évolution des prix d'un panier représentatif de biens et services consommés par les ménages (logement, alimentation, énergie, transports et santé).",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.2% per year over multi-decade periods, though short-term supply shocks can cause temporary surges.": "Dans les économies développées, l'inflation moyenne historique à long terme se situe généralement entre 2,0 % et 3,0 % par an, même si des chocs géopolitiques ou d'offre peuvent provoquer des pics ponctuels plus élevés.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds / ETFs), real estate, inflation-protected government bonds (TIPS or bonos ligados al IPC), and commodities—historically provides the most reliable long-term protection against purchasing power loss.": "Investir dans des actifs réels dont les rendements dépassent la hausse des prix (actions mondiales, immobilier locatif, obligations indexées, livrets d'épargne réglementés) préserve et fait croître le pouvoir d'achat réel de votre patrimoine.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Vous pouvez interrompre ou moduler vos versements à tout moment sans pénalité en suspendant votre prélèvement automatique. En revanche, liquider le capital déjà investi en cours d'emploi est restreint par la loi, hors cas de déblocage anticipé prévus par le code des assurances et la fiscalité.",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and loans). In an annuity due, payments occur at the beginning of each period (standard for lease agreements). Because money is invested earlier in an annuity due, it compounds for one additional cycle, resulting in a higher Future Value.": "Dans une annuité ordinaire, les flux interviennent à la fin de chaque période (prêts bancaires). Dans une annuité due, les versements ont lieu en tout début de période (loyers, crédit-bail). L'épargne étant placée plus tôt, elle bénéficie d'une période d'intérêts composés supplémentaire, augmentant la valeur future finale.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $1,000,000 portfolio generates approximately $3,333 per month before taxes, with annual adjustments for inflation.": "D'après la règle de retrait de 4 %, la mensualité brute disponible est de : (Capital final × 0,04) ÷ 12. Un capital de 1 000 000 € procure ainsi environ 3 333 € par mois avant impôts, réévalués annuellement selon l'inflation.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Si vous suivez la règle des 4 % avec un portefeuille équilibré (60 % actions et 40 % obligations), les simulations de l'étude Trinity montrent une probabilité de plus de 95 % que vos avoirs suffisent pendant au moins 30 ans. Un taux de retrait plus élevé (6 % ou 7 %) augmente sensiblement le risque d'épuiser vos fonds en 15 à 20 ans en cas de marché baissier. Consultez notre guide complet : <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">Fiscalité, rentes mensuelles et pérennité du capital retraite</a>.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty on top of ordinary income taxes at your marginal rate. A $20,000 withdrawal by someone in the 22% bracket would surrender roughly $6,400 in combined taxes and penalties.": "Si vous appliquez la règle des 4 % avec un portefeuille équilibré (60 % actions / 40 % obligations), les simulations de l'étude Trinity indiquent plus de 95 % de chances que votre capital dure au moins 30 ans. Un taux de retrait supérieur (6 % ou 7 %) majore sensiblement le risque d'épuisement prématuré en période de baisse des marchés.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New Salary - Old Salary) ÷ Old Salary) × 100. For example, moving from $60,000 to $66,000 is a 10% raise.": "Tout retrait anticipé d'un plan d'épargne retraite avant l'âge légal sans motif légitime déclenche l'imposition au barème ordinaire de l'impôt sur le revenu majorée d'une pénalité fiscale forfaitaire.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals $2.50 × 2,080 = $5,200 more in pre-tax annual income.": "Le plan retraite pour travailleur indépendant permet aux créateurs d'entreprise et professions libérales de déduire des cotisations substantielles de leur revenu d'activité imposable, tout en préparant leur future pension de retraite.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above a tax bracket threshold are taxed at the higher marginal rate—never your entire income. A pay raise will always increase your total take-home pay.": "Oui, de nombreux plans d'entreprise prévoient la faculté d'obtenir une avance jusqu'à 50 % de vos encours d'épargne salariale, remboursable avec intérêts crédités sur votre propre compte.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and HOA fees (if applicable). If your down payment is under 20%, private mortgage insurance (PMI) is also included.": "La mensualité de crédit immobilier réunit le capital amorti, les intérêts d'emprunt, la taxe foncière, l'assurance de prêt et les charges de copropriété le cas échéant.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money: divide 72 by your expected annual interest rate. For example, at an 8% return, money doubles in roughly 72 ÷ 8 = 9 years.": "Notre simulateur vous permet d'analyser l'arbitrage entre l'économie d'impôt immédiate (tranche marginale actuelle élevée) et l'exonération d'impôt sur les gains et rentes à la retraite.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, and pay ordinary income tax upon withdrawal in retirement. In a Roth 401(k), you contribute after-tax dollars, but all qualified retirement withdrawals—including all compound investment gains—are 100% tax-free.": "Selon l'étape 4 de la démarche de Dave Ramsey, vous affectez 15 % du revenu brut familial à l'épargne retraite une fois les dettes à la consommation apurées : d'abord jusqu'au plein abondement employeur, puis sur des supports individuels défiscalisés.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities, 40% bonds), historical data indicates a 95%+ probability that your savings will last at least 30 years.": "En respectant la règle des 4 % avec un portefeuille équilibré (60 % actions et 40 % obligations), les données historiques attestent d'une probabilité supérieure à 95 % que vos réserves financières durent au moins 30 ans.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000), which you repay through payroll deductions with interest going back into your account.": "Oui, de nombreux plans d'entreprise permettent d'emprunter ou d'obtenir une avance jusqu'à 50 % de vos encours d'épargne salariale, remboursable avec intérêts crédités sur votre propre compte.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions to compare long-term tax advantages.": "Notre simulateur permet d'alterner entre cotisations déductibles et versements nets pour comparer précisément les gains fiscaux et patrimoniaux à long terme.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts (such as a 401k up to the match, then a Roth IRA) after paying off all non-mortgage debt and building a 3- to 6-month emergency fund.": "L'étape 4 de la méthode Dave Ramsey préconise d'affecter 15 % du revenu brut familial à l'épargne retraite une fois les crédits à la consommation soldés et un fonds d'urgence de 3 à 6 mois constitué.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It features lower contribution limits than a standard 401(k) but requires mandatory employer contributions (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Le plan d'épargne d'entreprise simplifié s'adresse aux PME de moins de 100 salariés, avec une structure allégée et un abondement patronal obligatoire garantissant la participation de l'employeur.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your employer's HR or payroll department and updating your deferral percentage to 0%. However, cashing out existing money while still employed is generally prohibited by IRS regulations unless your plan offers an 'in-service distribution' (usually after age 59½) or you qualify for an IRS Hardship Withdrawal (which incurs income taxes and a 10% penalty).": "Le plan d'épargne simplifié s'adresse aux petites entreprises de moins de 100 salariés, offrant une formule allégée avec contribution patronale minimale obligatoire au bénéfice de l'ensemble des salariés.",
    "Nominal return is the raw percentage gain generated by your investments before inflation. Real return is the purchasing power gain after subtracting the rate of inflation (Real Return ≈ Nominal Return - Inflation Rate).": "Vous pouvez interrompre ou moduler vos cotisations d'épargne salariale en informant votre employeur de passer votre retenue à 0 %. Débloquer le capital existant en restant salarié est strictement limité aux cas de force majeure prévus par la loi.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit raise for strong performance typically falls between 4% and 8%, while a major promotion or job switch often commands a 10% to 20% salary increase.": "Une réévaluation générale liée au coût de la vie oscille entre 2 % et 4 %. Une augmentation au mérite se situe entre 4 % et 8 %, et une promotion ou embauche externe apporte couramment de 10 % à 20 % de revalorisation.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New - Old) ÷ Old) × 100. For example, moving from $75,000 to $82,500 is a 10% raise.": "Le rendement annualisé historique des marchés actions diversifiés s'établit en moyenne à environ 8 % à 10 % avant inflation (soit ~6 % à 7 % net d'inflation). Un profil offensif en actions vise 7 % à 9 %, tandis qu'un profil équilibré rapporte classiquement 5 % à 7 % par an.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $3.00/hour raise equals $3.00 × 2,080 = $6,240 more in pre-tax annual compensation.": "Soustrayez l'ancien salaire du nouveau pour obtenir le montant de l'augmentation, divisez par l'ancien salaire et multipliez par 100 : ((Nouveau - Ancien) / Ancien) × 100. Par exemple, passer de 45 000 € à 49 500 € représente 10 % de hausse.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of your income that falls into the higher tax bracket is taxed at the higher percentage rate. Your prior earnings are still taxed at their original lower rates, so a pay raise will always result in higher total take-home pay.": "Non. Le système fiscal progressif n'applique le taux supérieur qu'à la part des revenus excédant le seuil de tranche. Vos tranches inférieures restent intactes : une augmentation salariale améliore donc systématiquement votre revenu net final.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while making minimum payments on all other accounts. Once the smallest balance is eliminated, you roll its payment into the next smallest debt, generating psychological momentum through quick wins.": "La méthode boule de neige cible d'abord le remboursement des crédits aux plus faibles soldes restants dus, sans regarder les taux, pour libérer des comptes rapidement et créer une dynamique psychologique positive.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on all others. Once the balance with the highest APR is cleared, you redirect that full payment toward the next highest interest rate account.": "La méthode avalanche attaque d'abord la dette portant le taux d'intérêt le plus lourd, tout en versant les minima sur les autres. Dès que la dette la plus coûteuse est liquidée, l'effort financier se reporte sur le taux le plus élevé suivant.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid and eliminates debt faster. However, behavioral research shows that the quick psychological wins of the Debt Snowball method help many borrowers stay committed to their debt payoff journey.": "Financièrement, l'avalanche est la plus efficace car elle minimise le montant global des intérêts versés et raccourcit la durée totale de remboursement. Toutefois, les victoires rapides de la boule de neige maintiennent souvent une meilleure régularité chez les emprunteurs.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds), real estate, inflation-protected securities (TIPS), and high-yield savings accounts—preserves and grows your real wealth.": "Sur la base d'une durée légale de travail annuelle (ex. 2 080 heures), multipliez votre hausse de salaire horaire par 2 080. Par exemple, +2,50 €/h correspond à 5 200 € bruts annuels de rémunération en plus.",
    "How does this online TVM calculator solve Time Value of Money equations?": "Comment ce calculateur TVM en ligne résout-il les équations de la valeur temporelle de l'argent ?",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to link five core variables: Present Value (PV), Future Value (FV), Payment (PMT), Periodic Interest Rate (r), and Total Periods (n). You enter any four known variables, and the mathematical engine automatically calculates the fifth missing parameter instantly.": "Ce calculateur TVM s'appuie sur les équations financières d'actualisation et de capitalisation pour lier cinq variables clés : Valeur Actuelle (PV), Valeur Future (FV), Échéance (PMT), Taux d'intérêt périodique (r) et Nombre total de périodes (n). Vous saisissez quatre variables connues et le moteur mathématique détermine immédiatement la cinquième.",
    "How does this online TVM calculator solve Time Value of Money problems?": "Comment ce calculateur résout-il les problèmes financiers de valeur temporelle (TVM) ?",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (i), Number of Periods (n), and Periodic Payment (PMT). By inputting any four of these values, the calculator solves for the fifth using closed-form financial equations or numerical approximation (for interest rate).": "Le calculateur relie cinq variables financières fondamentales : Valeur Actuelle (PV), Valeur Future (FV), Taux d'intérêt par période (i), Nombre de périodes (n) et Paiement périodique (PMT). En renseignant quatre paramètres, l'outil résout l'inconnue par calcul analytique direct ou approximation numérique (pour le taux d'intérêt).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), the periodic installment you plan to deposit (PMT), the expected annual interest rate (r), the compounding frequency, and the total duration in years. The calculator solves for the exact final balance, displaying total interest earned and visual amortization charts.": "Sélectionnez 'Valeur Future (FV)' comme cible. Entrez votre capital initial (PV), le versement programmé (PMT), le taux annuel escompté (r), la fréquence de capitalisation et la durée en années. Le calculateur affiche le capital accumulé, les intérêts perçus et le graphique de croissance.",
    "How do I use this as a Future Value calculator?": "Comment utiliser cet outil comme calculateur de valeur future (Future Value) ?",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and duration, and optionally add recurring monthly payments (PMT). The calculator compounds the initial principal and annuity payments over time, displaying the final accumulated portfolio value and total interest earned.": "Pour estimer la valeur future, renseignez votre placement initial comme Valeur Actuelle (PV), fixez le taux d'intérêt annuel et la durée, et ajoutez éventuellement des versements mensuels (PMT). Le calculateur modélise la capitalisation du capital et des versements pour afficher l'épargne finale et les intérêts générés.",
    "What is the difference between an ordinary annuity and an annuity due?": "Quelle est la différence entre une rente ordinaire et une rente à terme d'avance (annuity due) ?",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (standard for lease agreements and rent). Because payments in an annuity due occur earlier, each installment earns an additional period of compound interest, resulting in a higher Future Value or higher Present Value.": "Dans une annuité ordinaire (terme échu), les échéances sont versées à la fin de chaque période (prêts bancaires). Dans une annuité due (terme à échoir), les versements sont effectués au début de la période (loyers). Les versements intervenant plus tôt, chaque flux génère une période d'intérêts en plus, produisant une Valeur Future plus élevée.",
    "What is the 5% rule for renting vs. buying?": "Qu'est-ce que la règle des 5 % pour comparer l'achat et la location ?",
    "The 5% rule (popularized by Ben Felix) estimates the non-recoverable annual costs of homeownership at roughly 5% of the property value: 1% for property taxes, 1% for maintenance and repairs, and 3% for the cost of capital (mortgage interest + equity opportunity cost). If renting an equivalent home costs less than 5% of its purchase price annually (or 5%/12 per month), renting is mathematically favorable.": "La règle des 5 % (popularisée par Ben Felix) chiffre les coûts annuels non récupérables d'un propriétaire à environ 5 % de la valeur du logement : 1 % de taxe foncière, 1 % de travaux d'entretien et 3 % de coût du capital (intérêts du prêt et coût d'opportunité des fonds propres). Si le loyer annuel d'un bien équivalent est inférieur à 5 % de son prix de vente (soit moins de 5 % ÷ 12 par mois), rester locataire et placer la différence est financièrement plus avantageux.",
    "Financial experts and the standard 28/36 rule recommend spending no more than 28% of your gross monthly income on housing costs (PITI: Principal, Interest, Taxes, and Insurance). Total monthly debt obligations (housing + cars + student loans + credit cards) should remain under 36% to maintain financial stability.": "Les directrices financières et la règle 28/36 recommandent de ne pas dépasser 28 % de vos revenus bruts mensuels pour l'ensemble des dépenses de logement (mensualité de crédit, assurance emprunteur et taxes foncières). La charge totale d'endettement tous crédits confondus (immobilier, voiture, prêts étudiants, cartes) doit idéalement rester sous 36 %.",
    "Under the empirical 4% Safe Withdrawal Rule, your retirement savings are statistically projected to last at least 30 years with a balanced stock/bond portfolio. For example, withdrawing 4% annually ($40,000 from a $1,000,000 balance) adjusted annually for inflation has historically survived almost every 30-year retirement window in modern market history.": "La méthode boule de neige consiste à solder en premier les crédits aux montants restants dus les plus faibles, sans tenir compte des taux, afin d'enregistrer rapidement des victoires psychologiques valorisantes.",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest over time.": "La méthode avalanche préconise de rembourser en priorité la dette portant le taux d'intérêt le plus lourd, tout en assurant les échéances minimales sur les autres emprunts.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested across periodic purchases rather than investing everything in a single lump sum. By buying fixed dollar amounts at regular intervals, you automatically purchase more shares when prices are low and fewer shares when prices are high, lowering your average cost per share over time.": "Mathématiquement, l'avalanche est la solution la plus performante car elle réduit au maximum le coût des intérêts. Toutefois, les victoires immédiates de la boule de neige permettent à de nombreux emprunteurs de garder le cap.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of share price.": "La Valeur Future (FV) correspond au montant patrimonial qu'atteindra un capital ou une série d'annuités à une échéance donnée sous l'effet des intérêts composés.",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement. At a minimum, always contribute enough to capture 100% of your employer's 401(k) match, as this provides an immediate 50% to 100% risk-free return on your money.": "Pour un capital initial assorti de versements réguliers : FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], où PV est le capital initial, r le taux d'intérêt annuel, m la fréquence de capitalisation par an, t la durée en années et PMT le versement périodique.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you are in the 24% federal tax bracket and contribute $10,000, you reduce your current tax bill by $2,400.": "Dans une annuité ordinaire, les versements ont lieu à la fin de chaque période. Dans une annuité due, ils sont effectués au début de chaque période, ce qui procure à chaque versement un cycle de capitalisation supplémentaire et produit un capital final supérieur.",
    "How much in a 401(k) do I need to retire?": "De quel capital ai-je besoin pour prendre ma retraite ?",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement spending minus guaranteed income like Social Security. For example, if you need $60,000 per year from your portfolio, your target nest egg is $1,500,000 to $1,800,000.": "La Valeur Future (FV ou valeur acquise) mesure la valeur patrimoniale prévisionnelle atteinte par un investissement initial ou des versements réguliers à une date future, selon un taux de rendement composé.",
    "How much will my 401(k) pay me per month in retirement?": "Combien mon capital retraite me versera-t-il par mois ?",
    "How much tax and penalty do I pay on early 401(k) withdrawals?": "Quels impôts et pénalités s'appliquent en cas de déblocage anticipé de l'épargne retraite ?",
    "What is a Solo 401(k) and how does it work for the self-employed?": "Qu'est-ce qu'un plan de retraite pour travailleur indépendant et comment fonctionne-t-il ?",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no common-law employees. It allows you to contribute both as an employee (deferring up to $23,000 in 2024) and as the employer (up to 25% of net business compensation), providing substantial tax deductions.": "Le plan retraite pour travailleur indépendant permet aux créateurs d'entreprise et professions libérales de déduire des cotisations substantielles de leur revenu d'activité imposable, tout en préparant leur future pension de retraite.",
    "Can I borrow against my 401(k) instead of taking an early withdrawal?": "Puis-je emprunter sur mon épargne retraite au lieu de faire un rachat anticipé ?",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000 (whichever is less). You repay the loan with interest back into your own account, usually over 5 years. However, if you leave your job, the outstanding balance typically becomes due rapidly or converts to a taxable distribution.": "Oui, de nombreux plans permettent une avance remboursable jusqu'à 50 % des avoirs. Le remboursement s'effectue avec intérêts au profit de votre propre contrat, généralement sur une durée de 5 ans.",
    "How do I use this as a Roth vs Traditional 401(k) calculator?": "Comment comparer une formule à fiscalité différée et une formule exonérée à la sortie ?",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) contributions. Traditional saves money on taxes today during your peak earning years, while Roth offers completely tax-free withdrawals in retirement.": "Notre simulateur vous permet d'analyser l'arbitrage entre l'économie d'impôt immédiate (tranche marginale actuelle élevée) et l'exonération d'impôt sur les gains et rentes à la retraite.",
    "What is a good salary increase percentage?": "Quel est le pourcentage d'une bonne augmentation de salaire ?",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong merit raises range from 5% to 8%, and promotions or job switches typically yield 10% to 20% increases. Any raise above current inflation increases your real purchasing power.": "Généralement, une revalorisation au titre du coût de la vie tourne autour de 2 % à 4 %, une augmentation au mérite se situe entre 5 % et 8 %, et une promotion ou embauche externe apporte 10 % à 20 % de hausse. Tout gain supérieur à l'inflation accroît réellement votre pouvoir d'achat.",
    "How do I calculate a salary increase percentage?": "Comment calculer le pourcentage d'une augmentation de salaire ?",
    "How do I convert an hourly pay raise into an annual salary increase?": "Comment convertir une augmentation de taux horaire en hausse de salaire annuel ?",
    "Will a pay raise push me into a higher tax bracket and reduce my take-home pay?": "Une augmentation peut-elle me faire changer de tranche d'imposition et réduire mon salaire net ?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest charges; over time, as the principal balance decreases, a progressively larger portion of each payment reduces the principal debt.": "Dans un prêt amortissable, les mensualités sont constantes. Au début, la majorité de la mensualité est consacrée au paiement des intérêts bancaires ; avec le temps et la baisse du capital restant dû, la part amortissant le capital devient prépondérante.",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the borrowing term, protecting you against rising interest rates. A variable-rate loan fluctuates with a market index, meaning payments can rise or fall over time.": "Un prêt à taux fixe garantit un taux d'intérêt et des mensualités invariables sur toute la durée de l'emprunt. Un prêt à taux variable est indexé sur les marchés monétaires (ex. Euribor), faisant varier les échéances à la hausse ou à la baisse.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders charge prepayment fees within the first 3 to 5 years. Always verify your loan agreement's prepayment terms before submitting extra payments.": "La plupart des prêts personnels et crédits immobiliers prévoient des possibilités de remboursement anticipé. Les indemnités de remboursement anticipé (IRA) sont strictement encadrées par la loi. Vérifiez toujours votre offre de prêt.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from prior periods. Unlike simple interest, compound growth produces an exponential wealth curve over long time horizons.": "Les intérêts composés sont calculés sur le capital initial majoré des intérêts accumulés lors des périodes antérieures. Contrairement à l'intérêt simple, ils créent une courbe de croissance patrimoniale exponentielle au fil des années.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total return. More frequent compounding converts interest into principal faster, creating a higher Effective Annual Rate (EAR) than the stated nominal APR.": "Plus la capitalisation est fréquente (annuelle, trimestrielle, mensuelle ou journalière), plus le capital final est élevé, car les gains sont réinvestis plus rapidement pour produire de nouveaux intérêts.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary) to determine the exact annual employer contribution added to your balance.": "Le calculateur applique la formule d'abondement de votre employeur (ex. 50 % jusqu'à 6 % du salaire) pour évaluer précisément la contribution patronale annuelle ajoutée à votre épargne.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by 40, 6x by 50, 8x by 60, and 10x by age 67.": "Les repères professionnels suggèrent de viser : 1 fois son salaire annuel à 30 ans, 3 fois à 40 ans, 6 fois à 50 ans, 8 fois à 60 ans et 10 fois à 67 ans.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, investment returns, and fee drag.": "Votre capital de fin de carrière dépendra des intérêts composés, de votre effort d'épargne régulier, de l'abondement de l'entreprise, des rendements de marché et des frais de gestion prélevés sur vos encours.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer debt (except the home mortgage) is paid off and a 3- to 6-month emergency fund is established.": "L'étape 4 de la démarche de Dave Ramsey invite à placer 15 % des revenus bruts du ménage dans des plans de retraite dès lors que toutes les dettes de consommation sont éteintes et qu'une réserve de précaution de 3 à 6 mois est constituée.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees, requiring a mandatory employer contribution (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Le plan d'épargne d'entreprise allégé pour PME prévoit une contribution patronale minimale obligatoire au bénéfice de l'ensemble des salariés éligibles.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation expenses (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income.": "La règle 20/4/10 préconise au moins 20 % d'apport initial, un emprunt de 4 ans maximum (48 mois) et un budget transport global inférieur à 10 % de vos revenus bruts.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more in total interest. Additionally, you risk becoming 'upside-down' (owing more than the car is worth) due to rapid vehicle depreciation.": "Une durée de remboursement étalée (ex. 72 ou 84 mois) réduit l'échéance mensuelle mais gonfle le total des intérêts et expose au risque de dette supérieure à la valeur vénale du véhicule.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance will exceed the vehicle's market value, leaving you in negative equity if the car is totaled or sold early.": "Une voiture neuve perd une part importante de sa valeur dès la première année. Sans apport personnel suffisant, le capital dû excède la cote du véhicule en cas de revente précipitée.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on all other debts. Once the smallest debt is eliminated, you roll its payment into the next smallest balance to build rapid psychological momentum.": "La méthode boule de neige consiste à solder en premier lieu les dettes aux montants les plus faibles pour enregistrer rapidement des victoires psychologiques valorisantes.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on the rest. Once your highest-APR balance is cleared, you target the next highest rate.": "La méthode avalanche préconise de rembourser prioritairement le crédit au taux d'intérêt le plus lourd, tout en assurant les échéances minimales sur les autres emprunts.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest you pay and eliminates debt in the shortest calendar time. However, the Debt Snowball provides psychological quick wins that help many borrowers stick with their payoff plan.": "Sur le plan mathématique, l'avalanche est la stratégie la plus économique car elle limite au maximum le coût des intérêts. La boule de neige apporte quant à elle un soutien motivationnel important.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt until it is completely paid off.": "Vous assurez le paiement des mensualités contractuelles partout et réservez l'intégralité de votre capacité d'épargne supplémentaire pour éteindre la dette prioritaire.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain confidence, then switch to the Avalanche method to tackle high-interest credit cards mathematically.": "Oui. Nombreux sont ceux qui soldent une ou deux petites dettes pour se rassurer et alléger leur trésorerie, avant de basculer sur l'avalanche pour anéantir les taux d'intérêt élevés.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of compound interest over time.": "La Valeur Future (FV ou valeur acquise) est le montant patrimonial prévisionnel atteint par un capital ou des versements réguliers à une échéance donnée, sous l'effet des intérêts composés.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a progressive decline in the purchasing power of your money.": "L'inflation est la hausse continue et générale des prix des biens et services au cours du temps, se traduisant par une diminution graduelle du pouvoir d'achat de la monnaie.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only buy about $7,440 worth of goods and services in 10 years.": "L'argent conservé sur des comptes bancaires non rémunérés perd chaque année de son pouvoir d'achat réel. Avec une inflation moyenne de 3 % par an, 10 000 € perdent environ 26 % de pouvoir d'achat en 10 ans.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average price change over time for a representative basket of consumer goods and services like housing, food, transportation, and medical care.": "L'inflation est mesurée au premier chef par l'Indice des Prix à la Consommation (IPC), qui retrace l'évolution moyenne pondérée des prix d'un panier représentatif de biens et services consommés par les ménages.",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.5% annually over multi-decade periods, though short-term spikes can exceed this range.": "Dans la zone euro et la plupart des économies développées, les banques centrales fixent un objectif d'inflation annuelle de 2 % afin de soutenir l'activité économique tout en préservant la stabilité des prix.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy.": "Pour la majorité des emprunteurs, les formules de remboursement basées sur les revenus offrent les mensualités les plus douces et plafonnent l'accumulation des intérêts impayés.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching may capitalize unpaid interest.": "Oui, il est possible de faire une demande d'aménagement ou de changement de formule de remboursement à tout moment auprès de l'organisme gestionnaire en cas de changement de situation financière.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into the loan balance or charges a slightly higher interest rate.": "Une renégociation ou un rachat de crédit 'sans frais initiaux' ne signifie pas la gratuité : la banque incorpore les frais au capital à rembourser ou majore légèrement le taux d'intérêt.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same remaining term, you lower your monthly payment. If you shorten the term, your payment may rise, but you pay off the debt faster.": "Cela dépend de la durée choisie : renégocier à un taux inférieur en conservant la même durée restante diminue à la fois les mensualités et le coût total. Raccourcir la durée d'emprunt peut augmenter l'échéance mensuelle tout en réduisant considérablement la charge globale d'intérêts sur la durée du crédit.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though approvals up to 43% or even 50% are possible with strong credit scores.": "Pour l'octroi d'un prêt immobilier, les banques et les autorités de régulation (HCSF) imposent généralement un taux d'endettement maximal de 35 % assurance comprise, avec de rares dérogations pour les profils disposant d'un reste à vivre très confortable.",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, Roth is superior. If you expect your tax bracket to be lower in retirement, Traditional is usually better.": "En règle générale, si vous anticipez une tranche d'imposition plus élevée à la retraite qu'aujourd'hui, privilégiez une enveloppe exonérée à la sortie (PEA / assurance-vie). Si votre taux marginal actuel est élevé, optez pour un plan déductible à l'entrée (PER) pour maximiser vos déductions fiscales immédiates.",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under 50, and $8,000 for those 50 and older.": "Les plafonds annuels de déduction fiscale pour l'épargne retraite sont fixés par la loi de finances et comportent des dispositifs de report des plafonds non consommés des trois années précédentes.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers.": "Certaines formules d'épargne défiscalisée sont soumises à des conditions de ressources ou à des plafonds légaux stricts définis par le code général des impôts.",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax-free and penalty-free.": "Sur les enveloppes fiscales dédiées (comme le PEA après 5 ans ou l'assurance-vie après 8 ans), les rachats bénéficient d'une fiscalité allégée et les versements initiaux peuvent être retirés sans pénalités.",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have top rates exceeding 10%).": "Le montant net de votre salaire perçu sur votre compte bancaire dépend étroitement de vos cotisations sociales salariales, de votre taux de prélèvement à la source et des abattements applicables.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and sometimes Private Mortgage Insurance (PMI) or HOA fees. The principal and interest portion is calculated using the standard amortization formula.": "Une mensualité de prêt immobilier standard comprend le capital et les intérêts (P&I), l'assurance de prêt obligatoire, la taxe foncière et les éventuelles charges de copropriété. La part de capital et d'intérêts se calcule au moyen du tableau d'amortissement constant.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a total monthly mortgage payment when using an escrow account.": "PITI désigne les quatre composantes d'une mensualité immobilière globale : le Capital emprunté (Principal), les Intérêts bancaires (Interest), les Taxes locales (Taxes) et l'Assurance de prêt (Insurance).",
    "How much should I contribute to my 401(k)?": "Combien dois-je verser sur mon plan d'épargne retraite ?",
    "Most financial advisors recommend contributing at least 15% of your gross annual salary toward retirement (including employer matching). At a minimum, always contribute enough to capture your employer's full matching contribution—missing the match is walking away from free money and an instant 50% to 100% return. For 2024, the IRS employee elective deferral limit is $23,000 per year, or $30,500 if you are age 50 or older.": "La plupart des spécialistes du patrimoine préconisent de consacrer au moins 15 % de ses revenus bruts annuels à l'épargne retraite (abondement employeur inclus). Au strict minimum, versez le montant requis pour obtenir 100 % de l'abondement patronal afin de ne pas renoncer à ce complément de salaire garanti.",
    "How does this 401(k) calculator with match calculate employer contributions?": "Comment ce calculateur évalue-t-il l'abondement de l'employeur ?",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% or 100%) up to your company's matching ceiling (e.g., up to 6% of salary). For example, on a $95,000 salary with a 6% contribution ($5,700), a 50% match adds an extra $2,850/year in employer deposits. The calculator projects both your personal deferrals and employer matching contributions compounded across your entire retirement horizon.": "Le simulateur applique la formule exacte d'abondement de votre employeur (ex. 50 % ou 100 % jusqu'à 6 % du salaire). Par exemple, sur un salaire de 60 000 € avec 6 % de cotisation (3 600 €), un abondement de 50 % apporte 1 800 € supplémentaires par an versés par l'entreprise. L'outil projette la capitalisation globale de vos apports et de l'abondement sur l'ensemble de votre horizon retraite.",
    "How much should I have in my 401(k) by age?": "Quel capital retraite devrais-je avoir accumulé selon mon âge ?",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30; 2x by age 35; 3x by age 40; 4x by age 45; 6x by age 50; 8x by age 60; and 10x your final salary by age 67. If you earn $90,000 at age 40, your target 401(k) balance is approximately $270,000 to remain on track for complete income replacement.": "Les objectifs patrimoniaux de référence suggèrent de détenir : 1 fois votre salaire annuel à 30 ans, 2 fois à 35 ans, 3 fois à 40 ans, 4 fois à 45 ans, 6 fois à 50 ans, 8 fois à 60 ans et 10 fois à 67 ans pour maintenir votre niveau de vie une fois à la retraite.",
    "Should I do a Roth or Traditional 401(k)?": "Faut-il choisir une déduction d'impôt immédiate ou une exonération à la sortie ?",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income and federal tax liability today; withdrawals in retirement are taxed as ordinary income. In a Roth 401(k), you contribute after-tax dollars, but your investment earnings grow completely tax-free and all qualified distributions in retirement are 100% tax-free. If you are in a low tax bracket now (early career), choose Roth; if you are currently in your peak earning years and highest tax bracket, choose Traditional.": "Avec un plan d'épargne retraite déductible (type PER), vos versements diminuent votre revenu imposable et votre impôt actuel, mais les retraits seront imposés à la sortie. Avec un placement non déductible (type PEA ou assurance-vie), vous investissez des fonds après impôt, mais vos gains capitalisent et se récupèrent totalement défiscalisés au terme. Privilégiez l'enveloppe non imposée à la sortie si votre fiscalité actuelle est faible, et la déduction immédiate si vous êtes dans vos années de plus forte imposition.",
    "How much does a 401(k) contribution reduce my taxes?": "De combien mes versements de retraite réduisent-ils mes impôts ?",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income dollar-for-dollar. The tax savings formula is: Annual Contribution × Marginal Tax Rate. For example, contributing $10,000 at a 24% federal tax bracket plus 5% state tax saves $2,900 in total taxes. Your take-home pay only drops by $7,100 while your retirement nest egg grows by a full $10,000.": "Chaque euro versé sur un support de retraite déductible réduit directement votre revenu imposable. La formule d'économie d'impôt est : Versement Annuel × Taux Marginal d'Imposition (TMI). Par exemple, verser 10 000 € avec un TMI de 30 % vous fait économiser 3 000 € d'impôt : votre salaire net ne baisse que de 7 000 € alors que votre capital retraite s'accroît de 10 000 €.",
    "How much will my 401(k) be worth at retirement?": "Quelle sera la valeur de mon épargne à l'âge de la retraite ?",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, and time. For example, contributing $600 per month starting at age 30 with a $25,000 starting balance and an average 7.5% annual return yields approximately $1,350,000 by age 65. The vast majority of this total (over 70%) comes from compound investment growth rather than out-of-pocket deposits.": "Votre capital prévisionnel dépend des intérêts composés, de votre régularité de versement, de l'abondement de l'entreprise et de la durée de placement. Par exemple, épargner 500 € par mois à partir de 30 ans avec 20 000 € d'apport initial et un rendement moyen de 7 % par an produit environ 1 000 000 € à 65 ans, dont plus de 70 % proviennent des intérêts réinvestis et de la capitalisation.",
    "How long will my 401(k) last in retirement?": "Pendant combien d'années mon capital retraite me permettra-t-il de vivre ?",
    "Can I cancel my 401(k) and cash out while still employed?": "Puis-je débloquer mon plan d'épargne retraite tout en restant salarié ?",
    "How does the Dave Ramsey 401(k) calculator 15% rule work?": "Comment fonctionne la règle des 15 % de Dave Ramsey ?",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into retirement once consumer debt is eliminated and a 3-to-6 month emergency fund is established. The Dave Ramsey 401k calculator strategy follows a 3-step order: (1) Invest in your company 401(k) up to the full employer match; (2) Max out a Roth IRA; (3) Put any remaining portion of the 15% into your Roth 401(k) or Traditional 401(k). Use our 'Dave Ramsey (15% Rule)' preset to model this exact path.": "Selon l'étape 4 de Dave Ramsey, vous placez 15 % des revenus bruts du foyer dans l'épargne retraite dès que les dettes de consommation sont remboursées et qu'un fonds de secours de 3 à 6 mois est constitué. La stratégie s'ordonne en 3 temps : (1) cotiser sur le plan d'entreprise jusqu'au plein abondement employeur ; (2) abonder les enveloppes individuelles non taxées ; (3) verser le solde sur son contrat d'entreprise. Utilisez notre bouton 'Règle des 15 % (Dave Ramsey)' pour simuler cette stratégie.",
    "What is a SIMPLE 401(k) calculator and who qualifies for a SIMPLE plan?": "Qu'est-ce qu'un plan d'épargne pour PME et qui y a droit ?",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. A simple 401k calculator models the required employer contributions: either a dollar-for-dollar match up to 3% of salary, or a flat 2% non-elective contribution for all eligible workers. SIMPLE 401(k) plans feature 100% immediate vesting, no complex nondiscrimination testing, and lower contribution limits ($16,000 in 2024, or $19,500 if age 50+).": "Le plan d'épargne d'entreprise simplifié pour PME s'adresse aux structures de moins de 100 salariés. Notre simulateur modélise les contributions obligatoires de l'employeur (abondement jusqu'à 3 % du salaire ou versement forfaitaire de 2 % pour tous les salariés), avec disponibilité immédiate des droits et gestion administrative simplifiée.",
    "What is Future Value (FV)?": "Qu'est-ce que la Valeur Future (FV) ?",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or compounding interest.": "La Valeur Future (FV ou valeur acquise) est la valeur financière qu'atteindra un capital actuel ou des versements réguliers à une échéance donnée, calculée sur la base d'un taux d'intérêt composé attendu.",
    "What is the formula for calculating Future Value with regular contributions?": "Quelle est la formule pour calculer la Valeur Future avec des versements réguliers ?",
    "For a lump sum with regular periodic additions: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], where PV is present value, r is annual interest rate, m is compounding frequency per year, t is time in years, and PMT is periodic contribution.": "Pour un capital initial accompagné de versements périodiques : FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], où PV est la valeur actuelle, r le taux d'intérêt annuel, m la fréquence de capitalisation par an, t la durée en années et PMT le versement périodique.",
    "What is the difference between an ordinary annuity and annuity due for future value?": "Quelle est la différence entre une annuité ordinaire et une annuité due pour la valeur future ?",
    "In an ordinary annuity, contributions are deposited at the end of each period. In an annuity due, contributions are made at the beginning of each period, which gives every contribution an extra period to compound and results in a higher ending future value.": "Dans une annuité ordinaire, les versements sont effectués à la fin de chaque période. Dans une annuité due, les versements ont lieu au début de chaque période, offrant à chaque versement une période de capitalisation supplémentaire qui engendre une valeur future plus élevée.",
    "How does compounding frequency impact the future value of an investment?": "Quel est l'impact de la fréquence de capitalisation sur la valeur future d'un placement ?",
    "More frequent compounding cycles (such as monthly or daily versus annually) result in higher future values because interest earned in earlier cycles begins generating its own interest sooner.": "Une fréquence de composition plus rapprochée (mensuelle ou quotidienne plutôt qu'annuelle) débouche sur un capital final supérieur, car les intérêts génèrent des rendements plus vite.",
    "What is a realistic annual rate of return for an investment calculator?": "Quel taux de rendement annuel est réaliste pour des projections financières ?",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of approximately 10% annually over long multi-decade horizons (or roughly 7% after adjusting for inflation). A diversified portfolio of stocks and bonds typically targets 6% to 8% nominal annual return.": "Historiquement, les marchés actions mondiaux diversifiés affichent environ 8 % à 10 % de performance nominale brute annuelle sur longue période (soit 6 % à 7 % net d'inflation). Un portefeuille équilibré en actions et obligations vise classiquement 5 % à 7 % par an.",
    "How do regular recurring investments compare to a one-time lump sum?": "Comment se comparent les versements programmés face à un investissement en une seule fois ?",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility by consistently purchasing shares at both market highs and lows. While lump-sum investing mathematically outperforms about 68% of the time due to long-term market upward trends, recurring monthly deposits instill discipline and build substantial wealth steadily.": "L'investissement programmé régulier (DCA) atténue le risque de mauvais timing et lisse la volatilité. Même si l'investissement en une seule fois surpasse statistiquement le DCA environ 68 % du temps en raison de la tendance haussière séculaire des marchés, les versements mensuels apportent une discipline d'épargne indispensable.",
    "What is the difference between nominal return and real return?": "Quelle est la différence entre rendement nominal et rendement réel ?",
    "How does compound interest multiply investment portfolios over time?": "Comment les intérêts composés démultiplient-ils la valeur d'un portefeuille dans le temps ?",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contributions make up the majority of your balance; however, after 10 to 20 years, investment returns and compounded earnings account for over 60% to 80% of total portfolio value.": "Les intérêts composés génèrent une croissance exponentielle. Au départ, vos versements représentent l'essentiel du capital ; après 15 à 20 ans, les rendements réinvestis constituent plus de 60 % à 80 % de la valeur totale de votre portefeuille.",
    "How do I calculate a percentage salary increase?": "Comment calculer le pourcentage d'une hausse de salaire ?",
    "To calculate the percentage increase: subtract your old salary from your new salary, divide the difference by your old salary, and multiply by 100: ((New - Old) / Old) × 100. For example, moving from $75,000 to $82,500 is (($82,500 - $75,000) / $75,000) × 100 = 10%.": "Pour calculer le pourcentage d'augmentation : déduisez l'ancien salaire du nouveau, divisez la différence par l'ancien salaire et multipliez par 100 : ((Nouveau - Ancien) / Ancien) × 100. Par exemple, passer de 45 000 € à 49 500 € représente : ((49 500 - 45 000) / 45 000) × 100 = 10 %.",
    "How much of my salary raise will I actually take home after taxes?": "Combien vais-je réellement percevoir en net après impôts sur mon augmentation ?",
    "Your net take-home boost depends on your marginal tax bracket and payroll deductions. Because raises are taxed at your highest marginal rate rather than your lower average rate, you typically take home between 55% and 75% of your gross increase (depending on state taxes and FICA).": "Votre gain net dépend de vos cotisations sociales et de votre tranche marginale d'imposition (TMI). Comme l'augmentation est taxée au taux marginal le plus haut plutôt qu'au taux moyen, vous conservez généralement entre 55 % et 75 % du montant brut supplémentaire.",
    "What is the difference between a merit raise and a cost-of-living adjustment (COLA)?": "Quelle est la différence entre une augmentation au mérite et une revalorisation au coût de la vie ?",
    "A Cost of Living Adjustment (COLA) is an across-the-board raise (typically 2% to 4%) designed to keep your purchasing power level with consumer inflation. A merit or performance raise is an individualized increase rewarded for outstanding work, increased duties, or hitting high performance benchmarks.": "Une revalorisation au coût de la vie est une augmentation générale (souvent de 2 % à 4 %) visant à maintenir le pouvoir d'achat face à l'inflation. Une augmentation au mérite est une hausse individuelle récompensant la performance, les compétences et les responsabilités exercées.",
    "How often should you ask for a salary increase?": "À quelle fréquence convient-il de demander une augmentation de salaire ?",
    "Standard corporate practice evaluates compensation annually during performance reviews. However, you should initiate compensation discussions whenever you take on significantly expanded responsibilities, complete major high-value certifications, or outperform annual targets by a substantial margin.": "Dans la pratique, les rémunérations sont revues annuellement lors des entretiens d'évaluation. Il est toutefois légitime de solliciter un entretien exceptionnel en cas d'élargissement substantiel de vos responsabilités, d'obtention de certifications clés ou de dépassement notable de vos objectifs.",
    "How is a mortgage payment calculated?": "Comment est calculée la mensualité d'un prêt immobilier ?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "Une mensualité de prêt comprend le capital et les intérêts, l'assurance emprunteur, les taxes foncières éventuelles et les frais de copropriété.",
    "What is the Debt Snowball method?": "Qu'est-ce que la méthode de la 'Boule de neige' ?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Elle consiste à solder d'abord les plus petits montants de dette, sans tenir compte du taux d'intérêt, procurant des victoires psychologiques rapides.",
    "What is the Debt Avalanche method?": "Qu'est-ce que la méthode de l''Avalanche' ?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Elle consiste à rembourser en priorité les dettes aux taux d'intérêt les plus élevés, ce qui minimise le coût financier total du crédit.",
    "What is net worth?": "Qu'est-ce que le patrimoine net ?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "C'est la différence entre la valeur totale de vos actifs (biens, épargne) et vos dettes cumulées.",
    "How much emergency fund is recommended?": "Quel montant dédier au fonds d'urgence ?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Il est recommandé de conserver l'équivalent de 3 à 6 mois de dépenses courantes sur un compte immédiatement disponible.",
    "What is Dollar-Cost Averaging (DCA)?": "Qu'est-ce que l'investissement programmé (DCA) ?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "C'est la pratique consistant à investir une somme fixe à intervalles réguliers pour lisser le coût d'achat moyen.",
    "What is inflation?": "Qu'est-ce que l'inflation ?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "C'est la hausse durable du niveau général des prix entraînant la perte de pouvoir d'achat de la monnaie.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "Un prêt sur 15 ans offre généralement un taux plus bas et permet de devenir propriétaire deux fois plus vite, ce qui fait économiser des dizaines de milliers d'euros d'intérêts. En revanche, un prêt sur 30 ans donne des mensualités plus faibles, donc plus de souplesse budgétaire au quotidien.",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Selon les standards australiens de retraite (norme ASFA), une personne seule a besoin d'une épargne retraite d'environ 595 000 € à 67 ans, tandis qu'un couple doit disposer d'environ 690 000 € pour maintenir un niveau de vie confortable à la retraite.",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "Le ratio de frais (expense ratio) correspond aux frais annuels prélevés par un fonds commun de placement ou un ETF pour sa gestion. Il s'exprime en pourcentage de votre investissement total (par exemple, 0,10 % représente 1 € par an pour 1 000 € investis).",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Tout versement supplémentaire est imputé directement sur le capital restant dû. Cela réduit le solde du prêt et les intérêts futurs, ce qui vous permet de solder votre crédit des années plus tôt et d'économiser une somme importante d'intérêts.",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "La demande d'un nouveau prêt entraîne une légère baisse temporaire de votre score de crédit (5 à 10 points) liée à la vérification du dossier. Toutefois, utiliser ce prêt pour solder vos cartes de crédit saturées fait chuter immédiatement votre taux d'utilisation du crédit, ce qui améliore généralement votre score de façon significative sous 30 à 60 jours.",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "Le bêta mesure la volatilité ou le risque systématique d'un actif par rapport au marché global. Un bêta de 1,0 signifie que le cours évolue au même rythme que le marché. Un bêta supérieur à 1,0 indique une volatilité plus forte (risque et rendement potentiels accrus), tandis qu'un bêta inférieur à 1,0 signale une volatilité plus faible.",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "Le TCAC (taux de croissance annuel composé, ou CAGR en anglais) représente le taux de rendement annualisé de votre investissement sur une période de détention, en supposant que les gains sont capitalisés chaque année.",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "Le MEDAF (modèle d'évaluation des actifs financiers, ou CAPM en anglais) est un modèle financier qui calcule le rendement attendu d'un investissement en fonction de son risque systématique (bêta). Il sert de référence pour déterminer le coût des fonds propres.",
    "Can I do a hybrid of Snowball and Avalanche?": "Peut-on combiner les méthodes Boule de neige et Avalanche ?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "Les versements à fiscalité avantageuse (y compris la cotisation patronale obligatoire et l'épargne salariale avant impôt) sont taxés à seulement 15 % au sein du fonds, contre une tranche marginale d'impôt sur le revenu pouvant atteindre 45 % hors prélèvements sociaux.",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Les intérêts composés quotidiens sont calculés et crédités sur votre solde chaque jour (365 fois par an). Les jours suivants, vous percevez des intérêts à la fois sur votre capital initial et sur les intérêts déjà accumulés, ce qui accélère la croissance exponentielle de votre patrimoine.",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "Le regroupement de crédits réunit plusieurs dettes à taux élevés (comme des cartes de crédit à 20 %–29 % de TAEG) en un seul prêt personnel à taux fixe plus bas (par exemple 8 %–14 % de TAEG). Cela réduit votre mensualité totale et vous fait économiser des milliers d'euros en intérêts.",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "Le regroupement de crédits solde intégralement vos créanciers grâce à un nouveau prêt à taux réduit, sans dégrader votre historique de crédit. La négociation de dettes (debt settlement) consiste à cesser vos paiements pour négocier un montant inférieur à ce que vous devez, ce qui endommage gravement et durablement votre dossier de crédit.",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "C'est l'écart entre le revenu brut ajusté et le seuil de pauvreté fédéral applicable à la taille du foyer fiscal.",
    "Do high-yield savings accounts (HYSA) compound daily?": "Les comptes d'épargne à haut rendement composent-ils les intérêts quotidiennement ?",
    "Does debt consolidation hurt your credit score?": "Le regroupement de crédits nuit-il à votre score de crédit ?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE signifie Indépendance Financière, Retraite Anticipée (Financial Independence, Retire Early). C'est une stratégie qui consiste à maximiser votre taux d'épargne (souvent 40 % à 70 % des revenus) et à investir dans des fonds indiciels à faibles frais jusqu'à ce que votre portefeuille génère suffisamment de revenus passifs pour couvrir durablement vos dépenses.",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Pour toute personne née en 1960 ou après, l'âge légal de départ à taux plein est de 67 ans. Si vous partez à cet âge, vous percevez 100 % de votre pension de base, sans décote pour départ anticipé.",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Pour chaque année où vous différez votre départ au-delà de l'âge du taux plein (jusqu'à 70 ans), votre pension augmente de 8 % par an grâce aux majorations pour report. Attendre 70 ans vous garantit environ 124 % de votre pension à taux plein, à vie.",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "Le taux d'endettement logement ne mesure que la part du revenu brut mensuel consacrée au logement : mensualité, taxe foncière, assurance habitation et charges de copropriété. Le taux d'endettement global y ajoute toutes les autres dettes récurrentes : prêt étudiant, cartes de crédit, crédit auto et prêts personnels.",
    "How can I lower my Debt-to-Income ratio?": "Comment réduire son taux d'endettement ?",
    "How do I calculate my refinance break-even point?": "Comment calculer le point mort (retour sur investissement) du rachat ?",
    "How do I calculate stock returns?": "Comment calculer le rendement total d'une action ?",
    "How do extra payments affect my mortgage payoff schedule?": "Quel est l'impact des remboursements anticipés sur le prêt ?",
    "How does DTI affect my mortgage application?": "Comment le taux d'endettement influence-t-il la demande de prêt ?",
    "How does debt consolidation save you money?": "Comment le regroupement de crédits vous fait-il économiser ?",
    "How does salary sacrificing boost superannuation growth?": "Comment l'épargne salariale avant impôt accélère-t-elle la croissance de votre retraite ?",
    "How does the 'extra payment' roll over in these strategies?": "Comment se reporte l'effort d'épargne supplémentaire ?",
    "How is discretionary income calculated for student loans?": "Comment est calculé le revenu disponible pour les prêts étudiants ?",
    "How is money inside Australian Super taxed?": "Comment l'épargne placée dans un fonds Super australien est-elle taxée ?",
    "How is your FIRE Number calculated?": "Comment votre objectif FIRE est-il calculé ?",
    "How much more do I get if I delay claiming Social Security until age 70?": "Combien gagnez-vous de plus en différant votre pension jusqu'à 70 ans ?",
    "How much more money do you earn with daily vs monthly compounding?": "Combien gagnez-vous de plus avec une capitalisation quotidienne plutôt que mensuelle ?",
    "How much super do I need for a comfortable retirement in Australia?": "De quelle épargne retraite avez-vous besoin pour une retraite confortable en Australie ?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Dans les deux méthodes, vous continuez à payer les mensualités minimales de toutes vos dettes. Toute somme supplémentaire disponible est ajoutée au remboursement de la dette ciblée (le plus petit solde ou le taux le plus élevé). Une fois cette dette soldée, vous reportez l'intégralité de sa mensualité (minimum + supplément) sur la dette suivante de votre liste.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Un prêt sur 15 ans est-il préférable à un prêt sur 30 ans ?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Il est généralement judicieux de renégocier si vous obtenez un taux plus bas, réduisez votre mensualité ou raccourcissez votre durée. L'objectif principal est de vérifier que l'économie totale d'intérêts dépasse les frais de dossier.",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "Le Lean FIRE vise à couvrir uniquement des dépenses essentielles et minimalistes (généralement moins de 40 000 € par an). Le Standard FIRE maintient un mode de vie confortable de classe moyenne (50 000 € à 100 000 € par an). Le Fat FIRE permet des dépenses abondantes et luxueuses (plus de 120 000 € par an) sans contrainte financière.",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Les banques utilisent le taux d'endettement pour mesurer votre capacité à assumer les mensualités. Un taux élevé signale un surendettement potentiel, ce qui peut entraîner un refus ou un taux majoré. En dessous de 36 %, le risque est considéré comme faible.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Mathématiquement, la méthode avalanche est supérieure car elle minimise les intérêts totaux versés. Pourtant, les études montrent que la méthode boule de neige réussit plus souvent en pratique, car l'élan psychologique des dettes soldées rapidement aide à rester motivé et à tenir le plan.",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Sur un dépôt de 100 000 € à 7 % de TAEG pendant 20 ans, la capitalisation quotidienne rapporte 405 514 € contre 403 873 € pour la capitalisation mensuelle, soit 1 641 € supplémentaires grâce à la seule fréquence de capitalisation.",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Issue de la célèbre étude Trinity, la règle des 4 % stipule que vous pouvez retirer 4 % de votre portefeuille initial chaque année (ajusté annuellement de l'inflation) avec plus de 95 % de probabilité de ne jamais épuiser votre capital pendant une retraite de 30 ans.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "PITI désigne le Capital (Principal), les Intérêts (Interest), les Impôts (Taxes) et l'Assurance (Insurance) : les quatre piliers de la charge mensuelle immobilière.",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "Elle protège le prêteur en cas de défaillance. Elle est couramment exigée lorsque l'apport personnel est inférieur à 20 % du prix d'acquisition.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Les frais de renégociation comprennent généralement les frais de dossier, les frais d'ouverture, l'expertise du bien, la recherche de titre et l'assurance, les frais de rapport de crédit et les frais d'enregistrement. Ils représentent entre 2 % et 6 % du montant emprunté.",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "L'épargne salariale avant impôt vous permet de verser une partie de votre salaire brut directement dans votre fonds de retraite. Comme vous évitez votre tranche marginale d'imposition plus élevée et profitez des intérêts composés pendant des décennies, ces versements supplémentaires peuvent ajouter des centaines de milliers d'euros à votre capital retraite.",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "La règle du 28/36 est une norme classique d'octroi de crédit immobilier. Elle recommande de consacrer au maximum 28 % du revenu brut mensuel aux dépenses de logement, et au maximum 36 % à l'ensemble des dettes (logement, cartes de crédit, crédit auto et prêt étudiant).",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "C'est un plan indexé sur les revenus qui protège le revenu de base et plafonne les mensualités à 5-10 % du revenu disponible.",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "L'âge d'équilibre se situe généralement entre 78 et 81 ans. Si vous pensez vivre au-delà de 80 ans, différer votre départ jusqu'à 70 ans rapporte presque toujours un montant cumulé plus élevé sur l'ensemble de votre vie.",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "La formule de capitalisation quotidienne est A = P(1 + r/365)^(365 * t), où P est le capital initial, r le taux d'intérêt annuel (en décimal) et t la durée en années. Lorsque des versements réguliers sont ajoutés, les intérêts sont calculés sur le solde quotidien actualisé.",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Pour calculer la rentabilité totale d'une action, soustrayez le prix d'achat du prix de vente pour obtenir la plus-value. Ajoutez les dividendes perçus. Divisez cette somme par le prix d'achat initial, puis multipliez par 100 pour obtenir le rendement en pourcentage.",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Pour trouver votre seuil de rentabilité, divisez le total des frais de renégociation par l'économie mensuelle réalisée. Par exemple, avec 3 000 € de frais et 150 € d'économie par mois, le seuil est de 20 mois (3 000 € / 150 €). Si vous prévoyez de vendre ou de déménager avant ce délai, la renégociation n'est pas rentable.",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "L'IRA traditionnel est défiscalisé à l'entrée et imposé à la sortie ; le Roth est alimenté après impôts mais garantit une exonération fiscale totale sur les plus-values.",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "En vertu de la législation fédérale australienne, les employeurs sont tenus de verser un pourcentage de votre salaire ordinaire dans votre fonds de retraite désigné. Ce taux doit atteindre 12 % selon la loi en vigueur.",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Méfiez-vous des frais de montage (généralement 1 % à 6 % du montant du prêt), assurez-vous que la nouvelle mensualité s'intègre confortablement dans votre budget et évitez de creuser de nouveaux soldes sur les cartes de crédit que vous venez de solder.",
    "What closing costs are associated with refinancing?": "Quels sont les frais liés au rachat de crédit ?",
    "What does Asset Beta (β) represent?": "Que représente le Bêta (β) d'un titre ?",
    "What does PITI stand for?": "Que signifie le sigle PITI ?",
    "What is CAGR in stock returns?": "Que signifie le CAGR en bourse ?",
    "What is PMI and when do I pay it?": "Qu'est-ce que l'assurance emprunteur / PMI et quand s'applique-t-elle ?",
    "What is an expense ratio?": "Qu'est-ce que le ratio de frais sur encours (TER) ?",
    "What is daily compound interest and how does it work?": "Qu'est-ce que les intérêts composés quotidiens et comment fonctionnent-ils ?",
    "What is my Full Retirement Age (FRA)?": "Quel est mon âge de départ à taux plein ?",
    "What is the 28/36 rule?": "Qu'est-ce que la règle budgétaire des 28/36 % ?",
    "What is the 4% Safe Withdrawal Rule?": "Qu'est-ce que la règle des 4 % de retrait sans risque ?",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Quel est le taux de la garantie de retraite obligatoire australienne (SG) ?",
    "What is the Capital Asset Pricing Model (CAPM)?": "Qu'est-ce que le MEDAF / CAPM ?",
    "What is the FIRE movement and what does it mean?": "Qu'est-ce que le mouvement FIRE et que signifie-t-il ?",
    "What is the SAVE plan?": "Qu'est-ce que le dispositif de remboursement SAVE ?",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "Quel est l'âge d'équilibre entre un départ à 62 ans ou à 70 ans ?",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Quelle est la différence entre le Lean FIRE, le Standard FIRE et le Fat FIRE ?",
    "What is the difference between debt consolidation and debt settlement?": "Quelle est la différence entre le regroupement de crédits et la négociation de dettes ?",
    "What is the difference between front-end and back-end DTI?": "Quelle est la différence entre endettement logement et endettement global ?",
    "What is the formula for daily compound interest?": "Quelle est la formule des intérêts composés quotidiens ?",
    "What is the key difference between a Roth and Traditional IRA?": "Quelle est la différence fondamentale entre IRA traditionnel et IRA Roth ?",
    "What should I look out for before consolidating debt?": "À quoi devez-vous faire attention avant de regrouper vos crédits ?",
    "When is the earliest age I can claim Social Security retirement benefits?": "Quel est l'âge minimal pour demander votre pension de retraite ?",
    "When should I refinance my loan?": "Quand est-il judicieux de renégocier ou faire racheter son prêt ?",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Laquelle est la meilleure : Boule de neige ou Avalanche ?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Oui, la grande majorité des comptes d'épargne à haut rendement et des comptes monétaires composent les intérêts quotidiennement et les créditent sur votre solde le dernier jour ouvré du mois.",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Oui. Certains préfèrent solder d'abord une ou deux petites dettes pour voir un progrès immédiat et libérer du budget (boule de neige), puis s'attaquer aux dettes restantes en visant les taux les plus élevés pour économiser les intérêts (avalanche).",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Vous pouvez réduire votre taux d'endettement soit en augmentant votre revenu brut mensuel (augmentation, activité complémentaire), soit en remboursant vos dettes récurrentes. Concentrez-vous sur le remboursement intégral des petits prêts pour faire disparaître leur mensualité minimale de votre calcul d'endettement.",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Vous pouvez commencer à percevoir votre pension de retraite dès 62 ans. Toutefois, un départ anticipé réduit définitivement votre mensualité jusqu'à 30 % par rapport à un départ à l'âge du taux plein.",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Votre objectif FIRE correspond à vos dépenses annuelles multipliées par 25 (selon la règle des 4 %) ou par 33 (selon une règle prudente de 3 %). Par exemple, si vous vivez confortablement avec 60 000 € par an, votre objectif FIRE est de 1 500 000 €.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into your new total loan balance or charges a slightly higher interest rate to cover them. This avoids paying cash upfront but increases the lifetime cost of the loan.": "Une renégociation « sans frais de dossier » ne signifie pas que les frais sont offerts. La banque les intègre soit au capital emprunté, soit à un taux légèrement majoré. Vous n'avancez rien au départ, mais le coût total du crédit augmente.",
    "Are there income limits for contributing to Traditional and Roth IRAs?": "Existe-t-il des plafonds de revenus pour cotiser ?",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower than it is today, a Traditional IRA is better.": "En règle générale, si vous pensez être plus imposé à la retraite qu'aujourd'hui, le Roth IRA est préférable. Si vous pensez être moins imposé à la retraite, l'IRA traditionnel est plus avantageux.",
    "Can I switch student loan repayment plans at any time?": "Peut-on changer de plan de remboursement en cours de route ?",
    "Can I withdraw money from my IRA before age 59½ without penalty?": "Peut-on retirer ses fonds avant 59 ans et demi sans pénalité ?",
    "Does refinancing lower my monthly payment or total interest?": "Le rachat réduit-il la mensualité ou le coût total ?",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under age 50, and $8,000 for those age 50 or older (which includes a $1,000 catch-up contribution).": "Pour 2024, le plafond annuel de versement est de 7 000 € pour les moins de 50 ans et de 8 000 € pour les 50 ans et plus (dont 1 000 € de versement de rattrapage).",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. However, if your income is very high relative to your debt, plans like PAYE or IBR might be better because they cap your monthly payment at what it would be under the Standard 10-Year Repayment Plan, whereas SAVE has no payment cap.": "Pour la plupart des emprunteurs, le plan SAVE offre la mensualité la plus basse et la meilleure prise en charge des intérêts. Mais si vos revenus sont très élevés par rapport à votre dette, les plans PAYE ou IBR peuvent être préférables car ils plafonnent la mensualité au niveau du plan standard sur 10 ans, contrairement à SAVE qui n'a pas de plafond.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though many will approve up to 43%. Government-backed loans like FHA and VA loans can be more flexible, sometimes allowing back-end DTIs up to 50% or higher if you have a strong credit score or significant cash reserves.": "Pour un crédit classique, les banques préfèrent généralement un taux d'endettement global de 36 % maximum, même si beaucoup acceptent jusqu'à 43 %. Les prêts aidés par l'État (type FHA ou VA) sont plus souples et peuvent aller jusqu'à 50 % ou plus si vous avez un excellent dossier ou une épargne importante.",
    "How does student loan forgiveness work under IDR plans?": "Comment fonctionne l'effacement de la dette étudiante ?",
    "If you pay under an IDR plan for 20 or 25 years (or as little as 10 years under SAVE for low initial balances), any remaining student debt is forgiven. However, under current tax laws, this forgiven balance may be treated as taxable income, although federal tax on forgiven student loans is temporarily suspended through 2025.": "Si vous remboursez selon un plan indexé sur les revenus pendant 20 ou 25 ans (voire 10 ans seulement avec SAVE pour les petits soldes de départ), le solde restant est effacé. Attention toutefois : ce montant effacé peut être considéré comme un revenu imposable, même si la taxation fédérale est temporairement suspendue jusqu'en 2025.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same or shorter term, you save on both. However, if you reset your term back to 30 years to get the lowest possible monthly payment, you might end up paying more total interest over the life of the loan despite the monthly savings.": "Les deux sont possibles, tout dépend de la nouvelle durée. Si vous renégociez à un taux plus bas en gardant la même durée ou en la raccourcissant, vous gagnez sur les deux tableaux. Mais si vous repartez sur 30 ans pour obtenir la mensualité la plus basse possible, vous risquez de payer plus d'intérêts au total malgré l'économie mensuelle.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers, and $230,000 to $240,000 for married couples filing jointly. Anyone can contribute to a Traditional IRA regardless of income, but the tax deductibility phases out if your income is high and you have access to a workplace retirement plan (like a 401k).": "Les Roth IRA sont soumis à des plafonds de revenus stricts : en 2024, l'éligibilité diminue progressivement entre 146 000 € et 161 000 € pour une personne seule, et entre 230 000 € et 240 000 € pour un couple déclarant conjointement. Chacun peut alimenter un IRA traditionnel quel que soit son revenu, mais la déductibilité fiscale diminue si vos revenus sont élevés et que vous bénéficiez déjà d'un plan retraite d'entreprise (type 401k).",
    "What are the contribution limits for IRAs in 2024?": "Quel est le plafond de versement annuel ?",
    "What is a 'no-closing-cost' refinance?": "Qu'est-ce qu'un rachat 'sans frais initiaux' ?",
    "What is the maximum DTI ratio lenders will accept?": "Quel est le taux d'endettement maximal accordé par les banques ?",
    "Which IDR plan is best for me?": "Quel plan de remboursement choisir ?",
    "Which IRA plan is better for me?": "Quel compte de retraite individuel privilégier ?",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax- and penalty-free, but withdrawing earnings early incurs taxes and a 10% penalty. With a Traditional IRA, withdrawing any funds early generally triggers both regular income tax and a 10% penalty, except for specific IRS-approved exemptions (e.g., qualifying first-time home purchase, higher education expenses, or disability).": "Avec un Roth IRA, vous pouvez retirer vos versements initiaux à tout moment et sans pénalité ni impôt, mais un retrait anticipé des gains entraîne impôts et pénalité de 10 %. Avec un IRA traditionnel, tout retrait anticipé est généralement soumis à l'impôt sur le revenu plus une pénalité de 10 %, sauf exceptions admises par l'administration fiscale (comme l'achat d'une première résidence principale, les frais d'études supérieures ou l'invalidité).",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause outstanding unpaid interest to capitalize (be added to your principal balance), which means you will start paying interest on that interest.": "Oui, vous pouvez demander à changer de plan de remboursement gratuitement sur studentaid.gov. Attention toutefois : ce changement peut parfois capitaliser les intérêts impayés (ils s'ajoutent au capital restant dû), ce qui signifie que vous paierez ensuite des intérêts sur ces intérêts.",
    "A 1% annual fee difference can erode 25% to 30% of your total ending portfolio wealth over a 30-year investment horizon.": "Un modeste écart de 1 % de frais annuels peut engloutir 25 % à 30 % de votre capital total final après 30 ans d'épargne !",
    "A 529 plan is a tax-advantaged savings and investment plan designed to encourage saving for future higher education expenses with tax-free growth and qualified withdrawals.": "Un plan d'investissement fiscalement avantageux permettant de financer les études supérieures avec plus-values et retraits exonérés d'impôt.",
    "A DRIP automatically uses your cash dividend payments to purchase additional shares or fractional shares of the stock, compounding your share count and future payouts without commission fees.": "Un mécanisme qui réinvestit automatiquement vos dividendes dans de nouvelles actions de l'entreprise sans frais de courtage, décuplant l'effet boule de neige.",
    "A negative net worth means your total debts exceed your total assets. This is common for young adults and recent graduates with student loans.": "Cela signifie que vos dettes dépassent vos avoirs, ce qui est fréquent chez les jeunes diplômés ou lors d'un achat immobilier récent.",
    "An expense ratio is the annual percentage fee charged by mutual funds and ETFs to cover fund management, administrative expenses, and operating costs.": "C'est le pourcentage annuel prélevé par les fonds et ETF pour couvrir les coûts de gestion financière et d'administration.",
    "Are dividend payments guaranteed?": "Les dividendes sont-ils garantis ?",
    "Assets include bank balances, investment accounts, home equity, and retirement funds. Liabilities include mortgages, student loans, car loans, and credit card debt.": "Actifs : épargne bancaire, comptes titres, valeur des biens immobiliers, PER. Passifs : prêts immobiliers, crédits conso, découverts.",
    "Automate recurring monthly transfers into a dedicated savings account immediately after your paycheck arrives (the 'pay yourself first' strategy).": "Automatisez un virement permanent vers un compte séparé dès le versement de votre salaire (le principe de 'se payer en premier').",
    "Beta measures an asset's volatility compared to the broader market. A beta of 1.0 indicates market-level volatility; above 1.0 indicates higher volatility, and below 1.0 indicates lower volatility.": "Il mesure la sensibilité du titre par rapport à l'indice de référence : Bêta = 1 réplique le marché ; supérieur à 1, l'actif est plus volatil que le marché.",
    "Build a starter emergency fund of 1 month of expenses or $1,000 to $2,000 first, then aggressively pay off high-interest consumer debt before expanding to 3-6 months.": "Créez d'abord une réserve initiale de 1 000 € à 2 000 €, remboursez ensuite agressivement vos crédits renouvelables, puis portez l'épargne à 3-6 mois.",
    "CAPM calculates an asset's expected return based on its risk relative to the overall market, using the formula: Expected Return = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate).": "Le modèle d'évaluation des actifs financiers détermine la rentabilité exigée d'un titre selon son risque de marché : Rendement = Taux sans risque + Bêta × Prime de risque.",
    "Can I use a 529 plan for trade schools or K-12 tuition?": "Peut-on l'utiliser pour des formations professionnelles ou le secondaire ?",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation is 3%, $100 today will only buy about $97 worth of goods next year.": "L'argent non rémunéré se déprécie : avec 3 % d'inflation, 100 € aujourd'hui ne permettront d'acheter que 97 € de biens l'an prochain.",
    "Compound Annual Growth Rate (CAGR) measures the geometric mean annual return of a stock over multiple years, smoothing out annual market fluctuations.": "Le taux de croissance annuel composé (CAGR) mesure la performance annuelle lissée d'un placement sur plusieurs exercices financiers.",
    "DCA prevents emotional decisions during extreme market peaks and crashes, automatically buying more units when prices are low and fewer when prices are high.": "Il élimine le facteur émotionnel, achète plus d'unités lorsque les cours chutent et lisse le prix de revient moyen.",
    "Dividend yield is the annual dividend divided by the current stock price. Yield on cost is the annual dividend divided by your original purchase price, which increases as companies raise their dividends over time.": "Le rendement actuel rapporte le dividende au cours du jour ; le rendement sur coût le rapporte à votre prix d'achat historique, augmentant à chaque hausse de dividende.",
    "Does DCA guarantee profits in cryptocurrency?": "Le DCA garantit-il des gains certains ?",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have progressive tax rates). Local taxes may also apply depending on the specific city or county you work or live in.": "Chaque État fixe ses propres tranches d'impôt sur le revenu (certains, comme le Texas et la Floride, n'en ont aucun, tandis que d'autres appliquent des taux progressifs). Des taxes locales peuvent aussi s'appliquer selon votre ville ou votre comté.",
    "FICA is a federal payroll tax that funds Social Security (6.2% on wages up to the wage base limit) and Medicare (1.45% plus an additional 0.9% on high earners).": "Ce sont les cotisations prélevées sur le salaire pour financer la retraite, l'assurance maladie, le chômage et la prévoyance.",
    "Fees are deducted annually from your total assets, meaning you lose both the fee money and all future compounding returns that money would have earned.": "Prélevés chaque année sur l'encours global, ils vous privent du capital prélevé ainsi que de tous les intérêts composés qu'il aurait générés.",
    "For goals under 3 to 5 years (like a car or home down payment), keep funds in safe, liquid instruments like High-Yield Savings Accounts (HYSA) or CDs. For goals 5+ years away, a diversified investment portfolio may be suitable.": "À moins de 3 à 5 ans (apport, auto), préférez les livrets bancaires sécurisés ; au-delà de 5 ans, un portefeuille diversifié en ETF est adapté.",
    "Gross pay is the total amount earned before any taxes or deductions. Net pay (take-home pay) is the actual cash deposited into your bank account after all deductions.": "Le brut est la rémunération contractuelle avant retenues ; le net est la somme réellement créditée sur votre compte bancaire.",
    "Historically, higher education tuition and fees have increased at an annual rate of 4% to 6%, outpacing general consumer inflation.": "Ils progressent historiquement de 4 % à 6 % par an, dépassant nettement l'inflation générale des prix.",
    "Historically, the broad stock market (S&P 500) has returned an average of 7% to 10% annually before inflation. Investments with higher expected returns generally involve higher risk of capital loss.": "Historiquement, les actions mondiales rapportent en moyenne 7 % à 10 % par an avant inflation ; des rendements plus élevés impliquent des risques proportionnels.",
    "How can I protect my money from losing value to inflation?": "Comment protéger son capital contre l'inflation ?",
    "How can I stay on track with my savings goals?": "Comment respecter son plan d'épargne sur la durée ?",
    "How do I calculate how much to save monthly for a goal?": "Comment calculer l'épargne mensuelle nécessaire pour un projet ?",
    "How do fees compound over time?": "Comment les frais de gestion se répercutent-ils dans le temps ?",
    "How does DCA apply to high-volatility assets like Crypto?": "Pourquoi le DCA est-il adapté aux cryptomonnaies ?",
    "How does a 529 plan impact financial aid eligibility?": "Quel est l'impact sur l'attribution de bourses d'études ?",
    "How does compounding frequency affect total returns?": "Quel est l'effet de la fréquence de capitalisation sur le capital final ?",
    "How does inflation affect my savings?": "Quel est l'impact de l'inflation sur l'épargne ?",
    "How does my W-4 filing status affect my paycheck?": "Quel est l'impact du taux de prélèvement à la source ?",
    "How fast do college costs increase?": "À quel rythme augmentent les frais de scolarité ?",
    "How is Return on Investment (ROI) calculated?": "Comment se calcule le retour sur investissement (ROI) ?",
    "How is inflation officially measured?": "Comment mesure-t-on l'inflation ?",
    "How much can a 1% fee difference affect my retirement savings?": "Quel est l'impact d'un écart de frais de 1 % sur la retraite ?",
    "How often should I calculate my net worth?": "À quelle fréquence faut-il faire son bilan patrimonial ?",
    "In a dedicated High-Yield Savings Account (HYSA) or money market account where it is FDIC-insured, earns interest, and can be accessed immediately without risk.": "Sur des livrets réglementés ou comptes d'épargne liquides et sécurisés, disponibles sans risque de perte en capital.",
    "In an ordinary annuity, payments occur at the end of each period. In an annuity due, payments occur at the beginning of each period, earning an extra compounding cycle of interest.": "La rente ordinaire se verse en fin de période ; la rente d'avance (terme à échoir) en début de période, profitant d'un cycle de capitalisation supplémentaire.",
    "In the United States, inflation has historically averaged between 2.5% and 3.2% per year over long multi-decade horizons.": "Dans les économies développées, elle s'est établie en moyenne historique de long terme entre 2 % et 3 % par an.",
    "Include only non-negotiable living costs: housing (rent/mortgage), utilities, groceries, basic transportation, minimum debt payments, and healthcare insurance.": "Uniquement les charges fixes indispensables : loyer ou mensualité, alimentation de base, énergies, assurances et santé.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks price changes across a standard market basket of consumer goods and services.": "Principalement à travers l'Indice des Prix à la Consommation (IPC), qui suit l'évolution des prix d'un panier représentatif de biens et services ménagers.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a decline in the purchasing power of money.": "La hausse généralisée et continue des prix des biens et services, qui entraîne une perte de pouvoir d'achat de la monnaie.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities, Treasury Inflation-Protected Securities (TIPS), real estate, and inflation-indexed bonds.": "En investissant dans des actifs de croissance dont la performance surpasse la hausse des prix : actions mondiales, obligations indexées et immobilier.",
    "Is DCA better than investing a lump sum?": "Le DCA est-il supérieur à l'investissement en une seule fois ?",
    "Low-cost index funds and ETFs typically have expense ratios between 0.02% and 0.10%, whereas actively managed mutual funds often charge 0.60% to 1.50% or more.": "Les ETF indiciels compétitifs facturent entre 0,05 % et 0,25 % par an, contre 1,5 % à 2,5 % pour les fonds traditionnels gérés activement.",
    "Lump sum investing historically wins in steadily rising markets, but DCA provides superior peace of mind, lower emotional risk, and downside protection in highly volatile markets.": "Dans un marché haussier continu, le versement unique l'emporte ; mais sur des actifs très volatils, le DCA protège du mauvais timing.",
    "Most financial planners recommend saving 3 to 6 months of essential living expenses, or 9 to 12 months for freelancers or single-income households.": "Les conseillers recommandent d'épargner 3 à 6 mois de dépenses courantes incompressibles (jusqu'à 12 mois pour les indépendants).",
    "Net worth is the total market value of everything you own (assets) minus everything you owe to creditors (liabilities).": "C'est la valorisation marchande totale de ce que vous possédez (actifs) diminuée de la totalité de vos dettes (passifs).",
    "No, DCA does not protect against prolonged declines or failing crypto projects; it only ensures you achieve the weighted average market purchase price.": "Non, le DCA ne protège pas de la faillite d'un projet ; il garantit seulement d'obtenir le cours moyen pondéré du marché.",
    "No, company boards can reduce, suspend, or eliminate dividend payouts at any time depending on company profitability and economic conditions.": "Non, le conseil d'administration peut réduire, suspendre ou supprimer les dividendes à tout moment selon les résultats et la conjoncture.",
    "Parent-owned 529 plans are assessed as parental assets on the FAFSA at a maximum rate of 5.64%, having minimal negative impact on financial aid eligibility.": "Détenu par les parents, il n'est comptabilisé qu'à un taux minime (environ 5,64 %), avec un impact négligeable sur les aides.",
    "Pre-tax deductions (like 401k and health insurance) reduce your taxable gross income before taxes are computed. Post-tax deductions (like Roth contributions or wage garnishments) are taken after taxes.": "Les cotisations avant impôt (mutuelle, épargne retraite) minorent le revenu imposable ; les retenues après impôt sont prélevées sur le net fiscal.",
    "ROI is calculated by subtracting the initial cost of the investment from the final value, and dividing that net gain by the initial cost: ROI = (Net Profit / Cost of Investment) × 100%.": "En soustrayant le coût d'achat initial à la valeur finale et en divisant ce profit par le coût initial : ROI = (Gain Net / Coût d'Investissement) × 100 %.",
    "Reviewing your net worth quarterly or semi-annually gives you a clear high-level view of your financial health without obsessing over daily market swings.": "Un pointage trimestriel ou semestriel offre une vision claire et stratégique sans se focaliser sur les fluctuations quotidiennes des marchés.",
    "Should I include my house and mortgage in my net worth?": "Faut-il inclure son logement et son prêt dans le patrimoine net ?",
    "Should I keep savings goal funds in high-yield savings or stocks?": "Faut-il placer son épargne projet sur livret ou en bourse ?",
    "Should I pay off debt or build an emergency fund first?": "Faut-il solder ses dettes ou constituer son matelas d'abord ?",
    "Simple ROI measures total percentage return regardless of duration. Annualized ROI (CAGR) standardizes the return into a per-year geometric rate, enabling fair comparison between investments held for different lengths of time.": "Le ROI simple donne le gain total sur toute la durée ; le ROI annualisé ramène cette performance à un rythme annuel moyen, permettant la comparaison.",
    "Simple return measures absolute percentage gain over the entire holding period, while annualized return shows the steady annual rate required to achieve that result.": "La performance absolue indique le gain total cumulé ; la performance annualisée indique la vitesse de progression annuelle constante correspondante.",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest.": "Ce principe financier fondamental affirme qu'un euro aujourd'hui vaut plus qu'un euro demain, car il peut être immédiatement investi pour produire des intérêts.",
    "The five core variables are Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Total Number of Periods (Nper), and Periodic Payment (PMT).": "La Valeur Actuelle (PV), la Valeur Future (FV), le Taux d'intérêt (Rate), le Nombre de périodes (Nper) et le Paiement régulier (PMT).",
    "The market risk premium is the additional return investors demand for choosing risky market equities over risk-free government securities.": "Le surplus de rentabilité exigé par les investisseurs pour détenir des actions plutôt que des titres d'État souverains sans risque.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your effective annual yield (APY) will be, as interest starts earning interest sooner.": "Plus les intérêts sont crédités fréquemment (mensuellement, quotidiennement), plus le rendement effectif annuel (TAEG/APY) est élevé.",
    "The risk-free rate is the theoretical rate of return of an investment with zero risk of default, typically represented by long-term government bond yields (like 10-year US Treasuries).": "Le rendement garanti d'un placement sans risque de défaut, représenté par les obligations d'État à 10 ans des pays solvables.",
    "Total stock return equals capital gains (ending price minus purchase price) plus any dividends received, divided by the original purchase cost.": "Il est égal à la plus-value latente ou réalisée (cours de vente moins cours d'achat) augmentée des dividendes perçus, rapportée au prix d'achat.",
    "Use it only for genuine, unexpected emergencies: sudden medical bills, unexpected car repairs, or living expenses following job loss.": "Exclusivement pour des imprévus critiques : panne de véhicule indispensable, dépenses de santé urgentes ou perte d'emploi.",
    "Watch out for advisory fees (AUM fees of 1%), front-end or back-end sales loads, trading commissions, account maintenance fees, and custodial charges.": "Les droits d'entrée, les frais d'arbitrage, les commissions de courtage et les frais de tenue de compte du courtier.",
    "Weekly or bi-weekly DCA aligned with your pay cycle is ideal for capturing market volatility while keeping trading fees manageable.": "Une fréquence hebdomadaire ou bimensuelle calée sur vos entrées de salaire optimise le lissage sans multiplier les frais de réseau.",
    "What are the core components of TVM calculations?": "Quelles sont les composantes clés du calcul TVM ?",
    "What counts as an asset vs. a liability?": "Que comprend l'actif et le passif ?",
    "What does it mean to have a negative net worth?": "Que signifie avoir un patrimoine net négatif ?",
    "What expenses should be included in an emergency fund budget?": "Quelles dépenses budgétiser dans l'épargne de précaution ?",
    "What happens to 529 funds if my child does not go to college?": "Que devient l'épargne si l'enfant ne fait pas d'études supérieures ?",
    "What is FICA tax?": "Que sont les cotisations sociales et taxes salariales ?",
    "What is a 529 plan?": "Qu'est-ce qu'un plan d'épargne études (529) ?",
    "What is a Dividend Reinvestment Plan (DRIP)?": "Qu'est-ce qu'un plan de réinvestissement des dividendes (DRIP) ?",
    "What is a good expense ratio for an index fund?": "Quel est le bon niveau de frais pour un ETF ?",
    "What is considered a good ROI?": "Qu'est-ce qu'un bon rendement financier ?",
    "What is dividend yield versus yield on cost?": "Quelle différence entre rendement actuel et rendement sur coût d'achat ?",
    "What is the Market Risk Premium?": "Qu'est-ce que la prime de risque de marché ?",
    "What is the Risk-Free Rate?": "Qu'est-ce que le taux sans risque ?",
    "What is the Time Value of Money (TVM)?": "Qu'est-ce que la valeur temps de l'argent (TVM) ?",
    "What is the best frequency for crypto DCA?": "Quelle est la fréquence optimale pour un DCA crypto ?",
    "What is the difference between an ordinary annuity and annuity due?": "Quelle est la différence entre rente ordinaire et rente à terme échu ?",
    "What is the difference between gross pay and net pay?": "Quelle est la différence entre salaire brut et salaire net ?",
    "What is the difference between pre-tax and post-tax deductions?": "Quelle est la différence entre déductions avant et après impôt ?",
    "What is the difference between simple ROI and annualized ROI?": "Quelle est la différence entre ROI simple et ROI annualisé (TCAC) ?",
    "What is the difference between simple return and annualized return?": "Quelle est la différence entre performance absolue et annualisée ?",
    "What is the historical average inflation rate?": "Quelle est la moyenne historique de l'inflation ?",
    "What other investment fees should I look out for?": "Quels autres frais de placement surveiller ?",
    "When is it appropriate to use emergency fund savings?": "Quand est-il légitime de piocher dans le fonds d'urgence ?",
    "Where should I keep my emergency fund?": "Où placer son épargne de précaution ?",
    "Why do state and local taxes vary so much?": "Pourquoi les fiscalités locales varient-elles autant ?",
    "Yes, qualified distributions can cover accredited trade schools, vocational programs, apprenticeships, and up to $10,000 per year for K-12 private school tuition.": "Oui, les apprentissages certifiés, écoles de métiers et jusqu'à 10 000 $ par an pour l'enseignement privé secondaire sont éligibles.",
    "Yes, you include the current fair market value of the home under assets and the remaining mortgage balance under liabilities. The difference is your home equity.": "Oui, on inscrit la valeur vénale de la maison à l'actif et le capital restant dû au passif ; la différence est votre valeur nette immobilière.",
    "You can change the beneficiary to another qualifying family member, use up to $10,000 for student loan repayment, or roll over up to $35,000 into a Roth IRA under SECURE 2.0 rules.": "Vous pouvez désigner un autre bénéficiaire au sein de la fratrie ou transférer jusqu'à 35 000 $ vers un compte de retraite individuel.",
    "You divide your target savings amount by the number of months until your deadline, while factoring in the compounding interest earned on your growing balance.": "Divisez le montant cible par le nombre de mois restants, en déduisant les intérêts composés générés par votre capital au fil de l'eau.",
    "Your W-4 form informs your employer how much federal income tax to withhold each pay period based on your filing status, dependents, and other income.": "Il détermine le montant d'impôt sur le revenu retenu chaque mois par l'employeur selon votre situation familiale et vos revenus annexes.",
    "A 0% APR balance transfer credit card can save significant interest if you pay off the full balance during the promotional period (typically 12-21 months) and factor in the 3%-5% transfer fee.": "Une offre promotionnelle à 0 % est très efficace pour effacer la dette si vous remboursez tout pendant la période d'exonération, frais de transfert inclus.",
    "A common benchmark is accumulating 25 times your anticipated annual retirement expenses, or replacing 70% to 80% of your pre-retirement income.": "La référence financière courante est de posséder 25 fois ses dépenses annuelles estimées, ou de garantir 70 % à 80 % de son dernier revenu d'activité.",
    "A larger down payment reduces your loan amount, eliminates Private Mortgage Insurance (PMI) if you put down 20%, and lowers your monthly mortgage payment.": "Un apport solide réduit le montant à emprunter, supprime les surcoûts d'assurance et permet de négocier les meilleurs taux bancaires.",
    "APR is higher because it amortizes all upfront lender fees, discount points, and closing costs into the effective yearly rate, revealing the true cost of credit.": "Parce qu'il convertit tous les frais annexes en un taux annuel équivalent, révélant le véritable coût global du financement.",
    "An employer match is money your employer contributes to your 401(k) account based on your own contributions (e.g. matching 50% of contributions up to 6% of your salary). It is effectively an instant return on your savings.": "C'est une contribution financière versée par l'entreprise en complément de votre propre épargne salariale (PERCO, PEE), constituant un gain immédiat à 100 %.",
    "Because upfront closing costs, moving fees, and commissions are substantial, homeowners usually need to stay in a property for 4 to 7 years for buying to financially outperform renting.": "En raison des frais de notaire et des droits de mutation, il faut généralement conserver le bien entre 4 et 7 ans pour que l'achat surpasse la location.",
    "Calculate the total bill including food, beverages, tax, and tip, and divide the total amount equally by the number of paying participants.": "Additionnez le montant global comprenant plats, boissons, taxes et pourboire, puis divisez équitablement par le nombre de personnes.",
    "Credit card minimum payments are often set around 1% to 2% of the balance plus accrued interest. As the balance slowly drops, the required minimum drops, extending payoff times to decades.": "Le paiement minimum couvre à peine les intérêts et 1 à 2 % du capital. La mensualité diminuant avec le solde, l'amortissement s'étire sur des décennies.",
    "Etiquette traditionally dictates calculating the tip percentage on the pre-tax food and beverage subtotal, though many automated payment terminals calculate tip on the post-tax total.": "La tradition veut qu'on le calcule sur le montant hors taxe des consommations, bien que les terminaux électroniques l'appliquent souvent sur le TTC.",
    "Every 1% increase in mortgage interest rates reduces your home purchasing power by roughly 10% for the same monthly payment budget.": "Chaque point de pourcentage (+1 %) de taux d'intérêt supplémentaire ampute votre capacité d'emprunt d'environ 10 % à mensualité égale.",
    "For 2024, the employee contribution limit is $23,000 for those under 50. Individuals aged 50 and older can contribute an additional $7,500 catch-up contribution for a total of $30,500.": "Le plafond légal est fixé à 23 000 $ pour les moins de 50 ans, avec une majoration de 7 500 $ pour les salariés de 50 ans et plus.",
    "Homeowners must pay property taxes, homeowners insurance, maintenance and repairs (typically 1-2% of home value annually), HOA dues, and potential capital improvement costs.": "La taxe foncière, les charges de copropriété, l'entretien courant (1 à 2 % de la valeur du bien par an) et les gros travaux de rénovation.",
    "How do interest rates affect purchasing power?": "Comment la hausse des taux affecte-t-elle le pouvoir d'achat immobilier ?",
    "How do multiple stacked discounts work?": "Comment s'appliquent les remises successives cumulées ?",
    "How do you calculate a percentage discount?": "Comment calculer une réduction commerciale en pourcentage ?",
    "How do you split a bill evenly among friends?": "Comment partager équitablement l'addition entre convives ?",
    "How does down payment size impact affordability?": "Quel est l'impact de l'apport personnel sur le budget d'achat ?",
    "How does inflation impact retirement spending?": "Comment l'inflation affecte-t-elle le pouvoir d'achat des retraités ?",
    "How does vehicle depreciation affect my loan?": "Quel est le risque lié à la décote automobile ?",
    "How long do I need to stay in a home for buying to beat renting?": "Combien d'années faut-il occuper un logement pour amortir l'achat ?",
    "How much faster can I pay off credit cards by paying extra?": "À quel point des versements volontaires accélèrent-ils le désendettement ?",
    "How much income should I spend on a mortgage?": "Quelle part de mon salaire puis-je consacrer à un prêt immobilier ?",
    "How much money do I need to retire comfortably?": "De quel capital a-t-on besoin pour une retraite sereine ?",
    "In most jurisdictions, sales tax is calculated on the discounted post-sale price, meaning you pay sales tax only on the actual money spent.": "La taxe est calculée sur le prix net remisé : vous ne payez la TVA que sur la somme réellement dépensée.",
    "In the United States and Canada, standard restaurant tipping guidelines range from 15% for adequate service, 18% for good service, to 20% or more for exceptional service.": "En Amérique du Nord, la norme va de 15 % à 20 % ; en Europe où le service est inclus, laisser 5 % à 10 % en espèces récompense un service soigné.",
    "Inflation steadily reduces the purchasing power of your savings. At a 3% inflation rate, everyday living expenses double roughly every 24 years, requiring growing investment portfolios.": "Avec 3 % d'inflation, le coût de la vie double en 24 ans : une partie de l'épargne retraite doit obligatoirement être investie sur des actifs de rendement.",
    "Is APR useful for comparing different loan offers?": "Le TAEG est-il l'indicateur le plus pertinent pour comparer ?",
    "Is a longer auto loan term better?": "Est-il avantageux d'allonger la durée d'un crédit auto ?",
    "Is sales tax applied before or after store discounts?": "La TVA s'applique-t-elle avant ou après remise ?",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk becoming 'underwater' (owing more than the vehicle is worth).": "Une durée longue abaisse la mensualité mais fait exploser les intérêts, avec le risque d'avoir un véhicule qui décote plus vite que le capital remboursé.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline).": "La règle générale recommande de limiter la mensualité de prêt entre 25 % et 33 % de vos revenus nets mensuels.",
    "Multiply the original price by the discount percentage divided by 100 to find the savings, and subtract that amount from the original price: Final Price = Original Price × (1 - Discount%).": "Multipliez le prix initial par le pourcentage de remise divisé par 100 pour trouver l'économie, puis déduisez-la : Prix Final = Prix Initial × (1 - Remise%).",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, you risk owing more on your loan than the car's market value.": "Un véhicule neuf perd environ 20 % de sa valeur dès la première année ; sans apport, votre dette dépassera la valeur réelle du véhicule.",
    "Paying even $50 or $100 above the minimum payment can cut your payoff timeline by several years and save thousands of dollars in compounding interest charges.": "Ajouter ne serait-ce que 50 € ou 100 € par mois permet de solder le compte plusieurs années plus tôt et d'économiser une fortune en agios.",
    "Should I use a balance transfer card to pay off debt?": "Faut-il recourir au rachat de crédit ou à une carte 0 % ?",
    "Should tips be calculated before or after sales tax?": "Le pourboire se calcule-t-il sur le montant hors taxe ou TTC ?",
    "Stacked discounts apply sequentially rather than additively. For example, 20% off plus an extra 10% off results in an effective 28% total discount, not 30%.": "Elles se calculent en cascade et non par simple addition : 20 % puis 10 % supplémentaires équivalent à 28 % de remise totale réelle (et non 30 %).",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total vehicle expenses under 10% of gross monthly income.": "Apporter au moins 20 %, emprunter sur 4 ans maximum (48 mois) et plafonner l'ensemble des dépenses automobiles à 10 % de ses revenus bruts.",
    "The money spent on down payment, closing costs, and ongoing property maintenance could otherwise remain invested in liquid assets like index funds that compound over time.": "L'apport personnel et les frais annexes mobilisés ne profitent plus du rendement composé des marchés boursiers (actions, ETF).",
    "Traditional 401(k) contributions are pre-tax and reduce your current taxable income, with withdrawals taxed in retirement. Roth 401(k) contributions are post-tax, but all qualified growth and withdrawals are completely tax-free.": "Le modèle traditionnel permet de déduire les versements de ses impôts actuels et taxe les retraits à la retraite ; le Roth investit du net et exonère totalement les gains futurs.",
    "What are the 401(k) contribution limits for 2024?": "Quels sont les plafonds de versement ?",
    "What hidden costs of homeownership should renters consider?": "Quels coûts cachés un locataire doit-il anticiper avant d'acheter ?",
    "What is an employer 401(k) match?": "Qu'est-ce que l'abondement de l'employeur ?",
    "What is the 20/4/10 rule for buying a car?": "Qu'est-ce que la règle 20/4/10 pour financer une voiture ?",
    "What is the difference between Traditional 401(k) and Roth 401(k)?": "Quelle est la différence entre plan classique et plan Roth ?",
    "What is the opportunity cost of buying a home?": "Quel est le coût d'opportunité de l'achat immobilier ?",
    "What is the standard tipping percentage?": "Quel est le pourcentage d'usage pour un pourboire ?",
    "Why does paying only the minimum take so long?": "Pourquoi ne rembourser que le minimum prend-il autant d'années ?",
    "Why is APR higher than the advertised interest rate?": "Pourquoi le TAEG est-il supérieur au taux débiteur affiché ?",
    "Yes, APR is the best metric for comparing loan offers with different fee structures, provided you plan to keep the loan for its full term.": "Oui, c'est l'étalon officiel qui permet de comparer équitablement des offres aux structures de frais et d'assurance différentes.",
    "How does an amortized loan work?": "Comment fonctionne un prêt amortissable classique ?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest. Over time, an increasing portion goes toward paying down the principal balance until the debt is fully paid off.": "Vous versez des échéances constantes. Au début, la part d'intérêts prédomine ; avec le temps, la part de capital remboursé augmente jusqu'à extinction de la dette.",
    "What is the difference between fixed-rate and variable-rate loans?": "Quelle est la différence entre un taux fixe et un taux variable ?",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the loan term. A variable-rate loan has an interest rate that adjusts periodically based on benchmark interest rates, which can increase or decrease your payments.": "Le taux fixe garantit un taux et des mensualités inchangés jusqu'au terme ; le taux variable s'ajuste périodiquement selon les indices de référence du marché.",
    "What is the difference between interest rate and APR?": "Quelle est la différence entre le taux nominal et le TAEG / APR ?",
    "The interest rate is the nominal cost of borrowing the principal balance. The Annual Percentage Rate (APR) reflects the total annual cost of the loan including points, broker fees, and origination charges.": "Le taux nominal correspond aux seuls intérêts du capital ; le TAEG (APR) intègre l'ensemble des frais obligatoires : assurance, dossier, garanties et courtage.",
    "What is the 4% rule in retirement planning?": "Qu'est-ce que la règle des 4 % pour la retraite ?",
    "The 4% rule suggests that withdrawing 4% of your retirement portfolio in the first year, adjusted for inflation annually thereafter, provides a high probability that your nest egg will last at least 30 years.": "Elle indique que retirer 4 % de son capital la première année, puis indexer ce montant sur l'inflation, offre une quasi-certitude de préserver ses fonds sur 30 ans.",
    "What is compound interest?": "Qu'est-ce que les intérêts composés ?",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It causes your wealth to grow exponentially over time.": "C'est la rémunération calculée à la fois sur le capital initial et sur les intérêts accumulés au fil des périodes, entraînant une croissance exponentielle.",
    "What is the Rule of 72?": "Qu'est-ce que la règle de 72 ?",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your annual interest rate (e.g. at 8%, your money doubles in about 9 years).": "Une méthode de calcul mental pour estimer le temps nécessaire pour doubler son capital : divisez 72 par le taux de rendement (ex. à 8 %, doublement en 9 ans).",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price.": "Une méthode consistant à investir une somme fixe à intervalles réguliers, indépendamment des variations de cours du marché.",
    "Can I pay off my loan early without penalty?": "Puis-je rembourser mon crédit par anticipation sans frais ?",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, but some lenders include a prepayment penalty clause. Always verify your loan agreement terms before making accelerated principal payments.": "Les crédits à la consommation permettent souvent le remboursement sans pénalités, mais les prêts immobiliers peuvent comporter des indemnités de remboursement anticipé (IRA).",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility.": "Sur 15 ans, le taux d'intérêt est plus bas et le coût total du crédit est nettement réduit ; sur 30 ans, les mensualités sont allégées, préservant votre trésorerie.",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule.": "Tout remboursement supplémentaire vient amortir le capital restant dû, ce qui réduit les intérêts futurs et permet de solder le crédit plusieurs années à l'avance.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum helps people stick to their plan.": "Mathématiquement, l'avalanche est optimale ; dans la réalité, la boule de neige rencontre un taux de réussite souvent plus élevé grâce au renforcement positif rapide.",
    "You continue paying minimums on all debts and add your extra cash to the target debt. Once that target debt is fully paid off, you roll its entire payment into the next debt on your list.": "Vous payez le minimum sur chaque ligne et concentrez votre surplus sur la dette cible ; une fois celle-ci liquidée, vous basculez l'intégralité du budget sur la suivante.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate (Avalanche).": "Oui. Vous pouvez éteindre une ou deux petites dettes pour libérer de la trésorerie (boule de neige), puis attaquer les dettes restantes par ordre de taux d'intérêt (avalanche).",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term, provided your total interest savings exceed the closing costs.": "L'opération est rentable si l'écart de taux permet de réduire la mensualité ou la durée, et que le gain sur les intérêts compense largement les frais de dossier et d'avenant.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees, ranging from 2% to 6% of the loan amount.": "Ils comprennent les indemnités de remboursement anticipé, les frais de dossier de la nouvelle banque et les frais de garantie ou de mainlevée d'hypothèque.",
    "Divide your total refinance closing costs by your monthly payment savings. If closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150).": "Divisez le total des frais engagés par l'économie mensuelle réalisée : 3 000 € de frais / 150 € d'économie = 20 mois pour rentabiliser l'opération.",
    "A no-closing-cost refinance means the lender either rolls the closing fees into your new total loan balance or charges a slightly higher interest rate to cover them.": "Les frais ne disparaissent pas : ils sont soit intégrés au capital emprunté, soit compensés par un taux d'intérêt légèrement supérieur.",
    "It depends on the term. Refinancing to a lower rate with the same or shorter term saves on both. Resetting your term back to 30 years lowers the monthly payment but can increase total lifetime interest.": "À durée égale ou raccourcie, vous gagnez sur les deux tableaux ; rallonger la durée réduit la mensualité mais peut augmenter le coût global des intérêts.",
    "The Saving on a Valuable Education (SAVE) plan is an income-driven repayment (IDR) plan that protects discretionary income up to 225% of the poverty line, lowers payments to 5%-10%, and stops unpaid interest from accumulating.": "Un plan américain indexé sur les revenus qui protège 225 % du seuil de pauvreté, réduit les mensualités et empêche l'accumulation d'intérêts impayés.",
    "If you pay under an IDR plan for 20 or 25 years (or 10 years under SAVE for low initial balances), any remaining student debt is forgiven.": "Après 20 à 25 ans d'échéances régulières indexées sur les revenus, le reliquat de dette fait l'objet d'une remise totale.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. Borrowers with very high incomes relative to debt may prefer PAYE or IBR due to payment caps.": "Le plan SAVE offre la mensualité la plus basse à la majorité des emprunteurs ; ceux aux revenus très élevés préfèrent souvent PAYE ou IBR avec plafonnement.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause unpaid interest to capitalize.": "Oui, le changement est gratuit, mais il peut dans certains cas entraîner la capitalisation des intérêts en attente.",
    "The 28/36 rule is a standard mortgage underwriting guideline stating that housing costs should not exceed 28% of gross monthly income, and total debt payments should not exceed 36%.": "Elle préconise de ne pas consacrer plus de 28 % de ses revenus bruts au logement, et pas plus de 36 % au remboursement de l'ensemble de ses crédits.",
    "Lenders use DTI to measure your ability to manage monthly payments. Lower DTIs below 36% receive the most favorable mortgage terms and lowest interest rates.": "Les banques l'analysent pour mesurer votre capacité de remboursement. Un taux inférieur à 35 % est la norme requise pour obtenir les meilleures conditions.",
    "Front-end DTI only includes housing expenses (mortgage, property tax, insurance, HOA). Back-end DTI includes housing plus all recurring debts like credit cards, auto loans, and student loans.": "Le premier ne prend en compte que la charge de logement ; le second additionne l'ensemble des crédits en cours (consommation, automobile, revolving).",
    "Conventional mortgages typically prefer back-end DTIs of 36% to 43%. Government-backed loans like FHA and VA may allow DTIs up to 50% with strong compensating factors.": "En France et en Europe, la règle prudentielle limite généralement le taux à 35 % assurance comprise (jusqu'à 43 % ou 50 % aux USA selon garanties).",
    "You can lower your DTI by increasing gross income or paying off smaller debts completely to eliminate their recurring monthly minimum payments.": "En augmentant ses revenus réguliers ou en remboursant par anticipation les petits crédits à la consommation pour supprimer leurs mensualités.",
    "If you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower, a Traditional IRA is better.": "Si votre tranche marginale d'imposition sera plus haute à la retraite, choisissez le Roth ; si vos revenus baisseront à la retraite, privilégiez le traditionnel.",
    "For 2024, the annual contribution limit for Traditional and Roth IRAs is $7,000 for individuals under age 50, and $8,000 for individuals age 50 or older.": "Le plafond annuel est de 7 000 $ (8 000 $ pour les 50 ans et plus).",
    "Roth IRAs have income phase-out ranges that restrict high earners. Anyone with earned income can contribute to a Traditional IRA, but tax deductibility may be limited by income and workplace retirement coverage.": "Le Roth IRA comporte des plafonds d'éligibilité pour les hauts revenus ; l'IRA traditionnel est ouvert à tous mais la déductibilité peut être plafonnée.",
    "Roth IRA original contributions can be withdrawn at any time penalty-free. Withdrawing investment earnings early or withdrawing Traditional IRA funds before 59½ usually incurs income taxes and a 10% penalty.": "Les versements initiaux d'un Roth peuvent être retirés sans pénalité ; les gains et les retraits d'IRA classique avant 59 ans et demi subissent l'impôt et 10 % de pénalité.",
    "State income tax rates range from 0% (in states like Texas, Florida, and Washington) to over 13% in high-tax states, while some cities also impose local municipal income taxes.": "Chaque collectivité ou État dispose de ses propres barèmes d'imposition sur le revenu et taxes d'habitation locales.",
  },
  pt: {
    "Front-end DTI only includes housing expenses (mortgage principal, interest, taxes, and insurance). Back-end DTI includes housing expenses plus all other recurring debts like student loans, auto loans, and minimum credit card payments.": "O DTI front-end (habitacional) inclui apenas despesas de moradia (amortização, juros da hipoteca, impostos e seguros). O DTI back-end (total) engloba os gastos com moradia mais todas as outras dívidas recorrentes, como financiamento estudantil, parcelas do carro e pagamento mínimo do cartão de crédito.",
    "You can lower your DTI by paying down outstanding credit card balances, paying off small personal loans, refinancing to lower rates, or increasing your gross monthly income (e.g. through a side business, raise, or adding a co-borrower).": "Você pode reduzir seu DTI amortizando saldos devedores de cartão de crédito, quitando pequenos empréstimos pessoais, refinanciando com taxas mais baixas ou aumentando sua renda bruta mensal (por exemplo, obtendo um aumento salarial, iniciando uma atividade extra ou incluindo um coobrigado/cônjuge no financiamento).",
    "By combining multiple high-interest credit card balances or personal loans into a single personal loan with a lower interest rate, you reduce the total amount of interest that accumulates each month. This lets more of your monthly payment go directly towards the principal balance.": "Ao unificar múltiplos saldos caros de cartão de crédito ou empréstimos pessoais em uma única linha de crédito com taxa de juros inferior, você reduz o volume de juros acumulados a cada mês. Isso permite que uma parcela maior do seu pagamento mensal seja direcionada para amortizar o saldo principal.",
    "Watch out for upfront origination fees, prepayment penalties, and ensure the new loan term isn't stretched so far out that you pay more total interest despite a lower monthly payment. Most importantly, avoid running up new balances on the cleared credit cards.": "Fique atento a tarifas iniciais de abertura de crédito, eventuais taxas de liquidação antecipada e certifique-se de que o novo prazo não seja excessivamente longo a ponto de gerar mais juros totais, mesmo com parcelas menores. Sobretudo, evite contrair novas dívidas nos cartões de crédito recém-quitados.",
    "The earliest age you can claim Social Security retirement benefits is 62. However, claiming early results in a permanent reduction of up to 30% of your monthly benefit compared to waiting until full retirement age.": "A idade mínima para solicitar a aposentadoria por idade é 62 anos. No entanto, a antecipação acarreta uma redução definitiva de até 30% no valor do benefício mensal em comparação com a espera até a idade plena de aposentadoria.",
    "For every year you delay claiming Social Security past your Full Retirement Age (up to age 70), your benefit increases by 8% per year in delayed retirement credits (up to a 24% permanent boost at age 70).": "Para cada ano em que você posterga a solicitação da aposentadoria além da sua Idade Plena (até os 70 anos), seu benefício recebe um bônus adicional de 8% ao ano (totalizando um acréscimo permanente de até 24% aos 70 anos).",
    "What is the Social Security break-even age between claiming early vs delaying?": "Qual é a idade de equilíbrio entre solicitar a aposentadoria antecipada ou adiar o benefício?",
    "The break-even age between claiming early at age 62 versus waiting until age 70 is typically around age 80 to 82. If you expect to live past this age, waiting until 70 produces significantly more lifetime wealth.": "A idade de equilíbrio entre se aposentar antecipadamente aos 62 anos ou aguardar até os 70 anos situa-se normalmente entre 80 e 82 anos de idade. Se a sua expectativa de vida superar esse patamar, esperar até os 70 anos proporciona um patrimônio acumulado consideravelmente maior ao longo da vida.",
    "Under Australian law, employers are required to contribute a statutory percentage of your ordinary time earnings into your superannuation fund. The rate is legislated to increase progressively to 12%.": "Pela legislação australiana, os empregadores são obrigados a recolher um percentual compulsório sobre a remuneração normal do trabalhador para o fundo de aposentadoria (Superannuation). A alíquota está estipulada em lei para alcançar progressivamente 12%.",
    "FIRE stands for Financial Independence, Retire Early. It is a financial movement dedicated to extreme savings and intentional investing, allowing people to retire decades before conventional retirement ages.": "FIRE é a sigla em inglês para Independência Financeira e Aposentadoria Precoce (Financial Independence, Retire Early). Trata-se de um movimento financeiro focado em alta taxa de poupança e investimentos estratégicos, possibilitando que pessoas se aposentem décadas antes da idade convencional.",
    "The 4% Rule, established by the Trinity Study, states that you can safely withdraw 4% of your invested portfolio in the first year of retirement, adjust that dollar amount for inflation every year thereafter, and have a 95%+ probability of your money lasting 30+ years.": "A Regra dos 4%, fundamentada pelo consagrado Estudo de Trinity, determina que você pode resgatar com segurança 4% da sua carteira investida no primeiro ano de aposentadoria, reajustando esse montante pela inflação a cada ano subsequente, mantendo mais de 95% de probabilidade de que os recursos durem por 30 anos ou mais.",
    "Your FIRE Number is calculated by multiplying your estimated annual living expenses by 25 (the inverse of the 4% rule): Annual Expenses × 25 = FIRE Goal.": "O seu Número FIRE é calculado multiplicando suas despesas anuais de custo de vida estimadas por 25 (o inverso da regra dos 4%): Despesas Anuais × 25 = Meta de Patrimônio FIRE.",
    "Lean FIRE targets a minimalist lifestyle with expenses below average (usually under $40,000/year). Standard FIRE covers typical baseline middle-class expenses ($40,000–$80,000/year). Fat FIRE supports an affluent lifestyle with abundant travel and luxury ($100,000+/year).": "O Lean FIRE tem como meta um estilo de vida minimalista com despesas abaixo da média (geralmente abaixo de R$ 100 mil a R$ 150 mil anuais / US$ 40 mil). O Standard FIRE cobre um padrão confortável de classe média. Já o Fat FIRE sustenta um estilo de vida mais abastado, com viagens frequentes e maior margem para supérfluos.",
    "Daily compound interest calculates interest on both your initial principal and previously accumulated interest each day. Over time, interest begins earning interest rapidly, creating an exponential curve that grows significantly faster than simple or monthly compounding.": "Os juros compostos diários calculam o rendimento a cada dia tanto sobre o principal inicial quanto sobre os juros acumulados anteriormente. Com o passar do tempo, os juros geram novos juros de forma acelerada, formando uma curva exponencial que supera com folga a capitalização simples ou mensal.",
    "The standard daily compounding formula is A = P(1 + r/365)^(365*t), where A is the final balance, P is initial principal, r is annual interest rate (decimal), and t is time in years.": "A fórmula padrão da capitalização diária é M = C(1 + i/365)^(365*t), onde M é o montante final, C é o capital inicial, i é a taxa de juros anual (em formato decimal) e t é o tempo em anos.",
    "On a $100,000 deposit at 5% APY over 20 years, daily compounding yields roughly $300 to $500 more than monthly compounding due to faster compounding reinvestment.": "Em uma aplicação de R$ 100.000 / US$ 100.000 a 5% ao ano por 20 anos, a capitalização diária rende cerca de R$ 300 a R$ 500 a mais do que a capitalização mensal em virtude do reinvestimento mais imediato dos juros.",
    "Yes! Most modern high-yield savings accounts and money market accounts compound interest daily and credit the earnings into your account on a monthly basis.": "Sim! A maioria das contas remuneradas modernas, fundos de liquidez diária e CDBs/contas de alto rendimento calcula juros compostos diariamente e credita os proventos na conta mensalmente.",
    "What is an HP 12C financial calculator and why is it used?": "O que é a calculadora financeira HP 12C e por que ela é tão utilizada?",
    "The HP 12C is the gold standard programmable financial calculator created by Hewlett-Packard in 1981. It is renowned for its durability, Reverse Polish Notation (RPN) efficiency, and is one of the few calculators permitted on the CFA, CFP, and Real Estate appraiser certification examinations.": "A HP 12C é o padrão ouro entre as calculadoras financeiras programáveis, lançada pela Hewlett-Packard em 1981. É reconhecida por sua extrema durabilidade, rapidez com Notação Polonesa Reversa (RPN) e é uma das raras calculadoras autorizadas nos exames oficiais de certificação CFA, CFP e perícia imobiliária.",
    "How does Reverse Polish Notation (RPN) work on the HP 12C?": "Como funciona a Notação Polonesa Reversa (RPN) na HP 12C?",
    "RPN eliminates the need for parentheses and an equals key. You enter numbers first onto a 4-level stack (X, Y, Z, T), and then press the operator. For example, to add 25 and 15, you press [2][5] [ENTER] [1][5] [+], giving 40 immediately.": "O sistema RPN elimina a necessidade de parênteses e da tecla de igual. Você insere primeiro os números em uma pilha operacional de 4 níveis (X, Y, Z, T) e depois pressiona o operador desejado. Por exemplo, para somar 25 e 15, você digita [2][5] [ENTER] [1][5] [+], obtendo 40 instantaneamente.",
    "How do I calculate Time Value of Money (TVM) on this emulator?": "Como calculo o Valor do Dinheiro no Tempo (TVM) neste emulador?",
    "Store your known values into the TVM registers (n for periods, i for interest rate, PV for present value, PMT for payment, FV for future value). Press the key of the unknown variable to solve for it. Remember financial sign conventions: cash outflows are entered with CHS (negative).": "Armazene os valores conhecidos nos registradores de TVM (n para prazos, i para taxa de juros, PV para valor presente, PMT para parcelas, FV para valor futuro). Pressione a tecla da variável que deseja descobrir. Lembre-se da convenção de sinais financeiros: saídas de caixa devem ser inseridas com sinal negativo usando a tecla CHS.",
    "Can I use my physical computer keyboard with this emulator?": "Posso usar o teclado físico do meu computador com este emulador?",
    "Yes! Use your computer numpad or number keys for digits 0-9, Enter for the ENTER stack key, standard arithmetic keys (+, -, *, /), and Backspace to clear the entry.": "Sim! Utilize o teclado numérico ou as teclas de 0 a 9 do teclado, a tecla Enter para a função ENTER da pilha, as operações aritméticas normais (+, -, *, /) e o Backspace para apagar a digitação.",
    "Is the TI BA II Plus permitted on CFA and CFP exams?": "A calculadora TI BA II Plus é permitida nos exames CFA e CFP?",
    "Yes! The Texas Instruments BA II Plus (including the Professional model) is one of only two official calculators authorized by the CFA Institute, GARP (FRM), and CFP Board for in-person certification examinations.": "Sim! A Texas Instruments BA II Plus (incluindo o modelo Professional) é uma das duas únicas calculadoras oficiais homologadas pelo CFA Institute, GARP (FRM) e CFP Board para exames presenciais de certificação.",
    "How do I solve for a TVM variable (like PV or PMT) on the TI BA II Plus?": "Como calculo uma variável de TVM (como PV ou PMT) na TI BA II Plus?",
    "Enter your known values by typing the number followed by the variable key (e.g., [1][0] [N], [8] [I/Y], [5][0][0] [CHS] [PMT]). To calculate the unknown value, press [CPT] followed by the variable key (e.g., [CPT] [PV]).": "Insira seus valores conhecidos digitando o número seguido da tecla da respectiva variável (ex: [1][0] [N], [8] [I/Y], [5][0][0] [CHS] [PMT]). Para calcular a incógnita, pressione [CPT] seguido da tecla da variável desejada (ex: [CPT] [PV]).",
    "What is the difference between BGN and END mode?": "Qual é a diferença entre o modo BGN e o modo END?",
    "END mode assumes cash flows occur at the end of each payment period (standard loans, ordinary annuities). BGN mode assumes payments occur at the beginning of each period (annuities due, lease payments).": "O modo END assume que as parcelas e fluxos ocorrem ao final de cada período (financiamentos tradicionais e anuidades postecipadas). O modo BGN assume pagamentos no início de cada período (anuidades antecipadas, aluguéis e contratos de leasing).",
    "Why does my answer have a negative sign?": "Por que o resultado do meu cálculo aparece com sinal negativo?",
    "Financial calculators strictly enforce cash flow conventions. Money paid out (outflow/deposit/investment) is negative; money received (inflow/loan proceeds/future payout) is positive.": "As calculadoras financeiras aplicam com rigor a convenção de fluxo de caixa. O dinheiro desembolsado (saída, aporte, investimento ou pagamento de parcela) é registrado como negativo; o dinheiro recebido (entrada, liberação do empréstimo ou resgate futuro) é registrado como positivo.",
    "How is a mortgage payment calculated?": "Como é calculada a prestação do financiamento imobiliário?",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees.": "A parcela mensal é composta por amortização e juros, seguros obrigatórios (MIP e DFI), taxas administrativas e condomínio.",
    "What is the Debt Snowball method?": "O que é o método Bola de Neve para quitar dívidas?",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates. It builds psychological momentum and motivation through quick wins.": "Consiste em pagar primeiro as dívidas de menor valor, independentemente da taxa de juros, gerando motivação psicológica através de vitórias rápidas.",
    "What is the Debt Avalanche method?": "O que é o método Avalanche para quitar dívidas?",
    "The Debt Avalanche method involves paying off your highest interest rate debts first. Mathematically, this minimizes the total interest you pay and helps you become debt-free faster.": "Prioriza o pagamento das dívidas com os maiores juros primeiro. Matematicamente, minimiza o total pago em juros e acelera a quitação.",
    "What is net worth?": "O que é o patrimônio líquido pessoal?",
    "Net worth is the total value of everything you own (assets) minus everything you owe (liabilities). It is a key metric used to measure your overall financial health.": "É o valor total de todos os seus bens e investimentos (ativos) menos todas as suas dívidas e obrigações (passivos).",
    "How much emergency fund is recommended?": "De quanto deve ser a reserva de emergência?",
    "Most financial advisors recommend saving 3 to 6 months of essential living expenses. If your income is highly volatile (e.g. freelancing) or you have dependents, targeting 9 to 12 months is safer.": "Recomenda-se guardar entre 3 e 6 meses de despesas básicas em aplicações de liquidez diária e baixo risco.",
    "What is Dollar-Cost Averaging (DCA)?": "O que é Dollar-Cost Averaging (DCA / Aporte Regular)?",
    "Dollar-Cost Averaging is the practice of investing a fixed dollar amount on a regular basis (e.g. weekly or monthly) regardless of the asset's price. This smooths out short-term price volatility and removes emotional timing decisions.": "É a aplicação periódica de quantias fixas (mensais), diluindo o preço médio de compra e reduzindo o risco de oscilações.",
    "What is inflation?": "O que é a inflação?",
    "Inflation is the general increase in prices and fall in the purchasing value of money over time. It means your money buys fewer goods and services in the future than it does today.": "É o aumento generalizado e contínuo dos preços, que resulta na perda do poder de compra da moeda.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility and makes the home more affordable on a month-to-month basis.": "Um financiamento de 15 anos costuma ter juros menores e permite quitar o imóvel na metade do tempo, economizando dezenas de milhares de reais em juros. Já o de 30 anos tem parcelas menores, o que dá mais folga no orçamento mensal.",
    "According to the ASFA Retirement Standard, a single person needs a superannuation balance of approximately $595,000 at age 67, while a couple needs approximately $690,000 to sustain a comfortable retirement lifestyle.": "Segundo o padrão de aposentadoria da ASFA, uma pessoa solteira precisa de um saldo de aproximadamente R$ 595.000 aos 67 anos, enquanto um casal precisa de cerca de R$ 690.000 para manter um padrão de vida confortável na aposentadoria.",
    "An expense ratio is the annual fee charged by a mutual fund or ETF to manage the fund. It is expressed as a percentage of your total investment (e.g. 0.10% means $1 per year for every $1,000 invested).": "A taxa de administração é a tarifa anual cobrada por um fundo de investimento ou ETF para gerir o fundo. Ela é expressa como um percentual do seu investimento total (por exemplo, 0,10% significa R$ 1 por ano para cada R$ 1.000 investidos).",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule and saving you a substantial amount in interest fees.": "Todo valor extra amortiza diretamente o saldo devedor, reduzindo os juros futuros. Assim você quita o financiamento anos antes do prazo e economiza muito em juros.",
    "Applying for a new loan causes a temporary small dip (5–10 points) due to a hard inquiry. However, using the loan to pay down maxed-out credit cards immediately drops your credit utilization ratio, which typically boosts your credit score significantly within 30 to 60 days.": "Solicitar um novo empréstimo causa uma pequena queda temporária (de 5 a 10 pontos) por causa da consulta ao seu crédito. No entanto, usar o empréstimo para quitar cartões de crédito no limite reduz imediatamente sua taxa de utilização do crédito, o que costuma aumentar bastante sua pontuação em 30 a 60 dias.",
    "Beta measures the volatility or systematic risk of an asset relative to the broader market. A Beta of 1.0 indicates price movements in lockstep with the market. Beta > 1.0 means higher volatility (higher risk/return), while Beta < 1.0 means lower volatility.": "O Beta mede a volatilidade ou o risco sistemático de um ativo em relação ao mercado como um todo. Um Beta de 1,0 indica que o preço acompanha o mercado. Beta acima de 1,0 significa maior volatilidade (mais risco e retorno potencial), enquanto Beta abaixo de 1,0 significa menor volatilidade.",
    "CAGR stands for Compound Annual Growth Rate. It represents the annualized rate of return on your investment over a holding period, assuming the gains compounded annually.": "CAGR é a sigla para Taxa de Crescimento Anual Composta. Ela representa o retorno anualizado do seu investimento ao longo de um período, considerando que os ganhos foram reinvestidos a cada ano.",
    "CAPM is a financial model that calculates the expected rate of return on an investment or asset, given its systematic risk level (Beta). It serves as a foundation for determining the cost of equity capital.": "O CAPM é um modelo financeiro que calcula o retorno esperado de um investimento ou ativo com base no seu nível de risco sistemático (Beta). Ele serve de base para determinar o custo do capital próprio.",
    "Can I do a hybrid of Snowball and Avalanche?": "Posso fazer um modelo híbrido entre Bola de Neve e Avalanche?",
    "Concessional contributions (including employer SG and pre-tax salary sacrifice) are taxed at a low concessional rate of 15% inside the fund, compared to your marginal personal income tax bracket which can reach up to 45% + Medicare levy.": "As contribuições com incentivo fiscal (incluindo a contribuição patronal obrigatória e aportes via salário antes dos impostos) são tributadas a apenas 15% dentro do fundo, enquanto sua faixa marginal de imposto de renda pode chegar a 45% mais a taxa do Medicare.",
    "Daily compound interest calculates and credits earned interest to your balance every single day (365 times per year). In subsequent days, you earn interest on both your initial principal and previously accumulated interest, accelerating exponential wealth growth.": "Os juros compostos diários calculam e creditam os juros ganhos no seu saldo todos os dias (365 vezes por ano). Nos dias seguintes, você ganha juros tanto sobre o capital inicial quanto sobre os juros já acumulados, acelerando o crescimento exponencial do patrimônio.",
    "Debt consolidation combines multiple high-interest debts (such as credit cards with 20%–29% APRs) into a single personal loan with a lower fixed interest rate (e.g., 8%–14% APR). This reduces your total monthly payment and cuts thousands of dollars in interest charges.": "A consolidação de dívidas reúne várias dívidas com juros altos (como cartões de crédito com CET de 20% a 29%) em um único empréstimo pessoal com taxa fixa menor (por exemplo, CET de 8% a 14%). Isso reduz sua parcela mensal total e economiza milhares de reais em juros.",
    "Debt consolidation pays off your creditors in full via a new lower-rate loan without damaging your credit history. Debt settlement involves stopping payments, negotiating to pay less than you owe, and incurs severe, long-lasting damage to your credit report.": "A consolidação de dívidas quita integralmente seus credores por meio de um novo empréstimo com taxa menor, sem prejudicar seu histórico de crédito. Já a renegociação com desconto envolve parar de pagar e negociar um valor menor do que você deve, o que causa danos graves e duradouros ao seu histórico de crédito.",
    "Discretionary income is the difference between your Adjusted Gross Income (AGI) and a percentage of the federal poverty guideline for your family size (150% for PAYE/IBR, 225% for SAVE).": "É a diferença entre a renda bruta tributável e a faixa de proteção da renda familiar legalmente resguardada.",
    "Do high-yield savings accounts (HYSA) compound daily?": "As contas de poupança de alto rendimento rendem juros compostos diários?",
    "Does debt consolidation hurt your credit score?": "Consolidar dívidas prejudica sua pontuação de crédito?",
    "FIRE stands for Financial Independence, Retire Early. It is a financial framework where individuals maximize their savings rate (often 40%–70% of income) and invest in low-cost index funds until their portfolio generates enough passive income to cover their living expenses forever.": "FIRE significa Independência Financeira, Aposentadoria Antecipada. É uma estratégia em que você maximiza sua taxa de poupança (geralmente de 40% a 70% da renda) e investe em fundos de índice baratos até que a carteira gere renda passiva suficiente para cobrir seus gastos para sempre.",
    "For anyone born in 1960 or later, Full Retirement Age is 67. If you claim at FRA, you receive 100% of your Primary Insurance Amount (PIA) without early reduction penalties.": "Para quem nasceu em 1960 ou depois, a idade plena de aposentadoria é 67 anos. Se você se aposentar nessa idade, recebe 100% do benefício-base sem penalidades por antecipação.",
    "For every year you delay claiming past your Full Retirement Age (up to age 70), your benefit increases by 8% per year via Delayed Retirement Credits (DRCs). Waiting until 70 gives you roughly 124% of your full benefit permanently for life.": "Para cada ano que você adia a aposentadoria após a idade plena (até os 70 anos), seu benefício aumenta 8% ao ano por meio de créditos por adiamento. Esperar até os 70 anos garante cerca de 124% do benefício integral pelo resto da vida.",
    "Front-end DTI (housing ratio) only calculates the percentage of gross monthly income spent on housing costs like mortgage payments, property taxes, home insurance, and HOA fees. Back-end DTI (total debt ratio) includes your housing costs plus all other recurring monthly debts like student loans, credit cards, car payments, and personal loans.": "O índice de moradia mede só o percentual da renda bruta gasto com habitação (parcela, IPTU, seguro e condomínio). O índice global soma a moradia e todas as outras dívidas mensais (financiamento estudantil, cartões, carro e empréstimos pessoais).",
    "How can I lower my Debt-to-Income ratio?": "Como reduzir o comprometimento da renda?",
    "How do I calculate my refinance break-even point?": "Como calcular o ponto de equilíbrio (Break-Even)?",
    "How do I calculate stock returns?": "Como calcular a rentabilidade total de ações?",
    "How do extra payments affect my mortgage payoff schedule?": "Qual o efeito das amortizações extraordinárias no financiamento?",
    "How does DTI affect my mortgage application?": "Como a relação dívida/renda afeta a aprovação do crédito?",
    "How does debt consolidation save you money?": "Como a consolidação de dívidas economiza seu dinheiro?",
    "How does salary sacrificing boost superannuation growth?": "Como o aporte via salário aumenta o crescimento da aposentadoria?",
    "How does the 'extra payment' roll over in these strategies?": "Como o valor extra é reaproveitado nas estratégias?",
    "How is discretionary income calculated for student loans?": "Como é calculada a renda discricionária para o crédito estudantil?",
    "How is money inside Australian Super taxed?": "Como o dinheiro dentro do Super australiano é tributado?",
    "How is your FIRE Number calculated?": "Como seu Número FIRE é calculado?",
    "How much more do I get if I delay claiming Social Security until age 70?": "Quanto a mais recebo se adiar minha aposentadoria até os 70 anos?",
    "How much more money do you earn with daily vs monthly compounding?": "Quanto a mais você ganha com capitalização diária em vez de mensal?",
    "How much super do I need for a comfortable retirement in Australia?": "De quanto preciso no Super para uma aposentadoria confortável na Austrália?",
    "In both methods, you continue paying the minimum required payments on all your debts. Any extra cash you can afford is added to the payment of your target debt (either the smallest balance or highest interest). Once that target debt is fully paid off, you roll its entire monthly payment (minimum + the extra cash) into the next debt on your list.": "Nos dois métodos, você paga o mínimo em todas as dívidas e destina o dinheiro extra à dívida-alvo (menor saldo ou maiores juros). Quando ela é quitada, você transfere toda a parcela dela para a próxima dívida da lista.",
    "Is a 15-year mortgage better than a 30-year mortgage?": "Financiar em 15 anos é melhor do que em 30 anos?",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term. The main goal is ensuring your total interest savings exceed the closing costs.": "Vale a pena refinanciar se você conseguir juros menores, reduzir a parcela ou encurtar o prazo, garantindo que a economia total em juros supere os custos de fechamento.",
    "Lean FIRE focuses on covering strictly essential, minimalist expenses (typically under $40,000/year). Standard FIRE maintains a comfortable middle-class lifestyle ($50,000–$100,000/year). Fat FIRE accounts for abundant luxury spending ($120,000+/year) without financial restraint.": "O Lean FIRE foca em cobrir apenas gastos essenciais e minimalistas (geralmente abaixo de R$ 40.000 por ano). O Standard FIRE mantém um padrão de vida confortável de classe média (R$ 50.000 a R$ 100.000 por ano). O Fat FIRE comporta gastos abundantes e luxuosos (acima de R$ 120.000 por ano) sem restrições financeiras.",
    "Lenders use DTI to measure your ability to manage monthly payments. A high DTI indicates you might be over-leveraged, leading to rejection or higher interest rates. DTIs below 36% are considered low risk.": "Os bancos usam o comprometimento de renda para avaliar sua capacidade de pagamento. Um índice alto indica endividamento excessivo, podendo gerar recusa ou juros maiores. Abaixo de 36% é considerado baixo risco.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum of clearing individual accounts quickly helps people stay motivated and stick to their plan.": "Matematicamente, a Avalanche é superior porque minimiza os juros totais. Mas estudos mostram que a Bola de Neve costuma ter mais sucesso na prática, pois o impulso de quitar contas rapidamente mantém a motivação.",
    "On a $100,000 deposit at 7% APR over 20 years, daily compounding yields $405,514 compared to $403,873 for monthly compounding—earning you an extra $1,641 purely from compounding frequency.": "Em um depósito de R$ 100.000 a 7% de CET ao ano por 20 anos, a capitalização diária rende R$ 405.514, contra R$ 403.873 da capitalização mensal — ou seja, R$ 1.641 a mais apenas pela frequência da capitalização.",
    "Originating from the landmark Trinity Study, the 4% rule states that you can withdraw 4% of your starting investment portfolio each year (adjusted annually for inflation) with a 95%+ probability that your portfolio will never run out of money over a 30-year retirement.": "Originada no histórico Estudo Trinity, a regra dos 4% diz que você pode sacar 4% da sua carteira inicial de investimentos por ano (com correção anual pela inflação) com mais de 95% de probabilidade de nunca zerar seu patrimônio ao longo de uma aposentadoria de 30 anos.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a homeowner's monthly housing payment. Together, they reflect the true cost of owning a home on a month-to-month basis.": "Representa Principal (amortização), Juros (Interest), Impostos (Taxes) e Seguros (Insurance), que compõem o custo habitacional mensal integral.",
    "Private Mortgage Insurance (PMI) is a policy that protects the lender if you default. It is typically required on conventional loans if your down payment is less than 20% of the home purchase price.": "É um seguro exigido pelos bancos para proteger o credor caso a entrada fornecida pelo comprador seja inferior a 20% do valor do imóvel.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees. These range from 2% to 6% of the loan amount.": "Os custos de refinanciamento incluem taxas de solicitação, de abertura, avaliação do imóvel, cartório, análise de crédito e registro, variando de 2% a 6% do valor do empréstimo.",
    "Salary sacrificing allows you to direct pre-tax wages straight into super. Because you avoid paying your higher marginal tax rate and benefit from compounding interest over decades, extra contributions can add hundreds of thousands of dollars to your retirement balance.": "O aporte via salário permite direcionar parte do salário bruto diretamente para a aposentadoria. Como você evita sua faixa mais alta de imposto e aproveita os juros compostos ao longo de décadas, essas contribuições extras podem somar centenas de milhares de reais ao seu saldo de aposentadoria.",
    "The 28/36 rule is a standard mortgage underwriting guideline. It states that a household should spend a maximum of 28% of its gross monthly income on housing expenses, and a maximum of 36% on total debt payments (including housing, credit cards, auto loans, and student loans).": "A regra 28/36 é um critério padrão de crédito imobiliário: gastar no máximo 28% da renda bruta mensal com moradia e no máximo 36% com todas as dívidas (moradia, cartões, carro e financiamento estudantil).",
    "The Saving on a Valuable Education (SAVE) plan is the newest income-driven repayment (IDR) plan. It raises the discretionary income shield to 225% of the poverty line, lowers payments to 5% of discretionary income for undergraduate loans, and stops unpaid interest from accumulating.": "É o mais novo modelo de amortização vinculado à renda, protegendo o salário mínimo e reduzindo o valor das parcelas.",
    "The break-even age is typically between 78 and 81 years old. If you expect to live past age 80, delaying claiming to age 70 almost always yields a higher cumulative lifetime payout.": "A idade de equilíbrio costuma ficar entre 78 e 81 anos. Se você espera viver além dos 80 anos, adiar a aposentadoria até os 70 anos quase sempre resulta em um valor total maior ao longo da vida.",
    "The daily compound formula is A = P(1 + r/365)^(365 * t), where P is initial principal, r is annual interest rate (as a decimal), and t is time in years. When recurring deposits are added, interest is calculated on daily running balances.": "A fórmula da capitalização diária é M = C(1 + i/365)^(365 × t), onde C é o capital inicial, i é a taxa anual de juros (em decimal) e t é o tempo em anos. Quando há depósitos recorrentes, os juros são calculados sobre o saldo diário atualizado.",
    "To calculate total stock return, subtract the purchase price from the selling price to find capital gains. Add any dividends received. Divide this sum by the initial purchase price, and multiply by 100 to get a percentage return.": "Para calcular o retorno total de uma ação, subtraia o preço de compra do preço de venda para achar o ganho de capital. Some os dividendos recebidos. Divida esse total pelo preço inicial de compra e multiplique por 100 para obter o retorno percentual.",
    "To find your break-even point, divide your total refinance closing costs by your monthly payment savings. For example, if closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150). If you plan to sell or move before reaching this point, refinancing may not make financial sense.": "Divida os custos totais de fechamento pela economia mensal. Por exemplo: R$ 3.000 de custos / R$ 150 de economia ao mês = 20 meses para se pagar. Se você pretende vender ou se mudar antes disso, o refinanciamento pode não valer a pena.",
    "Traditional IRA contributions are generally made pre-tax (reducing your current taxable income), but withdrawals in retirement are taxed as ordinary income. Roth IRA contributions are made with post-tax dollars; growth and withdrawals in retirement are completely tax-free.": "O tradicional permite dedução fiscal imediata e tributa na aposentadoria; o modelo Roth investe valor líquido mas isenta todos os lucros futuros.",
    "Under Australian Commonwealth law, employers are required to contribute a percentage of your ordinary time earnings into your designated superannuation fund. The rate is currently legislated to reach 12%.": "Pela lei federal australiana, os empregadores são obrigados a contribuir com um percentual dos seus ganhos regulares para o seu fundo de aposentadoria designado. A alíquota prevista em lei deve chegar a 12%.",
    "Watch out for origination fees (typically 1% to 6% of the loan amount), make sure the new monthly payment comfortably fits your budget, and avoid running up new balances on the credit cards you just paid off.": "Atenção às taxas de abertura (geralmente de 1% a 6% do valor do empréstimo), garanta que a nova parcela caiba com folga no seu orçamento e evite acumular novos saldos nos cartões que você acabou de quitar.",
    "What closing costs are associated with refinancing?": "Quais são os custos na portabilidade ou refinanciamento?",
    "What does Asset Beta (β) represent?": "O que representa o Beta (β) de uma ação?",
    "What does PITI stand for?": "O que significa a sigla PITI?",
    "What is CAGR in stock returns?": "O que significa CAGR em ações?",
    "What is PMI and when do I pay it?": "O que é o seguro de garantia habitacional (PMI)?",
    "What is an expense ratio?": "O que é a taxa de administração (Expense Ratio)?",
    "What is daily compound interest and how does it work?": "O que são juros compostos diários e como funcionam?",
    "What is my Full Retirement Age (FRA)?": "Qual é minha idade plena de aposentadoria?",
    "What is the 28/36 rule?": "O que é a regra do 28/36%?",
    "What is the 4% Safe Withdrawal Rule?": "O que é a regra dos 4% para saques seguros?",
    "What is the Australian Superannuation Guarantee (SG) rate?": "Qual é a alíquota da Garantia de Aposentadoria (SG) australiana?",
    "What is the Capital Asset Pricing Model (CAPM)?": "O que é o modelo CAPM?",
    "What is the FIRE movement and what does it mean?": "O que é o movimento FIRE e o que ele significa?",
    "What is the SAVE plan?": "O que é o plano estudantil de pagamento por renda (SAVE)?",
    "What is the Social Security break-even age between claiming at 62 vs 70?": "Qual é a idade de equilíbrio entre pedir a aposentadoria aos 62 ou aos 70 anos?",
    "What is the difference between Lean FIRE, Standard FIRE, and Fat FIRE?": "Qual é a diferença entre Lean FIRE, Standard FIRE e Fat FIRE?",
    "What is the difference between debt consolidation and debt settlement?": "Qual é a diferença entre consolidação e renegociação de dívidas com desconto?",
    "What is the difference between front-end and back-end DTI?": "Qual a diferença entre DTI habitacional e DTI total?",
    "What is the formula for daily compound interest?": "Qual é a fórmula dos juros compostos diários?",
    "What is the key difference between a Roth and Traditional IRA?": "Qual a diferença central entre previdência tradicional e modelo isento?",
    "What should I look out for before consolidating debt?": "Com o que devo tomar cuidado antes de consolidar dívidas?",
    "When is the earliest age I can claim Social Security retirement benefits?": "Qual é a idade mínima para pedir os benefícios de aposentadoria?",
    "When should I refinance my loan?": "Quando vale a pena fazer a portabilidade de crédito?",
    "Which method is better: Debt Snowball or Debt Avalanche?": "Qual é o melhor método: Bola de Neve ou Avalanche?",
    "Yes, the vast majority of high-yield savings accounts and money market accounts compound interest daily and credit the payment to your balance on the last business day of the month.": "Sim, a grande maioria das contas de poupança de alto rendimento e das contas do mercado monetário rende juros compostos diários e credita o valor no seu saldo no último dia útil do mês.",
    "Yes. Some people prefer to pay off one or two small debts first to get immediate visual progress and free up cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sim. Muita gente quita uma ou duas dívidas pequenas primeiro para ver progresso rápido e liberar orçamento (Bola de Neve) e depois ataca as dívidas restantes pelos maiores juros para economizar (Avalanche).",
    "You can lower your DTI by either increasing your gross monthly income (e.g., getting a raise, starting a side business) or paying down your recurring debts. Focus on paying off smaller loans entirely to eliminate their minimum monthly payment from your DTI calculation.": "Você reduz o índice aumentando a renda bruta mensal (aumento, renda extra) ou quitando dívidas recorrentes. Foque em zerar empréstimos menores para eliminar a parcela mínima deles do cálculo.",
    "You can start receiving Social Security retirement benefits as early as age 62. However, claiming early permanently reduces your monthly check by up to 30% compared to waiting for your Full Retirement Age (FRA).": "Você pode começar a receber os benefícios de aposentadoria a partir dos 62 anos. No entanto, antecipar reduz permanentemente sua parcela mensal em até 30% em comparação com esperar até a idade plena de aposentadoria.",
    "Your FIRE number is your annual living expenses multiplied by 25 (under a 4% rule) or multiplied by 33 (under a conservative 3% rule). For example, if you live comfortably on $60,000 per year, your FIRE number is $1,500,000.": "Seu Número FIRE é seus gastos anuais multiplicados por 25 (pela regra dos 4%) ou por 33 (pela regra conservadora dos 3%). Por exemplo, se você vive confortavelmente com R$ 60.000 por ano, seu Número FIRE é R$ 1.500.000.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into your new total loan balance or charges a slightly higher interest rate to cover them. This avoids paying cash upfront but increases the lifetime cost of the loan.": "Refinanciamento sem custos de fechamento não significa que as taxas são perdoadas. O banco incorpora os custos ao novo saldo devedor ou cobra juros um pouco maiores. Você não desembolsa nada à vista, mas o custo total do empréstimo aumenta.",
    "Are there income limits for contributing to Traditional and Roth IRAs?": "Há restrições de renda para contribuir?",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower than it is today, a Traditional IRA is better.": "Como regra geral, se você espera estar em uma faixa de imposto maior na aposentadoria do que hoje, o Roth IRA é melhor. Se espera uma faixa menor, o IRA Tradicional é melhor.",
    "Can I switch student loan repayment plans at any time?": "Posso mudar de plano de pagamento a qualquer momento?",
    "Can I withdraw money from my IRA before age 59½ without penalty?": "Posso resgatar os recursos antes dos 59 anos e meio sem multa?",
    "Does refinancing lower my monthly payment or total interest?": "A portabilidade reduz a parcela ou os juros totais?",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under age 50, and $8,000 for those age 50 or older (which includes a $1,000 catch-up contribution).": "Em 2024, o limite anual de contribuição para o IRA Tradicional e o Roth IRA é de R$ 7.000 para menores de 50 anos e R$ 8.000 para quem tem 50 anos ou mais (incluindo R$ 1.000 de contribuição extra).",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. However, if your income is very high relative to your debt, plans like PAYE or IBR might be better because they cap your monthly payment at what it would be under the Standard 10-Year Repayment Plan, whereas SAVE has no payment cap.": "Para a maioria, o plano SAVE oferece a menor parcela e o melhor subsídio de juros. Mas se sua renda é muito alta em relação à dívida, planos como PAYE ou IBR podem ser melhores, pois limitam a parcela ao valor do plano padrão de 10 anos, enquanto o SAVE não tem teto.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though many will approve up to 43%. Government-backed loans like FHA and VA loans can be more flexible, sometimes allowing back-end DTIs up to 50% or higher if you have a strong credit score or significant cash reserves.": "Em financiamentos convencionais, os bancos preferem comprometimento total de renda de até 36%, embora muitos aprovem até 43%. Programas com garantia pública podem aceitar até 50% ou mais com bom score de crédito e reservas.",
    "How does student loan forgiveness work under IDR plans?": "Como funciona o perdão da dívida estudantil?",
    "If you pay under an IDR plan for 20 or 25 years (or as little as 10 years under SAVE for low initial balances), any remaining student debt is forgiven. However, under current tax laws, this forgiven balance may be treated as taxable income, although federal tax on forgiven student loans is temporarily suspended through 2025.": "Pagando por um plano vinculado à renda durante 20 ou 25 anos (ou apenas 10 anos no SAVE para saldos iniciais baixos), a dívida estudantil restante é perdoada. Porém, o valor perdoado pode ser tributado como renda, embora o imposto federal esteja temporariamente suspenso até 2025.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same or shorter term, you save on both. However, if you reset your term back to 30 years to get the lowest possible monthly payment, you might end up paying more total interest over the life of the loan despite the monthly savings.": "Pode fazer os dois, dependendo do novo prazo. Com juros menores e prazo igual ou menor, você economiza na parcela e no total. Mas se reiniciar o prazo em 30 anos para ter a menor parcela possível, pode pagar mais juros no total apesar da economia mensal.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers, and $230,000 to $240,000 for married couples filing jointly. Anyone can contribute to a Traditional IRA regardless of income, but the tax deductibility phases out if your income is high and you have access to a workplace retirement plan (like a 401k).": "O Roth IRA tem limites de renda rígidos; em 2024, a elegibilidade cai entre R$ 146.000 e R$ 161.000 para solteiros e entre R$ 230.000 e R$ 240.000 para casais. Qualquer pessoa pode contribuir ao IRA Tradicional, mas a dedução fiscal diminui com renda alta e plano de aposentadoria no trabalho (como o 401k).",
    "What are the contribution limits for IRAs in 2024?": "Qual o limite de contribuição?",
    "What is a 'no-closing-cost' refinance?": "O que é um refinanciamento 'sem custos iniciais'?",
    "What is the maximum DTI ratio lenders will accept?": "Qual o limite máximo de comprometimento de renda aceito?",
    "Which IDR plan is best for me?": "Qual modalidade de amortização é mais vantajosa?",
    "Which IRA plan is better for me?": "Qual plano previdenciário escolher?",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax- and penalty-free, but withdrawing earnings early incurs taxes and a 10% penalty. With a Traditional IRA, withdrawing any funds early generally triggers both regular income tax and a 10% penalty, except for specific IRS-approved exemptions (e.g., qualifying first-time home purchase, higher education expenses, or disability).": "No Roth IRA, você pode sacar suas contribuições originais a qualquer momento sem imposto nem multa, mas sacar os rendimentos antes da hora gera imposto e multa de 10%. No IRA Tradicional, qualquer saque antecipado gera imposto de renda e multa de 10%, salvo exceções específicas (compra do primeiro imóvel, gastos com ensino superior ou invalidez).",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause outstanding unpaid interest to capitalize (be added to your principal balance), which means you will start paying interest on that interest.": "Sim, você pode pedir a troca de plano gratuitamente no studentaid.gov. Mas a troca pode capitalizar os juros não pagos (somá-los ao saldo devedor), fazendo você pagar juros sobre juros.",
    "A 1% annual fee difference can erode 25% to 30% of your total ending portfolio wealth over a 30-year investment horizon.": "Uma diferença de apenas 1% ao ano em taxas pode corroer entre 25% e 30% de todo o patrimônio final acumulado em 30 anos!",
    "A 529 plan is a tax-advantaged savings and investment plan designed to encourage saving for future higher education expenses with tax-free growth and qualified withdrawals.": "Um plano americano com incentivo fiscal voltado para custear a faculdade dos filhos com isenção de impostos sobre os lucros.",
    "A DRIP automatically uses your cash dividend payments to purchase additional shares or fractional shares of the stock, compounding your share count and future payouts without commission fees.": "Mecanismo que utiliza os proventos recebidos para comprar mais cotas da mesma empresa sem corretagem, multiplicando os juros compostos.",
    "A negative net worth means your total debts exceed your total assets. This is common for young adults and recent graduates with student loans.": "Significa que o valor das dívidas é maior que todos os bens que você possui, algo comum no início da vida adulta.",
    "An expense ratio is the annual percentage fee charged by mutual funds and ETFs to cover fund management, administrative expenses, and operating costs.": "O percentual anual cobrado por fundos de investimento e ETFs para remunerar a gestão, administração e custódia.",
    "Are dividend payments guaranteed?": "Os dividendos de ações são garantidos?",
    "Assets include bank balances, investment accounts, home equity, and retirement funds. Liabilities include mortgages, student loans, car loans, and credit card debt.": "Ativos: contas bancárias, ações, imóveis e previdência. Passivos: financiamento imobiliário, dívida do carro e cartões.",
    "Automate recurring monthly transfers into a dedicated savings account immediately after your paycheck arrives (the 'pay yourself first' strategy).": "Configure uma transferência automática para a aplicação financeira no dia do pagamento do salário ('pague a si mesmo primeiro').",
    "Beta measures an asset's volatility compared to the broader market. A beta of 1.0 indicates market-level volatility; above 1.0 indicates higher volatility, and below 1.0 indicates lower volatility.": "Mede a sensibilidade de um papel em relação ao índice de mercado: Beta 1 oscila igual ao Ibovespa; acima de 1 é mais volátil; abaixo de 1 é mais defensivo.",
    "Build a starter emergency fund of 1 month of expenses or $1,000 to $2,000 first, then aggressively pay off high-interest consumer debt before expanding to 3-6 months.": "Junte uma reserva inicial de 1 mês de despesas (R$ 1.000 a R$ 2.000), liquide as dívidas com juros altos e depois complete os 3 a 6 meses de reserva.",
    "CAPM calculates an asset's expected return based on its risk relative to the overall market, using the formula: Expected Return = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate).": "Calcula o retorno esperado de um ativo a partir do seu risco de mercado: Retorno = Taxa Livre de Risco + Beta × Prêmio de Risco do Mercado.",
    "Can I use a 529 plan for trade schools or K-12 tuition?": "Pode ser usado para cursos técnicos ou escola de ensino fundamental/médio?",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation is 3%, $100 today will only buy about $97 worth of goods next year.": "Dinheiro parado sem rendimento perde valor: com inflação de 3%, R$ 100 de hoje só comprarão o equivalente a R$ 97 no ano que vem.",
    "Compound Annual Growth Rate (CAGR) measures the geometric mean annual return of a stock over multiple years, smoothing out annual market fluctuations.": "A Taxa de Crescimento Anual Composto mede a rentabilidade geométrica média por ano, suavizando as oscilações do mercado.",
    "DCA prevents emotional decisions during extreme market peaks and crashes, automatically buying more units when prices are low and fewer when prices are high.": "Evita decisões precipitadas e emocionais, comprando mais frações de moeda nas quedas e diminuindo o preço médio de aquisição.",
    "Dividend yield is the annual dividend divided by the current stock price. Yield on cost is the annual dividend divided by your original purchase price, which increases as companies raise their dividends over time.": "O Dividend Yield divide o dividendo pelo preço atual da ação; o Yield on Cost divide o provento pelo preço pago na compra original.",
    "Does DCA guarantee profits in cryptocurrency?": "O DCA assegura lucro garantido em criptoativos?",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have progressive tax rates). Local taxes may also apply depending on the specific city or county you work or live in.": "Cada estado define suas próprias faixas de imposto de renda (alguns, como Texas e Flórida, nem cobram), e pode haver tributos municipais conforme a cidade onde você mora ou trabalha.",
    "FICA is a federal payroll tax that funds Social Security (6.2% on wages up to the wage base limit) and Medicare (1.45% plus an additional 0.9% on high earners).": "São contribuições previdenciárias e sociais deduzidas da folha de pagamento para financiar a aposentadoria pública e a seguridade social.",
    "Fees are deducted annually from your total assets, meaning you lose both the fee money and all future compounding returns that money would have earned.": "Como a taxa é deduzida anualmente do patrimônio total, você perde o valor cobrado e todos os juros compostos que ele geraria ao longo da vida.",
    "For goals under 3 to 5 years (like a car or home down payment), keep funds in safe, liquid instruments like High-Yield Savings Accounts (HYSA) or CDs. For goals 5+ years away, a diversified investment portfolio may be suitable.": "Para metas de até 3 a 5 anos (carro, entrada do imóvel), use Tesouro Selic e CDBs com liquidez; acima de 5 anos, uma carteira de ações e fundos é adequada.",
    "Gross pay is the total amount earned before any taxes or deductions. Net pay (take-home pay) is the actual cash deposited into your bank account after all deductions.": "Salário bruto é a remuneração estipulada em contrato; salário líquido é o valor que cai na conta bancária após o desconto de INSS e IRRF.",
    "Historically, higher education tuition and fees have increased at an annual rate of 4% to 6%, outpacing general consumer inflation.": "Historicamente as mensalidades de faculdades sobem entre 4% e 6% ao ano, acima da inflação oficial média.",
    "Historically, the broad stock market (S&P 500) has returned an average of 7% to 10% annually before inflation. Investments with higher expected returns generally involve higher risk of capital loss.": "Historicamente a bolsa ampla rende de 7% a 10% ao ano antes da inflação; rentabilidades muito maiores exigem tolerância a perdas de capital.",
    "How can I protect my money from losing value to inflation?": "Como proteger os investimentos contra a inflação?",
    "How can I stay on track with my savings goals?": "Como manter a disciplina com as metas de economia?",
    "How do I calculate how much to save monthly for a goal?": "Como calcular o valor a poupar mensalmente para uma meta?",
    "How do fees compound over time?": "Como as taxas corroem a rentabilidade no longo prazo?",
    "How does DCA apply to high-volatility assets like Crypto?": "Por que o DCA é ideal para criptomoedas?",
    "How does a 529 plan impact financial aid eligibility?": "Qual o impacto na obtenção de bolsas e auxílios estudantis?",
    "How does compounding frequency affect total returns?": "Como a frequência de capitalização afeta o saldo final?",
    "How does inflation affect my savings?": "Como a inflação prejudica o dinheiro guardado?",
    "How does my W-4 filing status affect my paycheck?": "Como os dependentes afetam a retenção na fonte?",
    "How fast do college costs increase?": "A que ritmo sobem os custos do ensino superior?",
    "How is Return on Investment (ROI) calculated?": "Como é calculado o Retorno sobre o Investimento (ROI)?",
    "How is inflation officially measured?": "Como a inflação é calculada oficialmente?",
    "How much can a 1% fee difference affect my retirement savings?": "Qual o impacto de 1% a mais de taxa na aposentadoria?",
    "How often should I calculate my net worth?": "Com que frequência devo medir meu patrimônio líquido?",
    "In a dedicated High-Yield Savings Account (HYSA) or money market account where it is FDIC-insured, earns interest, and can be accessed immediately without risk.": "Em aplicações de alta liquidez e baixo risco, como Tesouro Selic ou CDBs com liquidez diária e garantia do FGC.",
    "In an ordinary annuity, payments occur at the end of each period. In an annuity due, payments occur at the beginning of each period, earning an extra compounding cycle of interest.": "Na anuidade postecipada o pagamento ocorre no fim do período; na antecipada no início, rendendo um ciclo a mais de juros compostos.",
    "In the United States, inflation has historically averaged between 2.5% and 3.2% per year over long multi-decade horizons.": "Em economias estáveis gira historicamente entre 2% e 3% ao ano em prazos pluridecenais.",
    "Include only non-negotiable living costs: housing (rent/mortgage), utilities, groceries, basic transportation, minimum debt payments, and healthcare insurance.": "Apenas gastos básicos essenciais: moradia, contas de luz e água, alimentação essencial, plano de saúde e parcelas obrigatórias.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks price changes across a standard market basket of consumer goods and services.": "No Brasil pelo IPCA (Índice Nacional de Preços ao Consumidor Amplo), que acompanha uma cesta de produtos de famílias consumidoras.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a decline in the purchasing power of money.": "É o aumento generalizado e contínuo nos preços de produtos e serviços, que reduz o poder de compra da moeda ao longo do tempo.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities, Treasury Inflation-Protected Securities (TIPS), real estate, and inflation-indexed bonds.": "Investindo em títulos atrelados ao IPCA (como Tesouro IPCA+), fundos imobiliários e ações de boas empresas.",
    "Is DCA better than investing a lump sum?": "O aporte regular é melhor do que investir tudo de uma vez?",
    "Low-cost index funds and ETFs typically have expense ratios between 0.02% and 0.10%, whereas actively managed mutual funds often charge 0.60% to 1.50% or more.": "ETFs de índice custam tipicamente entre 0,05% e 0,30% ao ano, enquanto fundos multimercados ativos costumam cobrar 2% ao ano mais taxa de performance.",
    "Lump sum investing historically wins in steadily rising markets, but DCA provides superior peace of mind, lower emotional risk, and downside protection in highly volatile markets.": "Em mercados em forte alta o aporte único rende mais; mas em ativos com oscilações extremas, o DCA oferece tranquilidade e proteção.",
    "Most financial planners recommend saving 3 to 6 months of essential living expenses, or 9 to 12 months for freelancers or single-income households.": "Recomenda-se de 3 a 6 meses do custo de vida básico para assalariados (ou 9 a 12 meses para autônomos e empreendedores).",
    "Net worth is the total market value of everything you own (assets) minus everything you owe to creditors (liabilities).": "É a soma do valor de mercado de todos os seus bens e direitos (ativos) menos todas as suas dívidas (passivos).",
    "No, DCA does not protect against prolonged declines or failing crypto projects; it only ensures you achieve the weighted average market purchase price.": "Não, ele não impede perdas em projetos ruins ou em quedas estruturais contínuas; garante apenas o preço médio ponderado de mercado.",
    "No, company boards can reduce, suspend, or eliminate dividend payouts at any time depending on company profitability and economic conditions.": "Não, o conselho de administração pode reduzir, adiar ou cancelar os proventos dependendo dos lucros e do cenário econômico.",
    "Parent-owned 529 plans are assessed as parental assets on the FAFSA at a maximum rate of 5.64%, having minimal negative impact on financial aid eligibility.": "Se estiver em nome dos pais, apenas até 5,64% do saldo entra no cômputo da renda familiar, com impacto mínimo.",
    "Pre-tax deductions (like 401k and health insurance) reduce your taxable gross income before taxes are computed. Post-tax deductions (like Roth contributions or wage garnishments) are taken after taxes.": "Deduções pré-tributáveis (previdência, plano de saúde) diminuem a base de cálculo do IR; deduções pós-tributáveis ocorrem sobre o salário líquido.",
    "ROI is calculated by subtracting the initial cost of the investment from the final value, and dividing that net gain by the initial cost: ROI = (Net Profit / Cost of Investment) × 100%.": "Diminui-se o custo inicial do valor final e divide-se esse lucro pelo custo de aquisição: ROI = (Lucro Líquido / Custo do Investimento) × 100%.",
    "Reviewing your net worth quarterly or semi-annually gives you a clear high-level view of your financial health without obsessing over daily market swings.": "Uma checagem semestral ou trimestral oferece uma fotografia macro do progresso financeiro sem ansiedade pelas variações diárias.",
    "Should I include my house and mortgage in my net worth?": "Devo incluir minha casa financiada no patrimônio líquido?",
    "Should I keep savings goal funds in high-yield savings or stocks?": "Onde deixar o dinheiro das metas: renda fixa ou ações?",
    "Should I pay off debt or build an emergency fund first?": "Devo pagar as dívidas ou montar a reserva primeiro?",
    "Simple ROI measures total percentage return regardless of duration. Annualized ROI (CAGR) standardizes the return into a per-year geometric rate, enabling fair comparison between investments held for different lengths of time.": "O retorno simples mede o ganho acumulado total; o anualizado padroniza o ganho a uma taxa anual média, permitindo comparar investimentos de prazos distintos.",
    "Simple return measures absolute percentage gain over the entire holding period, while annualized return shows the steady annual rate required to achieve that result.": "O retorno simples mostra o ganho acumulado em todo o período; o anualizado aponta o ritmo de valorização médio por ano.",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest.": "Princípio financeiro que estabelece que um real hoje vale mais do que um real amanhã, pois pode ser aplicado e gerar juros imediatamente.",
    "The five core variables are Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Total Number of Periods (Nper), and Periodic Payment (PMT).": "Valor Presente (PV), Valor Futuro (FV), Taxa de juros (Rate), Número de períodos (Nper) e Pagamento periódico constante (PMT).",
    "The market risk premium is the additional return investors demand for choosing risky market equities over risk-free government securities.": "O retorno adicional exigido pelos investidores para assumir o risco da renda variável em relação à renda fixa garantida.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your effective annual yield (APY) will be, as interest starts earning interest sooner.": "Quanto mais frequente for a capitalização (mensal, diária), maior será a rentabilidade efetiva anual.",
    "The risk-free rate is the theoretical rate of return of an investment with zero risk of default, typically represented by long-term government bond yields (like 10-year US Treasuries).": "O rendimento de títulos soberanos com risco de inadimplência nulo (como títulos públicos do Tesouro de 10 anos).",
    "Total stock return equals capital gains (ending price minus purchase price) plus any dividends received, divided by the original purchase cost.": "Soma-se a valorização das cotas (ganho de capital) a todos os dividendos e juros sobre capital próprio recebidos, dividindo pelo custo de compra.",
    "Use it only for genuine, unexpected emergencies: sudden medical bills, unexpected car repairs, or living expenses following job loss.": "Apenas em emergências imprevisíveis: demissão, emergência médica inadiável ou conserto indispensável no automóvel.",
    "Watch out for advisory fees (AUM fees of 1%), front-end or back-end sales loads, trading commissions, account maintenance fees, and custodial charges.": "Taxas de corretagem, emolumentos da bolsa, custódia e taxa de performance de fundos de investimento.",
    "Weekly or bi-weekly DCA aligned with your pay cycle is ideal for capturing market volatility while keeping trading fees manageable.": "Aportes semanais ou quinzenais alinhados ao recebimento do salário equilibram o efeito preço médio sem gerar custos excessivos de taxas.",
    "What are the core components of TVM calculations?": "Quais são as 5 variáveis essenciais dos cálculos de matemática financeira?",
    "What counts as an asset vs. a liability?": "O que entra no ativo e o que entra no passivo?",
    "What does it mean to have a negative net worth?": "O que significa estar com patrimônio líquido negativo?",
    "What expenses should be included in an emergency fund budget?": "Quais contas entram no cálculo da reserva de emergência?",
    "What happens to 529 funds if my child does not go to college?": "O que acontece com os recursos se o filho não for para a faculdade?",
    "What is FICA tax?": "O que são descontos de INSS e encargos de folha?",
    "What is a 529 plan?": "O que é o plano 529 de poupança universitária?",
    "What is a Dividend Reinvestment Plan (DRIP)?": "O que é o reinvestimento automático de dividendos?",
    "What is a good expense ratio for an index fund?": "Qual é uma boa taxa para um fundo de índice (ETF)?",
    "What is considered a good ROI?": "O que é considerado uma boa rentabilidade?",
    "What is dividend yield versus yield on cost?": "Qual a diferença entre Dividend Yield e Yield on Cost?",
    "What is the Market Risk Premium?": "O que é o prêmio de risco do mercado?",
    "What is the Risk-Free Rate?": "O que é a taxa livre de risco?",
    "What is the Time Value of Money (TVM)?": "O que é o valor do dinheiro no tempo (TVM)?",
    "What is the best frequency for crypto DCA?": "Qual é a frequência recomendada para fazer aportes em cripto?",
    "What is the difference between an ordinary annuity and annuity due?": "Qual a diferença entre pagamentos postecipados e antecipados?",
    "What is the difference between gross pay and net pay?": "Qual a diferença entre salário bruto e salário líquido?",
    "What is the difference between pre-tax and post-tax deductions?": "Qual a diferença entre deduções antes e depois do imposto?",
    "What is the difference between simple ROI and annualized ROI?": "Qual a diferença entre retorno simples e retorno anualizado (CAGR)?",
    "What is the difference between simple return and annualized return?": "Qual a diferença entre retorno nominal absoluto e anualizado?",
    "What is the historical average inflation rate?": "Qual a média histórica da inflação?",
    "What other investment fees should I look out for?": "A quais outras taxas financeiras devo ficar atento?",
    "When is it appropriate to use emergency fund savings?": "Quando é correto utilizar a reserva de emergência?",
    "Where should I keep my emergency fund?": "Onde deixar guardada a reserva de emergência?",
    "Why do state and local taxes vary so much?": "Por que os impostos variam entre regiões?",
    "Yes, qualified distributions can cover accredited trade schools, vocational programs, apprenticeships, and up to $10,000 per year for K-12 private school tuition.": "Sim, escolas técnicas credenciadas e até 10.000 $ por ano para mensalidades escolares privadas são elegíveis.",
    "Yes, you include the current fair market value of the home under assets and the remaining mortgage balance under liabilities. The difference is your home equity.": "Sim, cadastra-se o valor de mercado atual do imóvel como ativo e o saldo devedor do financiamento como passivo; a diferença é o patrimônio imobiliário líquido.",
    "You can change the beneficiary to another qualifying family member, use up to $10,000 for student loan repayment, or roll over up to $35,000 into a Roth IRA under SECURE 2.0 rules.": "É possível transferir o titular para outro filho da família ou migrar até 35.000 $ para uma conta individual de aposentadoria.",
    "You divide your target savings amount by the number of months until your deadline, while factoring in the compounding interest earned on your growing balance.": "Divide-se o valor da meta pelos meses disponíveis, descontando os juros compostos que o saldo renderá ao longo do tempo.",
    "Your W-4 form informs your employer how much federal income tax to withhold each pay period based on your filing status, dependents, and other income.": "A declaração de dependentes e pensões reduz a retenção mensal do imposto de renda retido na fonte pela empresa.",
    "A 0% APR balance transfer credit card can save significant interest if you pay off the full balance during the promotional period (typically 12-21 months) and factor in the 3%-5% transfer fee.": "Sim, trocar o juro rotativo do cartão por um crédito consignado ou empréstimo pessoal com taxa fixa reduz drasticamente a dívida.",
    "A common benchmark is accumulating 25 times your anticipated annual retirement expenses, or replacing 70% to 80% of your pre-retirement income.": "A regra comum é acumular 25 vezes o seu custo de vida anual estimado, ou garantir de 70% a 80% da sua última remuneração ativa.",
    "A larger down payment reduces your loan amount, eliminates Private Mortgage Insurance (PMI) if you put down 20%, and lowers your monthly mortgage payment.": "Uma entrada maior reduz o saldo devedor, barateia as parcelas mensais e garante acesso às melhores taxas do mercado.",
    "APR is higher because it amortizes all upfront lender fees, discount points, and closing costs into the effective yearly rate, revealing the true cost of credit.": "Porque embute todos os custos contratuais, tarifas e tributos diluídos na taxa anualizada.",
    "An employer match is money your employer contributes to your 401(k) account based on your own contributions (e.g. matching 50% of contributions up to 6% of your salary). It is effectively an instant return on your savings.": "É a contribuição paritária que a empresa deposita para cada real investido pelo funcionário, representando um ganho imediato de 100%.",
    "Because upfront closing costs, moving fees, and commissions are substantial, homeowners usually need to stay in a property for 4 to 7 years for buying to financially outperform renting.": "Devido aos custos de ITBI, escritura e comissões, geralmente são necessários entre 4 e 7 anos para a compra ser financeiramente vantajosa.",
    "Calculate the total bill including food, beverages, tax, and tip, and divide the total amount equally by the number of paying participants.": "Some todo o consumo de comidas, bebidas, tributos e gorjeta, e divida o valor integral de forma equitativa pelo número de pagantes.",
    "Credit card minimum payments are often set around 1% to 2% of the balance plus accrued interest. As the balance slowly drops, the required minimum drops, extending payoff times to decades.": "O pagamento mínimo cobre apenas os juros e 1% a 2% do saldo. Como o valor cai conforme a dívida desce, o pagamento pode durar décadas.",
    "Etiquette traditionally dictates calculating the tip percentage on the pre-tax food and beverage subtotal, though many automated payment terminals calculate tip on the post-tax total.": "A etiqueta recomenda calcular sobre o subtotal consumido sem tributos, embora a maioria das maquininhas de cartão calcule sobre o total final.",
    "Every 1% increase in mortgage interest rates reduces your home purchasing power by roughly 10% for the same monthly payment budget.": "Cada 1% a mais na taxa de juros reduz o valor do imóvel que você consegue financiar em cerca de 10% para uma mesma parcela.",
    "For 2024, the employee contribution limit is $23,000 for those under 50. Individuals aged 50 and older can contribute an additional $7,500 catch-up contribution for a total of $30,500.": "Nos EUA o teto é de 23.000 $; no Brasil, no PGBL permite-se deduzir da base do IRPF aportes até o limite de 12% da renda bruta tributável.",
    "Homeowners must pay property taxes, homeowners insurance, maintenance and repairs (typically 1-2% of home value annually), HOA dues, and potential capital improvement costs.": "IPTU, taxa de condomínio, manutenções e reformas periódicas (cerca de 1% a 2% do valor do imóvel ao ano).",
    "How do interest rates affect purchasing power?": "De que forma os juros afetam a capacidade de compra?",
    "How do multiple stacked discounts work?": "Como funcionam descontos sucessivos acumulados?",
    "How do you calculate a percentage discount?": "Como calcular um desconto percentual?",
    "How do you split a bill evenly among friends?": "Como dividir a conta de restaurante igualmente entre amigos?",
    "How does down payment size impact affordability?": "Como o valor da entrada afeta o financiamento?",
    "How does inflation impact retirement spending?": "Qual o impacto da inflação no custo de vida aposentado?",
    "How does vehicle depreciation affect my loan?": "Como a depreciação do veículo afeta o financiamento?",
    "How long do I need to stay in a home for buying to beat renting?": "Quantos anos é preciso morar no imóvel para a compra superar o aluguel?",
    "How much faster can I pay off credit cards by paying extra?": "Quanto amortizações extras aceleram o fim das dívidas de cartão?",
    "How much income should I spend on a mortgage?": "Quanto da renda pode ser comprometido na prestação da casa?",
    "How much money do I need to retire comfortably?": "De quanto patrimônio preciso para ter uma aposentadoria tranquila?",
    "In most jurisdictions, sales tax is calculated on the discounted post-sale price, meaning you pay sales tax only on the actual money spent.": "Os impostos sobre o consumo incidem sobre o preço líquido com desconto, tributando apenas o valor efetivamente pago pelo consumidor.",
    "In the United States and Canada, standard restaurant tipping guidelines range from 15% for adequate service, 18% for good service, to 20% or more for exceptional service.": "Na América do Norte varia entre 15% e 20%; no Brasil a taxa de serviço sugerida na conta de bares e restaurantes é costumeiramente de 10% a 13%.",
    "Inflation steadily reduces the purchasing power of your savings. At a 3% inflation rate, everyday living expenses double roughly every 24 years, requiring growing investment portfolios.": "Com 3% de inflação anual, o custo de vida dobra em cerca de 24 anos, exigindo que o patrimônio continue investido em ativos rentáveis.",
    "Is APR useful for comparing different loan offers?": "O CET / APR é a melhor métrica para comparar propostas?",
    "Is a longer auto loan term better?": "Financiar o veículo em 60 ou 72 meses é vantajoso?",
    "Is sales tax applied before or after store discounts?": "O imposto incide antes ou após o desconto?",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk becoming 'underwater' (owing more than the vehicle is worth).": "Prazos muito longos baixam a parcela, mas aumentam excessivamente os juros e geram risco de a dívida superar o valor de tabela do carro.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline).": "Especialistas recomendam comprometer no máximo 25% a 30% da renda líquida mensal com parcelas imobiliárias.",
    "Multiply the original price by the discount percentage divided by 100 to find the savings, and subtract that amount from the original price: Final Price = Original Price × (1 - Discount%).": "Multiplique o preço original pela porcentagem de desconto dividida por 100 para descobrir a economia e subtraia: Preço Final = Preço Original × (1 - Desconto%).",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, you risk owing more on your loan than the car's market value.": "Carros novos perdem até 20% do valor no primeiro ano; sem uma boa entrada, a dívida fica superior ao valor de revenda do automóvel.",
    "Paying even $50 or $100 above the minimum payment can cut your payoff timeline by several years and save thousands of dollars in compounding interest charges.": "Pagar R$ 100 ou R$ 200 a mais por mês encurta anos de endividamento e economiza valores astronômicos em juros rotativos.",
    "Should I use a balance transfer card to pay off debt?": "Vale a pena pegar um empréstimo com juros menores para quitar o cartão?",
    "Should tips be calculated before or after sales tax?": "A gorjeta deve ser calculada antes ou depois dos impostos?",
    "Stacked discounts apply sequentially rather than additively. For example, 20% off plus an extra 10% off results in an effective 28% total discount, not 30%.": "Eles são aplicados em sequência sobre o saldo restante: 20% de desconto mais 10% extra resultam em 28% de abatimento real, e não 30%.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total vehicle expenses under 10% of gross monthly income.": "Dar ao menos 20% de entrada, financiar em no máximo 4 anos (48 meses) e manter as despesas automotivas totais abaixo de 10% da renda bruta.",
    "The money spent on down payment, closing costs, and ongoing property maintenance could otherwise remain invested in liquid assets like index funds that compound over time.": "O valor gasto em entrada e documentação poderia ficar investido rendendo juros compostos em títulos públicos e ações.",
    "Traditional 401(k) contributions are pre-tax and reduce your current taxable income, with withdrawals taxed in retirement. Roth 401(k) contributions are post-tax, but all qualified growth and withdrawals are completely tax-free.": "O modelo tradicional (PGBL) abate do IRPF hoje e tributa o total no resgate; o modelo pós-tributado (VGBL) não deduz agora, mas tributa apenas os rendimentos no futuro.",
    "What are the 401(k) contribution limits for 2024?": "Quais são os limites de aporte anual?",
    "What hidden costs of homeownership should renters consider?": "Quais custos ocultos da casa própria o inquilino deve considerar?",
    "What is an employer 401(k) match?": "O que é a contrapartida da empresa na previdência fechada?",
    "What is the 20/4/10 rule for buying a car?": "O que é a regra 20/4/10 para comprar um carro?",
    "What is the difference between Traditional 401(k) and Roth 401(k)?": "Qual a diferença entre o modelo PGBL e VGBL?",
    "What is the opportunity cost of buying a home?": "Qual o custo de oportunidade na compra de um imóvel?",
    "What is the standard tipping percentage?": "Qual é o valor habitual de gorjeta?",
    "Why does paying only the minimum take so long?": "Por que pagar apenas o mínimo da fatura do cartão é uma armadilha?",
    "Why is APR higher than the advertised interest rate?": "Por que o CET é maior que a taxa de juros anunciada?",
    "Yes, APR is the best metric for comparing loan offers with different fee structures, provided you plan to keep the loan for its full term.": "Sim, é o índice oficial mais seguro para comparar ofertas de instituições com tabelas de tarifas diferentes.",
    "How does an amortized loan work?": "Como funciona um empréstimo com tabela Price ou SAC?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest. Over time, an increasing portion goes toward paying down the principal balance until the debt is fully paid off.": "Na Tabela Price as parcelas são fixas (no início paga-se mais juros e no final mais amortização); na Tabela SAC a amortização é constante e as parcelas decrescem.",
    "What is the difference between fixed-rate and variable-rate loans?": "Qual a diferença entre taxa pré-fixada e pós-fixada?",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the loan term. A variable-rate loan has an interest rate that adjusts periodically based on benchmark interest rates, which can increase or decrease your payments.": "A taxa pré-fixada mantém os juros inalterados do início ao fim; a pós-fixada oscila conforme índices de referência como IPCA, TR ou Selic.",
    "What is the difference between interest rate and APR?": "Qual a diferença entre taxa nominal e Custo Efetivo Total (CET / APR)?",
    "The interest rate is the nominal cost of borrowing the principal balance. The Annual Percentage Rate (APR) reflects the total annual cost of the loan including points, broker fees, and origination charges.": "A taxa nominal reflete apenas os juros; o Custo Efetivo Total (CET / APR) engloba todas as tarifas bancárias, IOF, seguros e encargos.",
    "What is the 4% rule in retirement planning?": "O que é a regra dos 4% para a aposentadoria?",
    "The 4% rule suggests that withdrawing 4% of your retirement portfolio in the first year, adjusted for inflation annually thereafter, provides a high probability that your nest egg will last at least 30 years.": "Dita que retirar 4% do patrimônio no primeiro ano e corrigir pela inflação dá alta probabilidade de que os recursos durem mais de 30 anos.",
    "What is compound interest?": "O que são juros compostos?",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It causes your wealth to grow exponentially over time.": "São juros sobre juros: os rendimentos de cada período são incorporados ao capital inicial, gerando crescimento exponencial do patrimônio.",
    "What is the Rule of 72?": "O que é a regra dos 72?",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your annual interest rate (e.g. at 8%, your money doubles in about 9 years).": "Cálculo mental para saber em quantos anos o capital dobra: divida 72 pela taxa anual de juros (com 8% ao ano, o dinheiro dobra em cerca de 9 anos).",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price.": "Estratégia de investir um valor financeiro constante em intervalos periódicos pré-definidos, ignorando os preços momentâneos de tela.",
    "Can I pay off my loan early without penalty?": "Posso quitar o empréstimo antecipadamente sem tarifas?",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, but some lenders include a prepayment penalty clause. Always verify your loan agreement terms before making accelerated principal payments.": "No Brasil a liquidação antecipada de dívidas com desconto proporcional de juros é um direito garantido pelo Código de Defesa do Consumidor sem cobrança de multas.",
    "A 15-year mortgage typically offers a lower interest rate and allows you to pay off your home twice as fast, saving you tens of thousands of dollars in interest. However, a 30-year mortgage has lower monthly payments, which provides greater cash flow flexibility.": "Em 15 anos os juros totais são muito menores e o imóvel é quitado na metade do tempo; em 30 anos as parcelas mensais são mais acessíveis e dão flexibilidade.",
    "Any extra money you pay towards your mortgage is applied directly to the principal balance. This reduces the remaining loan balance and decreases the amount of interest that accumulates, helping you pay off your mortgage years ahead of schedule.": "Todo pagamento adicional abate diretamente o saldo devedor, reduzindo juros futuros e permitindo quitar o contrato anos mais cedo.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, studies show that the Debt Snowball method is often more successful in practice because the psychological momentum helps people stick to their plan.": "Matematicamente a Avalanche economiza mais dinheiro, mas na prática a Bola de Neve tem maior taxa de adesão pelo incentivo psicológico constante.",
    "You continue paying minimums on all debts and add your extra cash to the target debt. Once that target debt is fully paid off, you roll its entire payment into the next debt on your list.": "Você paga os mínimos em todas as dívidas e direciona a folga financeira para a dívida foco; quitada esta, todo o valor mensal é somado à dívida seguinte.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow (Snowball), and then pivot to targeting the remaining debts by highest interest rate (Avalanche).": "Sim. Muitas pessoas liquidam uma ou duas dívidas pequenas primeiro para desafogar o orçamento (Bola de Neve) e depois atacam as de maiores juros (Avalanche).",
    "It generally makes sense to refinance if you can secure a lower interest rate, reduce your monthly payment, or shorten your term, provided your total interest savings exceed the closing costs.": "Vale a pena quando você consegue uma taxa de juros menor, reduzindo o valor da parcela ou o prazo, com economia superior aos custos de transferência.",
    "Refinancing costs typically include application fees, origination fees, appraisal costs, title search and insurance, credit report fees, and recording fees, ranging from 2% to 6% of the loan amount.": "No crédito imobiliário podem existir taxas de avaliação do imóvel e averbação em cartório de registro de imóveis.",
    "Divide your total refinance closing costs by your monthly payment savings. If closing costs are $3,000 and you save $150 per month, your break-even point is 20 months ($3,000 / $150).": "Divida os custos totais pela economia mensal na parcela: R$ 3.000 em custos / R$ 150 economizados = 20 meses para recuperar o investimento.",
    "A no-closing-cost refinance means the lender either rolls the closing fees into your new total loan balance or charges a slightly higher interest rate to cover them.": "Os custos não desaparecem: são embutidos no saldo devedor total financiado ou compensados com uma taxa de juros ligeiramente mais alta.",
    "It depends on the term. Refinancing to a lower rate with the same or shorter term saves on both. Resetting your term back to 30 years lowers the monthly payment but can increase total lifetime interest.": "Se mantiver ou encurtar o prazo, economiza em ambos; se estender o prazo, a parcela diminui mas os juros totais pagos podem aumentar.",
    "The Saving on a Valuable Education (SAVE) plan is an income-driven repayment (IDR) plan that protects discretionary income up to 225% of the poverty line, lowers payments to 5%-10%, and stops unpaid interest from accumulating.": "Um plano governamental americano que ajusta a parcela à renda, protege 225% da linha de pobreza e impede o acúmulo de juros não pagos.",
    "If you pay under an IDR plan for 20 or 25 years (or 10 years under SAVE for low initial balances), any remaining student debt is forgiven.": "Pagando as parcelas vinculadas à renda durante 20 ou 25 anos, o saldo restante da dívida é perdoado pelo governo.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy. Borrowers with very high incomes relative to debt may prefer PAYE or IBR due to payment caps.": "Para a maioria o plano SAVE oferece o menor desembolso; quem tem renda alta prefere opções com teto máximo estipulado de parcela.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching plans can sometimes cause unpaid interest to capitalize.": "Sim, a solicitação é gratuita, mas a migração pode por vezes capitalizar juros acumulados sobre o principal.",
    "The 28/36 rule is a standard mortgage underwriting guideline stating that housing costs should not exceed 28% of gross monthly income, and total debt payments should not exceed 36%.": "Diretriz que orienta não comprometer mais de 28% da renda bruta em moradia e até no máximo 30-36% em parcelas de dívidas totais.",
    "Lenders use DTI to measure your ability to manage monthly payments. Lower DTIs below 36% receive the most favorable mortgage terms and lowest interest rates.": "Os bancos avaliam a capacidade de pagamento: um comprometimento de renda abaixo de 30% garante aprovação rápida e melhores taxas.",
    "Front-end DTI only includes housing expenses (mortgage, property tax, insurance, HOA). Back-end DTI includes housing plus all recurring debts like credit cards, auto loans, and student loans.": "O primeiro inclui apenas os custos da moradia; o segundo soma todos os financiamentos ativos (empréstimos, cartão e automóvel).",
    "Conventional mortgages typically prefer back-end DTIs of 36% to 43%. Government-backed loans like FHA and VA may allow DTIs up to 50% with strong compensating factors.": "No Brasil a legislação e os bancos limitam o comprometimento financeiro habitacional geralmente a no máximo 30% da renda comprovada.",
    "You can lower your DTI by increasing gross income or paying off smaller debts completely to eliminate their recurring monthly minimum payments.": "Aumentando a renda comprovada ou quitando pequenos empréstimos e cartões para eliminar as parcelas do orçamento.",
    "If you expect your tax bracket to be higher in retirement than it is today, a Roth IRA is better. If you expect your tax bracket in retirement to be lower, a Traditional IRA is better.": "Se sua alíquota de imposto for maior no futuro, prefira o modelo pós-fixado; se for menor no futuro, aproveite o benefício fiscal presente.",
    "For 2024, the annual contribution limit for Traditional and Roth IRAs is $7,000 for individuals under age 50, and $8,000 for individuals age 50 or older.": "O teto anual é de 7.000 $ para menores de 50 anos e 8.000 $ a partir dessa idade.",
    "Roth IRAs have income phase-out ranges that restrict high earners. Anyone with earned income can contribute to a Traditional IRA, but tax deductibility may be limited by income and workplace retirement coverage.": "O plano Roth tem faixas de renda limite para participantes com altos salários; o modelo tradicional é acessível a todos.",
    "Roth IRA original contributions can be withdrawn at any time penalty-free. Withdrawing investment earnings early or withdrawing Traditional IRA funds before 59½ usually incurs income taxes and a 10% penalty.": "Os valores aportados no plano Roth podem ser sacados a qualquer momento; rendimentos e planos tradicionais pagam IR e multa de 10%.",
    "State income tax rates range from 0% (in states like Texas, Florida, and Washington) to over 13% in high-tax states, while some cities also impose local municipal income taxes.": "Cada estado ou município possui regras próprias de tributação, com alíquotas diferenciadas de ICMS e ISS.",
    "The 5% rule estimates that homeownership costs roughly 5% of a property's value annually in unrecoverable expenses (1% property tax, 1% maintenance, and 3% cost of capital). Divide by 12 to find your break-even monthly rent. If you can rent an equivalent home for less, renting plus investing the savings builds greater wealth. For detailed math and worked case studies, read our complete guide: <a href=\"/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">How to Decide: Rent vs. Buy Your Home</a>.": "A regra dos 5% estima que os custos anuais irrecuperáveis da casa própria giram em torno de 5% do valor do imóvel (1% de IPTU/tributos, 1% de manutenção e reparos, e 3% de custo de oportunidade do capital). Divida esse montante por 12 para descobrir o valor de aluguel mensal de equilíbrio: se você puder alugar um imóvel equivalente por um valor menor e investir a economia, morar de aluguel acumulará um patrimônio maior no longo prazo. Para aprofundar os cálculos e ver simulações detalhadas, confira nosso guia: <a href=\"/pt/blog/how-to-decide-rent-vs-buy/\" class=\"text-primary underline font-medium\">Como Decidir: Comprar ou Alugar um Imóvel</a>.",
    "Most financial experts recommend spending no more than 25% to 28% of your gross monthly income on housing costs (the front-end DTI guideline). For a deep dive into bank underwriting formulas, salary matrices, and the 28/36 rule, read our complete guide: <a href=\"/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">How Much House Can I Afford?</a>.": "A maioria dos analistas financeiros e critérios bancários recomenda não comprometer mais de 25% a 28% da sua renda mensal bruta com habitação (índice de comprometimento básico / DTI). Para conferir as fórmulas de análise de crédito dos bancos, matrizes salariais e a regra 28/36, leia nosso guia completo: <a href=\"/pt/blog/how-much-house-can-i-afford/\" class=\"text-primary underline font-medium\">Quanto Posso Pagar por um Imóvel?</a>.",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to solve for any of the five core TVM variables: Present Value (PV), Future Value (FV), Periodic Payment (PMT), Annual Interest Rate (I/Y), and Number of Compounding Periods (N).": "Esta calculadora financeira de TVM utiliza as fórmulas padrão de juros compostos e fluxo de caixa descontado para calcular qualquer uma das cinco variáveis fundamentais do valor do dinheiro no tempo: Valor Presente (PV), Valor Futuro (FV), Pagamento Periódico (PMT), Taxa de Juros Anual (I/Y) e Número de Períodos de Capitalização (N).",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), planned recurring periodic deposits (PMT), interest rate, and duration. The calculator computes the total compounded ending balance instantly.": "Selecione 'Valor Futuro (FV)' como a variável de destino. Digite o saldo inicial aplicado (PV), os aportes periódicos programados (PMT), a taxa de juros e o prazo. A calculadora calcula instantaneamente o montante final composto acumulado.",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (common in lease and insurance contracts), earning an extra compounding cycle of interest.": "Em uma anuidade ordinária (postecipada), os pagamentos acontecem no final de cada período (padrão em financiamentos imobiliários e empréstimos pessoais). Em uma anuidade antecipada, os pagamentos são feitos no início de cada período (comum em contratos de locação e seguros), gerando um ciclo extra de capitalização de juros.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of the asset's fluctuating market price. For a full breakdown of the math, comparisons with lump-sum investing, and crypto fee traps, read our complete guide: <a href=\"/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">What Does DCA Mean in Crypto?</a>.": "Dollar-Cost Averaging (DCA) ou Aportes Constantes é uma estratégia em que você investe uma quantia fixa de dinheiro em intervalos regulares, independentemente da cotação de mercado do ativo. Para conhecer os cálculos completos, comparações com aportes únicos e como evitar taxas abusivas em criptomoedas, consulte nosso guia: <a href=\"/pt/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">O que Significa DCA em Cripto?</a>.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an \"in-service distribution\" (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Você pode paralisar ou cancelar contribuições futuras da folha de pagamento a qualquer instante sem custo, solicitando ao setor de RH o ajuste da taxa para 0%. No entanto, resgatar valores já depositados no plano de previdência corporativa enquanto continua empregado na empresa costuma ser vedado pelo regulamento, salvo regras legais específicas de resgate em atividade ou situações comprovadas de extrema necessidade. Mesmo quando permitido, resgates precoces acarretam pesada tributação de imposto de renda e penalidades. Leia nosso guia completo: <a href=\"/pt/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Posso Cancelar meu Plano de Previdência e Resgatar os Recursos Enquanto Empregado?</a>.",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (Rate), Number of Periods (Nper), and Periodic Payment (PMT). By inputting any four variables, our solver computes the fifth unknown mathematically using standard financial algebra formulas.": "A calculadora de TVM correlaciona cinco variáveis fundamentais: Valor Presente (PV), Valor Futuro (FV), Taxa de Juros Periódica (Rate), Número de Períodos (Nper) e Pagamento Periódico (PMT). Ao preencher quatro dessas variáveis, nosso algoritmo resolve matematicamente a quinta incógnita através das fórmulas universais da álgebra financeira.",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and total periods (years or months), specify any periodic recurring payment (PMT), and leave Future Value empty. The calculator instantly compounds your principal and contributions to reveal the ending balance.": "Para calcular o Valor Futuro, insira o aporte inicial como Valor Presente (PV), defina a taxa de juros anual e o número total de períodos (anos ou meses), informe qualquer aporte periódico recorrente (PMT) e deixe o campo Valor Futuro em branco. A calculadora capitaliza imediatamente seu montante e aportes para exibir o saldo final.",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and personal loans). In an annuity due, payments occur at the beginning of each period (common in lease payments and rent), allowing each cash flow to earn an extra period of compounding interest.": "Em uma anuidade ordinária, os pagamentos ocorrem ao final de cada período (padrão para financiamentos imobiliários e empréstimos pessoais). Em uma anuidade antecipada, os pagamentos são feitos no início de cada período (comum em contratos de aluguel e leasing), permitindo que cada fluxo financeiro usufrua de um período extra de capitalização de juros compostos.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested into equal periodic purchases (e.g. $50 every week) regardless of asset price, smoothing out market volatility over time.": "Dollar-Cost Averaging (DCA) é uma estratégia de investimento na qual você divide o capital total a ser investido em aportes periódicos de valor fixo (ex.: R$ 200 por semana) independentemente da cotação do ativo, reduzindo o impacto da volatilidade do mercado ao longo do tempo.",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement living expenses minus Social Security. If you need $60,000 per year from your portfolio, your target retirement nest egg is $1,500,000 ($60,000 × 25). This nest egg provides sustainable inflation-adjusted income throughout a 30-year retirement.": "Pela Regra dos 25 (o inverso da taxa de retirada segura de 4%), você necessita de aproximadamente 25 a 30 vezes o total das despesas anuais previstas na aposentadoria, descontados eventuais benefícios previdenciários públicos garantidos. Se você precisar de R$ 60.000 por ano da sua carteira, sua meta patrimonial é de R$ 1.500.000 (R$ 60.000 × 25), proporcionando renda sustentável corrigida pela inflação por 30 anos.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $500,000 401(k) generates ~$1,667/month ($20,000/year); a $1,000,000 401(k) generates ~$3,333/month ($40,000/year); and a $1,500,000 401(k) generates ~$5,000/month ($60,000/year). Combined with Social Security, this replaces 70% to 90% of pre-retirement income.": "Com base na regra dos 4% de resgate sustentável, sua retirada mensal estimada é obtida por: (Saldo Final Acumulado × 0,04) ÷ 12. Por exemplo, uma carteira de R$ 500.000 gera ~R$ 1.667/mês; R$ 1.000.000 gera ~R$ 3.333/mês; e R$ 1.500.000 gera ~R$ 5.000/mês. Somado à previdência social, esse fluxo substitui entre 70% e 90% da renda da ativa.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\\\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\\\" class=\\\"text-primary underline font-medium\\\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Caso siga a regra dos 4% de retirada segura e preserve uma carteira balanceada (ex.: 60% em ações e 40% em renda fixa), os dados históricos do Estudo Trinity atestam mais de 95% de chance de o capital sustentar todos os resgates por 30 anos sem esgotamento. Resgates anuais maiores (como 6% ou 7%) elevam expressivamente o perigo de exaustão em 15 a 20 anos em mercados em baixa. Leia nosso guia completo: <a href=\"/pt/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">Previdência Privada: Impostos, Renda Mensal e Longevidade do Patrimônio</a>.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty PLUS ordinary federal and state income taxes on the distributed amount. For someone in the 22% federal bracket and 5% state bracket, an early withdrawal of $20,000 forfeits $7,400 (37%) to penalties and taxes, leaving only $12,600. Key exceptions to the penalty include the Rule of 55 (leaving an employer at age 55 or older), qualifying hardship distributions, or Substantially Equal Periodic Payments (SEPP / Rule 72t).": "Qualquer resgate antecipado de planos de previdência fechada antes do prazo legal sem justificativa válida acarreta aplicação de multa fiscal rescisória somada à tributação integral de imposto de renda. Para quem está na faixa de 27,5%, um saque antecipado de R$ 20.000 pode perder mais de R$ 7.000 (35%+) em encargos e retenções, restando menos de R$ 13.000 líquidos.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals, freelancers, and small business owners with no full-time W-2 employees (other than a spouse). It allows dual contributions: up to $23,000 in elective employee deferrals ($30,500 if age 50+) PLUS an employer profit-sharing contribution up to 25% of net adjusted business earnings (20% for sole proprietors), up to a combined maximum of $69,000 in 2024.": "A previdência corporativa de titular único é uma modalidade destinada a profissionais autônomos, consultores PJ e donos de empresas sem funcionários integrais. Ela autoriza aportes duplos (como pessoa física e jurídica), alcançando elevados limites legais de diferimento tributário.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000, whichever is less. A 401(k) loan avoids income tax and the 10% IRS penalty because you repay principal and interest back into your own account (usually over 5 years). However, if you leave your employer before repaying, the remaining balance usually becomes due by the federal tax filing deadline, or it converts into a taxable early distribution.": "Sim, muitos fundos e planos corporativos oferecem empréstimos com garantia do próprio saldo acumulado de até 50% dos recursos integralizados. Essa modalidade não gera incidência de impostos nem multas de resgate, pois as parcelas e os juros são restituídos diretamente para a sua própria conta ao longo de até 5 anos.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) with one click. A Traditional 401k calculator mode shows your immediate federal and state tax savings today, while retirement withdrawals are taxed as ordinary income. A Roth 401k calculator mode models post-tax contributions that generate 100% tax-free growth and 100% tax-free withdrawals in retirement.": "Nossa calculadora previdenciária possibilita alternar entre aportes dedutíveis de imposto no presente (fiscalidade diferida na saída) e investimentos pós-tributados com resgates futuros livres de encargos fiscais, permitindo comparar qual opção gera maior riqueza líquida.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\\\"/blog/can-i-cancel-401k-cash-out-while-employed/\\\" class=\\\"text-primary underline font-medium\\\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Você pode paralisar ou cancelar contribuições futuras da folha salarial a qualquer momento sem taxas, alinhando com o setor de recursos humanos o ajuste da taxa para 0%. Contudo, resgatar valores já retidos no fundo previdenciário enquanto mantém o contrato de trabalho ativo costuma ser vedado, salvo situações legais de resgate por invalidez, desemprego ou idade mínima regulamentar. Leia nosso guia completo: <a href=\"/pt/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Posso Cancelar meu Plano de Previdência e Resgatar os Recursos Enquanto Empregado?</a>.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong performance or merit raises average 4% to 7%, and promotions or job changes typically command a 10% to 20%+ increase in base compensation.": "Historicamente, os reajustes anuais de reposição inflacionária variam entre 3% e 5%, aumentos por mérito alcançam de 5% a 8%, e promoções de cargo ou mudanças de empresa proporcionam com frequência ganhos de 10% a 20% ou mais.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: Raise % = ((New Salary - Old Salary) / Old Salary) × 100%.": "Subtraia o salário anterior do novo salário para encontrar o valor do reajuste, divida pela remuneração original e multiplique por 100. Por exemplo: (R$ 8.000 - R$ 7.000) / R$ 7.000 × 100 = 14,29% de aumento.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Considerando a jornada padrão de 40 horas semanais e 52 semanas anuais (2.080 horas trabalhadas ao ano), multiplique o valor do aumento por hora por 2.080. Um aumento de R$ 5,00 por hora representa R$ 10.400 adicionais na renda bruta anual.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above each tax bracket threshold are taxed at the higher marginal rate; income below the threshold remains taxed at the lower previous rates. A pay raise will always increase your net take-home pay.": "Não. Os regimes tributários modernos aplicam alíquotas progressivas escalonadas. Apenas os rendimentos que ultrapassam o piso da nova faixa do IRPF sofrem a cobrança da alíquota marginal mais elevada; o valor anterior permanece tributado nas alíquotas menores. Um reajuste salarial sempre elevará seu rendimento líquido final.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, private mortgage insurance (PMI) if down payment is under 20%, and homeowner association (HOA) fees. For the complete mathematical formula and a comparison with reverse mortgages, read our comprehensive guide: <a href=\"/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">What is a Reverse Mortgage & How Payments Work</a>.": "A parcela mensal padrão de um financiamento imobiliário compreende o Principal e Juros contratuais (P&I), IPTU e tributos municipais, seguros obrigatórios habitacionais (MIP e DFI) e taxas de condomínio. Para entender as fórmulas matemáticas completas e a comparação com modalidades inversas, confira nosso artigo: <a href=\"/pt/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">O que é Hipoteca Reversa e Como Funcionam os Pagamentos</a>.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders may charge an early payoff fee. Check your loan contract terms before making lump-sum payments.": "A amortização antecipada de empréstimos e financiamentos é um direito assegurado por normas de defesa do consumidor com abatimento proporcional dos juros futuros, sendo proibidas taxas ou multas de liquidação adiantada em contratos bancários de pessoas físicas.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from previous periods. It enables wealth to grow exponentially over time compared to simple interest.": "Juros compostos são calculados sobre o saldo inicial adicionado aos juros acumulados em todos os ciclos antecedentes. Com o passar dos anos, essa dinâmica resulta em multiplicação exponencial do capital acumulado.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money. Divide 72 by your expected annual interest rate (e.g., at 8% annual return, your money doubles in approximately 9 years: 72 / 8 = 9).": "A Regra dos 72 é um atalho prático para estimar em quanto tempo o seu dinheiro vai dobrar. Divida 72 pela taxa de juros anual: com rendimento de 8% ao ano, seus recursos dobram em aproximadamente 9 anos (72 ÷ 8 = 9).",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total returns. More frequent compounding means interest starts earning interest sooner, producing slightly higher annual percentage yields (APY).": "Quanto mais curta a frequência de capitalização dos juros (diária, mensal ou anual), maior o rendimento total acumulado. Capitalizações contínuas somam os rendimentos ao montante mais cedo, potencializando os ganhos nos períodos seguintes.",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement (including employer matching). At a bare minimum, contribute enough to capture the full employer match—otherwise, you are leaving free compensation on the table.": "A maioria dos planejadores financeiros recomenda investir pelo menos 15% da sua remuneração bruta anual em previdência e longo prazo. No mínimo, contribua sempre o suficiente para capturar 100% da contrapartida da sua empresa.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary, or dollar-for-dollar up to 4%) and calculates the combined total deposited into your retirement account each pay period.": "A ferramenta com contrapartida aplica o benefício patronal de matching concedido pela sua organização corporativa sobre o salário bruto, demonstrando a vultosa riqueza gerada pelos aportes da empresa ao longo da sua carreira.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by age 40, 6x by age 50, 8x by age 60, and 10x by age 67.": "As referências patrimoniais globais (como as diretrizes da Fidelity) recomendam manter acumulado: 1x o salário anual aos 30 anos, 3x aos 40 anos, 6x aos 50 anos, 8x aos 60 anos e 10x na idade de aposentadoria plena.",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, but pay income tax on withdrawals in retirement. In a Roth 401(k), you contribute after-tax dollars, but qualified withdrawals in retirement are 100% tax-free. Generally, choose Roth if you expect to be in a higher tax bracket in retirement, and Traditional if you are in a high tax bracket today.": "No plano com diferimento fiscal (Tradicional/PGBL), as contribuições reduzem a base tributável hoje, gerando economia fiscal imediata, mas os resgates na aposentadoria sofrem incidência de imposto. No modelo pós-tributado (Roth/VGBL), os aportes são feitos com a renda líquida, assegurando resgates futuros totalmente isentos de imposto de renda.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you contribute $10,000 and your marginal tax bracket is 24%, you save approximately $2,400 in federal income taxes this year.": "Cada real investido em previdência com diferimento fiscal reduz a renda tributável em proporção de um para um. Se você estiver na alíquota marginal de 27,5% no IRPF, uma contribuição de R$ 10.000 gera uma economia de R$ 2.750 no imposto devido do ano.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer match, investment returns, and years until retirement. Use this calculator's interactive chart to simulate your balance under conservative (5%), moderate (7%), and aggressive (9%) return assumptions.": "Seu patrimônio acumulado depende dos juros compostos, da taxa de poupança mensal, dos aportes patronais e do prazo até a aposentadoria. Começar jovem e capturar a totalidade da contrapartida do empregador multiplica expressivamente o patrimônio de longo prazo.",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 times your anticipated annual retirement expenses. For example, if you need $60,000 per year from your portfolio, you need an estimated $1.5 million nest egg ($60,000 × 25).": "Pela Regra dos 25 (o inverso da taxa de retirada segura de 4%), você necessita de aproximadamente 25 vezes o total das despesas anuais previstas para usufruir de uma aposentadoria tranquila e financeiramente independente.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending Balance × 0.04) / 12. For instance, a $1,000,000 retirement portfolio generates approximately $3,333 per month in sustainable retirement income, adjusted for inflation over a 30-year retirement.": "Com base na taxa de resgate seguro de 4%, sua renda mensal é estimada por: (Saldo Final Acumulado × 0,04) ÷ 12. Assim, uma carteira de R$ 1.000.000 proporciona aproximadamente R$ 3.333 por mês em renda sustentável.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities / 40% fixed income), historical backtesting (Trinity Study) indicates your portfolio has an over 95% probability of lasting at least 30 years without running out of money.": "Ao seguir a regra de retirada de 4% com uma alocação equilibrada (ex.: 60% em ações e 40% em renda fixa), os estudos históricos demonstram que sua reserva tem mais de 95% de chance de sustentar seu padrão de vida por pelo menos 30 anos sem esgotamento.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty plus standard income tax on the entire amount. Total taxes and penalties can easily exceed 35%–45% of your withdrawal.": "Resgatar valores de fundos de previdência fechados antes do prazo legal implica em retenção de imposto de renda e penalidades contratuais, tornando os resgates precipitados muito onerosos.",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no full-time employees. It allows business owners to contribute both as employee and employer, enabling significantly higher annual tax-deductible contribution limits.": "O plano previdenciário de participante único é uma modalidade destinada a profissionais liberais e microempresários sem empregados em regime integral, permitindo aportes como pessoa física e jurídica com teto ampliado de dedução fiscal.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000). The interest you pay goes back into your own account, avoiding taxes and penalties as long as you repay it on schedule (usually within 5 years).": "Sim, a legislação e muitos planos de previdência corporativa autorizam empréstimos com garantia do próprio saldo de até 50% do total integralizado, com devolução das parcelas e juros para a própria conta do participante.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions. The tool models post-tax spending power at retirement so you can see whether paying taxes now vs. at retirement yields a larger final nest egg.": "Nossa calculadora de previdência permite alternar entre contribuições com dedução fiscal imediata e aportes pós-tributados com resgates futuros livres de impostos, comparando qual modalidade oferece maior eficiência.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer non-mortgage debt is fully cleared. You first invest up to the employer match, then fund a Roth IRA, and put any remainder back into your employer plan.": "No Passo 4 da metodologia Dave Ramsey, você direciona 15% da renda bruta familiar para investimentos de aposentadoria assim que quitar todas as dívidas de consumo, restando apenas o financiamento da casa própria.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It provides cost-effective retirement plans with mandatory employer contributions (either a 3% match or a 2% non-elective contribution).": "Os planos previdenciários simplificados são estruturados para pequenas empresas com até 100 colaboradores, com contrapartida patronal obrigatória e processos de gestão descomplicados em relação aos grandes fundos corporativos.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your HR or plan administrator. However, cashing out existing vested funds while still actively employed is generally prohibited by plan rules, unless you qualify for a hardship distribution. For detailed options, see our guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Employed?</a>": "Você pode paralisar ou alterar os descontos futuros de contribuição previdenciária em folha a qualquer momento e sem custos comunicando o setor de RH e fixando a taxa em 0%.",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of ~10% annually before inflation. After factoring in 2.5%–3% average inflation and ETF expense ratios, a realistic long-term real return assumption is 6.5% to 7.0% per year for a 100% equity portfolio, or 5.0% to 6.0% for a balanced 60/40 stocks and bonds portfolio.": "Historicamente, os mercados globais de ações entregam um retorno nominal médio em torno de 10% ao ano antes da inflação. Para planejamentos de longo prazo, projeções conservadoras utilizam entre 6% e 8% ao ano para contemplar o desconto inflacionário.",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility stress by purchasing more shares when prices are low and fewer when prices are high. While historical data shows investing a lump sum immediately outperforms DCA about 68% of the time because markets rise long-term, recurring contributions are far easier to budget and provide psychological discipline.": "Aportes regulares e programados (DCA) reduzem o risco de timing e a volatilidade do mercado ao comprar cotas continuamente a preços variados, construindo grande patrimônio por meio da disciplina de longo prazo.",
    "Nominal return is the raw percentage gain generated by your investments before inflation and taxes. Real return is your actual purchasing power gain after subtracting the inflation rate. For example, if your portfolio gains 9% nominal in a year where inflation is 3%, your real return is approximately 6%.": "O retorno nominal é o percentual bruto de ganho entregue pelos seus investimentos antes de considerar a desvalorização da moeda. O retorno real representa o ganho efetivo de poder de compra após deduzir a inflação.",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contribution cash makes up the vast majority of your portfolio. Over 20 to 30 years, accumulated reinvested earnings surpass your total principal deposits and begin generating more annual income than your own salary.": "O crescimento composto gera expansão exponencial do patrimônio. Nos primeiros anos, os aportes pessoais respondem pela maior parte do saldo; com o passar do tempo, os rendimentos sobre rendimentos superam os depósitos próprios.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation costs (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income. This prevents you from becoming 'car poor' and prevents negative equity.": "A regra 20/4/10 orienta dar pelo menos 20% de entrada, financiar o veículo em no máximo 4 anos (48 meses) e manter as despesas totais com transporte (parcela, seguro, combustível e IPVA) abaixo de 10% da sua renda bruta mensal.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more total interest and risk owing more than the vehicle is worth (negative equity or being 'underwater') as the car depreciates. Sticking to 48 or 60 months is significantly safer.": "Prazos estendidos (como 60 ou 72 meses) reduzem o valor da parcela mensal, mas encarecem brutalmente o custo total em juros e aumentam o risco de ficar com patrimônio negativo (devendo ao banco mais do que o carro vale no mercado).",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance can exceed the market value of the car. If the car is totaled or stolen, standard insurance only pays market value, leaving you responsible for the remaining loan balance unless you have GAP insurance.": "Veículos novos sofrem depreciação acelerada (perdendo frequentemente até 20% no primeiro ano). Sem uma entrada adequada, você corre o risco de dever mais do que o valor de mercado do automóvel na Tabela Fipe, o que gera prejuízo em caso de sinistro ou revenda antecipada.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit-based raise typically ranges from 4% to 8%, while a promotion within the same company averages 8% to 12%. Switching companies or industries often commands a 15% to 25% salary increase.": "Historicamente, reajustes anuais de reposição inflacionária variam entre 3% e 5%, aumentos por mérito giram em torno de 5% a 8%, e promoções ou transições de carreira proporcionam saltos salariais de 10% a 20% ou mais.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100. Formula: [(New Salary - Old Salary) / Old Salary] × 100. For example, moving from $60,000 to $66,000 is a 10% raise: ($6,000 / $60,000) × 100.": "Subtraia seu salário antigo do novo salário para determinar o aumento em dinheiro, divida essa diferença pelo salário antigo e multiplique por 100. Fórmula: [(Novo Salário - Salário Antigo) / Salário Antigo] × 100. Por exemplo, passar de R$ 6.000 para R$ 6.600 representa um aumento de 10%: (R$ 600 / R$ 6.000) × 100.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly wage increase by 2,080. For example, a $2.50/hour raise equals an annual gross increase of $5,200 ($2.50 × 2,080).": "Considerando a jornada padrão de 40 horas semanais e 52 semanas anuais (2.080 horas trabalhadas ao ano), multiplique o valor do aumento por hora por 2.080. Um aumento de R$ 5,00 por hora representa R$ 10.400 adicionais na renda bruta anual.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of income that falls into the new, higher bracket is taxed at the higher percentage rate. Every dollar earned below that threshold is still taxed at the lower previous rates. A pay raise will always increase your total net take-home pay.": "Não. Os regimes tributários modernos aplicam alíquotas progressivas escalonadas. Apenas os rendimentos que ultrapassam o piso da nova faixa do IRPF sofrem a cobrança da alíquota marginal mais elevada; o valor anterior permanece tributado nas alíquotas menores. Um reajuste salarial sempre elevará seu rendimento líquido final.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on everything else. Once the smallest debt is cleared, you roll its entire payment into the next smallest debt. This generates psychological momentum through rapid early wins.": "O método Bola de Neve prioriza a quitação das dívidas de menor saldo primeiro, independentemente da taxa de juros. Isso proporciona alívio psicológico imediato e vitórias rápidas que incentivam a perseverar até a eliminação completa das pendências financeiras.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while paying minimums on all others. Mathematically, this minimizes total interest charges paid across all debts and clears debt in the fastest possible timeframe.": "O método Avalanche prioriza quitar primeiro as dívidas com as maiores taxas de juros (como rotativo do cartão e cheque especial), pagando o mínimo nas demais. Matematicamente, é a estratégia mais econômica por minimizar o volume total de juros pagos aos credores.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid. However, behavioural studies show that the Debt Snowball method often yields higher real-world completion rates because the psychological motivation of eliminating individual accounts quickly prevents people from giving up on their debt-free plan.": "Do ponto de vista financeiro, o método Avalanche é superior por minimizar o montante de juros pagos e antecipar o término da dívida. Contudo, o método Bola de Neve oferece grandes vantagens comportamentais pelas vitórias rápidas no início do processo.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt. Once that target debt is paid in full, its entire monthly budget (its minimum payment + the extra cash) rolls into the next debt on your roster, creating an ever-larger monthly payment that accelerates debt payoff.": "Você mantém os pagamentos mínimos de todas as obrigações e direciona qualquer sobra financeira para a dívida prioritária. Quando ela for liquidada, todo o valor daquela parcela é somado à dívida seguinte, gerando um efeito multiplicador que acelera a quitação.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain motivation (Snowball), and then switch to attacking the remaining debts by highest interest rate to save on interest costs (Avalanche).": "Sim. É muito comum liquidar uma ou duas dívidas pequenas primeiro para abrir espaço no orçamento mensal e ganhar confiança, migrando em seguida para a estratégia Avalanche a fim de combater os juros mais pesados com eficiência matemática.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or interest. It answers the fundamental financial question: 'How much will my money be worth tomorrow if I invest it today?'": "Valor Futuro (FV) é o montante financeiro correspondente a um patrimônio atual, aporte único ou fluxo de parcelas em uma data futura determinada, com base em uma taxa projetada de rentabilidade composta.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a reduction in purchasing power per unit of currency. When inflation occurs, each dollar or euro buys a smaller percentage of a good or service.": "Inflação é a elevação generalizada e contínua dos preços de produtos e serviços ao longo do tempo, corroendo o poder de compra da moeda. Uma nota de dinheiro hoje compra significativamente menos bens do que comprava há 10 ou 20 anos.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only have the purchasing power equivalent of about $7,440 in 10 years, even though the nominal account balance remains unchanged.": "Dinheiro parado em contas sem rendimento perde poder de compra ano após ano pela corrosão inflacionária. Com uma inflação média de 4% ao ano, R$ 10.000 terão o poder de compra equivalente a apenas R$ 6.755 após uma década.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average change over time in prices paid by consumers for a representative 'basket' of goods and services, including housing, food, transportation, energy, and healthcare.": "A inflação é aferida principalmente por índices de preços ao consumidor (como IPCA no Brasil ou CPI nos EUA), que monitoram a variação mensal de custos de uma cesta representativa de despesas das famílias, incluindo habitação, alimentação, transporte e saúde.",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.2% per year over multi-decade periods, though short-term supply shocks can cause temporary surges.": "Na maioria das economias desenvolvidas e emergentes com metas de inflação, as taxas médias históricas situam-se entre 3% e 4,5% ao ano em ciclos plurianuais, podendo registrar picos atípicos durante choques econômicos globais.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds / ETFs), real estate, inflation-protected government bonds (TIPS or bonos ligados al IPC), and commodities—historically provides the most reliable long-term protection against purchasing power loss.": "Investir em ativos cujos rendimentos superem a inflação — como carteiras diversificadas de ações, fundos imobiliários e títulos públicos indexados à inflação (Tesouro IPCA+) — é a forma mais segura de preservar e expandir o poder de compra real no longo prazo.",
    "You can stop or cancel future payroll contributions at any time without penalty by setting your deferral to 0%. However, cashing out money already in your 401(k) while remaining employed is usually prohibited by IRS rules, unless your plan specifically permits an 'in-service distribution' (typically available only after age 59½) or an IRS-qualified Hardship Distribution. Even if permitted, an early cash-out triggers mandatory 20% federal withholding plus a 10% IRS penalty and state income taxes. Read our complete guide: <a href=\"/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Can I Cancel My 401(k) and Cash Out While Still Employed?</a>.": "Você pode paralisar ou cancelar depósitos futuros em folha a qualquer instante e sem custo procurando o RH da sua empresa. Todavia, sacar o saldo já acumulado enquanto permanecer trabalhando costuma ser restrito pelas regras do plano, salvo hipóteses de grave emergência ou desligamento da empresa. Veja nosso guia detalhado: <a href=\"/pt/blog/can-i-cancel-401k-cash-out-while-employed/\" class=\"text-primary underline font-medium\">Posso Cancelar meu Plano de Previdência e Sacar os Recursos Enquanto Empregado?</a>",
    "In an ordinary annuity, payments occur at the end of each period (standard for mortgages and loans). In an annuity due, payments occur at the beginning of each period (standard for lease agreements). Because money is invested earlier in an annuity due, it compounds for one additional cycle, resulting in a higher Future Value.": "Em uma anuidade ordinária (postecipada), as parcelas vencem ao final de cada período (padrão em financiamentos imobiliários e empréstimos). Na anuidade antecipada, as parcelas ocorrem no início de cada período (comum em contratos de locação e seguros), rendendo um ciclo adicional de capitalização composta.",
    "Based on the 4% safe withdrawal rule, your monthly payout is estimated as: (Ending 401k Balance × 0.04) ÷ 12. For example, a $1,000,000 portfolio generates approximately $3,333 per month before taxes, with annual adjustments for inflation.": "Pela regra dos 4% de retirada segura, a renda mensal sustentável é estimada por: (Saldo Acumulado × 0,04) ÷ 12. Por exemplo, uma carteira de R$ 1.000.000 gera aproximadamente R$ 3.333 por mês em renda vitalícia com reajuste inflacionário ao longo de 30 anos.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g. 60% equities and 40% fixed income), historical market data from the Trinity Study indicates a 95%+ probability that your savings will last at least 30 years. Withdrawing at a higher rate (such as 6% or 7% annually) significantly increases the risk of exhausting funds within 15 to 20 years during market downturns. Read our complete guide: <a href=\"/blog/how-much-401k-reduces-taxes-pays-monthly-lasts/\" class=\"text-primary underline font-medium\">401(k) Taxes, Monthly Payouts, and Longevity Guide</a>.": "Aplicando a regra dos 4% com uma carteira balanceada (ex.: 60% em ações e 40% em títulos de renda fixa), os testes históricos do Estudo Trinity atestam mais de 95% de chance de o capital sustentar todos os resgates por 30 anos sem esgotamento.",
    "Withdrawing funds from a Traditional 401(k) before age 59½ triggers a 10% IRS early withdrawal penalty on top of ordinary income taxes at your marginal rate. A $20,000 withdrawal by someone in the 22% bracket would surrender roughly $6,400 in combined taxes and penalties.": "Resgatar recursos da previdência fechada antes do prazo legal acarreta retenção na fonte de imposto de renda e multas contratuais, podendo comprometer de 30% a 45% do valor total sacado.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New Salary - Old Salary) ÷ Old Salary) × 100. For example, moving from $60,000 to $66,000 is a 10% raise.": "Subtraia o salário anterior do novo salário para encontrar o valor do reajuste, divida pela remuneração original e multiplique por 100. Por exemplo: (R$ 8.000 - R$ 7.000) / R$ 7.000 × 100 = 14,3% de aumento.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $2.50/hour raise equals $2.50 × 2,080 = $5,200 more in pre-tax annual income.": "Considerando a jornada padrão de 40 horas semanais e 52 semanas anuais (2.080 horas no ano), multiplique o aumento por hora por 2.080. Um aumento de R$ 5,00 por hora equivale a R$ 10.400 adicionais na renda bruta anual.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the dollars earned above a tax bracket threshold are taxed at the higher marginal rate—never your entire income. A pay raise will always increase your total take-home pay.": "Não. A tributação de renda progressiva incide por faixas salariais. Apenas o valor que excede o teto da faixa anterior é tributado na alíquota maior; a renda abaixo continua taxada nas alíquotas inferiores. Um aumento salarial sempre trará mais dinheiro líquido para a sua conta.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and HOA fees (if applicable). If your down payment is under 20%, private mortgage insurance (PMI) is also included.": "A prestação mensal de um financiamento imobiliário abrange o pagamento do principal e juros contratuais, seguros habitacionais obrigatórios (MIP/DFI), tributos imobiliários (IPTU) e condomínio quando aplicável.",
    "The Rule of 72 is a quick mental formula to estimate how many years it takes to double your money: divide 72 by your expected annual interest rate. For example, at an 8% return, money doubles in roughly 72 ÷ 8 = 9 years.": "A Regra dos 72 é um atalho prático para estimar em quanto tempo o seu dinheiro vai dobrar. Divida 72 pela taxa de juros anual: com rendimento de 8% ao ano, seus recursos dobram em aproximadamente 9 anos (72 ÷ 8 = 9).",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income today, and pay ordinary income tax upon withdrawal in retirement. In a Roth 401(k), you contribute after-tax dollars, but all qualified retirement withdrawals—including all compound investment gains—are 100% tax-free.": "No regime com diferimento fiscal (Tradicional/PGBL), as contribuições são deduzidas da base de cálculo tributável presente, mas os saques na aposentadoria são tributados. No modelo pós-tributado (Roth/VGBL), os aportes são feitos com a renda líquida, garantindo que os resgates futuros sejam totalmente isentos de tributação.",
    "If you follow the 4% safe withdrawal rule and maintain a balanced portfolio (e.g., 60% equities, 40% bonds), historical data indicates a 95%+ probability that your savings will last at least 30 years.": "Ao adotar a regra dos 4% com uma alocação equilibrada (ex.: 60% em renda variável e 40% em renda fixa), os dados históricos do Estudo Trinity confirmam uma chance superior a 95% de a reserva financeira perdurar por 30 anos ou mais.",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance (maximum $50,000), which you repay through payroll deductions with interest going back into your account.": "Sim, a legislação e diversos regulamentos corporativos autorizam empréstimos com garantia do saldo previdenciário de até 50% do total integralizado, com devolução das parcelas acrescidas de juros diretamente para a conta do próprio participante.",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (after-tax) contributions to compare long-term tax advantages.": "Nossa calculadora previdenciária possibilita alternar entre aportes dedutíveis de imposto no presente e investimentos pós-tributados com resgates futuros livres de encargos fiscais, permitindo comparar qual opção gera maior riqueza líquida.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts (such as a 401k up to the match, then a Roth IRA) after paying off all non-mortgage debt and building a 3- to 6-month emergency fund.": "Pelo Passo 4 de Dave Ramsey, você investe 15% da renda bruta familiar em aplicações de aposentadoria de longo prazo assim que estiver sem qualquer dívida de consumo, restando unicamente o financiamento imobiliário.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. It features lower contribution limits than a standard 401(k) but requires mandatory employer contributions (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Planos de previdência simplificados para pequenas empresas são voltados a companhias com até 100 funcionários, contando com contrapartida patronal obrigatória e menor complexidade burocrática em comparação aos grandes fundos corporativos.",
    "You can stop or cancel future payroll contributions at any time without penalty by contacting your employer's HR or payroll department and updating your deferral percentage to 0%. However, cashing out existing money while still employed is generally prohibited by IRS regulations unless your plan offers an 'in-service distribution' (usually after age 59½) or you qualify for an IRS Hardship Withdrawal (which incurs income taxes and a 10% penalty).": "Você pode suspender ou cancelar contribuições futuras da folha salarial a qualquer momento e sem taxas, alinhando com o setor de recursos humanos o ajuste da taxa para 0%.",
    "Nominal return is the raw percentage gain generated by your investments before inflation. Real return is the purchasing power gain after subtracting the rate of inflation (Real Return ≈ Nominal Return - Inflation Rate).": "O retorno nominal é o ganho percentual bruto dos investimentos antes de considerar a inflação. O retorno real reflete o ganho genuíno de poder de compra após deduzir o índice inflacionário.",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 5%. A merit raise for strong performance typically falls between 4% and 8%, while a major promotion or job switch often commands a 10% to 20% salary increase.": "Historicamente, a reposição da inflação anual varia entre 3% e 5%, aumentos meritórios alcançam de 4% a 7%, e mudanças de cargo ou promoções de carreira chegam frequentemente a 10% ou 20%+ de acréscimo.",
    "Subtract your old salary from your new salary to determine the dollar raise, divide that difference by your old salary, and multiply by 100: ((New - Old) ÷ Old) × 100. For example, moving from $75,000 to $82,500 is a 10% raise.": "Subtraia seu salário antigo do novo salário para determinar o aumento salarial em dinheiro, divida essa diferença pelo salário antigo e multiplique por 100: ((Novo - Antigo) ÷ Antigo) × 100. Por exemplo, passar de R$ 7.500 para R$ 8.250 representa um reajuste de 10%.",
    "Assuming a standard 40-hour work week and 52 weeks per year (2,080 working hours annually), multiply your hourly raise by 2,080. For example, a $3.00/hour raise equals $3.00 × 2,080 = $6,240 more in pre-tax annual compensation.": "Em uma jornada de 40 horas semanais por 52 semanas no ano (2.080 horas anuais), multiplique o aumento por hora por 2.080. Um aumento de R$ 5,00 por hora representa R$ 10.400 a mais na renda anual bruta.",
    "No. United States federal income taxes use progressive marginal tax brackets. Only the portion of your income that falls into the higher tax bracket is taxed at the higher percentage rate. Your prior earnings are still taxed at their original lower rates, so a pay raise will always result in higher total take-home pay.": "Não. Sistemas de tributação progressiva incidem exclusivamente sobre a parcela que excede o limite de cada faixa de renda. Atingir uma faixa salarial superior jamais reduzirá o total do seu salário líquido.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while making minimum payments on all other accounts. Once the smallest balance is eliminated, you roll its payment into the next smallest debt, generating psychological momentum through quick wins.": "O método Bola de Neve consiste em liquidar primeiro as dívidas de menor valor nominal, gerando impulso psicológico positivo por meio de vitórias financeiras rápidas.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on all others. Once the balance with the highest APR is cleared, you redirect that full payment toward the next highest interest rate account.": "O método Avalanche prioriza quitar as dívidas com as taxas de juros mais pesadas primeiro, mantendo os pagamentos mínimos nas restantes para economizar o máximo de juros matematicamente.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest paid and eliminates debt faster. However, behavioral research shows that the quick psychological wins of the Debt Snowball method help many borrowers stay committed to their debt payoff journey.": "Matematicamente, o método Avalanche proporciona a maior economia de juros e menor custo total. No entanto, a Bola de Neve oferece o reforço motivacional necessário para muitas famílias manterem a disciplina até o fim.",
    "Investing in assets whose earnings outpace inflation—such as diversified equities (stock index funds), real estate, inflation-protected securities (TIPS), and high-yield savings accounts—preserves and grows your real wealth.": "Investir em ativos que historicamente superam a inflação — como fundos de ações, imóveis e títulos públicos atrelados ao IPCA — é a estratégia mais confiável para blindar e aumentar seu poder de compra no longo prazo.",
    "How does this online TVM calculator solve Time Value of Money equations?": "Como esta calculadora online de TVM resolve as equações do valor do dinheiro no tempo?",
    "This financial TVM calculator uses standard compound interest and discounted cash flow formulas to link five core variables: Present Value (PV), Future Value (FV), Payment (PMT), Periodic Interest Rate (r), and Total Periods (n). You enter any four known variables, and the mathematical engine automatically calculates the fifth missing parameter instantly.": "Esta calculadora financeira de TVM aplica as fórmulas universais de juros compostos e fluxo de caixa descontado para encontrar qualquer uma das cinco variáveis do valor do dinheiro no tempo: Valor Presente (PV), Valor Futuro (FV), Pagamento Periódico (PMT), Taxa de Juros Anual (I/Y) e Número de Períodos de Capitalização (N).",
    "How does this online TVM calculator solve Time Value of Money problems?": "Como esta calculadora de TVM resolve problemas de valor do dinheiro no tempo?",
    "The TVM calculator links five fundamental variables: Present Value (PV), Future Value (FV), Interest Rate per Period (i), Number of Periods (n), and Periodic Payment (PMT). By inputting any four of these values, the calculator solves for the fifth using closed-form financial equations or numerical approximation (for interest rate).": "A calculadora de TVM integra as cinco variáveis fundamentais: Valor Presente (PV), Valor Futuro (FV), Taxa de Juros por Período (Rate), Número de Períodos (Nper) e Parcela Periódica (PMT). Ao digitar quatro valores, o algoritmo calcula a quinta variável por meio de equações financeiras analíticas.",
    "Select 'Future Value (FV)' as the solve-for target. Input your current principal balance (PV), the periodic installment you plan to deposit (PMT), the expected annual interest rate (r), the compounding frequency, and the total duration in years. The calculator solves for the exact final balance, displaying total interest earned and visual amortization charts.": "Selecione 'Valor Futuro (FV)' como o objetivo do cálculo. Digite o valor inicial aplicado (PV), os depósitos periódicos regulares (PMT), a taxa de juros e o tempo. A calculadora exibe imediatamente o montante final composto.",
    "How do I use this as a Future Value calculator?": "Como utilizar esta ferramenta como uma calculadora de Valor Futuro?",
    "To calculate Future Value, enter your initial deposit as Present Value (PV), set your annual interest rate and duration, and optionally add recurring monthly payments (PMT). The calculator compounds the initial principal and annuity payments over time, displaying the final accumulated portfolio value and total interest earned.": "Para calcular o Valor Futuro, digite o capital inicial como Valor Presente (PV), informe a taxa anual de juros e a quantidade de períodos (em anos ou meses), adicione aportes recorrentes (PMT) caso existam e deixe o campo Valor Futuro em branco. A ferramenta calculará o montante final com capitalização de juros.",
    "What is the difference between an ordinary annuity and an annuity due?": "Qual é a diferença entre uma anuidade ordinária e uma anuidade antecipada?",
    "In an ordinary annuity, payments occur at the end of each period (standard for loans and mortgages). In an annuity due, payments occur at the beginning of each period (standard for lease agreements and rent). Because payments in an annuity due occur earlier, each installment earns an additional period of compound interest, resulting in a higher Future Value or higher Present Value.": "Em uma anuidade ordinária (terme échu), os pagamentos acontecem no fim de cada período (padrão em empréstimos e financiamentos). Na anuidade antecipada, os pagamentos ocorrem no início do período (comum em contratos de seguro e aluguel), auferindo um período extra de capitalização de juros.",
    "What is the 5% rule for renting vs. buying?": "O que é a regra dos 5% para decidir entre alugar ou comprar um imóvel?",
    "The 5% rule (popularized by Ben Felix) estimates the non-recoverable annual costs of homeownership at roughly 5% of the property value: 1% for property taxes, 1% for maintenance and repairs, and 3% for the cost of capital (mortgage interest + equity opportunity cost). If renting an equivalent home costs less than 5% of its purchase price annually (or 5%/12 per month), renting is mathematically favorable.": "A regra dos 5% (popularizada por Ben Felix) estima os custos anuais irrecuperáveis da casa própria em cerca de 5% do valor total do imóvel: 1% de IPTU/impostos, 1% de manutenção e 3% de custo de oportunidade do capital. Se o aluguel mensal de um imóvel equivalente for inferior a 5% do valor de venda dividido por 12, morar de aluguel e investir a diferença tende a ser financeiramente superior.",
    "Financial experts and the standard 28/36 rule recommend spending no more than 28% of your gross monthly income on housing costs (PITI: Principal, Interest, Taxes, and Insurance). Total monthly debt obligations (housing + cars + student loans + credit cards) should remain under 36% to maintain financial stability.": "Especialistas em finanças pessoais e a clássica regra 28/36 recomendam comprometer no máximo 28% da sua renda mensal bruta com habitação (parcela do financiamento, juros, IPTU e seguros) e no máximo 36% com todas as dívidas e financiamentos combinados.",
    "Under the empirical 4% Safe Withdrawal Rule, your retirement savings are statistically projected to last at least 30 years with a balanced stock/bond portfolio. For example, withdrawing 4% annually ($40,000 from a $1,000,000 balance) adjusted annually for inflation has historically survived almost every 30-year retirement window in modern market history.": "Pela Regra Empírica dos 4% de Retirada Segura, seus investimentos de aposentadoria têm projeção estatística para durar no mínimo 30 anos com uma carteira balanceada de ações e renda fixa. Por exemplo, resgatar 4% ao ano (R$ 40.000 de um patrimônio de R$ 1.000.000) com correção anual pela inflação sobreviveu historicamente a praticamente todos os períodos de 30 anos de aposentadoria no mercado moderno.",
    "The Time Value of Money principle states that a dollar today is worth more than a dollar in the future because today's dollar can be invested and earn interest over time.": "O princípio do Valor do Dinheiro no Tempo (TVM) estabelece que uma quantia em dinheiro disponível hoje vale mais do que a mesma quantia no futuro devido ao seu potencial de gerar rendimentos. O capital investido agora rende juros compostos, crescendo de forma exponencial em comparação a valores poupados tardiamente.",
    "Dollar-Cost Averaging (DCA) is an investment strategy where you divide the total amount to be invested across periodic purchases rather than investing everything in a single lump sum. By buying fixed dollar amounts at regular intervals, you automatically purchase more shares when prices are low and fewer shares when prices are high, lowering your average cost per share over time.": "O Dollar-Cost Averaging (DCA) é a metodologia na qual você distribui o valor total a ser aplicado em compras periódicas de cotas de um ativo, amenizando a volatilidade e eliminando a tentação arriscada de tentar prever os movimentos de curto prazo do mercado.",
    "Dollar-Cost Averaging is an investment strategy where you invest a fixed amount of money at regular intervals regardless of share price.": "Dollar-Cost Averaging (DCA) é a estratégia de aplicar um montante constante em intervalos regulares, sem se preocupar com as oscilações pontuais de cotação do ativo. Para conhecer os cálculos detalhados, o comparativo com aportes únicos e como evitar custos ocultos, confira nosso artigo: <a href=\"/pt/blog/what-does-dca-mean-in-crypto/\" class=\"text-primary underline font-medium\">O que Significa DCA em Criptomoedas?</a>.",
    "Most financial advisors recommend contributing at least 15% of your gross annual income toward retirement. At a minimum, always contribute enough to capture 100% of your employer's 401(k) match, as this provides an immediate 50% to 100% risk-free return on your money.": "A maior parte dos assessores e planejadores de finanças orienta aplicar ao menos 15% dos ganhos brutos anuais para a aposentadoria. No mínimo, contribua sempre o suficiente para aproveitar a totalidade da contrapartida patronal da sua empresa.",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income by one dollar. For example, if you are in the 24% federal tax bracket and contribute $10,000, you reduce your current tax bill by $2,400.": "Cada real investido em planos previdenciários dedutíveis reduz sua base tributável na proporção de um para um. Se a sua faixa marginal de imposto de renda for de 27,5%, aplicar R$ 10.000 em planos com incentivo fiscal economiza R$ 2.750 em impostos devidos no ano.",
    "How much in a 401(k) do I need to retire?": "Quanto preciso ter acumulado na previdência para me aposentar?",
    "Under the Rule of 25 (the inverse of the 4% safe withdrawal rule), you need roughly 25 to 30 times your planned annual retirement spending minus guaranteed income like Social Security. For example, if you need $60,000 per year from your portfolio, your target nest egg is $1,500,000 to $1,800,000.": "Pela Regra dos 25 (o inverso da taxa de retirada de 4%), é necessário acumular cerca de 25 a 30 vezes suas despesas anuais para desfrutar de uma aposentadoria confortável. Por exemplo, para um orçamento anual de R$ 60.000, o objetivo financeiro é de aproximadamente R$ 1,5 milhão.",
    "How much will my 401(k) pay me per month in retirement?": "Quanto meu plano de previdência renderá por mês na aposentadoria?",
    "How much tax and penalty do I pay on early 401(k) withdrawals?": "Quanto se paga de impostos e multas em resgates antecipados de previdência?",
    "What is a Solo 401(k) and how does it work for the self-employed?": "O que é um plano de previdência individual para autônomos e como ele funciona?",
    "A Solo 401(k) (or One-Participant 401k) is a retirement plan for self-employed professionals and small business owners with no common-law employees. It allows you to contribute both as an employee (deferring up to $23,000 in 2024) and as the employer (up to 25% of net business compensation), providing substantial tax deductions.": "O plano previdenciário individual de titular único é desenhado para profissionais autônomos, consultores e donos de pequenas empresas sem empregados com carteira assinada. Ele permite realizar aportes combinados (pessoa física e jurídica), alcançando elevados tetos de dedução tributária.",
    "Can I borrow against my 401(k) instead of taking an early withdrawal?": "Posso pegar um empréstimo com garantia do saldo previdenciário em vez de fazer um resgate antecipado?",
    "Yes, many employer plans permit a 401(k) loan for up to 50% of your vested balance or $50,000 (whichever is less). You repay the loan with interest back into your own account, usually over 5 years. However, if you leave your job, the outstanding balance typically becomes due rapidly or converts to a taxable distribution.": "Sim, diversos fundos e instituições financeiras concedem crédito consignado ou empréstimo com garantia do saldo previdenciário de até 50% dos recursos integralizados. As parcelas são reembolsadas com juros creditados de volta na sua própria conta, sem incidência de impostos de resgate ou multas rescisórias.",
    "How do I use this as a Roth vs Traditional 401(k) calculator?": "Como usar esta ferramenta como uma calculadora comparativa entre regimes tributários de previdência?",
    "Our 401k calculator allows you to toggle between Traditional (pre-tax) and Roth (post-tax) contributions. Traditional saves money on taxes today during your peak earning years, while Roth offers completely tax-free withdrawals in retirement.": "Nossa calculadora de previdência permite simular com facilidade a diferença entre regimes dedutíveis no presente e opções pós-tributadas com saques isentos no futuro, demonstrando qual estrutura patrimonial gera maior renda líquida.",
    "What is a good salary increase percentage?": "Qual é um bom percentual de aumento salarial?",
    "Historically, standard annual cost-of-living adjustments (COLA) range from 3% to 4%, strong merit raises range from 5% to 8%, and promotions or job switches typically yield 10% to 20% increases. Any raise above current inflation increases your real purchasing power.": "Historicamente, a reposição da inflação anual oscila de 3% a 5%, reajustes por desempenho destacável giram entre 5% e 8%, e promoções de nível hierárquico ou contratações em novas empresas alcançam ganhos de 10% a 20%+.",
    "How do I calculate a salary increase percentage?": "Como calcular o percentual de um aumento salarial?",
    "How do I convert an hourly pay raise into an annual salary increase?": "Como converter um aumento no valor da hora trabalhada em ganho anual?",
    "Will a pay raise push me into a higher tax bracket and reduce my take-home pay?": "Um aumento salarial pode me colocar em uma faixa de imposto mais alta e diminuir meu salário líquido?",
    "With an amortized loan, you make equal periodic payments. Early in the loan term, the majority of each payment goes toward interest charges; over time, as the principal balance decreases, a progressively larger portion of each payment reduces the principal debt.": "Em um empréstimo ou financiamento com amortização periódica (como na Tabela Price), as parcelas são regulares. No início do contrato, a maior fatia de cada prestação é destinada ao pagamento de juros bancários; à medida que o tempo passa, uma parcela cada vez maior abate o saldo devedor principal.",
    "A fixed-rate loan maintains the exact same interest rate and payment throughout the borrowing term, protecting you against rising interest rates. A variable-rate loan fluctuates with a market index, meaning payments can rise or fall over time.": "Em uma operação com taxa pré-fixada, a taxa de juros e as prestações permanecem inalteradas do início ao fim do contrato. Em linhas pós-fixadas (atreladas ao CDI, TR ou IPCA), a taxa oscila periodicamente conforme os índices de mercado, fazendo com que as parcelas sofram variações.",
    "Most consumer loans and conventional mortgages allow prepayment without penalties, though some lenders charge prepayment fees within the first 3 to 5 years. Always verify your loan agreement's prepayment terms before submitting extra payments.": "A amortização antecipada de empréstimos e financiamentos é um direito assegurado por normas de defesa do consumidor com abatimento proporcional dos juros futuros, sendo proibidas taxas ou multas de liquidação adiantada em contratos bancários de pessoas físicas.",
    "Compound interest is interest calculated on both the initial principal and the accumulated interest from prior periods. Unlike simple interest, compound growth produces an exponential wealth curve over long time horizons.": "Juros compostos são calculados sobre o saldo inicial adicionado aos juros acumulados em todos os ciclos antecedentes. Com o passar dos anos, essa dinâmica resulta em multiplicação exponencial do capital acumulado.",
    "The more frequently interest compounds (annually, monthly, daily), the higher your total return. More frequent compounding converts interest into principal faster, creating a higher Effective Annual Rate (EAR) than the stated nominal APR.": "Quanto mais curta a frequência de capitalização dos juros (diária, mensal ou anual), maior o rendimento total acumulado. Capitalizações contínuas somam os rendimentos ao montante mais cedo, potencializando os ganhos nos períodos seguintes.",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% match on the first 6% of salary) to determine the exact annual employer contribution added to your balance.": "A ferramenta com contrapartida aplica o benefício patronal de matching concedido pela sua organização corporativa sobre o salário bruto, demonstrando a vultosa riqueza gerada pelos aportes da empresa ao longo da sua carreira.",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30, 3x by 40, 6x by 50, 8x by 60, and 10x by age 67.": "As métricas internacionais de previdência (como as regras práticas da Fidelity) sugerem manter acumulado: 1x o rendimento anual aos 30 anos, 3x aos 40, 6x aos 50, 8x aos 60 e 10x na aposentadoria integral.",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, investment returns, and fee drag.": "Seu patrimônio futuro depende do poder dos juros compostos, da regularidade dos depósitos mensais, da participação patronal, do retorno da carteira e do prazo de acumulação. Iniciar os aportes uma década mais cedo pode mais que dobrar o patrimônio final acumulado.",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into tax-advantaged retirement accounts once all consumer debt (except the home mortgage) is paid off and a 3- to 6-month emergency fund is established.": "Seguindo a estratégia de Dave Ramsey (Baby Step 4), aplica-se 15% da receita bruta da família em investimentos de previdência após quitar integralmente todos os cartões, empréstimos e financiamentos de consumo.",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees, requiring a mandatory employer contribution (either a dollar-for-dollar match up to 3% or a 2% non-elective contribution for all eligible employees).": "Planos previdenciários simplificados atendem empresas de menor porte, estabelecendo contrapartida patronal obrigatória e processos de gestão descomplicados em relação aos fundos de pensão tradicionais.",
    "The 20/4/10 rule recommends putting down at least 20%, financing for no longer than 4 years (48 months), and keeping total monthly transportation expenses (loan payment, insurance, gas, and maintenance) under 10% of your gross monthly income.": "A diretriz 20/4/10 orienta desembolsar pelo menos 20% do valor do carro na entrada, financiar em no máximo 4 anos (48 meses) e manter as despesas gerais de transporte (prestação, combustível, seguro e impostos) em menos de 10% da receita bruta mensal.",
    "Longer terms (like 72 or 84 months) lower your monthly payment, but you pay substantially more in total interest. Additionally, you risk becoming 'upside-down' (owing more than the car is worth) due to rapid vehicle depreciation.": "Financiamentos muito longos (como 60 ou 72 meses) suavizam a prestação mensal imediata, mas elevam brutalmente a carga total de juros e expõem o comprador ao risco de dever mais do que o preço de tabela do veículo.",
    "New cars depreciate rapidly (often losing 20% in the first year). Without an adequate down payment, your loan balance will exceed the vehicle's market value, leaving you in negative equity if the car is totaled or sold early.": "Automóveis zero-quilômetro sofrem desvalorização expressiva nos primeiros 12 meses. Sem uma entrada substancial, você corre o perigo de dever ao banco um saldo superior à cotação do veículo, complicando sua situação em casos de roubo, perda total ou venda rápida.",
    "The Debt Snowball method involves paying off your smallest debt balances first, regardless of interest rates, while paying minimums on all other debts. Once the smallest debt is eliminated, you roll its payment into the next smallest balance to build rapid psychological momentum.": "O método Bola de Neve recomenda quitar primeiro a dívida de menor valor total, sem considerar a taxa de juros. Esse processo produz incentivo emocional positivo e alívio mental, ajudando a manter o foco até zerar todas as pendências.",
    "The Debt Avalanche method involves paying off your highest interest rate debts first while maintaining minimum payments on the rest. Once your highest-APR balance is cleared, you target the next highest rate.": "O método Avalanche ataca prioritariamente as dívidas que cobram as taxas de juros mais elevadas (como cartão de crédito e cheque especial). Do ponto de vista analítico, é a abordagem que mais poupa recursos em juros bancários.",
    "Mathematically, the Debt Avalanche method is superior because it minimizes the total interest you pay and eliminates debt in the shortest calendar time. However, the Debt Snowball provides psychological quick wins that help many borrowers stick with their payoff plan.": "Avaliando sob o prisma estritamente matemático, a estratégia Avalanche é a mais eficiente por reduzir os encargos financeiros totais e encurtar o tempo de endividamento. No entanto, a Bola de Neve é extremamente eficaz no aspecto comportamental pelas conquistas rápidas.",
    "You continue paying minimums on all debts and add your extra cash to the target priority debt until it is completely paid off.": "Você continua quitando as parcelas mínimas de cada dívida e concentra todo o dinheiro restante na obrigação selecionada. Assim que ela for eliminada, todo o recurso mensal antes destinado a ela é direcionado para a próxima dívida da lista, acelerando a quitação.",
    "Yes. Many people pay off one or two small debts first to free up immediate cash flow and gain confidence, then switch to the Avalanche method to tackle high-interest credit cards mathematically.": "Sim. É frequente pagar inicialmente uma ou duas contas de menor valor para desafogar o orçamento mensal imediato e conquistar motivação, passando em seguida para a técnica Avalanche para enfrentar os juros mais altos.",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of compound interest over time.": "Valor Futuro (FV) é a quantia em dinheiro que uma aplicação presente, depósito único ou fluxo de aportes atingirá em uma data estipulada no futuro, sob uma taxa prevista de crescimento ou juros compostos.",
    "Inflation is the general rise in prices for goods and services over time, resulting in a progressive decline in the purchasing power of your money.": "Inflação é a alta generalizada dos preços no decorrer dos anos, diminuindo o poder de compra da moeda. O mesmo dinheiro hoje compra uma quantidade sensivelmente menor de produtos e serviços do que no passado.",
    "Cash sitting in zero-interest accounts loses purchasing power each year. If inflation runs at 3% annually, $10,000 today will only buy about $7,440 worth of goods and services in 10 years.": "Recursos guardados em espécie ou em contas sem remuneração sofrem perda contínua de poder de compra pela inflação. Com uma taxa de 4% ao ano, R$ 10.000 terão o poder aquisitivo real de aproximadamente R$ 6.755 após 10 anos.",
    "Inflation is primarily measured using the Consumer Price Index (CPI), which tracks the average price change over time for a representative basket of consumer goods and services like housing, food, transportation, and medical care.": "A inflação é calculada oficialmente através de índices de preços ao consumidor (como IPCA ou IPC), que mensuram as alterações de custos de uma cesta habitual de consumo familiar contendo alimentação, moradia, transporte e cuidados de saúde.",
    "In the United States and most developed economies, headline inflation has historically averaged between 2.5% and 3.5% annually over multi-decade periods, though short-term spikes can exceed this range.": "Na maior parte dos países industrializados e economias em consolidação, a inflação média histórica mantém-se em patamares de 3% a 4% anuais ao longo de décadas, sofrendo picos extraordinários em momentos de crise sistêmica.",
    "For most borrowers, the SAVE plan offers the lowest monthly payment and the best interest subsidy.": "Para a maioria dos estudantes e tomadores de financiamento educacional, planos de amortização vinculados à renda disponível oferecem as menores parcelas mensais e proteção contra o acúmulo descontrolado de juros, garantindo previsibilidade e eventual quitação proporcional após o prazo regulamentar.",
    "Yes, you can apply to switch repayment plans for free at studentaid.gov. However, switching may capitalize unpaid interest.": "Sim, é possível solicitar a renegociação ou troca de modalidade de pagamento junto ao órgão gestor do financiamento educacional sem tarifas. Contudo, a migração de plano pode acarretar a incorporação de juros não pagos ao principal em determinados contratos.",
    "A no-closing-cost refinance doesn't mean the fees are waived. Instead, the lender either rolls the closing costs into the loan balance or charges a slightly higher interest rate.": "Um refinanciamento ou portabilidade anunciado 'sem custos iniciais' não significa gratuidade das tarifas. Na prática, a instituição financeira incorpora as despesas cartorárias e de avaliação ao saldo devedor principal ou cobra uma taxa de juros ligeiramente superior para cobrir tais custos.",
    "It can do both, but it depends on the new loan's term. If you refinance to a lower rate with the same remaining term, you lower your monthly payment. If you shorten the term, your payment may rise, but you pay off the debt faster.": "A operação pode cumprir ambos os objetivos a depender do prazo contratado. Se você refinanciar para uma taxa menor mantendo o mesmo prazo restante, tanto a prestação mensal quanto os juros totais diminuem. Se alongar o prazo, a parcela mensal cai, mas o montante total de juros acumulados ao final da dívida pode aumentar.",
    "For standard conventional mortgages, lenders usually prefer a back-end DTI of 36% or less, though approvals up to 43% or even 50% are possible with strong credit scores.": "Em financiamentos imobiliários convencionais, as instituições bancárias exigem preferencialmente um comprometimento total de renda (DTI geral) de até 30% a 36%, embora proponentes com excelente score de crédito e patrimônio comprovado possam ser aprovados com índices de até 40% a 45%.",
    "As a general rule, if you expect your tax bracket to be higher in retirement than it is today, Roth is superior. If you expect your tax bracket to be lower in retirement, Traditional is usually better.": "Como regra financeira geral: se você projeta estar em uma faixa de imposto mais alta na velhice do que atualmente, o modelo pós-tributado (Roth/VGBL) é matematicamente superior. Se você está hoje no auge de renda e prevê uma alíquota menor no futuro, o modelo com diferimento fiscal (Tradicional/PGBL) proporciona uma valiosa dedução tributária imediata no presente.",
    "For 2024, the annual contribution limit for both Traditional and Roth IRAs is $7,000 for those under 50, and $8,000 for those 50 and older.": "Para planos individuais de previdência e aposentadoria, a legislação estabelece tetos regulamentares anuais de dedução fiscal, permitindo abater até 12% da renda bruta anual tributável na declaração completa do Imposto de Renda.",
    "Roth IRAs have strict income limits; in 2024, eligibility phases out between $146,000 and $161,000 for single filers.": "Determinadas modalidades de incentivo tributário possuem limites de renda familiar para elegibilidade; por outro lado, planos de previdência privada aberta permanecem acessíveis a qualquer faixa de rendimentos, variando apenas o formato de dedutibilidade fiscal entre declarações completas ou simplificadas.",
    "With a Roth IRA, you can withdraw your original contributions at any time for any reason tax-free and penalty-free.": "Em investimentos pós-tributados, o capital originalmente aportado pode ser resgatado a qualquer momento sem incidência de novos impostos. No entanto, os rendimentos auferidos sacados antes dos prazos mínimos de carência sofrem incidência de imposto de renda e penalidades de resgate antecipado.",
    "Each state set its own income tax brackets (some states have no income tax at all, like Texas and Florida, while others have top rates exceeding 10%).": "Cada jurisdição e estado possui alíquotas próprias de impostos sobre circulação e renda. Nossa calculadora utiliza a média dos encargos fiscais vigentes, mas permite personalizar os percentuais para refletir com exatidão a tributação da sua localidade.",
    "A standard monthly mortgage payment consists of Principal & Interest (P&I), property taxes, homeowners insurance, and sometimes Private Mortgage Insurance (PMI) or HOA fees. The principal and interest portion is calculated using the standard amortization formula.": "A prestação mensal de um financiamento imobiliário compõe-se de Principal e Juros (P&I), impostos prediais (IPTU), seguros obrigatórios habitacionais (MIP e DFI) e taxas de condomínio. Para conferir as fórmulas matemáticas e o funcionamento das amortizações, confira nosso guia: <a href=\"/pt/blog/what-is-a-reverse-mortgage-how-it-works/\" class=\"text-primary underline font-medium\">O que é Hipoteca Reversa e Como Funcionam os Pagamentos</a>.",
    "PITI stands for Principal, Interest, Taxes, and Insurance. These are the four basic components that make up a total monthly mortgage payment when using an escrow account.": "PITI representa o acrônimo de Principal, Juros, Impostos e Seguros. São os quatro elementos fundamentais que compõem o encargo mensal do mutuário em um financiamento habitacional.",
    "How much should I contribute to my 401(k)?": "Quanto devo contribuir mensalmente para o meu plano de previdência?",
    "Most financial advisors recommend contributing at least 15% of your gross annual salary toward retirement (including employer matching). At a minimum, always contribute enough to capture your employer's full matching contribution—missing the match is walking away from free money and an instant 50% to 100% return. For 2024, the IRS employee elective deferral limit is $23,000 per year, or $30,500 if you are age 50 or older.": "A maioria dos planejadores financeiros recomenda investir pelo menos 15% da sua remuneração bruta anual em previdência e longo prazo. Se não for viável atingir 15% de imediato, contribua no mínimo o valor necessário para capturar 100% da contrapartida da sua empresa, aumentando o percentual em 1% a cada reajuste salarial.",
    "How does this 401(k) calculator with match calculate employer contributions?": "Como esta calculadora de previdência com contrapartida calcula as contribuições da empresa?",
    "The 401k calculator with match applies your employer's matching formula (e.g., 50% or 100%) up to your company's matching ceiling (e.g., up to 6% of salary). For example, on a $95,000 salary with a 6% contribution ($5,700), a 50% match adds an extra $2,850/year in employer deposits. The calculator projects both your personal deferrals and employer matching contributions compounded across your entire retirement horizon.": "A calculadora aplica o percentual de contrapartida corporativa (ex.: 50% ou 100%) sobre o teto estabelecido pela empresa, somando as contribuições do empregador aos seus depósitos e capitalizando todo o saldo com juros compostos.",
    "How much should I have in my 401(k) by age?": "Quanto devo ter acumulado na previdência de acordo com a minha idade?",
    "Standard retirement benchmarks (such as Fidelity guidelines) suggest having: 1x your annual salary by age 30; 2x by age 35; 3x by age 40; 4x by age 45; 6x by age 50; 8x by age 60; and 10x your final salary by age 67. If you earn $90,000 at age 40, your target 401(k) balance is approximately $270,000 to remain on track for complete income replacement.": "As referências patrimoniais globais (como as diretrizes da Fidelity) recomendam manter acumulado: 1x o salário anual aos 30 anos, 3x aos 40 anos, 6x aos 50 anos, 8x aos 60 anos e 10x na idade de aposentadoria plena.",
    "Should I do a Roth or Traditional 401(k)?": "Devo escolher um plano de previdência com dedução fiscal agora ou isenção no resgate futuro?",
    "In a Traditional 401(k), you contribute pre-tax dollars, lowering your taxable income and federal tax liability today; withdrawals in retirement are taxed as ordinary income. In a Roth 401(k), you contribute after-tax dollars, but your investment earnings grow completely tax-free and all qualified distributions in retirement are 100% tax-free. If you are in a low tax bracket now (early career), choose Roth; if you are currently in your peak earning years and highest tax bracket, choose Traditional.": "No regime com benefício fiscal presente (Tradicional/PGBL), os aportes abatem sua base tributável hoje, gerando economia fiscal imediata, mas os resgates na velhice são tributados. No modelo pós-tributado (Roth/VGBL), os aportes são feitos com o salário líquido, e todos os resgates futuros de principal e juros são totalmente isentos de imposto de renda.",
    "How much does a 401(k) contribution reduce my taxes?": "Quanto uma contribuição para a previdência reduz meus impostos?",
    "Every dollar contributed to a pre-tax Traditional 401(k) reduces your taxable income dollar-for-dollar. The tax savings formula is: Annual Contribution × Marginal Tax Rate. For example, contributing $10,000 at a 24% federal tax bracket plus 5% state tax saves $2,900 in total taxes. Your take-home pay only drops by $7,100 while your retirement nest egg grows by a full $10,000.": "Cada real aportado em planos com incentivo fiscal reduz sua renda tributável na proporção exata de um para um. Para quem está na alíquota marginal máxima do IRPF (27,5%), um aporte de R$ 10.000 gera uma economia de R$ 2.750 no imposto devido do exercício.",
    "How much will my 401(k) be worth at retirement?": "Qual será o valor acumulado no meu plano de previdência ao me aposentar?",
    "Your projected 401(k) balance depends on compound interest, contribution rate, employer matching, and time. For example, contributing $600 per month starting at age 30 with a $25,000 starting balance and an average 7.5% annual return yields approximately $1,350,000 by age 65. The vast majority of this total (over 70%) comes from compound investment growth rather than out-of-pocket deposits.": "O montante final acumulado depende dos juros compostos, da taxa de poupança mensal, dos aportes patronais e do prazo até a aposentadoria. Começar jovem e capturar a totalidade da contrapartida do empregador multiplica expressivamente o patrimônio de longo prazo.",
    "How long will my 401(k) last in retirement?": "Por quanto tempo meu saldo de previdência vai durar na aposentadoria?",
    "Can I cancel my 401(k) and cash out while still employed?": "Posso cancelar meu plano corporativo e resgatar o saldo enquanto continuo empregado?",
    "How does the Dave Ramsey 401(k) calculator 15% rule work?": "Como funciona a regra dos 15% de Dave Ramsey na previdência?",
    "Under Dave Ramsey's Baby Step 4, you invest 15% of your gross household income into retirement once consumer debt is eliminated and a 3-to-6 month emergency fund is established. The Dave Ramsey 401k calculator strategy follows a 3-step order: (1) Invest in your company 401(k) up to the full employer match; (2) Max out a Roth IRA; (3) Put any remaining portion of the 15% into your Roth 401(k) or Traditional 401(k). Use our 'Dave Ramsey (15% Rule)' preset to model this exact path.": "Pelo Passo 4 da metodologia Dave Ramsey, você investe 15% da renda bruta familiar em aposentadoria assim que eliminar todas as dívidas de consumo e constituir uma reserva de emergência completa correspondente a 3 a 6 meses do seu custo de vida.",
    "What is a SIMPLE 401(k) calculator and who qualifies for a SIMPLE plan?": "O que é um plano de previdência simplificado e quem tem direito a ele?",
    "A SIMPLE 401(k) (Savings Incentive Match Plan for Employees) is designed for small businesses with 100 or fewer employees. A simple 401k calculator models the required employer contributions: either a dollar-for-dollar match up to 3% of salary, or a flat 2% non-elective contribution for all eligible workers. SIMPLE 401(k) plans feature 100% immediate vesting, no complex nondiscrimination testing, and lower contribution limits ($16,000 in 2024, or $19,500 if age 50+).": "Planos de previdência simplificados são voltados para empresas de pequeno e médio porte com até 100 colaboradores, com custos operacionais reduzidos e regras obrigatórias de contrapartida da empresa aos funcionários.",
    "What is Future Value (FV)?": "O que é Valor Futuro (FV)?",
    "Future Value (FV) is the monetary value of a current asset, lump sum, or cash flow stream at a specified date in the future, based on an assumed rate of growth or compounding interest.": "Valor Futuro (FV) é o montante monetário que uma quantia atual, aporte único ou série de depósitos alcançará em uma data futura determinada, com base em uma taxa de juros ou crescimento composto. Ele mensura quanto seu dinheiro vai render e se expandir com o tempo.",
    "What is the formula for calculating Future Value with regular contributions?": "Qual é a fórmula matemática para calcular o Valor Futuro com aportes regulares?",
    "For a lump sum with regular periodic additions: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], where PV is present value, r is annual interest rate, m is compounding frequency per year, t is time in years, and PMT is periodic contribution.": "Para um capital inicial com depósitos periódicos regulares: FV = PV × (1 + r/m)^(m×t) + PMT × [((1 + r/m)^(m×t) - 1) / (r/m)], onde PV é o valor presente, PMT a parcela periódica, r a taxa anual de juros, m a frequência de capitalização no ano e t o prazo em anos.",
    "What is the difference between an ordinary annuity and annuity due for future value?": "Qual é a diferença entre uma anuidade ordinária e uma anuidade antecipada no cálculo do Valor Futuro?",
    "In an ordinary annuity, contributions are deposited at the end of each period. In an annuity due, contributions are made at the beginning of each period, which gives every contribution an extra period to compound and results in a higher ending future value.": "Em uma anuidade ordinária (postecipada), os aportes são efetuados no final de cada período. Em uma anuidade antecipada, os depósitos ocorrem no primeiro dia de cada intervalo, proporcionando um ciclo adicional de rendimento de juros compostos sobre cada parcela.",
    "How does compounding frequency impact the future value of an investment?": "Como a frequência de capitalização afeta o Valor Futuro de um investimento?",
    "More frequent compounding cycles (such as monthly or daily versus annually) result in higher future values because interest earned in earlier cycles begins generating its own interest sooner.": "Ciclos de capitalização mais frequentes (como mensais ou diários em vez de anuais) produzem um Valor Futuro mais elevado, pois os juros creditados são reinvestidos no principal mais cedo, gerando novos juros com maior agilidade.",
    "What is a realistic annual rate of return for an investment calculator?": "Qual é uma taxa anual de rentabilidade realista para usar em simulações de investimentos?",
    "Historically, the broad US stock market (S&P 500) has generated an average nominal return of approximately 10% annually over long multi-decade horizons (or roughly 7% after adjusting for inflation). A diversified portfolio of stocks and bonds typically targets 6% to 8% nominal annual return.": "Historicamente, os mercados acionários amplos entregam retornos nominais médios de aproximadamente 10% ao ano antes da inflação. Para projeções conservadoras de longo prazo, considerando o abatimento da inflação e taxas de gestão de fundos, uma rentabilidade real entre 6,0% e 7,5% ao ano é considerada padrão e prudente.",
    "How do regular recurring investments compare to a one-time lump sum?": "Como se comparam aportes mensais recorrentes em relação a uma aplicação única inicial?",
    "Regular recurring investments (Dollar-Cost Averaging) reduce timing risk and volatility by consistently purchasing shares at both market highs and lows. While lump-sum investing mathematically outperforms about 68% of the time due to long-term market upward trends, recurring monthly deposits instill discipline and build substantial wealth steadily.": "Aportes mensais constantes (DCA) atenuam a volatilidade e o risco de timing ao adquirir cotas a preços variados ao longo dos ciclos. Um aporte único inicial desfruta de mais tempo de capitalização integral, mas expõe o investidor ao risco de aplicar todo o capital em um topo de mercado.",
    "What is the difference between nominal return and real return?": "Qual é a diferença entre retorno nominal e retorno real?",
    "How does compound interest multiply investment portfolios over time?": "Como os juros compostos multiplicam uma carteira de investimentos ao longo dos anos?",
    "Compound growth creates exponential portfolio expansion. In the early years, personal contributions make up the majority of your balance; however, after 10 to 20 years, investment returns and compounded earnings account for over 60% to 80% of total portfolio value.": "O crescimento composto promove uma expansão exponencial do patrimônio. Nos primeiros anos, os depósitos próprios respondem pela maior parte do saldo; com a passagem do tempo, os rendimentos gerados sobre rendimentos acumulados superam amplamente os novos aportes.",
    "How do I calculate a percentage salary increase?": "Como calcular o percentual de um aumento salarial?",
    "To calculate the percentage increase: subtract your old salary from your new salary, divide the difference by your old salary, and multiply by 100: ((New - Old) / Old) × 100. For example, moving from $75,000 to $82,500 is (($82,500 - $75,000) / $75,000) × 100 = 10%.": "Para calcular o percentual de aumento: subtraia a remuneração antiga da nova remuneração, divida a diferença pelo salário antigo e multiplique por 100. Por exemplo, uma mudança de R$ 7.500 para R$ 8.250 calcula-se por: (R$ 8.250 - R$ 7.500) / R$ 7.500 × 100 = 10% de reajuste.",
    "How much of my salary raise will I actually take home after taxes?": "Quanto do meu aumento salarial realmente sobrará líquido após os impostos?",
    "Your net take-home boost depends on your marginal tax bracket and payroll deductions. Because raises are taxed at your highest marginal rate rather than your lower average rate, you typically take home between 55% and 75% of your gross increase (depending on state taxes and FICA).": "O ganho líquido real disponível depende da sua faixa marginal de imposto de renda e dos descontos previdenciários em folha. Como os acréscimos salariais incidem na sua alíquota marginal mais alta, você geralmente recebe líquido entre 65% e 75% do valor bruto do aumento.",
    "What is the difference between a merit raise and a cost-of-living adjustment (COLA)?": "Qual é a diferença entre um aumento por mérito e um reajuste por custo de vida (dissídio)?",
    "A Cost of Living Adjustment (COLA) is an across-the-board raise (typically 2% to 4%) designed to keep your purchasing power level with consumer inflation. A merit or performance raise is an individualized increase rewarded for outstanding work, increased duties, or hitting high performance benchmarks.": "O reajuste de custo de vida ou dissídio coletivo é uma correção salarial geral (normalmente de 3% a 5%) desenhada para repor o poder aquisitivo corroído pela inflação. O aumento por mérito é uma valorização individual concedida por desempenho de destaque, assunção de novas atribuições ou promoção de cargo.",
    "How often should you ask for a salary increase?": "Com que frequência é recomendável solicitar um aumento salarial?",
    "Standard corporate practice evaluates compensation annually during performance reviews. However, you should initiate compensation discussions whenever you take on significantly expanded responsibilities, complete major high-value certifications, or outperform annual targets by a substantial margin.": "A prática corporativa tradicional realiza avaliações de remuneração anualmente nos ciclos formais de desempenho. No entanto, é plenamente oportuno pautar uma revisão salarial quando você assume novas responsabilidades de peso, obtém certificações técnicas relevantes ou após 12 a 18 meses de entregas consistentemente superiores às metas.",
  },
};

// Merge allFaqs into faqTranslations
for (const lang of Object.keys(allFaqs) as Lang[]) {
  if (!faqTranslations[lang]) {
    faqTranslations[lang] = {};
  }
  if (allFaqs[lang]) {
    Object.assign(faqTranslations[lang], allFaqs[lang]);
  }
}
